//コピージョブを取得 
// sc_Select に、PCGE_JobPutNothing以外が設定されていた場合は、引数を有効とする.
APIC_Job* PnlComGetJobCopy( PCGE_JobPutNo sc_Select )
{
	if( ( onlyPanel.ep_PanelStatus == EP_PNS_AllManuscriptSettingChange ) && ( sc_JobPutNo != PCGE_JobPutJBLBox ) ) {
		// 全原稿設定変更中.
		return comPanelJob;
	}
	if( sc_Select == PCGE_JobPutNothing ) {
		sc_Select = sc_JobPutNo;
	}
	switch( sc_Select ) {
		case 0:
			if( !( cp_copyJob ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
			return cp_copyJob;
			break;
		case 1:		return cp_jbcopyJob;		break;
		default: break;
	}
	LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
	return NULL;
}
//スキャンジョブを取得
// sc_Select に、PCGE_JobPutNothing以外が設定されていた場合は、引数を有効とする.
APIC_Job* PnlComGetJobScan( PCGE_JobPutNo sc_Select )
{
	return( PnlComGetJobScanFax( sc_Select ) ) ;
}
//ファクスジョブを取得
// sc_Select に、PCGE_JobPutNothing以外が設定されていた場合は、引数を有効とする.
APIC_Job* PnlComGetJobFax( PCGE_JobPutNo sc_Select )
{
	return( PnlComGetJobScanFax( sc_Select ) ) ;
}
// スキャナ/ファクスジョブを取得
// sc_Select に、PCGE_JobPutNothing以外が設定されていた場合は、引数を有効とする.
APIC_Job* PnlComGetJobScanFax( PCGE_JobPutNo sc_Select )
{
	if( sc_Select == PCGE_JobPutNothing ) {
		sc_Select = sc_JobPutNo ;
	}
	switch( sc_Select ) {
		case PCGE_JobPutOther :
//		if( cp_scanfaxJob == NULL ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ) ; }
//		return(cp_scanfaxJob) ;
			// カレントジョブのファクスアプリフラグにより戻り値を切り替える.
			if( True == onlyPanel.getFaxAppMode() ) {
				if( cp_faxJob == NULL ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ) ; }
				return ( cp_faxJob );
			} else {
				if( cp_scanfaxJob == NULL ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ) ; }
				return( cp_scanfaxJob ) ;
			}
		case PCGE_JobPutJBLBox :
			return( cp_jbscanfaxJob ) ;
		case PCGE_JobPutFaxOnly:
			return ( cp_faxJob );
		case PCGE_JobPutFaxScan:
			return ( cp_scanfaxJob );
		default : break ;
	}
//Comment HCLT-Krishna 10/07/2019 Removing unneccessary log.
//	LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ) ;
	return( NULL ) ;
}

// ScanToDeviceジョブを取得.
// 拡張を考慮し他の関数と同じ引数とする.
APIC_Job* PnlComGetJobScanToDevice( PCGE_JobPutNo sc_Select )
{
	if( cp_scantodeviceJob == NULL ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ) ; }
	return( cp_scantodeviceJob ) ;
}

