//================================================================================================
// 概要		:管理者設定・ユーザ認証／部門管理・ユーザ認証設定・ユーザ登録・ユーザ登録_ユーザ表示・ユーザ名入力 : 文字列比較.
// 戻り値	:short.
//================================================================================================
short ADMIN_stricmp( char* s1, char* s2 )
{
	register char chr1, chr2;
	while( 1 ) {
		chr1 = *s1++;
		chr2 = *s2++;
		if( !chr1 || !chr2 )
		{ break; }
		if( toupper( chr1 ) != toupper( chr2 ) )
		{ return( ( short )( chr1 - chr2 ) ); }
	}
	return( ( short )( chr1 - chr2 ) );
}
