		case PRINTEREXTERNALPANELNUM:	// 2007/04/16 12加藤正：[Thames1P]外部パネルアプリ(市場でのサービス冶具パネル)モード。 0x00:OFF／0x01:ON.
			uc_SWvalue = pc_SoftDipSw->getSoftDipSwBit( 4, 3 );				// DipSWCommonAPIから値を取得.
			break;
#endif	// #ifdef DEF_ThamesCus	// Thames固有.
		case BLANKPAPERRESTRAINT:	// 2007/12/20 12井西：[ThamesFNX特ROM]白紙抑制制御対応 0x00:従来通り／0x01:白紙抑制.
			uc_SWvalue = 0;
			if( True == pc_SoftDipSw->getSoftDipSwBit( 14, 1 ) ) {
				uc_SWvalue |= 0x01;
			}
