// comment 2016/07/25 SCD2-Sky門 [特ROM][CQ532653]FQ-OPSD-1600045-OFP033 ランニングモードを実施後、給紙トレイのEcoチェックが外れる.
//概要    :全トレイのEco設定をバックアップ.
void PnlComBackupCopy_PaperTypeEx(){
	APIC_PrintJobSetting* pc_PrintJobSetting = PnlComGetPrintJobSetting();
	if( NULL == pc_PrintJobSetting ){
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	APIC_FeedTray* pc_FeedTray = PnlComGetFeedTray(); 
	if( NULL == pc_FeedTray ){
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	// Eco設定使用可能、且つ、Eco設定がバックアップ中ではない場合.
	if( ( True == pc_PrintJobSetting->getPaperTypeNormalEx() )
	  &&( False == pc_PrintJobSetting->getPaperTypeNormalEx_BackupStatus() ) ){
		// Eco設定がバックアップ中を設定.
		pc_PrintJobSetting->setPaperTypeNormalEx_BackupStatus( True );
		TYPS_PaperTypeNormalEx_Backup s_PaperTypeNormalEx_Backup;	// Eco設定(バックアップ)情報構造体.
		memset( &s_PaperTypeNormalEx_Backup, 0, sizeof(s_PaperTypeNormalEx_Backup) );
		// トレイ数分ループ.
		for( uchar uc_cnt = 0 ; TYPE_FeedTrayMax > uc_cnt ; uc_cnt++ ){
			// 現在のEco設定を取得.
			s_PaperTypeNormalEx_Backup.b_PaperTypeNormalEx_Backup[ uc_cnt ] = pc_FeedTray->getPaperType( e_AryShowFeedTrayTbl2[ uc_cnt ] ).getPaperTypeNormalEx();
		}
		// Eco設定を保存.
		pc_PrintJobSetting->setPaperTypeNormalEx_Backup( s_PaperTypeNormalEx_Backup );
	}
}
// comment 2016/07/25 SCD2-Sky門 [特ROM][CQ532653]FQ-OPSD-1600045-OFP033 ランニングモードを実施後、給紙トレイのEcoチェックが外れる.
//概要    :全トレイのEco設定をリストア.
void PnlComRecoveryCopy_PaperTypeEx(){
	APIC_PrintJobSetting* pc_PrintJobSetting = PnlComGetPrintJobSetting();
	if( NULL == pc_PrintJobSetting ){
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	APIC_FeedTray* pc_FeedTray = PnlComGetFeedTray(); 
	if( NULL == pc_FeedTray ){
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	// Eco設定使用可能、且つ、Eco設定がバックアップ中の場合.
	if( ( True == pc_PrintJobSetting->getPaperTypeNormalEx() )
	  &&( True == pc_PrintJobSetting->getPaperTypeNormalEx_BackupStatus() ) ){
		// Eco設定がバックアップ中を解除.
		pc_PrintJobSetting->setPaperTypeNormalEx_BackupStatus( False );
		TYPC_PaperType c_PaperType;	// 用紙種類クラス.
		TYPS_PaperTypeNormalEx_Backup s_PaperTypeNormalEx_Backup;	// Eco設定(バックアップ)情報構造体.
		memset( &s_PaperTypeNormalEx_Backup, 0, sizeof(s_PaperTypeNormalEx_Backup) );
		// 不揮発に保存されているEco設定を取得.
		pc_PrintJobSetting->getPaperTypeNormalEx_Backup( &s_PaperTypeNormalEx_Backup );
		// トレイ数分ループ.
		for( uchar uc_cnt = 0 ; TYPE_FeedTrayMax > uc_cnt ; uc_cnt++ ){
			// 用紙種類を取得.
			c_PaperType = pc_FeedTray->getPaperType( e_AryShowFeedTrayTbl2[ uc_cnt ] );
			TYPE_PaperType e_PaperType = c_PaperType.getPaperType();
			// 普通紙設定の場合.
			if( TYPE_PaperTypeNormal == e_PaperType ){
				// 不揮発から取得したEco設定を反映.
				c_PaperType.setPaperTypeNormalEx( s_PaperTypeNormalEx_Backup.b_PaperTypeNormalEx_Backup[ uc_cnt ] );
				// 給紙トレイ情報の用紙種類設定.
				pc_FeedTray->setPaperType( e_AryShowFeedTrayTbl2[ uc_cnt ], c_PaperType );
			}
		}
	}
}
