//概要    :コピー用共通データを復帰
//戻り値  :なし
void PnlComRecoveryCopy_Com( TYPC_Common* const pc_Dst, TYPE_RecoveryCommon e_RecoveryCommon )
{
	if( NULL == pc_Dst ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	TYPC_Common* pc_Src = PnlComGetReturnCopy_Com();
	if( !pc_Src ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
	switch( e_RecoveryCommon ) {
		case TYPE_RecoveryCommonAll:	memcpy( pc_Dst ,pc_Src ,sizeof( TYPC_Common ) );			break;	// TYPC_Common全体.
		default:	LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	break;
	}
}
//概要    :コピー用スキャンデータを復帰
void PnlComRecoveryCopy_Scan( TYPC_Scan* const pc_Dst, TYPE_RecoveryScan e_RecoveryScan )
{
	if( NULL == pc_Dst ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	TYPC_Scan* pc_Src = PnlComGetReturnCopy_Scan();
	if( !pc_Src ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
	switch( e_RecoveryScan ) {
		// TYPC_Scan全体.
		case TYPE_RecoveryScanAll: memcpy( pc_Dst ,pc_Src ,sizeof( TYPC_Scan ) ); break;
		// 原稿サイズ.
		case TYPE_RecoveryScanOriginalSize:
			pc_Dst->c_OriginalSize.setAutoSize( pc_Src->c_OriginalSize.getAutoSize() );
			pc_Dst->c_OriginalSize.setPaperSize( pc_Src->c_OriginalSize.getPaperSize() );
			break;
		// ブック連写.
		case TYPE_RecoveryScanPageShot:
			pc_Dst->c_PageShot.setPageShot( pc_Src->c_PageShot.getPageShot() );
			pc_Dst->c_PageShot.setPageShotCover( pc_Src->c_PageShot.getPageShotCover() );
			pc_Dst->c_PageShot.setAdfMode( pc_Src->c_PageShot.getAdfMode() );
			break;
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); break;
	}
}
//概要    :コピー用プリントデータを復帰
void PnlComRecoveryCopy_Print( TYPC_Print* const pc_Dst, TYPE_RecoveryPrint e_RecoveryPrint )
{
	if( NULL == pc_Dst ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	TYPC_Print* pc_Src = PnlComGetReturnCopy_Print();
	if( NULL == pc_Src ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	switch( e_RecoveryPrint ) {
		// TYPC_Print全体.
		case TYPE_RecoveryPrintAll: memcpy( pc_Dst ,pc_Src ,sizeof( TYPC_Print ) ); break;
		// 用紙種類（用紙種類・両面2面目フラグ）.
		case TYPE_RecoveryPrintPaperTypeKind:
			pc_Dst->c_PaperType.setPaperType( pc_Src->c_PaperType.getPaperType() );
			pc_Dst->c_PaperType.setFeed2ndSidedPaper( pc_Src->c_PaperType.getFeed2ndSidedPaper() );
			break;
		// 用紙種類（画像位置指定）.
		case TYPE_RecoveryPrintPaperTypePosition: pc_Dst->c_PaperType.setWidePaperImagePosition( pc_Src->c_PaperType.getWidePaperImagePosition() ); break;
		// 用紙サイズ.
		case TYPE_RecoveryPrintPaperSize:
			pc_Dst->c_PaperSize.e_SizeCode = pc_Src->c_PaperSize.e_SizeCode;
			pc_Dst->c_PaperSize.c_SizeMM = pc_Src->c_PaperSize.c_SizeMM;
			pc_Dst->c_PaperSize.b_WideOn = pc_Src->c_PaperSize.b_WideOn;
			break;
		// 用紙とじ代.
		case TYPE_RecoveryPrintBindDirection:
			pc_Dst->c_BindDirection.setBindDirection( pc_Src->c_BindDirection.getBindDirection() );
			pc_Dst->c_BindDirection.setOpenDirection( pc_Src->c_BindDirection.getOpenDirection() );
			pc_Dst->c_BindDirection.setBindWidth( pc_Src->c_BindDirection.getBindWidth() );
			pc_Dst->c_BindDirection.setReduceShiftOn( pc_Src->c_BindDirection.getReduceShiftOn() );
			break;
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); break;
	}
}
