//概要    :コピー用用紙種類を復帰
void PnlComRecoveryCopy_PaperType( APIC_FeedTray* const pc_Dst, TYPE_FeedTray e_FeedTray, TYPE_RecoveryFeedTrayPaperType e_RecoveryFeedTrayPaperType )
{
	if( !pc_Dst ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	TYPC_PaperType* pc_Src = PnlComGetReturnCopy_PaperType();
	if( !pc_Src ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
	switch( e_RecoveryFeedTrayPaperType ) {
		// 用紙種類全体.
		case TYPE_RecoveryFeedTrayPaperTypeAll: pc_Dst->setPaperType( e_FeedTray, *pc_Src ); break;
		// 用紙種類（用紙種類・両面2面目フラグ）.
		case TYPE_RecoveryFeedTrayPaperTypeKind:
		{
			TYPC_PaperType c_PaperTypeKind = pc_Dst->getPaperType( e_FeedTray );
			c_PaperTypeKind.setPaperType( pc_Src->getPaperType() );
			c_PaperTypeKind.setFeed2ndSidedPaper( pc_Src->getFeed2ndSidedPaper() );
			pc_Dst->setPaperType( e_FeedTray, c_PaperTypeKind );
			break;
		}
		// 用紙種類（画像位置指定）.
		case TYPE_RecoveryFeedTrayPaperTypePosition:
		{
			TYPC_PaperType c_PaperTypePosition = pc_Dst->getPaperType( e_FeedTray );
			c_PaperTypePosition.setWidePaperImagePosition( pc_Src->getWidePaperImagePosition() );
			pc_Dst->setPaperType( e_FeedTray, c_PaperTypePosition );
			break;
		}
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); break;
	}
}
