//概要    :オペレーション設定データを保存
void PnlComBackupOperationSet( PCGE_OperationSetting const e_OperationSetting )
{
	APIC_OperationSetting* pc_OperationSetting = PnlComGetOperationSetting();
	switch( e_OperationSetting ) {
		case PCGE_OperationSettingPaperSizeUnfix: {
			for( uchar i = 0; uc_SizeUnfixSizeTrayType > i; ++i ) {
				s_PanelUseOperationSetting.c_AryPaperSizeUnfix01[i] = pc_OperationSetting->getPaperSizeUnfix01( e_AryUnfixSizeTrayType[i] );
				s_PanelUseOperationSetting.c_AryPaperSizeUnfix02[i] = pc_OperationSetting->getPaperSizeUnfix02( e_AryUnfixSizeTrayType[i] );
			}
			break;
		}
		case PCGE_OperationSettingPaperSizeUnfixName: {
			for( uchar j = 0; uc_SizeUnfixSizeTrayType > j; ++j ) {
				if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
					pc_OperationSetting->getPaperSizeUnfix01NameUTF8( s_PanelUseOperationSetting.sc_AryPaperSizeUnfixName01[j], e_AryUnfixSizeTrayType[j], TYPE_CharSetUTF8 );
					pc_OperationSetting->getPaperSizeUnfix02NameUTF8( s_PanelUseOperationSetting.sc_AryPaperSizeUnfixName02[j], e_AryUnfixSizeTrayType[j], TYPE_CharSetUTF8 );
				} else {
					pc_OperationSetting->getPaperSizeUnfix01NameUTF8( s_PanelUseOperationSetting.sc_AryPaperSizeUnfixName01[j], e_AryUnfixSizeTrayType[j], getCharSetForCAPI() );
					pc_OperationSetting->getPaperSizeUnfix02NameUTF8( s_PanelUseOperationSetting.sc_AryPaperSizeUnfixName02[j], e_AryUnfixSizeTrayType[j], getCharSetForCAPI() );
				}	// DonauLastFum【ネットワーク通信文字拡張】【13東阪】2009/04/30 Add.
			}
			break;
		}
		case PCGE_OperationSettingMagMemoryCopy:
			s_PanelUseOperationSetting.c_MagMemory01 = pc_OperationSetting->getMagMemory01();
			s_PanelUseOperationSetting.c_MagMemory02 = pc_OperationSetting->getMagMemory02();
			s_PanelUseOperationSetting.c_MagMemory03 = pc_OperationSetting->getMagMemory03();
			s_PanelUseOperationSetting.c_MagMemorySmall = pc_OperationSetting->getMagMemorySmall();
			break;
		case PCGE_OperationSettingEraseFrameCopy:
			s_PanelUseOperationSetting.sf_EraseFrameAll = pc_OperationSetting->getEraseFrameAll();
			s_PanelUseOperationSetting.sf_EraseFrameTop = pc_OperationSetting->getEraseFrameTop();
			s_PanelUseOperationSetting.sf_EraseFrameLeft = pc_OperationSetting->getEraseFrameLeft();
			s_PanelUseOperationSetting.sf_EraseFrameRight = pc_OperationSetting->getEraseFrameRight();
			s_PanelUseOperationSetting.sf_EraseFrameBottom = pc_OperationSetting->getEraseFrameBottom();
			break;
		case PCGE_OperationSettingMagMemoryScan:
			s_PanelUseOperationSetting.c_MagMemory01Scan = pc_OperationSetting->getMagMemory01Scan();
			s_PanelUseOperationSetting.c_MagMemory02Scan = pc_OperationSetting->getMagMemory02Scan();
			s_PanelUseOperationSetting.c_MagMemory03Scan = pc_OperationSetting->getMagMemory03Scan();
			s_PanelUseOperationSetting.c_MagMemorySmallScan = pc_OperationSetting->getMagMemorySmallScan();
			break;
		case PCGE_OperationSettingEraseFrameScan:
			s_PanelUseOperationSetting.sf_EraseFrameAllScan = pc_OperationSetting->getEraseFrameAllScan();
			s_PanelUseOperationSetting.sf_EraseFrameTopScan = pc_OperationSetting->getEraseFrameTopScan();
			s_PanelUseOperationSetting.sf_EraseFrameLeftScan = pc_OperationSetting->getEraseFrameLeftScan();
			s_PanelUseOperationSetting.sf_EraseFrameRightScan = pc_OperationSetting->getEraseFrameRightScan();
			s_PanelUseOperationSetting.sf_EraseFrameBottomScan = pc_OperationSetting->getEraseFrameBottomScan();
			break;
		case PCGE_OperationSettingCenterCreaseCopy: s_PanelUseOperationSetting.sf_EraseCreaseCopy = pc_OperationSetting->getEraseCrease(); break;
		case PCGE_OperationSettingPaperShiftWidth: s_PanelUseOperationSetting.sf_PaperShiftWidth = pc_OperationSetting->getPaperShiftWidth(); break;
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); break;
	}
}
