//概要    : CC/BCCの自動登録により追加された登録先の数を取得
short PnlComGetEmailSendAddrAddCount(short ss_AddrCnt)
{

	ACSE_CCScanToEmail	sc_CCScanToEmailFunc	= ACSE_CCScanToEmail_Convent;		// 送信先 CC  ScanToE-mail機能設定.
	ACSE_BCCScanToEmail	sc_BCCScanToEmailFunc	= ACSE_BCCScanToEmail_Convent;		// 送信先 BCC ScanToE-mail機能設定.
	short				ss_Ret					= ss_AddrCnt;						// 追加する送信登録件数.

	// 宛先件数が0 の場合はコンフィグ値は確認不要.
	if (0 == ss_AddrCnt){
		return ss_Ret;
	}

	// コンフィグ値読込み
	APIC_AuthCust *pc_AuthCust = APIC_AuthCust::newInstance();
	if (NULL == pc_AuthCust){
		return ss_Ret;
	}
	pc_AuthCust->getCCScanToEmail(&sc_CCScanToEmailFunc);
	pc_AuthCust->getBCCScanToEmail(&sc_BCCScanToEmailFunc);

	// CC/BCCの自動登録により追加された登録先の数の算出.
	if ((ACSE_CCScanToEmail_UserAddress  == sc_CCScanToEmailFunc) ||
		(ACSE_CCScanToEmail_AdminAddress == sc_CCScanToEmailFunc) ){
		ss_Ret++;
	}
	if ((ACSE_BCCScanToEmail_UserAddress  == sc_BCCScanToEmailFunc) ||
		(ACSE_BCCScanToEmail_AdminAddress == sc_BCCScanToEmailFunc) ){
		ss_Ret++;
	}

	return ss_Ret;
}

struct TYPS_PaperAutoDetect {
	Bool          b_On;
	TYPE_FeedTray e_FeedTray;
};
static TYPS_PaperAutoDetect s_AryPaperAutoDetect[] = {
	{ True, TYPE_FeedTrayManual },
	{ True, TYPE_FeedTray1,     },
	{ True, TYPE_FeedTray2,     },
	{ True, TYPE_FeedTray3,     },
	{ True, TYPE_FeedTray4,     },
	{ True, TYPE_FeedTray5,     },
};
const uchar uc_SizeAutoDetect = ( uchar )( sizeof( s_AryPaperAutoDetect ) / sizeof( TYPS_PaperAutoDetect ) );
//概要    :用紙サイズ自動検出設定データを保存
void PnlComBackupPaperSizeAutoDetectOn( APIC_FeedTray* const pc_Src )
{
	if( NULL == pc_Src ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	for( uchar i = 0; uc_SizeAutoDetect > i; ++i ) {
		// 用紙自動検出モード設定データを保存.
		s_AryPaperAutoDetect[i].b_On = pc_Src->getPaperSizeAutoDetectOn( s_AryPaperAutoDetect[i].e_FeedTray );
	}
}
//概要    :用紙サイズ自動検出設定データを復帰
void PnlComRecoveryPaperSizeAutoDetectOn( APIC_FeedTray* const pc_Dst )
{
	if( !pc_Dst ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	for( uchar i = 0; uc_SizeAutoDetect > i; ++i ) {
		// 用紙自動検出モード設定データを復帰.
		pc_Dst->setPaperSizeAutoDetectOn( s_AryPaperAutoDetect[i].e_FeedTray, s_AryPaperAutoDetect[i].b_On );
	}
}

//概要    :フィニッシャ情報、暫定救済情報から、中折り機能の有効状態を判定.
Bool isHalfFoldEnable()
{
	Bool	b_FoldOn = False;
	APIC_PrinterSystem*	pc_PrinterSystem = PnlComGetPrinterSystem();
	APIC_SystemStatus*	pc_SystemStatus = PnlComGetSystemStatus();

	if( NULL == pc_PrinterSystem ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return	False;
	}
	if( NULL == pc_SystemStatus ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return	False;
	}
	if( True != pc_PrinterSystem->isExistFinisher() ) {
		return	False;
	}

	TYPE_FinisherType	e_FinisherType = pc_PrinterSystem->getFinisherType();
	TYPS_FoldFunction	s_FoldFunction = pc_PrinterSystem->getFoldFunction();

// comment 2015/05/05 【HCLT_Thangachamy】【MinervaSBK】【制御構成変更_No.14 & 制御構成変更_No.15】 Adding Finisher support for FS-536 and FS-537.
	if( ( e_FinisherType == TYPE_FinisherTypeFS526 )
	    || ( TYPE_FinisherTypeFS527 == e_FinisherType )
	    || ( TYPE_FinisherTypeFS535 == e_FinisherType )
	    || ( TYPE_FinisherTypeFS534 == e_FinisherType )
	    || ( TYPE_FinisherTypeFS536 == e_FinisherType )
//comment 2018/10/24 HCLT-Jagadeesh [IT6_Eagle] [機器構成変更_No.5] Adding Finisher support for FS-540/ FS-539.
//	    || ( TYPE_FinisherTypeFS537 == e_FinisherType ) )
	    || ( TYPE_FinisherTypeFS537 == e_FinisherType )
	    || ( TYPE_FinisherTypeFS539 == e_FinisherType )
	    || ( TYPE_FinisherTypeFS540 == e_FinisherType ) )
	{
		if( ( True == s_FoldFunction.b_FoldCenterInner )	// 内中折り機能あり.
		    && ( TYPE_TemporaryRescueStatusReset == pc_SystemStatus->getTemporaryRescueUserStatus( TYPE_TemporaryRescueUnitFolder ) ) )	// 「中折り･中とじ･三つ折り」暫定救済なし.
		{
			b_FoldOn = True;	// 中折り有効.
		}
	}
	return	b_FoldOn;
}
