//概要    :紙折りモードの有効状態を判定.
Bool isFoldModeEnable()
{
	// 中折り・中とじ・三つ折り・Ｚ折りの何れかが有効であれば、紙折り有効と判定.
	return	( isHalfFoldEnable() || isCenterStapleFoldEnable() || isTriFoldEnable() || isZFoldEnable() );
}

//概要    : 「折り/とじ」機能の判定.
//戻り値  : PCGE_FoldBindFunction_None					// 「折り/とじ」機能無し.
//		  : PCGE_FoldBindFunction_PaperFoldCenterBind	// 「紙折り/中とじ」.
//		  : PCGE_FoldBindFunction_PaperFold				// 「紙折り」.
//		  : PCGE_FoldBindFunction_CenterBindFold		// 「中とじ/折り」.
//		  : PCGE_FoldBindFunction_CenterBind			// 「中とじ」.
PCGE_FoldBindFunction chkFoldBindFunction()
{
	APIC_PrinterSystem* pc_PrinterSystem = PnlComGetPrinterSystem();
	PCGE_FoldBindFunction e_FoldBindFunction = PCGE_FoldBindFunction_None;	// (初期値)「折り/とじ」機能無し.
//Comment 2016/09/01  【HCLT-Krishna】 【IT5_3.3】【Accurev ID:1003217】Getting the System status from API for Interim relief condition check.
	APIC_SystemStatus*	pc_SystemStatus = PnlComGetSystemStatus();
// comment 2015/05/05 【HCLT_Thangachamy】【MinervaSBK】【制御構成変更_No.14 & 制御構成変更_No.15】 Adding Finisher support for FS-536 and FS-537.
	if( ( ( ( pc_PrinterSystem->getFinisherType() == TYPE_FinisherTypeFS608 )		// FS-608装着.
	        ||( ( pc_PrinterSystem->getFinisherType() == TYPE_FinisherTypeFS526 )		// FS-526装着.
	            &&( pc_PrinterSystem->isExistSaddleUnitOption() == True ) )				// サドルユニット有り.
	        ||( ( pc_PrinterSystem->getFinisherType() == TYPE_FinisherTypeFS527 )		// FS-527装着.
	            &&( pc_PrinterSystem->isExistSaddleUnitOption() == True ) )				// サドルユニット有り.
	        ||( ( TYPE_FinisherTypeFS535 == pc_PrinterSystem->getFinisherType() )		// FS-535装着.
	            &&( True == pc_PrinterSystem->isExistSaddleUnitOption() ) )				// サドルユニット有り.
	        ||( ( TYPE_FinisherTypeFS534 == pc_PrinterSystem->getFinisherType() )		// FS-534装着.
	            &&( True == pc_PrinterSystem->isExistSaddleUnitOption() ) )				// サドルユニット有り.
	        ||( ( TYPE_FinisherTypeFS536 == pc_PrinterSystem->getFinisherType() )		// FS-536装着.
	            &&( True == pc_PrinterSystem->isExistSaddleUnitOption() ) )				// サドルユニット有り.
	        ||( ( TYPE_FinisherTypeFS537 == pc_PrinterSystem->getFinisherType() )		// FS-537装着.
//comment 2018/10/24 HCLT-Jagadeesh [IT6_Eagle] [機器構成変更_No.5] Adding Finisher support for FS-540.
//	            &&( True == pc_PrinterSystem->isExistSaddleUnitOption() ) ) )				// サドルユニット有り.
				&&( True == pc_PrinterSystem->isExistSaddleUnitOption() ) )				// サドルユニット有り.	
	        ||( ( TYPE_FinisherTypeFS539 == pc_PrinterSystem->getFinisherType() )		// FS-537装着.	        	
	            &&( True == pc_PrinterSystem->isExistSaddleUnitOption() ) )				// サドルユニット有り.
	        ||( ( TYPE_FinisherTypeFS540 == pc_PrinterSystem->getFinisherType() )		// FS-537装着.	        	
	            &&( True == pc_PrinterSystem->isExistSaddleUnitOption() ) ) )				// サドルユニット有り.
	      &&( True != ppc_PrinterSystem->getFoldFunction().b_FoldZshaped ) )			// Z折りユニット非装着.
	    ||( ( ( pc_PrinterSystem->getFinisherType() == TYPE_FinisherTypeFS608 )		// FS-608装着.
	          ||( ( ( pc_PrinterSystem->getFinisherType() == TYPE_FinisherTypeFS526 )		// FS-526装着.
	                ||( TYPE_FinisherTypeFS535 == pc_PrinterSystem->getFinisherType() )		// FS-535装着.
//comment 2018/10/24 HCLT-Jagadeesh [IT6_Eagle] [機器構成変更_No.5] Adding Finisher support for FS-540.
	                ||( TYPE_FinisherTypeFS540 == pc_PrinterSystem->getFinisherType() )
	                ||( TYPE_FinisherTypeFS537 == pc_PrinterSystem->getFinisherType() ) )
//Comment 2016/09/01  【HCLT-Krishna】 【IT5_3.3】【Accurev ID:1003217】Adding the condition check for the Saddle Unit not in Interim Relief state.
//	              &&( pc_PrinterSystem->isExistSaddleUnitOption() == True ) ) )				// サドルユニット有り.
	          	&&( ( pc_PrinterSystem->isExistSaddleUnitOption() == True )					// サドルユニット有り.
	          		&&( TYPE_TemporaryRescueStatusReset == pc_SystemStatus->getTemporaryRescueUserStatus( TYPE_TemporaryRescueUnitFolder ) ) ) ) ) // [Half fold/Tri fold/Center stapling] not in Interim Relief.
	        &&( True == ppc_PrinterSystem->getFoldFunction().b_FoldZshaped ) ) )		// Z折りユニット装着.
	{
		e_FoldBindFunction = PCGE_FoldBindFunction_PaperFoldCenterBind;		// 「紙折り/中とじ」を設定.
	}
// comment 2015/05/05 【HCLT_Thangachamy】【MinervaSBK】【制御構成変更_No.15】 Adding Finisher support for FS-537.
	else if( ( ( pc_PrinterSystem->getFinisherType() == TYPE_FinisherTypeFS517 )		// FS-517装着.
	           ||( pc_PrinterSystem->getFinisherType() == TYPE_FinisherTypeFS518 )		// FS-518装着.
	           ||( ( ( pc_PrinterSystem->getFinisherType() == TYPE_FinisherTypeFS526 )		// FS-526装着.
	                 ||( TYPE_FinisherTypeFS535 == pc_PrinterSystem->getFinisherType() )		// FS-535装着. 
//comment 2018/10/24 HCLT-Jagadeesh [IT6_Eagle] [機器構成変更_No.5] Adding Finisher support for FS-540.
//	                 ||( TYPE_FinisherTypeFS537 == pc_PrinterSystem->getFinisherType() ))
	                 ||( TYPE_FinisherTypeFS537 == pc_PrinterSystem->getFinisherType() )
	                 ||( TYPE_FinisherTypeFS540 == pc_PrinterSystem->getFinisherType() ))
//Comment 2016/09/01  【HCLT-Krishna】 【IT5_3.3】【Accurev ID:1003217】Adding the condition check for the Saddle Unit in Interim Relief state.
//	               &&( pc_PrinterSystem->isExistSaddleUnitOption() == False ) ) )			// サドルユニット無し.
	           	&&( ( pc_PrinterSystem->isExistSaddleUnitOption() == False )				// サドルユニット無し.
	           		||( TYPE_TemporaryRescueStatusReset != pc_SystemStatus->getTemporaryRescueUserStatus( TYPE_TemporaryRescueUnitFolder ) ) ) ) )		// [Half fold/Tri fold/Center stapling] in Interim Relief.
	         &&( True == ppc_PrinterSystem->getFoldFunction().b_FoldZshaped ) )			// Z折りユニット装着.
	{
		e_FoldBindFunction = PCGE_FoldBindFunction_PaperFold;				// 「紙折り」を設定.
	}
	else if( pc_PrinterSystem->getFinisherType() == TYPE_FinisherTypeCB )	// CB-FN装着.
	{
		e_FoldBindFunction = PCGE_FoldBindFunction_CenterBindFold;			// 「中とじ/折り」を設定.
	}
	else if( pc_PrinterSystem->getFinisherType() == TYPE_FinisherTypeX3 )	// FN-X3装着.
	{
		e_FoldBindFunction = PCGE_FoldBindFunction_CenterBind;	// 「中とじ」を設定.
	}
	return e_FoldBindFunction;
}
//概要    :メモリ残量設定
//戻り値  :True:有効	False無効
void PnlComSetUiDataMemoryRemain( PNumberField* const pField )
{
	*pField = PnlComGetFreeMemory();
}
//概要    :WebDAV宛先データの有効無効判定
//戻り値  :True:有効	False無効
Bool PnlComIsEnableWebDavData( TYPS_WebDavAddress* const pc_Data )
{
	if( '\0' == pc_Data->sc_HostAddress[0] ) { return False; }
	if( '\0' == pc_Data->sc_Dir[0] ) 		{ return False; }
	if( '\0' == pc_Data->sc_LoginName[0] ) 	{ return False; }
	if( '\0' == pc_Data->sc_Password[0] ) 	{ return False; }
	return True;
}
//===============================================================================================.
// 概要	：残金不足警告表示を「表示しない」が有効か無効かを判定.
// 戻値	：True:「表示しない」が有効  False:「表示しない」が無効.
//===============================================================================================.
Bool PnlComIsEnableOutOfMoneyWarningDisplay()
{
	Bool b_isRet = False;

	if( ( True == onlyPanel.bl_IWSAction ) && ( True == onlyPanel.bl_IWSJobStart ) ) {
		APIC_OutOfMoneyWarningDisplaySetting* p_OutOfMoneyWarningDisplaySetting = APIC_OutOfMoneyWarningDisplaySetting::newInstance();
		if( ( NULL != p_OutOfMoneyWarningDisplaySetting )
		    && ( False == p_OutOfMoneyWarningDisplaySetting->getOutOfMoneyWarningDisplaySetting() ) ) {
			b_isRet = True;
		}
	}

	return b_isRet;
}
//概要    :下地の用紙アイコンを決定する
uchar CP_FinishingIcon::decidePaperIconType( TYPC_Finishing c_Finishing )
{
	uchar uc_Return = PCGD_FinPaperIcon_Normal;					// 通常用紙背景.
	// 紙折りモードを判定.
	switch( c_Finishing.getFoldMode() ) {
		case TYPE_FoldModeCenterOuter:	// 中折り.
		case TYPE_FoldModeCenterInner: uc_Return = PCGD_FinPaperIcon_CenterFold; break;	// 中折り用紙背景.
		case TYPE_FoldModeLetterIn:		// 3つ折り.
		case TYPE_FoldModeLetterOut: uc_Return = PCGD_FinPaperIcon_ThreeFold; break;	// 袋折り用紙背景.
		case TYPE_FoldModeZShaped:	uc_Return = PCGD_FinPaperIcon_ZFold; break;			// Z折り用紙背景.

			break;
		default: break;
	}
	return uc_Return;
}
