Bool CP_FinishingIcon::displayIconThisMode( TYPC_Finishing c_Finishing, TYPC_Nin1 c_Nin1, Bool b_LonlyDisp, Bool b_AutoDisp, Bool b_FinishingGamen, Bool b_isWarning, Bool b_RedetectDir, APIC_Job* pc_Job )
{
	short ss_FinishingType = 0;									// 仕上げパターン(0で初期化).
	b_MmbCreaseDisp = False;									// 折りモード無しで初期化.

	// ステープル暫定救済中.
	if( TYPE_TemporaryRescueStatusSet == ppc_SystemStatus->getTemporaryRescueUserStatus( TYPE_TemporaryRescueUnitStaple )
	    && !( TYPE_StapleModeCenter == c_Finishing.getStapleMode() ) ) {
		c_Finishing.setStapleMode( TYPE_StapleModeNone );
		c_Finishing.setStaplePosition( TYPE_BindDirectionAuto );
		c_Finishing.setStaplePositionAuto( True );
	}
	// PK暫定救済.

	if( True == PnlComIsRescueStatusSetPunch() ) {	// パンチ暫定救済中.// No329852対応.

		c_Finishing.setPunchMode( TYPE_PunchModeNone );
		c_Finishing.setPunchPosition( TYPE_BindDirectionAuto );
		c_Finishing.setPunchPositionAuto( True );
	}

	uchar uc_FinishingIcon = decidePaperIconType( c_Finishing ); 	// アイコンタイプを決定.
	// ステープル位置／パンチ位置を取得.
	TYPE_BindDirection e_PreStaplePosition = c_Finishing.getStaplePosition();
	if( ( True == b_RedetectDir ) && ( NULL != pc_Job ) && ( NULL != pc_Job->getAutoSelect() ) ) {
		e_PreStaplePosition = pc_Job->getAutoSelect()->getCornerStapleAutoModeBindDir();
	}
	const TYPE_BindDirection e_PunchPosition = c_Finishing.getPunchPosition();
	const TYPE_BindDirection e_StaplePosition = ( TYPE_StapleModeCorner == c_Finishing.getStapleMode()
	        && c_Finishing.getStaplePosition() == TYPE_BindDirectionAuto
	        && e_PunchPosition != TYPE_BindDirectionAuto )
	        ? e_PunchPosition : e_PreStaplePosition;
	// パンチ表示ポジションデータ（0：無し、1：左／自動、2：上、3：右）.
	short ss_PunchPos = 0;
	// パンチ表示位置（パターン）を決定.
	switch( e_PunchPosition ) {
		case TYPE_BindDirectionAuto:	ss_PunchPos = ( ( False == b_AutoDisp ) ? 0 : 1 );	break;	// ステープル／自動.
		case TYPE_BindDirectionLeft:	ss_PunchPos = 2;								break;	// ステープル／パンチ位置・左.
		case TYPE_BindDirectionTop:		ss_PunchPos = 3;								break;	// ステープル／パンチ位置・上.
		case TYPE_BindDirectionRight:	ss_PunchPos = 4;								break;	// ステープル／パンチ位置・右.
		default:	if( !( 0 ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }	break;
	}
	// 表示するアイコンを決定
	switch( uc_FinishingIcon ) {
		// 通常用紙背景.
		case PCGD_FinPaperIcon_Normal:
			// コーナー綴じ(1点）.
			if( TYPE_StapleModeCorner == c_Finishing.getStapleMode() ) {
				// ステープル／自動.
				if( TYPE_BindDirectionAuto == e_StaplePosition ) {
					// コーナー1点綴じ自動の最初の値をセット.
					ss_FinishingType = 5;
					ss_PunchPos = 1;
				} else if( ( TYPE_BindDirectionLeft == e_StaplePosition ) || ( TYPE_BindDirectionTop == e_StaplePosition ) ) {
					// ステープル／左.
					// ステープル／上.
					// コーナー1点綴じ左の最初の値をセット.
					ss_FinishingType = 7;
					if( TYPE_BindDirectionLeft == e_PunchPosition ) {
						ss_PunchPos = 1;
					} else if( TYPE_BindDirectionTop == e_PunchPosition ) {
						ss_PunchPos = 2;
					}
				} else if( TYPE_BindDirectionRight == e_StaplePosition ) {
					// ステープル／右.
					// コーナー1点綴じ右の最初の値をセット.
					ss_FinishingType = 10;
					if( TYPE_BindDirectionRight == e_PunchPosition ) {
						ss_PunchPos = 1;
					} else if( TYPE_BindDirectionTop == e_PunchPosition ) {
						ss_PunchPos = 2;
					}
				}
			} else if( TYPE_StapleModeSide == c_Finishing.getStapleMode() ) {
				// サイド綴じ(サイド2点）.
				// ステープル／自動.
				if( ( TYPE_BindDirectionAuto == e_StaplePosition ) && ( TYPE_BindDirectionAuto == e_PunchPosition ) ) {
					// 2点綴じ自動の最初の値をセット.
					ss_FinishingType = 13;
				} else if( TYPE_BindDirectionLeft == e_StaplePosition ) {
					// ステープル／左.
					// 左2点綴じの最初の値をセット.
					ss_FinishingType = 15;
					ss_PunchPos = 1;
				} else if( TYPE_BindDirectionTop == e_StaplePosition ) {
					// ステープル／上.
					// 上2点綴じの最初の値をセット.
					ss_FinishingType = 17;
					ss_PunchPos = 1;
				} else if( TYPE_BindDirectionRight == e_StaplePosition ) {
					// ステープル／右.
					// 右2点綴じの最初の値をセット.
					ss_FinishingType = 19;
					ss_PunchPos = 1;
				}
			} else if( c_Finishing.getStapleMode() == TYPE_StapleModeCenter ) {
				// センターステープル
				ss_FinishingType = 45;
			} else {
				// ステープル無し または センター（ありえない）.
				// ステープル無しの最初の値をセット.
				ss_FinishingType = 0;
			}
			// パンチ位置によるオフセット値を足す.
			if( TYPE_PunchModeNone != c_Finishing.getPunchMode() ) {
				// パンチありであれば、パンチ位置に応じたオフセット値を足す.
				ss_FinishingType = ( short )( ss_FinishingType + ss_PunchPos );
			}
			break;
		// 中折り用紙背景.
		case PCGD_FinPaperIcon_CenterFold:
			// センターステープルあり且つ、折り目消しあり、または折り目消しなしとそれ以外(パンチ設定はありえない).
			if( TYPE_StapleModeCenter == c_Finishing.getStapleMode() ) {	// センターステープルあり.
				if( True == c_Nin1.getBookletCenterErase() ) {
					ss_FinishingType = 45;	// 折り目消しあり.
				} else {
					ss_FinishingType = 46;	// 折り目消しなし.
				}
			} else {	// センターステープルなし.
				ss_FinishingType = 21;
			}
			// 折りモードフラグセット.
			b_MmbCreaseDisp = True;
			break;
		// 3つ折り用紙背景.
		case PCGD_FinPaperIcon_ThreeFold:
			ss_FinishingType = 23;
			// 折りモードフラグセット.
			b_MmbCreaseDisp = True;
			break;
		// Z折り用紙背景.
		case PCGD_FinPaperIcon_ZFold:
			if( TYPE_StapleModeCorner == c_Finishing.getStapleMode() ) {
				// コーナー綴じ(1点）.
				if( TYPE_BindDirectionAuto == e_StaplePosition ) {
					// ステープル／自動.
					// コーナー1点綴じ自動の最初の値をセット.
					ss_FinishingType = 29;
					ss_PunchPos = 1;
				} else if( ( TYPE_BindDirectionLeft == e_StaplePosition ) || ( TYPE_BindDirectionTop == e_StaplePosition ) ) {
					// ステープル／左.
					// ステープル／上.
					// コーナー1点綴じ左の最初の値をセット.
					ss_FinishingType = 31;
					if( TYPE_BindDirectionLeft == e_PunchPosition ) {
						ss_PunchPos = 1;
					} else if( TYPE_BindDirectionTop == e_PunchPosition ) {
						ss_PunchPos = 2;
					}
				} else if( TYPE_BindDirectionRight == e_StaplePosition )	{
					// ステープル／右.
					// コーナー1点綴じ右の最初の値をセット.
					ss_FinishingType = 34;
					if( TYPE_BindDirectionRight == e_PunchPosition ) {
						ss_PunchPos = 1;
					} else if( TYPE_BindDirectionTop == e_PunchPosition ) {
						ss_PunchPos = 2;
					}
				}
			} else if( TYPE_StapleModeSide == c_Finishing.getStapleMode() ) {
				// サイド綴じ(サイド2点）.
				if( ( TYPE_BindDirectionAuto == e_StaplePosition ) && ( TYPE_BindDirectionAuto == e_PunchPosition ) ) {
					// ステープル／自動.
					// 2点綴じ自動の最初の値をセット.
					ss_FinishingType = 37;
				} else if( TYPE_BindDirectionLeft == e_StaplePosition ) {
					// ステープル／左.
					// 左2点綴じの最初の値をセット.
					ss_FinishingType = 39;
					ss_PunchPos = 1;
				} else if( TYPE_BindDirectionTop == e_StaplePosition ) {
					// ステープル／上.
					// 上2点綴じの最初の値をセット.
					ss_FinishingType = 41;
					ss_PunchPos = 1;
				} else if( TYPE_BindDirectionRight == e_StaplePosition ) {
					// ステープル／右.
					// 右2点綴じの最初の値をセット.
					ss_FinishingType = 43;
					ss_PunchPos = 1;
				}
			} else {
				// ステープル無し.
				// ステープル無しの最初の値をセット.
				ss_FinishingType = 24;
			}
			// パンチ位置によるオフセット値を足す.
			if( TYPE_PunchModeNone != c_Finishing.getPunchMode() ) {
				// パンチありであれば、パンチ位置に応じたオフセット値を足す.
				ss_FinishingType = ( short )( ss_FinishingType + ss_PunchPos );
			}
			// 折りモードフラグセット.
			b_MmbCreaseDisp = True;
			break;
		default: break;
	}
	// アイコン非表示.
	Gra_DisplayIcon->showEnable( False );
	// パンチモードと仕向けからパンチタイプを決定しグラフィックテーブルを決める.
	if( TYPE_PunchMode3 == c_Finishing.getPunchMode() ) {
		if( b_isWarning == True ) {
			// 3穴表示.
			if( ( ushort )ss_FinishingType < sizeof( uc_TblFinishingIcon3PointPunch_Warning )/sizeof( uc_TblFinishingIcon3PointPunch_Warning[0] ) ) {
				Gra_DisplayIcon->changeGraphic( uc_TblFinishingIcon3PointPunch_Warning[ss_FinishingType] );
			}
		} else {
			// 3穴表示.
			Gra_DisplayIcon->changeGraphic( uc_TblFinishingIcon3PointPunch[ss_FinishingType] );
		}
	} else if( TYPE_PunchMode4 == c_Finishing.getPunchMode() ) {
		if( b_isWarning == True ) {
			// 4穴表示.
			if( ( ushort )ss_FinishingType < sizeof( uc_TblFinishingIcon4PointPunch_Warning ) / sizeof( uc_TblFinishingIcon4PointPunch_Warning[0] ) ) {
				Gra_DisplayIcon->changeGraphic( uc_TblFinishingIcon4PointPunch_Warning[ss_FinishingType] );
			}
		} else {
			// 4穴表示.
			Gra_DisplayIcon->changeGraphic( uc_TblFinishingIcon4PointPunch[ss_FinishingType] );
		}
	} else {
		if( b_isWarning == True ) {
			// 2穴（およびパンチ無し）表示.
			if( ( sizeof( uc_TblFinishingIcon2PointPunch_Warning ) / sizeof( uchar* ) ) > ( ushort )ss_FinishingType )
			{
				Gra_DisplayIcon->changeGraphic( uc_TblFinishingIcon2PointPunch_Warning[ss_FinishingType] );
			}
			else
			{
				SYSF_logMsg( "CP_FinishingIcon::displayIconThisMode() - uc_TblFinishingIcon2PointPunch_Warning OverRun ERROR. -", 0, 0 , 0 , 0 , 0 , 0 , 0 );
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
				return False;
			}
		} else {
			// 2穴（およびパンチ無し）表示.
			Gra_DisplayIcon->changeGraphic( uc_TblFinishingIcon2PointPunch[ss_FinishingType] );
		}
	}
	// アイコン表示.
	const Bool b_Display = ( ( ( 0 == ss_FinishingType ) && ( False == b_LonlyDisp ) ) ? False : True );
	Gra_DisplayIcon->showEnable( b_Display );
	// 変化したらフラグオン.
	_bl_DisplayChange = False;
	if( uc_MmbPreFinPaperIcon != uc_FinishingIcon ) {
		_bl_DisplayChange = True;
	}
	// 前回データを取り込み.
	uc_MmbPreFinPaperIcon = uc_FinishingIcon;
	return b_Display;
}
//概要    :今のモードでアイコンを表示する
Bool CP_FinishingIcon::displayIconNowMode( APIC_Job* pc_OneJob, Bool b_AutoDisp, Bool b_FinishingGamen )
{
	Bool b_Return = False;
	if( NULL == pc_OneJob ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return ( b_Return ); }
	if( ( PCGE_JobPutOther == sc_JobPutNo ) && ( EP_PNS_PrintStopSingleStep != onlyPanel.ep_PanelStatus ) && ( True == PnlComIsFixedOriginalSize( pc_OneJob ) ) ) {
		// アイコン表示.
		b_Return = CP_FinishingIcon::displayIconThisMode( pc_OneJob->getJobSpec()->pc_Print->c_Finishing, pc_OneJob->getJobSpec()->pc_Print->c_Nin1, False, b_AutoDisp, b_FinishingGamen, False, True, pc_OneJob );
	} else {
		// アイコン表示.
		b_Return = CP_FinishingIcon::displayIconNowMode( pc_OneJob->getJobSpec(), b_AutoDisp, b_FinishingGamen );
	}
	return b_Return;
}
//概要    :今のモードでアイコンを表示する
Bool CP_FinishingIcon::displayIconNowMode( TYPC_JobSpec* c_JobSpec, Bool b_AutoDisp, Bool b_FinishingGamen )
{
	// アイコン表示.
	Bool b_Return = displayIconThisMode( c_JobSpec->pc_Print->c_Finishing, c_JobSpec->pc_Print->c_Nin1,False, b_AutoDisp, b_FinishingGamen );
	return b_Return;
}
