void CP_ImageAdjustIcon::displayIconThisMode( TYPE_ImageAdjust _ec_ImageAdjust )
{
	register short level = 3;
	if( PCGD_ImageAdjustIconType_1 == uc_MmbIconType ) {
		if( True == onlyPanel.bl_isEnlargeDisplayMode ) {
			// 拡大のテーブルはLaplataと共通なので逆になっている
			// 通常の並びと異なるので変換も変える
			switch( _ec_ImageAdjust ) {
				case TYPE_ImageAdjustP09:	// 画質調整レベル・微調＋９・祖調＋３.
				case TYPE_ImageAdjustP08:	// 画質調整レベル・微調＋８.
				case TYPE_ImageAdjustP07: level = 0;	break;	// 画質調整・調整レベル表示（+4）.
				case TYPE_ImageAdjustP06:	// 画質調整レベル・微調＋６・祖調＋２.
				case TYPE_ImageAdjustP05: level = 1;	break;	// 画質調整・調整レベル表示（+3）.
				case TYPE_ImageAdjustP04:	// 画質調整レベル・微調＋４.
				case TYPE_ImageAdjustP03: level = 2;	break;	// 画質調整・調整レベル表示（+2）.
				case TYPE_ImageAdjustP02:	// 画質調整レベル・微調＋２.
				case TYPE_ImageAdjustP01: level = 3;	break;	// 画質調整・調整レベル表示（+1）.
				case TYPE_ImageAdjustStd: level = 4;	break;	// 画質調整・調整レベル表示（0）.
				case TYPE_ImageAdjustM01:	// 画質調整レベル・微調－１.
				case TYPE_ImageAdjustM02: level = 5;	break;	// 画質調整・調整レベル表示（+1）.
				case TYPE_ImageAdjustM03:	// 画質調整レベル・微調－３・祖調－１.
				case TYPE_ImageAdjustM04: level = 6;	break;	// 画質調整・調整レベル表示（-2）.
				case TYPE_ImageAdjustM05:	// 画質調整レベル・微調－５.
				case TYPE_ImageAdjustM06: level = 7;	break;	// 画質調整・調整レベル表示（-3）.
				case TYPE_ImageAdjustM07:	// 画質調整レベル・微調－７.
				case TYPE_ImageAdjustM08:	// 画質調整レベル・微調－８.
				case TYPE_ImageAdjustM09: level = 8;	break;	// 画質調整・調整レベル表示（-4）.
				default:	break;
			}
		} else {
			switch( _ec_ImageAdjust ) {
				case TYPE_ImageAdjustP09:	// 画質調整レベル・微調＋９・祖調＋３.
				case TYPE_ImageAdjustP08:	// 画質調整レベル・微調＋８.
				case TYPE_ImageAdjustP07: level = 8;	break;	// 画質調整・調整レベル表示（+4）.
				case TYPE_ImageAdjustP06:	// 画質調整レベル・微調＋６・祖調＋２.
				case TYPE_ImageAdjustP05: level = 7;	break;	// 画質調整・調整レベル表示（+3）.
				case TYPE_ImageAdjustP04:	// 画質調整レベル・微調＋４.
				case TYPE_ImageAdjustP03: level = 6;	break;	// 画質調整・調整レベル表示（+2）.
				case TYPE_ImageAdjustP02:	// 画質調整レベル・微調＋２.
				case TYPE_ImageAdjustP01: level = 5;	break;	// 画質調整・調整レベル表示（+1）.
				case TYPE_ImageAdjustStd: level = 4;	break;	// 画質調整・調整レベル表示（0）.
				case TYPE_ImageAdjustM01:	// 画質調整レベル・微調－１.
				case TYPE_ImageAdjustM02: level = 3;	break;	// 画質調整・調整レベル表示（+1）.
				case TYPE_ImageAdjustM03:	// 画質調整レベル・微調－３・祖調－１.
				case TYPE_ImageAdjustM04: level = 2;	break;	// 画質調整・調整レベル表示（-2）.
				case TYPE_ImageAdjustM05:	// 画質調整レベル・微調－５.
				case TYPE_ImageAdjustM06: level = 1;	break;	// 画質調整・調整レベル表示（-3）.
				case TYPE_ImageAdjustM07:	// 画質調整レベル・微調－７.
				case TYPE_ImageAdjustM08:	// 画質調整レベル・微調－８.
				case TYPE_ImageAdjustM09: level = 0;	break;	// 画質調整・調整レベル表示（-4）.
				default:	break;
			}
		}
	} else {
		switch( _ec_ImageAdjust ) {
			case TYPE_ImageAdjustP09:	// 画質調整レベル・微調＋９・祖調＋３
			case TYPE_ImageAdjustP08: level = 6;	break;	// 画質調整・調整レベル表示７
			case TYPE_ImageAdjustP07:	// 画質調整レベル・微調＋７
			case TYPE_ImageAdjustP06:	// 画質調整レベル・微調＋６・祖調＋２
			case TYPE_ImageAdjustP05: level = 5;	break;	// 画質調整・調整レベル表示６
			case TYPE_ImageAdjustP04:	// 画質調整レベル・微調＋４
			case TYPE_ImageAdjustP03:	// 画質調整レベル・微調＋３・祖調＋１
			case TYPE_ImageAdjustP02: level = 4;	break;	// 画質調整・調整レベル表示５
			case TYPE_ImageAdjustP01:	// 画質調整レベル・微調＋１
			case TYPE_ImageAdjustStd:	// 画質調整レベル・標準
			case TYPE_ImageAdjustM01: level = 3;	break;	// 画質調整・調整レベル表示４
			case TYPE_ImageAdjustM02:	// 画質調整レベル・微調－２
			case TYPE_ImageAdjustM03:	// 画質調整レベル・微調－３・祖調－１
			case TYPE_ImageAdjustM04: level = 2;	break;	// 画質調整・調整レベル表示３
			case TYPE_ImageAdjustM05:	// 画質調整レベル・微調－５
			case TYPE_ImageAdjustM06:	// 画質調整レベル・微調－６・祖調－２
			case TYPE_ImageAdjustM07: level = 1;	break;	// 画質調整・調整レベル表示２
			case TYPE_ImageAdjustM08:	// 画質調整レベル・微調－８
			case TYPE_ImageAdjustM09: level = 0;	break;	// 画質調整・調整レベル表示１
			default:	break;
		}
	}
	if( True == onlyPanel.bl_isEnlargeDisplayMode ) {
		Gra_DisplayIcon->changeGraphic( uc_AryMonoDensityIconEnlarge[level] );
	} else {
		Gra_DisplayIcon->changeGraphic( ppuc_AryIconTable[uc_MmbIconType][level] );
	}
	Gra_DisplayIcon->showEnable( True );
}
