void CP_BackDensityConfirm::displayIconThisMode( const TYPE_BackDensity e_BackDensity )
{
	if( NULL == Gra_DisplayIcon ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	uchar uc_Level = 0;
	Bool b_Auto = False;
	switch( e_BackDensity ) {
		case TYPE_BackDensityLevelD4:												// 濃い+4.
		case TYPE_BackDensityLevelD3:												// 濃い+3.
		case TYPE_BackDensityLevelD2:		uc_Level = 0;					break;	// 濃い+2.
		case TYPE_BackDensityLevelD1:		uc_Level = 1;					break;	// 濃い+1.
		case TYPE_BackDensityLevelN:		uc_Level = 2;					break;	// 標準.
		case TYPE_BackDensityLevelL1:		uc_Level = 3;					break;	// 薄い-1.
		case TYPE_BackDensityLevelL2:		uc_Level = 4;					break;	// 薄い-2.
		case TYPE_BackDensityLevelL3:		uc_Level = 5;					break;	// 薄い-3.
		case TYPE_BackDensityLevelL4:		uc_Level = 6;					break;	// 薄い-4.
		case TYPE_BackDensityLevelL5:		uc_Level = 7;					break;	// 薄い-5.
		case TYPE_BackDensityLevelL6:		uc_Level = 8;					break;	// 薄い-6.
		case TYPE_BackDensityUnselect:		uc_Level = 9;	b_Auto = True;	break;	// Auto.
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); break;
	}
	// 表示するアイコンテーブルの取得.
	const uchar** puc_AryBackDensityIcon = ( ( PCGD_DensityIconTypeConfirm == uc_MmbIconType ) ? &( uc_AryBackDensityIconConfirm[0] ) : &( uc_AryBackDensityIconBasic[0] ) );
	if( NULL == Txt_MmbDisplayIcon ) {
		// アイコンレベルの切り替え.
		Gra_DisplayIcon->changeGraphic( puc_AryBackDensityIcon[uc_Level] );
	} else {
		if( False == b_Auto ) {
			// アイコンレベルの表示と切り替え.
			Txt_MmbDisplayIcon->showEnable( False );
			Gra_DisplayIcon->changeGraphic( puc_AryBackDensityIcon[uc_Level] );
			Gra_DisplayIcon->showEnable( True );
		} else {
			// オート濃度の表示.
			Gra_DisplayIcon->showEnable( False );
			Txt_MmbDisplayIcon->showEnable( True );
		}
	}
}
