//概要    :用紙サイズをXY入れ替えて設定
void PnlComSetPaperSizeReverse( TYPC_OriginalSize* const cp_OriginSize , TYPC_PaperSize c_size )
{
	if( !cp_OriginSize ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	c_size.c_SizeMM = c_size.c_SizeMM.xyReverse();
	cp_OriginSize->setPaperSize( c_size );
	return;
}
//概要    :用紙サイズをXY入れ替えて取得.
TYPC_PaperSize PnlComGetPaperSizeReverse( TYPC_OriginalSize* const cp_OriginSize )
{
	if( !cp_OriginSize ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		TYPC_PaperSize c_sizeTmp;
		return c_sizeTmp;
	}
	TYPC_PaperSize c_size = cp_OriginSize->getPaperSize();
	c_size.c_SizeMM = c_size.c_SizeMM.xyReverse();
	return c_size;
}
//概要    :用紙サイズをXY入れ替えて取得	(パネル表示に使用).
void PnlComGetReadPaperSizeReverse( TYPC_OriginalSize* const cp_OriginSize, TYPC_PaperSize& c_size )
{
	if( !cp_OriginSize ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		TYPC_PaperSize c_sizeTmp;
		return;
	}
	c_size = cp_OriginSize->getPaperSize();
	c_size.c_SizeMM = c_size.c_SizeMM.xyReverse();
	return;
}
//概要    :用紙、原稿サイズの種類判定処理.
char PnlComJudgePaperSizeKind( TYPC_PaperSize const cPaperSize )
{
	char scPaperSizeKind = PNLCOM_NONESIZE;
	// ワイド.
	if( cPaperSize.b_WideOn ) {
		scPaperSizeKind = PNLCOM_WIDESIZE;
	} else {
		// ワイド以外.
		switch( cPaperSize.e_SizeCode ) {
			case TYPE_SizeCodeUnknown:	scPaperSizeKind = PNLCOM_NONESIZE;	break;
			case TYPE_SizeCodeFlsSef:	scPaperSizeKind = PNLCOM_FLSSIZE;	break;
			case TYPE_SizeCodeSRA3Sef:
			case TYPE_SizeCodeA3Sef:
			case TYPE_SizeCodeA4Sef:
			case TYPE_SizeCodeA4Lef:
			case TYPE_SizeCodeA5Sef:
			case TYPE_SizeCodeA5Lef:
			case TYPE_SizeCodeA6Sef:
			case TYPE_SizeCodeA6Lef:
			case TYPE_SizeCodeB4Sef:
			case TYPE_SizeCodeB5Sef:
			case TYPE_SizeCodeB5Lef:
			case TYPE_SizeCodeB6Sef:
			case TYPE_SizeCodeB6Lef:
			case TYPE_SizeCodeA0x2Sef:
			case TYPE_SizeCodeA0Sef:
			case TYPE_SizeCodeA1Sef:
			case TYPE_SizeCodeA2Sef:
			case TYPE_SizeCodeB0Sef:
			case TYPE_SizeCodeB1Sef:
			case TYPE_SizeCodeB2Sef:
			case TYPE_SizeCodeB3Sef:	scPaperSizeKind = PNLCOM_METRICSIZE;	break;
			case TYPE_SizeCodeLedgerSef:
			case TYPE_SizeCode11x15Sef:
			case TYPE_SizeCode11x14Sef:
			case TYPE_SizeCodeLegalSef:
			case TYPE_SizeCodeLetterSef:
			case TYPE_SizeCodeLetterLef:
			case TYPE_SizeCodeExecutiveSef:
			case TYPE_SizeCodeExecutiveLef:
			case TYPE_SizeCodeInvoiceSef:
			case TYPE_SizeCodeInvoiceLef:
			case TYPE_SizeCode48x64Sef:
			case TYPE_SizeCode36x48Sef:
			case TYPE_SizeCode24x36Sef:
			case TYPE_SizeCode18x24Sef:
			case TYPE_SizeCode44x68Sef:
			case TYPE_SizeCode34x44Sef:
			case TYPE_SizeCode22x34Sef:
			case TYPE_SizeCode17x22Sef:
			case TYPE_SizeCode12x18Sef:
#ifdef DEF_A4_Cus	// A3A4FUM OPS2 Sky後藤(拓) 2015/01/19.
			case TYPE_SizeCodeSpFolioSef:
			case TYPE_SizeCodeGovermentLetterSef:
			case TYPE_SizeCode8x10Sef:
#endif // DEF_A4_Cus	// A3A4FUM OPS2 Sky後藤(拓) 2015/01/19.
				scPaperSizeKind = PNLCOM_INCHSIZE;
				break;
			case TYPE_SizeCodePostcard_JpSef:
			case TYPE_SizeCodePostcard_JpLef:
#ifdef DEF_A4_Cus	// A3A4FUM OPS2 Sky後藤(拓) 2015/01/19.
			case TYPE_SizeCodeDoublePostcard_JpSef:
#endif // DEF_A4_Cus	// A3A4FUM OPS2 Sky後藤(拓) 2015/01/19.
			case TYPE_SizeCodePostcard_EuSef:
			case TYPE_SizeCodePostcard_EuLef:
			case TYPE_SizeCodeIN4x6Sef:
			case TYPE_SizeCodeIN4x6Lef:	scPaperSizeKind = PNLCOM_POSTCARDSIZE;	break;
			case TYPE_SizeCodePhotoESef:
			case TYPE_SizeCodePhotoELef:
			case TYPE_SizeCodePhotoLSef:
			case TYPE_SizeCodePhotoLLef:
			case TYPE_SizeCode9x13Sef:
			case TYPE_SizeCode9x13Lef:
			case TYPE_SizeCode10x15Sef:
			case TYPE_SizeCode10x15Lef:
			case TYPE_SizeCode13x18Sef:
			case TYPE_SizeCode13x18Lef:
			case TYPE_SizeCodeIN3x5Sef:
			case TYPE_SizeCodeIN3x5Lef:
			case TYPE_SizeCodeIN225x325Sef:
			case TYPE_SizeCodeIN225x325Lef:	scPaperSizeKind = PNLCOM_PHOTOSIZE;	break;
			case TYPE_SizeCodeNonStandard:	scPaperSizeKind = PNLCOM_FREESIZE;	break;
			case TYPE_SizeCode8KSef:
			case TYPE_SizeCode16KSef:
			case TYPE_SizeCode16KLef:
#ifdef DEF_A4_Cus	// A3A4FUM OPS2 Sky後藤(拓) 2015/01/19.
			case TYPE_SizeCode32KSef:
#endif // DEF_A4_Cus	// A3A4FUM OPS2 Sky後藤(拓) 2015/01/19.
			case TYPE_SizeCodeEnvelopeB5:
			case TYPE_SizeCodeEnvelopeC5:
			case TYPE_SizeCodeEnvelopeDL:
			case TYPE_SizeCodeEnvelopeCom10:
			case TYPE_SizeCodeEnvelopeMornarch:
				scPaperSizeKind = PNLCOM_816SIZE;
				break;
			default:	LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	break;
		}
	}
	return( scPaperSizeKind );
}
//概要    :JobSpecへカラーを設定
void PnlComSetPnlColor( TYPC_Common* const pc_Common, TYPC_Scan* const pc_Scan, const TYPE_PNL_COLOR e_Color, TYPC_Send* const pc_Send )
{
	if( ( !pc_Common ) || ( !pc_Scan ) ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	const Bool bAuto = ( TYPE_PNL_COLOR_AUTO == e_Color )? True:False;
	const Bool bBin	 = ( TYPE_PNL_COLOR_BIN  == e_Color )? True:False;
	TYPE_ColorMode e_ColorMode;
	switch( e_Color ) {
		case TYPE_PNL_COLOR_AUTO:		e_ColorMode = TYPE_ColorModeUnselect;	break;	//	自動.
		case TYPE_PNL_COLOR_FULLCOLOR:	e_ColorMode = TYPE_ColorModeFullColor;	break;	//	フルカラー.
		case TYPE_PNL_COLOR_GRAY:		e_ColorMode = TYPE_ColorModeBlack;		break;	//	グレースケール.
		case TYPE_PNL_COLOR_BIN:		e_ColorMode = TYPE_ColorModeUnselect;	break;	//	白黒2値.
		default:	LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	return;
	}
	pc_Scan->setAcsOn( bAuto );
	pc_Common->setBinary( bBin );
	pc_Common->setColorMode( e_ColorMode );
	if( pc_Send != NULL ) {
		if( TYPE_FileFormatCompactPdf == pc_Send->c_ComSend.getFileFormat() ) {
			// コンパクトPDFの場合.
// comment 2015/10/30 OPS1 Sky東島 [MinervaSBK][CQ520939].
//			if( TYPE_ColorModeFullColor != e_ColorMode ) {
//				// カラーモードがコンパクトPDF対応のフルカラー以外に変更される場合、.
//				// ファイル形式をPDFに変更する.
			if( True == bBin ) {
				// コンパクトPDFは白黒2値とは両立できないため.
				// ファイル形式をPDFに変更する.
				pc_Send->c_ComSend.setFileFormat( TYPE_FileFormatPdf );
			}
		}
	}
	return;
}
//概要    :JobSpecからカラーを取得.
TYPE_PNL_COLOR PnlComGetPnlColor( TYPC_Common* const pc_Common ,TYPC_Scan* const pc_Scan )
{
	if( ( !pc_Common ) || ( !pc_Scan ) ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return TYPE_PNL_COLOR_AUTO;	// 自動.
	}
	const Bool bAuto = pc_Scan->getAcsOn();
	const Bool bBin  = pc_Common->getBinary();
	const TYPE_ColorMode e_ColorMode = pc_Common->getColorMode();
	TYPE_PNL_COLOR e_Color = TYPE_PNL_COLOR_AUTO;
	//	自動.
	if( bAuto ) {
		//	組み合わせチェック.
		if( TYPE_ColorModeUnselect != e_ColorMode ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
		e_Color = TYPE_PNL_COLOR_AUTO;
	}
	//	白黒2値.
	else if( bBin ) {
		//	組み合わせチェック.
		if( TYPE_ColorModeUnselect != e_ColorMode ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
// comment 2021/4/20 FPT-LinhNV46 [MinervaSSBK][OP_BTS-32525] ADFでA4SEF原稿をセットし、Mopriaでカラーモード：白黒を設定し、Mopria　Scanを実施中時、パネルから実行中履歴の設定内容に「カラー：グレースケール」が表示される.
		return TYPE_PNL_COLOR_BIN;
		//e_Color = TYPE_PNL_COLOR_BIN;
	} else {
		//	組み合わせチェック.
		if( TYPE_ColorModeUnselect == e_ColorMode ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
	}
	switch( e_ColorMode ) {
		case TYPE_ColorModeUnselect:											break;
		case TYPE_ColorModeFullColor:		e_Color = TYPE_PNL_COLOR_FULLCOLOR;	break;	//	フルカラー.
		case TYPE_ColorModeBlack:			e_Color = TYPE_PNL_COLOR_GRAY;		break;	//	グレースケール.
		default:	LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	break;
	}
	return e_Color;
}
//概要    :引数のTYPC_Point<float>がNULLポイントか判定.
Bool PnlComIsPointNull( const TYPC_Point<float> c_pt )
{
	if( ( 0 != c_pt.x ) || ( 0 != c_pt.y ) ) {
		return False;
	}
	return True;
}
//概要    :枠消しで有効な個所数を取得.
//戻り値  : True：有効	False：無効
char PnlComGetEnableFrameEraseCount( TYPC_OriginalErase c_OriginalErase )
{
	uchar uc_Counter = 0;
	if( c_OriginalErase.getTop()    != 0 ) { ++uc_Counter; }
	if( c_OriginalErase.getLeft()   != 0 ) { ++uc_Counter; }
	if( c_OriginalErase.getRight()  != 0 ) { ++uc_Counter; }
	if( c_OriginalErase.getBottom() != 0 ) { ++uc_Counter; }
	return uc_Counter;
}
