//概要    :コピー画面ステータスセットアップセットアップ
void PnlComSetupCopyGamenStatus( APIC_Job* pc_Job )
{
	if( !( NULL != pc_Job ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }
	TYPC_Scan*   pc_Scan   = pc_Job->getJobSpec()->pc_Scan;
	TYPC_Common* pc_Common = pc_Job->getJobSpec()->pc_Common;
	TEXT_ID td_Status = s_EXPAutoColor;
	TEXT_ID td_Color = s_MonoColorRed;
	const Bool b_2ColorOn = PnlComSetColorStr( pc_Common, pc_Scan, &td_Status, &td_Color, True );
	if( True == b_2ColorOn ) {
		// ２色カラー・モノカラー設定時.
		Btx_StatusActCopyColor.changeText( &Txt_ActCopyColorInfo,  td_Status );
		Btx_StatusActCopyColor.changeText( &Txt_ActCopyColorInfo2, td_Color );
		Btx_StatusActCopyColor.showEnableAdd( &Txt_ActCopyColorInfo2, True );
	} else {
		// ２色カラー以外設定時.
		Btx_StatusActCopyColor.showEnableAdd( &Txt_ActCopyColorInfo2, False );
		Btx_StatusActCopyColor.changeText( &Txt_ActCopyColorInfo, td_Status );
	}
	// 用紙ステータスセットアップ表示．
	PnlComSetActPaperStataus( pc_Job, &Tsf_ActCopyPaperInfo,( PSinglePartsGraphic* )&Btx_StatusActCopyPaper );
	// 倍率ステータスセットアップ表示.
	PCGS_SetupMag st_SetupMag;
	st_SetupMag.pc_Btx_MagStatus  = &Btx_StatusActCopyMag;
	st_SetupMag.pc_Num_MagValue   = &Num_ActCopyMagValue;
	st_SetupMag.pc_Ktx_MagTxtX    = &Txt_ActCopyMagZoomX;
	st_SetupMag.pc_Ktx_MagTxtY    = &Txt_ActCopyMagZoomY;
	st_SetupMag.pc_Num_MagValueX  = &Num_ActCopyMagZoomX;
	st_SetupMag.pc_Num_MagValueY  = &Num_ActCopyMagZoomY;
	st_SetupMag.pc_Ktx_MagTxtFix  = &Txt_ActCopyMagInfo;
	st_SetupMag.pc_Ktx_MagTxtAuto = &Txt_ActCopyMagAuto;
	PnlComSetMagStatus( pc_Job, PCGD_MaxMagInput, &st_SetupMag );
	// 片面/両面ステータスセットアップ表示.
	uchar	uc_FaceFrom = 0;
	uchar	uc_FaceTo   = 0;
	uchar	uc_Nin1     = 0;
	PnlComSetFaceStatausStr( pc_Job->getJobSpec(), &Btx_StatusActCopyFace, &Txt_ActCopyFaceInfo, &Txt_ActCopyFaceInfo2, &uc_FaceFrom, &uc_FaceTo, &uc_Nin1 );
}
