//概要    :メンバのデフォルト設定
void PCGC_JobSpecCopyBackup::setDefault()
{
	b_NonDirectInputNumber	= False;	//	部数用ダイレクト入力フラグ.
	b_SortAutoChangeOn		= True;		// ソート/ノンソート自動切換えフラグ.
	b_AssignBoxNumber		= False;	// ボックス番号指定状態.
	b_AssignBoxNumberBackup = False;	// ボックス番号指定状態バックアップ.
	b_MemoryInOnJobStart = False;		// スタート前の分割読込み設定.
	b_AutoStapleOn = True;				// ステープル位置ユーザAuto設定.
	b_AutoPunchOn = True;				// パンチ位置ユーザAuto設定.
	b_StopJobBackupFlg = False;	// ジョブバックアップ管理フラグ.
	b_SettingFirstReflect = False;		// 仕上りプレビュー初回時設定反映フラグ.
	b_ForceMemoryIn = False;			// スタート前の強制連続読込み(仕上りプレビュー以外).
	b_SampleStopMenuCopyDirectInput = False; // コピー部数直接入力フラグ(確認コピー設定変更メニュー用).
	sc_PasswordCopyCount = 0;			// パスワードコピー入力カウント.
	b_PasswordCopyDisp = False;			// パスワードコピー遷移判定フラグ.
}
