			case PNLE_FaxBackupKind_KeybordNonClear1728A:		pc_ScanFaxBack->b_MmbKeybordNonClear1728A	 = bl_OnOff;	break;
			case PNLE_FaxBackupKind_KeybordNonClear1728B:		pc_ScanFaxBack->b_MmbKeybordNonClear1728B	 = bl_OnOff;	break;
			case PNLE_FaxBackupKind_KeybordNonClear1728C:		pc_ScanFaxBack->b_MmbKeybordNonClear1728C	 = bl_OnOff;	break;
			case PNLE_FaxBackupKind_KeybordNonClear1728D:		pc_ScanFaxBack->b_MmbKeybordNonClear1728D	 = bl_OnOff;	break;
			case PNLE_FaxBackupKind_KeybordNonClear1728E:		pc_ScanFaxBack->b_MmbKeybordNonClear1728E	 = bl_OnOff;	break;
			case PNLE_FaxBackupKind_KeybordNonClear440008:		pc_ScanFaxBack->b_MmbKeybordNonClear440008	 = bl_OnOff;	break;
			case PNLE_FaxBackupKind_KeybordNonClear440009:		pc_ScanFaxBack->b_MmbKeybordNonClear440009	 = bl_OnOff;	break;
			case PNLE_FaxBackupKind_KeybordNonClear440010:		pc_ScanFaxBack->b_MmbKeybordNonClear440010	 = bl_OnOff;	break;
			case PNLE_FaxBackupKind_KeybordNonClear1731A:		pc_ScanFaxBack->b_MmbKeybordNonClear1731A	 = bl_OnOff;	break;
			case PNLE_FaxBackupKind_KeybordNonClear1731B:		pc_ScanFaxBack->b_MmbKeybordNonClear1731B	 = bl_OnOff;	break;
			case PNLE_FaxBackupKind_KeybordNonClear1731C:		pc_ScanFaxBack->b_MmbKeybordNonClear1731C	 = bl_OnOff;	break;
			case PNLE_FaxBackupKind_MemoryInOnJobStart:			pc_ScanFaxBack->b_MmbMemoryInOnJobStart	 	 = bl_OnOff;	break;
