		pc_ScanFaxBack->b_MmbKeybordNonClear1728D = False;		// 1728dFAXLDAP検索複合検索姓.
		pc_ScanFaxBack->b_MmbKeybordNonClear1728E = False;		// 1728eFAXLDAP検索複合検索名.
		pc_ScanFaxBack->b_MmbKeybordNonClear440008 = False;		// (440008)FAXLDAP検索複合検索 都市名.
