//概要    :直接入力BOX宛先登録
//備考    :登録不可時はFalse、登録可能時にはTrueを返す。未登録エリアへの登録は*sc_SetIndexに-1を入れること
Bool PnlComSetDirectBoxAddress( const TYPS_BoxAddress s_SetBoxAddress, char* sc_SetIndex )
{
	if( ( -1 != *sc_SetIndex ) && ( ( *sc_SetIndex < 1 ) || ( TYPD_MaxDirectBoxAddress < *sc_SetIndex ) ) ) {
		// 設定範囲以外の値
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	} else if( -1 == *sc_SetIndex ) {
		// 未登録エリアへの登録を行うため、登録可能位置を検索する
		if( -1 == ( *sc_SetIndex = PnlComIsDirectBoxAddress() ) ) {
			return False;  // 登録可能な場所は無い
		}
	}
	// 短縮宛先選択時にファイリングナンバーボックスが.
	// 宛先に選択されていた場合、消去する.
	if( NULL == PnlComGetJobScan() ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	if( True == isOn( CNK_FilingNumber, PnlComGetJobScan() ) ) {
		cancel( CNK_ScanToBox, CNK_Size, PnlComGetJobScan() );	// 直接入力ボックス宛先を削除する.
		cancel( CNK_FilingNumber, CNK_Size, PnlComGetJobScan() );	// ファイリングナンバー設定を解除する.
	}
	TYPC_BroadcastAddress* pc_BroadcastAddress = PnlComGetBroadcastAdress();
	if( NULL == pc_BroadcastAddress ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	// 登録可能.
	TYPC_DirectBoxAddress* pc_DirectBoxAddress = PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageBoxAddress( *sc_SetIndex );
	if( NULL == pc_DirectBoxAddress ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	pc_DirectBoxAddress->setBoxAddress( s_SetBoxAddress );
	pc_DirectBoxAddress->setOn( True );
	// 宛先件数+1
	PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.incrementSelectCount();
	PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend.incrementSelectBoxCount();
	if( *sc_SetIndex > 0 ) {
		pc_BroadcastAddress->setDirectAddress( *sc_SetIndex, TYPE_SendModeBox, True );
	}
	return True;
}
