//概要    :直接入力メール宛先登録(ファクスジョブ用)
Bool PnlComSetDirectEmailAddressFaxJob( const TYPS_MailAddress s_SetMailAddress, char sc_SetIndex )
{
	return PnlComSetDirectEmailAddressFaxJob( s_SetMailAddress, sc_SetIndex, -1 );
}
//概要    :直接入力メール宛先登録(ファクスジョブ用)
Bool PnlComSetDirectEmailAddressFaxJob( const TYPS_MailAddress s_SetMailAddress, char sc_SetIndex, short ss_DigitalID )
{
	TYPC_BroadcastAddress* pc_BroadcastAddress = PnlComGetBroadcastAdress();
	if( NULL == pc_BroadcastAddress ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	if( ( -1 != sc_SetIndex )
	    && ( ( sc_SetIndex < 1 )
	         || ( ( onlyPanel.isSearchDigitalID() == False || onlyPanel.isEquivalentAddressOn() == True ) && ( TYPD_MaxDirectMailAddress < sc_SetIndex ) )
	         || ( ( onlyPanel.isSearchDigitalID() == True || onlyPanel.isEquivalentAddressOn() == True ) && ( TYPD_DIGITAL_ID_FOR_PDF_ENCRYPTION_MAX < sc_SetIndex ) )
	       ) )
	{
		// 設定範囲以外の値
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	} else if( -1 == sc_SetIndex ) {
		// 未登録エリアへの登録を行うため、登録可能位置を検索する
		if( -1 == ( sc_SetIndex = PnlComIsDirectEmailAddressFaxJob() ) ) {
			// 登録可能な場所は無い
			return False;
		}
	}
	TYPC_DirectMailAddress* pc_DirectMailAddress = NULL;
	// デジタルID選択中の場合、または、同時設定（送信先宛先利用）の場合.
	if( True == onlyPanel.isSearchDigitalID() || onlyPanel.isEquivalentAddressOn() == True ) {
		// 登録可能.
		pc_DirectMailAddress = PnlComGetDigitalIDAddressBook()->pageDigitalIDAddress( sc_SetIndex );
		if( !( NULL != pc_DirectMailAddress ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
		pc_DirectMailAddress->setMailAddress( s_SetMailAddress );
		// 登録種別 Emailを登録
		pc_DirectMailAddress->setSendMode( TYPE_SendModeEmail );
		pc_DirectMailAddress->setOn( True );
		PnlComGetDigitalIDAddressBook()->incrementSelectCount( 1 );
	}
	// 宛先選択中の場合、または、同時設定（送信先宛先利用）の場合.
	if( False == onlyPanel.isSearchDigitalID() || onlyPanel.isEquivalentAddressOn() == True ) {
		// 登録可能.
		if( NULL == PnlComGetJobFax() ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return False;
		}
		pc_DirectMailAddress = PnlComGetJobFax()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageMailAddress( sc_SetIndex );
		if( NULL == pc_DirectMailAddress ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return False;
		}
		pc_DirectMailAddress->setMailAddress( s_SetMailAddress );
		// 登録種別 Emailを登録
		pc_DirectMailAddress->setSendMode( TYPE_SendModeEmail );
		pc_DirectMailAddress->setOn( True );
		// 宛先件数+1
		PnlComGetJobFax()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.incrementSelectCount();
	}
	if( sc_SetIndex > 0 ) {
		if( True == onlyPanel.isEquivalentAddressOn() ) {
			PnlComGetBroadcastDigitalIDAddress()->setDirectAddress( sc_SetIndex, TYPE_SendModeEmail, True, ss_DigitalID );
			PnlComGetBroadcastAddressForSend()->setDirectAddress( sc_SetIndex, TYPE_SendModeEmail, True );
		} else if( True == onlyPanel.isSearchDigitalID() ) {
			pc_BroadcastAddress->setDirectAddress( sc_SetIndex, TYPE_SendModeEmail, True, ss_DigitalID );
		} else {
			pc_BroadcastAddress->setDirectAddress( sc_SetIndex, TYPE_SendModeEmail, True );
		}
	}
	return True;
}
// ScanToMe対応.
//概要    :直接入力メール宛先登録(ファクスジョブ用).
Bool PnlComSetDirectEmailAddressFaxJob2( const TYPS_MailAddress s_SetMailAddress, char* psc_SetIndex )
{
	if( NULL == psc_SetIndex ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	TYPC_BroadcastAddress* pc_BroadcastAddress = PnlComGetBroadcastAdress();
	if( NULL == pc_BroadcastAddress ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	char sc_SetIndex = *psc_SetIndex;
	*psc_SetIndex = -1;
	if( ( -1 != sc_SetIndex ) && ( ( sc_SetIndex < 1 ) || ( TYPD_MaxDirectMailAddress < sc_SetIndex ) ) ) {
		// 設定範囲以外の値.
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	} else if( -1 == sc_SetIndex ) {
		// 未登録エリアへの登録を行うため、登録可能位置を検索する.
		if( -1 == ( sc_SetIndex = PnlComIsDirectEmailAddressFaxJob() ) ) {
			// 登録可能な場所は無い.
			return False;
		}
	}
	// 登録可能.
	if( NULL == PnlComGetJobFax() ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	TYPC_DirectMailAddress* pc_DirectMailAddress = PnlComGetJobFax()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageMailAddress( sc_SetIndex );
	if( NULL == pc_DirectMailAddress ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	pc_DirectMailAddress->setMailAddress( s_SetMailAddress );
	// 登録種別 Emailを登録.
	pc_DirectMailAddress->setSendMode( TYPE_SendModeEmail );
	pc_DirectMailAddress->setOn( True );
	// 宛先件数+1.
	PnlComGetJobFax()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.incrementSelectCount();
	*psc_SetIndex = sc_SetIndex;
	if( sc_SetIndex > 0 ) {
		pc_BroadcastAddress->setDirectAddress( sc_SetIndex, TYPE_SendModeEmail, True );
	}
	return True;
}

