//概要    :直接入力メール宛先登録解除(ファクスジョブ用)
//備考    :解除不可時はFalse、解除可能時にはTrueを返す。
Bool PnlComClearDirectEmailAddressFaxJob( char sc_ClearIndex )
{
	TYPC_BroadcastAddress* pc_BroadcastAddress = PnlComGetBroadcastAdress();
	if( NULL == pc_BroadcastAddress ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	if( ( sc_ClearIndex < 1 )
	    || ( ( onlyPanel.isSearchDigitalID() == True || onlyPanel.isEquivalentAddressOn() == True ) && ( TYPD_DIGITAL_ID_FOR_PDF_ENCRYPTION_MAX < sc_ClearIndex ) )
	    || ( ( onlyPanel.isSearchDigitalID() == False || onlyPanel.isEquivalentAddressOn() == True ) && ( TYPD_MaxDirectMailAddress < sc_ClearIndex ) ) )
	{
		// 設定範囲以外の値
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	TYPC_DirectMailAddress* pc_DirectMailAddress = NULL;
	// デジタルID選択中の場合、または、同時設定（送信先宛先利用）の場合.
	if( True == onlyPanel.isSearchDigitalID() || onlyPanel.isEquivalentAddressOn() == True ) {
		// 登録可能 .
		pc_DirectMailAddress = PnlComGetDigitalIDAddressBook()->pageDigitalIDAddress( sc_ClearIndex );
		if( !( NULL != pc_DirectMailAddress ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
		TYPS_MailAddress s_MailAddress;
		memset( s_MailAddress.sc_MailToAddress, '\0', sizeof( s_MailAddress.sc_MailToAddress ) );
		// 宛先をクリア .
		pc_DirectMailAddress->setMailAddress( s_MailAddress );
		// 登録種別 宛先無しを登録 .
		pc_DirectMailAddress->setSendMode( TYPE_SendModeNotSetting );
		pc_DirectMailAddress->setOn( False );
		// 宛先件数-1 .
		PnlComGetDigitalIDAddressBook()->decrementSelectCount( 1 );
		// 同報宛先から削除.
		PnlComGetBroadcastDigitalIDAddress()->setDirectAddress( sc_ClearIndex, TYPE_SendModeEmail, False );
	}
	// 宛先選択中の場合、または、同時設定（送信先宛先利用）の場合.
	if( False == onlyPanel.isSearchDigitalID() || onlyPanel.isEquivalentAddressOn() == True ) {
		// 登録可能 .
		APIC_Job* _pc_FaxJob = PnlComGetJobFax();
		if( NULL == _pc_FaxJob ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return False;
		}
		pc_DirectMailAddress = _pc_FaxJob->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageMailAddress( sc_ClearIndex );
		if( NULL == pc_DirectMailAddress ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return False;
		}
		if( ( char )( sizeof( s_smimeCertTable )/sizeof( s_smimeCertTable[0] ) ) < sc_ClearIndex ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return False;
		}
		// 証明書保存用構造体からも削除.
		s_smimeCertTable[ sc_ClearIndex - 1 ].ss_Index = 0;
		s_smimeCertTable[ sc_ClearIndex - 1 ].ps_LdapSearchResultSmime.ss_x509size = 0;
		memset( s_smimeCertTable[ sc_ClearIndex - 1 ].ps_LdapSearchResultSmime.sc_x509, '\0', sizeof( s_smimeCertTable[ sc_ClearIndex - 1 ].ps_LdapSearchResultSmime.sc_x509 ) );
		TYPS_MailAddress s_MailAddress;
		memset( s_MailAddress.sc_MailToAddress, '\0', sizeof( s_MailAddress.sc_MailToAddress ) );
		// 宛先をクリア .
		pc_DirectMailAddress->setMailAddress( s_MailAddress );
		// IPアドレス登録時 .
		if( pc_DirectMailAddress->getSendMode() == TYPE_SendModeIPAddressFax ) {
			// ポート番号をデフォルトでクリア .
			pc_DirectMailAddress->setIPFaxPortNum( getFaxIPAddressPortNoDefault() );
		}
		// 登録種別 宛先無しを登録 .
		pc_DirectMailAddress->setSendMode( TYPE_SendModeNotSetting );
		pc_DirectMailAddress->setOn( False );
		// 宛先件数-1 .
		_pc_FaxJob->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.decrementSelectCount();
		// 同報宛先から削除.
		PnlComGetBroadcastAddressForSend()->setDirectAddress( sc_ClearIndex, TYPE_SendModeEmail, False );
	}
	return True;
}
//
// 概要    : 直接入力I-FAX宛先登録
// 内容    : 直接入力I-FAX宛先を登録する。
// 戻り値  : 登録不可時はFalse／登録完了時はTrueを返す。
// 引数    : [In] *ps_setIFaxAddress : 登録するI-FAX宛先のポインタ
//         : [In] *s_IfaxSendInfo : I-Fax情報
//         : [In] b_ColorMachine : カラー機情報
//         : [Out]*sc_SetIndex : 登録が成功した場合、登録したインデクス値を返す
//
Bool PnlComSetDirectIFaxAddressFaxJob(
    TYPS_MailAddress*	ps_setIFaxAddress,		// Mail宛先
    TYPS_IfaxSendInfo*	s_IfaxSendInfo,		// I-Fax情報
    Bool				b_ColorMachine,  		// カラー情報
    char*				sc_SetIndex 			// インデクス値
) {
	if( ( -1 != *sc_SetIndex ) && ( ( *sc_SetIndex < 1 ) || ( TYPD_MaxDirectMailAddress < *sc_SetIndex ) ) ) {
		// 設定範囲以外の値
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return ( False );
	}
	else if( -1 == *sc_SetIndex ) { // 未登録エリアへの登録を行うため、登録可能位置を検索する
		if( -1 == ( *sc_SetIndex = PnlComIsDirectEmailAddressFaxJob() ) ) {
			// 登録可能な場所は無い
			return False;
		}
	}

	TYPC_BroadcastAddress* pc_BroadcastAddress = PnlComGetBroadcastAdress();
	if( NULL == pc_BroadcastAddress ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}

	if( NULL == PnlComGetJobScanFax() ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	TYPC_DirectMailAddress* pc_DirectMailAddress = PnlComGetJobScanFax()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageMailAddress( *sc_SetIndex );
	if( NULL == pc_DirectMailAddress ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}

	// I-Fax宛先登録
	pc_DirectMailAddress->setMailAddress( *ps_setIFaxAddress );
	// 登録種別 I-Fax宛先を登録
	pc_DirectMailAddress->setSendMode( TYPE_SendModeIfax );
	// 解像度情報を設定
	pc_DirectMailAddress->setIfaxSendInfo( *s_IfaxSendInfo );
	// カラー情報を設定
	pc_DirectMailAddress->setColorMachine( b_ColorMachine );
	// 登録種別 I-Fax宛先を有効化
	pc_DirectMailAddress->setOn( True );
	// 宛先件数+1
	PnlComGetJobScanFax()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.incrementSelectCount();
	// 同報宛先に登録
	pc_BroadcastAddress->setDirectAddress( *sc_SetIndex, TYPE_SendModeIfax, True );

	return ( True );
}

//
// 概要    : 直接入力IP-FAX宛先登録
// 内容    : 直接入力IP-FAX宛先を登録する。
// 戻り値  : 登録不可時はFalse／登録完了時はTrueを返す。
// 引数    : [In] *ps_setIPFaxAddress : 登録するIP-FAX宛先のポインタ
//         : [In] PortNum : ポート番号
//         : [In] b_ColorMachine : カラー情報
//         : [In] *sc_SetIndex : 登録インデクス値（未登録エリアへの登録は-1を代入してコールする）
//         : [Out]*sc_SetIndex : 登録が成功した場合、登録したインデクス値を返す
//
Bool PnlComSetDirectIPFaxAddressFaxJob(
    TYPS_MailAddress*	ps_setIPFaxAddress,	// IP宛先
    ushort				PortNum,				// ポート番号
    Bool				b_ColorMachine,  		// カラー情報
    char*				sc_SetIndex 			// インデクス値
) {
	if( ( -1 != *sc_SetIndex ) && ( ( *sc_SetIndex < 1 ) || ( TYPD_MaxDirectMailAddress < *sc_SetIndex ) ) ) {
		// 設定範囲以外の値
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return ( False );
	}
	else if( -1 == *sc_SetIndex ) { // 未登録エリアへの登録を行うため、登録可能位置を検索する
		if( -1 == ( *sc_SetIndex = PnlComIsDirectEmailAddressFaxJob() ) ) {
			// 登録可能な場所は無い
			return False;
		}
	}

	TYPC_BroadcastAddress* pc_BroadcastAddress = PnlComGetBroadcastAdress();
	if( NULL == pc_BroadcastAddress ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}

	if( NULL == PnlComGetJobScanFax() ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	TYPC_DirectMailAddress* pc_DirectIPFaxAddress = PnlComGetJobScanFax()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageMailAddress( *sc_SetIndex );
	if( NULL == pc_DirectIPFaxAddress ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}

	// IP-Fax宛先登録
	pc_DirectIPFaxAddress->setMailAddress( *ps_setIPFaxAddress );
	// 登録種別 IP-Fax宛先を登録
	pc_DirectIPFaxAddress->setSendMode( TYPE_SendModeIPAddressFax );
	// カラー機情報を設定
	pc_DirectIPFaxAddress->setColorMachine( b_ColorMachine );
	// ポート番号設定
	pc_DirectIPFaxAddress->setIPFaxPortNum( PortNum );

	// 登録種別 IP-Fax宛先を有効化
	pc_DirectIPFaxAddress->setOn( True );
	// 宛先件数+1
	PnlComGetJobScanFax()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.incrementSelectCount();
	// 同報宛先に登録
	pc_BroadcastAddress->setDirectAddress( *sc_SetIndex, TYPE_SendModeIPAddressFax, True );

	return ( True );
}

//概要    :直接入力IFAX宛先登録解除(ファクスジョブ用)
//備考    :解除不可時はFalse、解除可能時にはTrueを返す。
Bool PnlComClearDirectIFaxAddressFaxJob( char sc_ClearIndex )
{
	// 直接入力宛先を使用時は宛先を削除する.
	TYPC_BroadcastAddress* pc_BroadcastAddress = PnlComGetBroadcastAdress();
	if( NULL == pc_BroadcastAddress ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	if( ( sc_ClearIndex < 1 ) || ( TYPD_MaxDirectMailAddress < sc_ClearIndex ) ) {
		// 設定範囲以外の値
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	// 登録解除
	if( NULL == PnlComGetJobFax() ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	TYPC_DirectMailAddress* pc_DirectMailAddress = PnlComGetJobFax()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageMailAddress( sc_ClearIndex );
	if( NULL == pc_DirectMailAddress ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	// 証明書保存用構造体からも削除.
	s_smimeCertTable[ sc_ClearIndex - 1 ].ss_Index = 0;
	s_smimeCertTable[ sc_ClearIndex - 1 ].ps_LdapSearchResultSmime.ss_x509size = 0;
	memset( s_smimeCertTable[ sc_ClearIndex - 1 ].ps_LdapSearchResultSmime.sc_x509, '\0', sizeof( s_smimeCertTable[ sc_ClearIndex - 1 ].ps_LdapSearchResultSmime.sc_x509 ) );
	TYPS_MailAddress s_MailAddress;
	memset( s_MailAddress.sc_MailToAddress, '\0', sizeof( s_MailAddress.sc_MailToAddress ) );
	// 宛先をクリア
	pc_DirectMailAddress->setMailAddress( s_MailAddress );
	// IPアドレス登録時
	if( pc_DirectMailAddress->getSendMode() == TYPE_SendModeIPAddressFax ) {
		// ポート番号をデフォルトでクリア
		pc_DirectMailAddress->setIPFaxPortNum( getFaxIPAddressPortNoDefault() );
	}
	// 登録種別 宛先無しを登録
	pc_DirectMailAddress->setSendMode( TYPE_SendModeNotSetting );
	pc_DirectMailAddress->setOn( False );
	// 宛先件数-1
	PnlComGetJobFax()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.decrementSelectCount();
	pc_BroadcastAddress->setDirectAddress( sc_ClearIndex, TYPE_SendModeIfax, False );
	pc_DirectMailAddress->setIfaxSendInfo( c_JobControl.getDefaultIfaxPartnerReceptAbility() );

	return True;
}
//概要    :直接入力WebDAV宛先登録解除
Bool PnlComClearDirectWebDavAddress( char sc_ClearIndex )
{
	TYPC_BroadcastAddress* pc_BroadcastAddress = PnlComGetBroadcastAdress();
	if( NULL == pc_BroadcastAddress ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	if( ( sc_ClearIndex < 1 ) || ( TYPD_MaxDirectWebDavAddress < sc_ClearIndex ) ) {
		// 設定範囲以外の値
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	// 登録解除
	if( NULL == PnlComGetJobScan() ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	TYPC_DirectWebDavAddress* pc_DirectWebDavAddress = PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageWebDavAddress( sc_ClearIndex );
	if( NULL == pc_DirectWebDavAddress ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	pc_DirectWebDavAddress->setOn( False );
	// 宛先件数-1
	PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.decrementSelectCount();
	pc_BroadcastAddress->setDirectAddress( sc_ClearIndex, TYPE_SendModeWebDav, False );
	return True;
}
//概要    :設定確認リストクラス：リスト情報作成
void PCGC_ScanSettingList::createListData( EP_CharSet e_CharSet )
{
	if( NULL == PnlComGetJobScan() ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	e_MmbCharSet = e_CharSet;
	ss_MmbMaxCount = 0;
	memset( s_MmbScanSettingList, 0, sizeof( s_MmbScanSettingList ) );
	/*-------------------------------------
		短縮宛先情報生成
	-------------------------------------*/
	short ss_MaxEntryCount = APIC_ShorteningAddress::getMaxShorteningAddress();
	// 短縮選択数の計算
	for( short m = 1; m <= ss_MaxEntryCount; m++ ) {
		if( True == PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend.getShorteningAddress( m ) ) {
			// 選択されている短縮を発見
			s_MmbScanSettingList[ss_MmbMaxCount].e_Type  = TYPE_ScanSettingListTypeShortening;
			s_MmbScanSettingList[ss_MmbMaxCount].ss_Page = m;
			s_MmbScanSettingList[ss_MmbMaxCount].b_On    = True;
			ss_MmbMaxCount++;
		}
	}
	/*-------------------------------------
		直接入力：FTP情報生成
	-------------------------------------*/
	for( char j = 1; j <= TYPD_MaxDirectFtpAddress; j++ ) {
		// C_APIからデータを取得する
		TYPC_DirectFtpAddress* pc_DirectFtpAddress = PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageFtpAddress( j );
		if( !( NULL != pc_DirectFtpAddress ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
		if( True == pc_DirectFtpAddress->getOn() ) {
			// 選択されている直接入力宛先を発見
			s_MmbScanSettingList[ss_MmbMaxCount].e_Type  = TYPE_ScanSettingListTypeFtp;
			s_MmbScanSettingList[ss_MmbMaxCount].ss_Page = j;
			s_MmbScanSettingList[ss_MmbMaxCount].b_On    = True;
			ss_MmbMaxCount++;
		}
	}
	/*-------------------------------------
		直接入力：SMB情報生成
	-------------------------------------*/
	for( char k = 1; k <= TYPD_MaxDirectSmbAddress; k++ ) {
		// C_APIからデータを取得する
		TYPC_DirectSmbAddress* pc_DirectSmbAddress = PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageSmbAddress( k );
		if( !( NULL != pc_DirectSmbAddress ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
		if( True == pc_DirectSmbAddress->getOn() ) {
			// 選択されている直接入力宛先を発見
			s_MmbScanSettingList[ss_MmbMaxCount].e_Type  = TYPE_ScanSettingListTypeSmb;
			s_MmbScanSettingList[ss_MmbMaxCount].ss_Page = k;
			s_MmbScanSettingList[ss_MmbMaxCount].b_On    = True;
			ss_MmbMaxCount++;
		}
	}
	/*-------------------------------------
		直接入力：BOX情報生成
	-------------------------------------*/
	for( char l = 1; l <= TYPD_MaxDirectBoxAddress; l++ ) {
		// C_APIからデータを取得する
		TYPC_DirectBoxAddress* pc_DirectBoxAddress = PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageBoxAddress( l );
		if( !( NULL != pc_DirectBoxAddress ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
		if( True == pc_DirectBoxAddress->getOn() ) {
			// 選択されている直接入力宛先を発見
			s_MmbScanSettingList[ss_MmbMaxCount].e_Type  = TYPE_ScanSettingListTypeBox;
			s_MmbScanSettingList[ss_MmbMaxCount].ss_Page = l;
			s_MmbScanSettingList[ss_MmbMaxCount].b_On    = True;
			ss_MmbMaxCount++;
		}
	}
	/*-------------------------------------
		直接入力：E-Mail情報生成
	-------------------------------------*/
	for( char i = 1; i <= TYPD_MaxDirectMailAddress; i++ ) {
		// C_APIからデータを取得する
		TYPC_DirectMailAddress* pc_DirectMailAddress = PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageMailAddress( i );
		if( !( NULL != pc_DirectMailAddress ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
		if( True == pc_DirectMailAddress->getOn() ) {
			// 選択されている直接入力宛先を発見
			s_MmbScanSettingList[ss_MmbMaxCount].e_Type  = TYPE_ScanSettingListTypeMail;
			s_MmbScanSettingList[ss_MmbMaxCount].ss_Page = i;
			s_MmbScanSettingList[ss_MmbMaxCount].b_On    = True;
			ss_MmbMaxCount++;;
		}
	}
	/*-------------------------------------
		直接入力：WebDAV情報生成
	-------------------------------------*/
	for( char n = 1; n <= TYPD_MaxDirectFtpAddress; n++ ) {
		// C_APIからデータを取得する
		TYPC_DirectWebDavAddress* pc_DirectWebDavAddress = PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageWebDavAddress( n );
		if( !( NULL != pc_DirectWebDavAddress ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
		if( True == pc_DirectWebDavAddress->getOn() ) {
			// 選択されている直接入力宛先を発見
			s_MmbScanSettingList[ss_MmbMaxCount].e_Type  = TYPE_ScanSettingListTypeWebDav;
			s_MmbScanSettingList[ss_MmbMaxCount].ss_Page = n;
			s_MmbScanSettingList[ss_MmbMaxCount].b_On    = True;
			ss_MmbMaxCount++;
		}
	}
}
//概要    :設定確認リストクラス：リスト総数取得
const short PCGC_ScanSettingList::getMaxListCount()
{
	return	ss_MmbMaxCount;
}
//概要    :設定確認リストクラス：種別取得
const short PCGC_ScanSettingList::getType( short ss_Index )
{
	if( True == convListData( ss_Index ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
	return s_MmbScanSettingListInfo.puc_Type;
}
