//概要    :設定確認リストクラス：左エリア同報宛先表示用文字列取得
const char* PCGC_ScanSettingList::getLeftAddress( short ss_Index )
{
	if( True == convListData( ss_Index ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
	//短縮宛先名が入っているのなら.
	if( 0 < strlen( s_MmbScanSettingListInfo.sc_Name ) ) {
		return s_MmbScanSettingListInfo.sc_Name;
	} else {
		// 短縮宛先名が入っていないのならば(ダイレクトもしくは短縮宛先の登録名無し).
		return s_MmbScanSettingListInfo.sc_Address;
	}
}
//概要    :設定確認リストクラス：リスト内情報変換
Bool PCGC_ScanSettingList::convListData( short ss_Index )
{
	if( 0 >= ss_MmbMaxCount ) {
		// 登録されているものが存在しないならば何もしない
		return False;
	}
	if( ( 1 > ss_Index ) || ( ss_MmbMaxCount < ss_Index ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }		// 範囲外ならばアサート
	// リストインデックス位置を取得
	PCGS_ScanSettingList* ps_ScanSettingList = &s_MmbScanSettingList[ss_Index - 1];
	APIC_ShorteningAddress*	pc_ShorteningAddress;
	TYPC_DirectMailAddress*	pc_DirectMailAddress;
	TYPC_DirectFtpAddress*	pc_DirectFtpAddress;
	TYPC_DirectSmbAddress*	pc_DirectSmbAddress;
	TYPC_DirectBoxAddress*	pc_DirectBoxAddress;
	TYPC_DirectWebDavAddress*	pc_DirectWebDavAddress;
	// 保持領域の初期化
	s_MmbScanSettingListInfo.puc_Type = NULL;
	memset( s_MmbScanSettingListInfo.sc_Name, 0, sizeof( s_MmbScanSettingListInfo.sc_Name ) );
	memset( s_MmbScanSettingListInfo.sc_Address, 0, sizeof( s_MmbScanSettingListInfo.sc_Address ) );
	if( NULL == PnlComGetJobScan() ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	// 個々の情報をメンバ変数へ設定
	switch( ps_ScanSettingList->e_Type ) {
		case TYPE_ScanSettingListTypeShortening:
			/*-------------------------------------
				短縮
			-------------------------------------*/
			pc_ShorteningAddress = APIC_ShorteningAddress::newInstance( ps_ScanSettingList->ss_Page );
			if( NULL == pc_ShorteningAddress ) {
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
				return False;				// 静的解析 2012/09/04 第一OPS 酒井(健).
			}
			// 名称の設定
			if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
				pc_ShorteningAddress->getAddressNameUTF8( s_MmbScanSettingListInfo.sc_Name, TYPE_CharSetUTF8 );
			} else {
				pc_ShorteningAddress->getAddressNameUTF8( s_MmbScanSettingListInfo.sc_Name, getCharSetForCAPI() );
			} // DonauLastFum【ネットワーク通信文字拡張】【13東阪】2009/04/30 Add.
			if( TYPE_SendModeEmail == pc_ShorteningAddress->getSendMode() ) {
				// メールが登録されている
				setMailAddress( pc_ShorteningAddress->getMailAddress() );
			} else if( TYPE_SendModeFtp == pc_ShorteningAddress->getSendMode() ) {
				// FTPが登録されている
				if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
					setFtpAddress( pc_ShorteningAddress->getFtpAddress( TYPE_CharSetUTF8 ) );
				} else {
					setFtpAddress( pc_ShorteningAddress->getFtpAddress( getCharSetForCAPI() ) );
				} // DonauLastFum【ネットワーク通信文字拡張】【13東阪】2009/04/30 Add.
			} else if( TYPE_SendModeSmb == pc_ShorteningAddress->getSendMode() ) {
				// SMBが登録されている
				if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
					setSmbAddress( pc_ShorteningAddress->getSmbAddress( TYPE_CharSetUTF8 ) );
				} else {
					setSmbAddress( pc_ShorteningAddress->getSmbAddress( getCharSetForCAPI() ) );
				} // DonauLastFum【ネットワーク通信文字拡張】【13東阪】2009/04/30 Add.
			} else if( TYPE_SendModeBox == pc_ShorteningAddress->getSendMode() ) {
				// BOXが登録されている
				setBoxAddress( pc_ShorteningAddress->getBoxAddress() );
			}
			else if( TYPE_SendModeWebDav == pc_ShorteningAddress->getSendMode() ) {
				// WebDavが登録されている
				if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
					setWebDavAddress( pc_ShorteningAddress->getWebDavAddressUTF8( TYPE_CharSetUTF8 ) );
				} else {
					setWebDavAddress( pc_ShorteningAddress->getWebDavAddressUTF8( getCharSetForCAPI() ) );
				} // DonauLastFum【ネットワーク通信文字拡張】【13東阪】2009/04/30 Add.
			} else {
				// FAXその他の登録：スキャンでは未対応
				;
			}
			break;
		case TYPE_ScanSettingListTypeMail:
			/*-------------------------------------
				直接入力：メール
			-------------------------------------*/
			// 取得時にデジタルID検索中か判断し、検索中であれば証明書用の同報宛先管理クラスのポインタを返す.
			pc_DirectMailAddress = PnlComGetDirectMailAddress( &PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend, ps_ScanSettingList->ss_Page );
			if( !( NULL != pc_DirectMailAddress ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
			// メールが登録されている
			setMailAddress( pc_DirectMailAddress->getMailAddress() );
			break;
		case TYPE_ScanSettingListTypeFtp:
			/*-------------------------------------
				直接入力：FTP
			-------------------------------------*/
			pc_DirectFtpAddress = PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageFtpAddress( ps_ScanSettingList->ss_Page );
			if( !( NULL != pc_DirectFtpAddress ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
			// FTPが登録されている
			if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
				setFtpAddress( pc_DirectFtpAddress->getFtpAddress( TYPE_CharSetUTF8 ) );
			} else {
				setFtpAddress( pc_DirectFtpAddress->getFtpAddress( getCharSetForCAPI() ) );
			}

			break;
		case TYPE_ScanSettingListTypeSmb:
			/*-------------------------------------
				直接入力：SMB
			-------------------------------------*/
			pc_DirectSmbAddress = PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageSmbAddress( ps_ScanSettingList->ss_Page );
			if( !( NULL != pc_DirectSmbAddress ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
			// SMBが登録されている
			if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
				setSmbAddress( pc_DirectSmbAddress->getSmbAddress( TYPE_CharSetUTF8 ) );
			} else {
				setSmbAddress( pc_DirectSmbAddress->getSmbAddress( getCharSetForCAPI() ) );		// 2008/05/20 CQ302084 豊島：UTF8対応.
			} // DonauLastFum【ネットワーク通信文字拡張】【13東阪】2009/04/30 Add.
			break;
		case TYPE_ScanSettingListTypeBox:
			/*-------------------------------------
				直接入力：BOX
			-------------------------------------*/
			pc_DirectBoxAddress = PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageBoxAddress( ps_ScanSettingList->ss_Page );
			if( !( NULL != pc_DirectBoxAddress ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
			// BOXが登録されている
			setBoxAddress( pc_DirectBoxAddress->getBoxAddress() );
			break;
		case TYPE_ScanSettingListTypeWebDav:
			/*-------------------------------------
				直接入力：WebDAV
			-------------------------------------*/
			pc_DirectWebDavAddress = PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageWebDavAddress( ps_ScanSettingList->ss_Page );
			if( !( NULL != pc_DirectWebDavAddress ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
			// WebDavが登録されている
			if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
				setWebDavAddress( pc_DirectWebDavAddress->getWebDavAddressUTF8( TYPE_CharSetUTF8 ) );
			} else {
				setWebDavAddress( pc_DirectWebDavAddress->getWebDavAddressUTF8( getCharSetForCAPI() ) );
			} // DonauLastFum【ネットワーク通信文字拡張】【13東阪】2009/04/30 Add.
			break;
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
	}
	return False;
}
//概要    :設定確認リストクラス：メール宛先設定
void PCGC_ScanSettingList::setMailAddress( TYPS_MailAddress s_MailAddress )
{
	// 種別の設定
	s_MmbScanSettingListInfo.e_SendMode  = TYPE_SendModeEmail;
	s_MmbScanSettingListInfo.puc_Type = s_SendEMail;
	// 宛先の設定
	s_MmbScanSettingListInfo.s_MailAddress = s_MailAddress;
	getSelectString( TYPD_MaxMailAddress, ( char* )s_MailAddress.sc_MailToAddress, ( char* )s_MmbScanSettingListInfo.sc_Address, PCGD_ScanSettingAddressStartPoint, e_MmbCharSet );
}
//概要    :設定確認リストクラス：FTP宛先設定
void PCGC_ScanSettingList::setFtpAddress( TYPS_FtpAddress s_FtpAddress )
{
	// 種別の設定
	s_MmbScanSettingListInfo.e_SendMode  = TYPE_SendModeFtp;
	s_MmbScanSettingListInfo.puc_Type = s_KEYFileSendFTP;
	// 宛先の設定
	s_MmbScanSettingListInfo.s_FtpAddress = s_FtpAddress;
	char sc_Address[TYPD_MaxMailAddress+1];
	PnlComJointAddress( s_FtpAddress.sc_HostAddress, s_FtpAddress.sc_Dir, sc_Address );
	getSelectString( TYPD_MaxMailAddress, ( char* )sc_Address, ( char* )s_MmbScanSettingListInfo.sc_Address, PCGD_ScanSettingAddressStartPoint, e_MmbCharSet );
}
//概要    :設定確認リストクラス：SMB宛先設定
void PCGC_ScanSettingList::setSmbAddress( TYPS_SmbAddress s_SmbAddress )
{
	// 種別の設定
	s_MmbScanSettingListInfo.e_SendMode  = TYPE_SendModeSmb;
	s_MmbScanSettingListInfo.puc_Type = s_KEYFileSendSMB;
	// 宛先の設定
	s_MmbScanSettingListInfo.s_SmbAddress = s_SmbAddress;
	char sc_Address[TYPD_MaxMailAddress+1];
	memset( sc_Address, 0, sizeof( sc_Address ) );
// comment 2016/12/19 MSE岡田 [IT5_3.4][xxxxxxx] SMB宛先のホスト名とディレクトリパスを結合する処理を共通関数で行うように修正する.
//	PnlComJointAddress( s_SmbAddress.sc_HostAddress, /*sc_ConvertDir*/s_SmbAddress.sc_Dir, sc_Address );
	PnlComJointAddressForSMB( s_SmbAddress.sc_HostAddress, s_SmbAddress.sc_Dir, sc_Address, sizeof( sc_Address ) );
	getSelectString( TYPD_MaxMailAddress, ( char* )sc_Address, ( char* )s_MmbScanSettingListInfo.sc_Address, PCGD_ScanSettingAddressStartPoint, e_MmbCharSet );
}
//概要    :設定確認リストクラス：BOX宛先設定
void PCGC_ScanSettingList::setBoxAddress( TYPS_BoxAddress s_BoxAddress )
{
	// 種別の設定
	s_MmbScanSettingListInfo.e_SendMode  = TYPE_SendModeBox;
	s_MmbScanSettingListInfo.puc_Type = s_Box;
	// 宛先の設定
	s_MmbScanSettingListInfo.s_BoxAddress = s_BoxAddress;
	// ボックス番号の設定.
	PanelLog( PNLD_LogKind_BoxSend, "setBoxId: P1[%d]", s_BoxAddress.sl_BoxNo, 0, 0, 0, 0, 0 );
// Commment 2017/09/22 HCL_Venkataramesh [IT5_4.2][RQ-686][WP689] setBoxId support for Network2 user.
//	cp_DocList->setBoxId( s_BoxAddress.sl_BoxNo );
	PNLC_NetworkLan::getInstance()->setBoxIdPNL( cp_DocList, s_BoxAddress.sl_BoxNo );
	// ボックス情報の取得（この時点でCommonAPI用文字列をパネル用に変換）.
	APIC_BoxInfo c_BoxInfo;
	if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
		PanelLog( PNLD_LogKind_BoxSend, "getBoxInfo P1[%p] P2[%p] P3[%d]", NULL, &c_BoxInfo, -1, 0, 0, 0 );
		cp_DocList->getBoxInfo( NULL, &c_BoxInfo, LIBE_CharSetDefault );
	} else {
		PanelLog( PNLD_LogKind_BoxSend, "getBoxInfo P1[%p] P2[%p] P3[%d]", NULL, &c_BoxInfo, getCharSetForCAPI(), 0, 0, 0 );
		cp_DocList->getBoxInfo( NULL, &c_BoxInfo, ( LIBE_CharSet )getCharSetForCAPI() );
	}
	// ボックス名保存用バッファ.
	char sc_AryBoxName[sizeof( c_BoxInfo.sc_BoxName )];
	memset( sc_AryBoxName, '\0', sizeof( sc_AryBoxName ) );
	// ボックス名をコピー.
	strcpy( sc_AryBoxName, c_BoxInfo.sc_BoxName );
	// ボックス名が未登録の場合.
	if( 0 == strlen( sc_AryBoxName ) ) {
		// ボックス番号を取得.
		sprintf( sc_AryBoxName,"%09d", s_BoxAddress.sl_BoxNo );
	}
	getSelectString( TYPD_MaxMailAddress, ( char* )sc_AryBoxName, ( char* )s_MmbScanSettingListInfo.sc_Address, PCGD_ScanSettingAddressStartPoint, e_MmbCharSet );
}
//概要    :設定確認リストクラス：WebDAV宛先設定
