//概要    :設定確認リストクラス：短縮登録可能領域の取得
const short PCGC_ScanSettingList::getEntryPositionShorteningAddress( APIC_ShorteningAddress** pc_ShorteningAddress )
{
	// 入力値のチェック
	if( NULL == pc_ShorteningAddress ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return -1;
	}
	// 短縮登録最大数取得
	short ss_MaxEntryCount = APIC_ShorteningAddress::getMaxShorteningAddress();
	// 短縮選択数の計算
//Comment 2017/09/04 [HCL-Suganya] [IT5 4.2][RQ-686] [WP97]Multiple Network support.
	TYPE_NetworkSpecific e_NetworkSpecific = PNLC_NetworkLan::getInstance()->getLine();
	for( short i = 1; i <= ss_MaxEntryCount; i++ ) {
//Comment 2017/09/04 [HCL-Suganya] [IT5 4.2][RQ-686] [WP97]Multiple Network support.
//		*pc_ShorteningAddress = APIC_ShorteningAddress::newInstance( i );
		*pc_ShorteningAddress = APIC_ShorteningAddress::newInstance( i , e_NetworkSpecific );
// comment 2018/01/17【HCLT-Jagadeesh】【IT5_4.2】Kloc work Changes ID:394710 【NPD.FUNC.MUST】.
		if( ( NULL != *pc_ShorteningAddress ) && ( False == ( *pc_ShorteningAddress )->getRegistration() ) ) {
			// 登録可能個所を発見
			return i;
		}
	}
	// 登録可能な位置が見つからなかった
	return -1;
}
