//概要    :設定確認リストクラス：リスト情報削除
//備考    :正確には選択されている個所の登録を解除するだけである
void PCGC_ScanSettingList::deleteListData( short ss_Index )
{
// comment 2017/01/24 [HCLT_Joylin]Accurev ID:1010037 Kloc work Changes ID:166241 [NPD.FUNC.MUST] NULL Check is added.
//	if( NULL == PnlComGetJobScan() ) {
//		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
//		return;
//	}
	APIC_Job* pc_ScanFaxJob = PnlComGetJobScan();
	if ( NULL == pc_ScanFaxJob ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
        return;
	}
	TYPC_JobSpec* pc_JobSpec = pc_ScanFaxJob->getJobSpec();
    if ( NULL == pc_JobSpec ) {
         LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
         return;
     }
	TYPC_Send* pc_Send = pc_JobSpec->pc_Send;
    if ( NULL == pc_Send ) {
         LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
         return;
     }
	PCGS_ScanSettingList* ps_ScanSettingList = &s_MmbScanSettingList[ss_Index - 1];
	switch( ps_ScanSettingList->e_Type ) {
		case TYPE_ScanSettingListTypeShortening:
			/*-------------------------------------
				短縮
			-------------------------------------*/
// comment 2017/01/24 [HCLT_Joylin]Accurev ID:1010037 Kloc work Changes ID:166241 [NPD.FUNC.MUST] NULL Check is added.
//			PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend.setShorteningAddress( ps_ScanSettingList->ss_Page, False );
			pc_Send->c_ComSend.setShorteningAddress( ps_ScanSettingList->ss_Page, False );
			// 登録状態を解除する
			ps_ScanSettingList->b_On = False;
			// 登録数-1
// comment 2017/01/24 [HCLT_Joylin]Accurev ID:1010037 Kloc work Changes ID:166241 [NPD.FUNC.MUST] NULL Check is added.
//			PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend.decrementSelecShorteningAddressCount();
			pc_Send->c_ComSend.decrementSelecShorteningAddressCount();
			break;
		case TYPE_ScanSettingListTypeTempSend:
			/*-------------------------------------
				一時配信
			-------------------------------------*/
// comment 2017/01/24 [HCLT_Joylin]Accurev ID:1010037 Kloc work Changes ID:166241 [NPD.FUNC.MUST] NULL Check is added.
//			PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend.setTempSendNo( TYPD_NotSetting );
			pc_Send->c_ComSend.setTempSendNo( TYPD_NotSetting );
			// 登録状態を解除する
			ps_ScanSettingList->b_On = False;
			// 登録数-1
// comment 2017/01/24 [HCLT_Joylin]Accurev ID:1010037 Kloc work Changes ID:166241 [NPD.FUNC.MUST] NULL Check is added.
//			PnlComGetJobScan()->getJobSpec()->pc_Send->c_ComSend.decrementSelecShorteningAddressCount();
			pc_Send->c_ComSend.decrementSelecShorteningAddressCount();
			break;
		case TYPE_ScanSettingListTypeMail:
			/*-------------------------------------
				直接入力：メール
			-------------------------------------*/
			// 登録状態を解除する
			PnlComClearDirectEmailAddress( ( char )ps_ScanSettingList->ss_Page );
			break;
		case TYPE_ScanSettingListTypeFtp:
			/*-------------------------------------
				直接入力：FTP
			-------------------------------------*/
			// 登録状態を解除する
			PnlComClearDirectFtpAddress( ( char )ps_ScanSettingList->ss_Page );
			break;
		case TYPE_ScanSettingListTypeSmb:
			/*-------------------------------------
				直接入力：SMB
			-------------------------------------*/
			// 登録状態を解除する
			PnlComClearDirectSmbAddress( ( char )ps_ScanSettingList->ss_Page );
			break;
		case TYPE_ScanSettingListTypeBox:
			/*-------------------------------------
				直接入力：BOX
			-------------------------------------*/
			// 登録状態を解除する
			PnlComClearDirectBoxAddress( ( char )ps_ScanSettingList->ss_Page );
			break;
		case TYPE_ScanSettingListTypeWebDav:
			/*-------------------------------------
				直接入力：WebDav
			-------------------------------------*/
			// 登録状態を解除する
			PnlComClearDirectWebDavAddress( ( char )ps_ScanSettingList->ss_Page );
			break;
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
	}
}
