APIC_TrackManager*	PnlComGetTrackManager()	// 部門管理（ＡＰＩ）
{
// comment 2022/07/27 Sky中野 [IT6_2.2MR3][OP_BTS-38572].
//	if( !( cp_TrackManager ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
	if( NULL == cp_TrackManager ) {
		// NULLの場合はインスタンスを取得しなおす.
		ExpPanelLog( PNLD_ExpLogKind_AlwaysLogOut, "[PnlComGetTrackManager] Call APIC_TrackManager::newInstance()", 0, 0, 0, 0, 0, 0 );
		cp_TrackManager = APIC_TrackManager::newInstance();
		if( NULL == cp_TrackManager ) {
			// 再取得後もNULLの場合は、エラーログを出力.
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		}
	}
	return cp_TrackManager;
}
