// 文字列更新処理.
// 引数 char *psc_DstBuf 操作対象文字列バッファ char *psc_InputStr 入力文字列 char sc_MaxRange 1行あたりの表示幅.
// 使用時にはpsc_DstBufのサイズがpsc_InputStrを超えないことを保障した上で使用すること！.
void PCGC_SlideTextMgr::updateTextBuf( char* psc_DstBuf, char* psc_InputStr, char sc_MaxRange ) {
	if( NULL == psc_DstBuf || NULL == psc_InputStr ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	strcpy( psc_DstBuf, psc_InputStr );
	init_CLCD( psc_DstBuf, sc_MaxRange, ss_MmbMaxInputSize, pc_MmbCursorTextField, e_MmbCharSet, sc_MmbMaxYRange, ss_MmbSubMaxInputSizeUTF8 );
	return;
}

// comment 2015/08/17 OPS1-Sky浜野 [MinervaSBK][CQ515414] キーボード濁点、半濁点操作改善対応.
// ----------------------------------------------------------------------------------.
/**
 *	@brief	確定文字の濁点・半濁点の置き換え.
 *	@param[in]		オプション値.
 *	@param[in]		入力文字列.
 *	@retval			変換成功有無.
 */
// ----------------------------------------------------------------------------------.
Bool PCGC_SlideTextMgr::replaceInputString( uchar uc_Option, char* psc_InputString )
{
	uchar uc_Param 					= 0;
	short ss_BytePos				= 0;						// 変換対象の文字位置.
	short ss_ReplacePos				= 0;						// 変換対象のカーソル位置.
	char sc_InputUTF8[4+1];										// UTF8文字.
	char sc_Replace[3];											// 変換後の文字.
	char sc_StringSJIS[3];										// SJIS文字.
	char sc_StringUTF8[4+1];										// UTF8文字.
	memset( sc_InputUTF8, 0x00, sizeof(sc_InputUTF8) );
	memset( sc_Replace, 0x00, sizeof(sc_Replace) );
	memset( sc_StringSJIS, 0x00, sizeof(sc_StringSJIS) );
	memset( sc_StringUTF8, 0x00, sizeof(sc_StringUTF8) );
	KeybordType e_KeyBordType;
	
	// NULLチェック.
	if( NULL == psc_InputString ) {
		return False;
	}
	
	// 変換対象(psc_InputString) UTF8.
	// 確定入力文字が存在しない.
	if( 0 == strlen( psc_InputString ) ){
		return False;
	}
	
	// テキスト表示パーツのNULLチェック.	
	if( NULL == pc_MmbCursorTextField ) {
		return False;
	}
	
	// 変換対象カーソル位置取得.
	pc_MmbCursorTextField->getCursorPosition( ss_ReplacePos );
	// 直前文字がない.
	if( 0 == ss_ReplacePos ){
		return False;
	}
	
	// 表示文字列取得.
	psc_InputString += ss_MmbOffset;
	
	short ss_MaxByte = ( short )( strlen( psc_InputString ) );
	
	// 対象文字バイト数算出
	short ss_CharLength = 0;
	while( EndOfString != *(psc_InputString + ss_BytePos) ) {
		// UTF8の1文字のバイト数を加算し、変換位置を算出する.
		short ss_TmpByte  = LIBF_getUTF8ByteCount(psc_InputString + ss_BytePos);
		ss_CharLength++;
		
		if( ss_ReplacePos == ss_CharLength ) {
			break;
		}
		
		// 表示文字バイト数を超過した場合.
		if( ss_MaxByte <= ( ss_BytePos + ss_TmpByte ) ) {
			break;
		}
		
		ss_BytePos = ( short )( ss_BytePos + ss_TmpByte );
	}

	short ss_Bytes = LIBF_getUTF8ByteCount( &psc_InputString[ss_BytePos] );
// comment 2018/01/18【HCLT-Vijayaraghavan】【IT5_4.2】Kloc work Changes ID:394579【SV.STRBO.BOUND_COPY.OVERFLOW】.
	//strncpy( sc_InputUTF8, &psc_InputString[ss_BytePos], ss_Bytes );
	if ( ss_Bytes < sizeof( sc_InputUTF8 ) ) {
		strncpy( sc_InputUTF8, &psc_InputString[ss_BytePos], ss_Bytes );
	} else {
		strncpy( sc_InputUTF8, &psc_InputString[ss_BytePos], ( sizeof( sc_InputUTF8 ) - 1 ) );
	}
	// UTF8→SJIS変換
	LIBF_ConvertFromUTF8( sc_InputUTF8, (LIBE_CharSet)TYPE_CharSetSJIS, sc_StringSJIS, sizeof(sc_StringSJIS) );
	
	switch( uc_Option ) {
		case PLBD_DakuTenKeyCode:		uc_Param = 155;	break;
		case PLBD_HanDakuTenKeyCode:	uc_Param = 156;	break;
		case PLBD_SmallCharKeyCode:		uc_Param = 157;	break;
		default:
			break;
	}
	
	getReplaceChar( uc_Param, sc_StringSJIS, sc_Replace, e_KeyBordType );
	
	// 変換対象がない.
	if( 0 == strlen( sc_Replace ) ) {
		return False;
	}
	
	// SJIS→UTF8変換
	LIBF_ConvertToUTF8( (LIBE_CharSet)TYPE_CharSetSJIS, sc_Replace, sc_StringUTF8, sizeof(sc_StringUTF8) );

	// 濁点、半濁点置き換え（終端文字列はコピーしない）.
	short ss_CopySize = LIBF_getUTF8ByteCount( sc_StringUTF8 );
	
	strncpy( &psc_InputString[ss_BytePos], sc_StringUTF8, ss_CopySize );
	
	return True;
}

// ----------------------------------------------------------------------------------.
/**
 *	@brief	確定文字の濁点・半濁点・小文字有効設定.
 *	@param[in]		入力文字列.
 *	@retval			なし.
 */
// ----------------------------------------------------------------------------------.
void PCGC_SlideTextMgr::setEnableCharType( char* psc_InputString )
{
	short ss_BytePos				= 0;						// 変換対象の文字位置.
	short ss_ReplacePos				= 0;						// 変換対象のカーソル位置.
	char sc_InputUTF8[4+1];										// UTF8文字.
	char sc_StringSJIS[3];										// SJIS文字.
	memset( sc_InputUTF8, 0x00, sizeof(sc_InputUTF8) );
	memset( sc_StringSJIS, 0x00, sizeof(sc_StringSJIS) );
	
	if( NULL == psc_InputString ) {
		m_uc_EnableCharType = PNLD_CharType_None;
		return;
	}
	
	// 変換対象(psc_InputString) UTF8.
	// 確定入力文字が存在しない.
	if( 0 == strlen( psc_InputString ) ){
		m_uc_EnableCharType = PNLD_CharType_None;
		return;
	}
	
	// テキスト表示パーツのNULLチェック.	
	if( NULL == pc_MmbCursorTextField ) {
		m_uc_EnableCharType = PNLD_CharType_None;
		return;
	}
	
	// 変換対象カーソル位置取得.
	pc_MmbCursorTextField->getCursorPosition( ss_ReplacePos );
	// 直前文字がない.
	if( 0 == ss_ReplacePos ){
		m_uc_EnableCharType = PNLD_CharType_None;
		return;
	}
	
	short ss_MaxByte = ( short )( strlen( psc_InputString ) );

	// 対象文字バイト数算出
	short ss_CharLength = 0;
	while( EndOfString != *(psc_InputString + ss_BytePos) ) {
		// UTF8の1文字のバイト数を加算し、変換位置を算出する.
		short ss_TmpByte  = LIBF_getUTF8ByteCount(psc_InputString + ss_BytePos);
		ss_CharLength++;
		
		if( ss_ReplacePos == ss_CharLength ) {
			break;
		}
		
		// 表示文字バイト数を超過した場合.
		if( ss_MaxByte <= ( ss_BytePos + ss_TmpByte ) ) {
			break;
		}

		ss_BytePos = ( short )( ss_BytePos + ss_TmpByte );
	}

	short ss_Bytes = LIBF_getUTF8ByteCount( &psc_InputString[ss_BytePos] );
// comment 2018/01/18【HCLT-Vijayaraghavan】【IT5_4.2】Kloc work Changes ID:394579【SV.STRBO.BOUND_COPY.OVERFLOW】.	
//	strncpy( sc_InputUTF8, &psc_InputString[ss_BytePos], ss_Bytes );
	if ( ss_Bytes < sizeof( sc_InputUTF8 ) ) {
		strncpy( sc_InputUTF8, &psc_InputString[ss_BytePos], ss_Bytes );
	} else {
		strncpy( sc_InputUTF8, &psc_InputString[ss_BytePos], ( sizeof( sc_InputUTF8 ) - 1 ) );
	}
	// UTF8→SJIS変換
	LIBF_ConvertFromUTF8( sc_InputUTF8, (LIBE_CharSet)TYPE_CharSetSJIS, sc_StringSJIS, sizeof(sc_StringSJIS) );

	m_uc_EnableCharType = getEnableReplaceChar( sc_StringSJIS );
}

// ----------------------------------------------------------------------------------.
/**
 *	@brief	確定文字の濁点・半濁点・小文字有効取得.
 *	@retval			濁点・半濁点・小文字有効設定.
 */
// ----------------------------------------------------------------------------------.
uchar PCGC_SlideTextMgr::getEnableCharType()
{
	return m_uc_EnableCharType;
}

