	//		pc_AccessTokenManager->createCPUPassword( uc_CPUPassword );
	//	}else{
	//		pc_AccessTokenManager->deleteCPUPassword();
	//	}
	//}
	// CPU Password情報を保持する.
	//PNLC_CloudCollaboration* pc_CloudCollaboration = PNLC_CloudCollaboration::getInstance();
	//if( NULL != pc_CloudCollaboration ) {
	//	pc_CloudCollaboration->setCPUPassword( uc_CPUPassword );
	//}
	// Public、一般、Box管理者、管理者(管理者設定を開く時以外)のログインで、ブラウザ起動済.
// comment 2019/4/24 Sky蒲原 [EagleH][AR1074141] ログイン時にタブの初期化を行わない.
//	if( (NULL != pc_User)
//// comment 2019/01/24 SCD2-Sky小畑 [WebUIv3][OP_BTS-2724] 管理者権限でユーザログインできない問題の対応.
