//	  && ( (TYPE_UserTypePublicUser == pc_User->getUserType()) || (TYPE_UserTypeUser == pc_User->getUserType() ) ||
//	       (TYPE_UserTypeBoxAdmin == pc_User->getUserType()) ||
//	       ((TYPE_UserTypeAdmin == pc_User->getUserType()) && (TYPE_LoginAuthorityMode_Admin == PNLC_ActionDataLib::newInstance()->getLoginAuthorityMode()) ))
//// comment 2019/03/06 SCD2-Sky小畑 [WebUIv3][OP_BTS-3170] タブ初期化中にタブ初期化をしてしまう対応.
