//概要    :全てのジョブへ部門情報を設定する.
void PnlComSetJobTrackInfo( Bool b_IntModeForce )
{
	APIC_Track* pc_Track = PnlComGetTrack();
	if( NULL == pc_Track ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return;}
	// 部門管理番号取得.
	int32_t i32_TrackNo = pc_Track->getTrackNo(); // 2013/11/01 【US-20U-PN3G】20万人対応.
	// 部門管理番号取得.
	// 割り込み時.
	if( onlyPanel.ec_IntMode == EC_IntMode_On ) {
		// 動作中でなければ.
		if( False == PnlComGetJobActionOn( cp_copyJob ) ) {
			cp_copyJob->getJobSpec()->pc_Common->c_UserAcount.setTrackNo( i32_TrackNo );
		}
	} else if( True == b_IntModeForce ) {
		// 動作中でなければ.
		if( False == PnlComGetJobActionOn( cp_intJob ) ) {
			cp_intJob->getJobSpec()->pc_Common->c_UserAcount.setTrackNo( i32_TrackNo );
		}
	} else {
		// 動作中でなければ.
		if( False == PnlComGetJobActionOn( cp_copyJob ) ) {
			cp_copyJob->getJobSpec()->pc_Common->c_UserAcount.setTrackNo( i32_TrackNo );
		}
		if( False == PnlComGetJobActionOn( cp_scanJob ) ) {
			cp_scanJob->getJobSpec()->pc_Common->c_UserAcount.setTrackNo( i32_TrackNo );
		}
		if( False == PnlComGetJobActionOn( cp_faxJob ) ) {
			cp_faxJob->getJobSpec()->pc_Common->c_UserAcount.setTrackNo( i32_TrackNo );
		}
		if( False == PnlComGetJobActionOn( cp_scanfaxJob ) ) {
			cp_scanfaxJob->getJobSpec()->pc_Common->c_UserAcount.setTrackNo( i32_TrackNo );
		}
	}
}
