//概要    :ユーザ認証中状態を取得.
Bool PnlComGetUserAccountOn()
{
	if( TYPE_UserAuthenticationOff != ppc_UserAuthentication->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine())			// ユーザ認証がOFFでなければ.
	    && TYPE_CertificationActionOnlyPublic != ppc_UserAuthentication->getCertificationAction(PNLC_NetworkLan::getInstance()->getLine())	// ユーザ認証でPublicのみでの動作方法でなければ.
	    && NULL != PnlComGetUser() ) {																// ユーザ認証ポインタを取得出来ていれば.
		return True;
	}
// comment Sky東島 [RQ-686] 複合機の複数ネットワーク対応.
	if( ( True == PNLC_NetworkLan::getInstance()->getVlanSetting() )
	 && ( NULL != PnlComGetUser() ) ){
		// VLAN設定有効時にはユーザー認証OFF状態の場合でもユーザー認証中と判断する.
		return True;
	}
	return False;
}
	
// Comment 2020/06/20【HCLT-Selvaraj】【IT6_2.0MR3】【制御構成変更_No.34】Set Digital post flag when Switch ON the MFP,waking up from power save and sleep.
Bool PnlComGetDigitPostON()
{
// Comment 2020/06/26【HCLT-Selvaraj】【IT6_2.0MR3】【OP_BTS-24977】Increasing array size to support double byte characters.
	//char strMessage[400+1];
	char strMessage[1600+1];
	memset( strMessage, '\0', sizeof( strMessage ) );
	Bool bl_postEnable;
	APIC_SystemSetting* pc_SystemSet = PnlComGetSystemSetting();
	if ( NULL != pc_SystemSet ) {
		pc_SystemSet->getPostItMessage(strMessage);
		bl_postEnable = pc_SystemSet->getPostItSettingEnabled();
		
		if( True == bl_postEnable 
		  && 0 != strlen(strMessage)
// Comment 2020/07/08 [HCLT-Ranjith] [IT62.0_MR3] [OP_BTS-25184] Adding Digital postit icon for Account Track screen.
// 		  && TYPE_UserAuthenticationOff != ppc_UserAuthentication->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()) ) {
		  && ( ( TYPE_UserAuthenticationOff != ppc_UserAuthentication->getUserAuthentication( PNLC_NetworkLan::getInstance()->getLine() ) )
//		 	 || ( True == PnlComGetTrackOn() ) ) ) {
// comment 2022/07/27 Sky中野 [IT6_2.2MR3][OP_BTS-38572].
//			 || ( TYPE_TrackModeOff != ppc_TrackManager->getTrackMode(PNLC_NetworkLan::getInstance()->getLine()) ) ) ){
			 || ( TYPE_TrackModeOff != PnlComGetTrackManager()->getTrackMode(PNLC_NetworkLan::getInstance()->getLine()) ) ) ){
			return True;
		} else {
			return False;
		}
	}
	return False;
}
//概要    :Publicユーザ認証中状態を取得.
Bool PnlComGetUserAccountPublic()
{
	if( TYPE_UserAuthenticationOff != ppc_UserAuthentication->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine())			// ユーザ認証がOFFでなければ.
	    && TYPE_CertificationActionOnlyPublic != ppc_UserAuthentication->getCertificationAction(PNLC_NetworkLan::getInstance()->getLine())	// ユーザ認証でPublicのみでの動作方法でなければ.
	    && NULL != PnlComGetUser() ) {																// ユーザ認証ポインタを取得出来ていれば.
		char sc_UserName[PCGD_MaxUserName*3 + PCGD_EndCode];	// ユーザ認証名.
		// ユーザー認証名取得Buf初期化.
		memset( sc_UserName, '\0', sizeof( sc_UserName ) );
		// ユーザ認証名取得.
		if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
			PnlComGetUser()->getUserNameUTF8( sc_UserName, TYPE_CharSetUTF8 );
		} else {
			PnlComGetUser()->getUserNameUTF8( sc_UserName, getCharSetForCAPI() );
		} // DonauLastFum【ネットワーク通信文字拡張】【13東阪】2009/04/30 Add.
		// Publicユーザーで認証されているかチェック.
		if( strcmp( sc_UserName, "Public" ) == 0 ) {
			return True;
		}
	}
// comment Sky東島 [RQ-686] 複合機の複数ネットワーク対応.
	if( ( True == PNLC_NetworkLan::getInstance()->getVlanSetting() )
	 && ( NULL != PnlComGetUser() )
	 && ( TYPE_UserTypePublicUser == PnlComGetUser()->getUserType() ) ){
		// VLAN設定有効時にはユーザー認証OFF状態の場合でもユーザー認証中と判断する.
		return True;
	}
	return False;
}
