//概要    :ユーザより連動する部門でloginする.
TYPE_TrackResult PnlComLoginUserTrack()
{

	if( NULL == PnlComGetUser() ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return TYPE_TrackResultPasswordNG; }

	// 部門管理情報取得.
	PnlComSetTrack( PnlComGetUser()->getTrack() );
	if( NULL == PnlComGetTrack() ) {
		return TYPE_TrackResultPasswordNG;
	}
	TYPE_TrackResult e_TrackResult = TYPE_TrackResultPasswordNG;
	char sc_TrackName[PCGD_MaxTrackName + PCGD_EndCode];
	char sc_TrackPassword[TYPD_DepPasswordMaxAreaSize];
	PnlComGetTrack()->getTrackName( sc_TrackName );
	PnlComGetTrack()->getTrackPassword( sc_TrackPassword );
	// 部門管理login条件取得.
	short ss_TrackCondition = TYPD_TrackFunctionMask_None;
	PanelLog( PNLD_LogKind_Auth, "req_login() P1[%s] P2[%s] P3[%d] P4[NULL] P5[%d] P6[%d]", sc_TrackName, sc_TrackPassword, ss_TrackCondition, e_TrackResult, JLGE_InspectLogIfOperationPanel, 0 );
	PanelLog( PNLD_LogKind_Auth, "req_login() P7[%d] P8[%d] P9[%d] P10[%d] P11[%d]", False, False, False, TYPE_LoginMode_Normal, PnlComGetUser()->getUserNo(), 0 );
	// 部門管理login.
	PnlComSetTrack( APIC_Track::req_login( sc_TrackName, sc_TrackPassword, ss_TrackCondition, NULL, &e_TrackResult, JLGE_InspectLogIfOperationPanel, False, False, False, TYPE_LoginMode_Normal, PnlComGetUser()->getUserNo() ) );
	return e_TrackResult;
}
//概要    :使用者変更時のモードリセット処理.
void PnlComInitJobMode()
{
// comment 2023/09/14 Sky東島 [IT6_2.3][OP_BTS-44767].
	if( True == onlyPanel.getDontRunInitJobMode() ){
		// 何もしない.
		return;
	}
// comment Sky森本（弘） 2018/06/26 [Eagle][市場問題(FQ-OPSD-1700387-OFP195)] 短縮宛先が選択されているにも関わらず送信操作ログに全宛先解除が記録される．
	// モードリセット処理中格納
	PNLC_OperationLog::newInstance()->setInitJobSetting( True );
	Bool b_InheritorOff = False;
	// 部門管理のみであれば対象のジョブの初期化.
	if( PnlComGetTrackOnlyOn() ) {
		// 部門対象でコピージョブ動作中でなければ.
// comment 2022/07/27 Sky中野 [IT6_2.2MR3][OP_BTS-38572].
//		if( ppc_TrackManager->getTrackEnableAtCopy()
		if( PnlComGetTrackManager()->getTrackEnableAtCopy()
		    && False == PnlComGetJobActionOn( cp_copyJob ) ) {
			c_JobControl.InitJobSetting( cp_copyJob );				// コピージョブを初期化
		}
		// 部門対象でコピージョブ動作中であれば.
// comment 2022/07/27 Sky中野 [IT6_2.2MR3][OP_BTS-38572].
//		else if( ppc_TrackManager->getTrackEnableAtCopy()
		else if( PnlComGetTrackManager()->getTrackEnableAtCopy()
		         && True == PnlComGetJobActionOn( cp_copyJob ) ) {
			b_InheritorOff = True;
		}
		// 部門対象でスキャンジョブ動作中でなければ.
// comment 2022/07/27 Sky中野 [IT6_2.2MR3][OP_BTS-38572].
//		if( ppc_TrackManager->getTrackEnableAtScan()
		if( PnlComGetTrackManager()->getTrackEnableAtScan()
		    && False == PnlComGetJobActionOn( cp_scanJob ) ) {
			c_JobControl.InitJobSetting( cp_scanJob );				// スキャンジョブを初期化
		}
		// 部門対象でスキャンジョブ動作中であれば.
// comment 2022/07/27 Sky中野 [IT6_2.2MR3][OP_BTS-38572].
//		else if( ppc_TrackManager->getTrackEnableAtScan()
		else if( PnlComGetTrackManager()->getTrackEnableAtScan()
		         && True == PnlComGetJobActionOn( cp_scanJob ) ) {
			b_InheritorOff = True;
		}
		// 部門対象でＦＡＸジョブ動作中でなければ.
// comment 2022/07/27 Sky中野 [IT6_2.2MR3][OP_BTS-38572].
//		if( ppc_TrackManager->getTrackEnableAtFax()
		if( PnlComGetTrackManager()->getTrackEnableAtFax()
		    && False == PnlComGetJobActionOn( cp_faxJob ) ) {
			c_JobControl.InitJobSetting( cp_faxJob );				// ファックスジョブを初期化
		}
		// 部門対象でＦＡＸジョブ動作中であれば.
// comment 2022/07/27 Sky中野 [IT6_2.2MR3][OP_BTS-38572].
//		else if( ppc_TrackManager->getTrackEnableAtFax()
		else if( PnlComGetTrackManager()->getTrackEnableAtFax()
		         && True == PnlComGetJobActionOn( cp_faxJob ) ) {
			b_InheritorOff = True;
		}
		// 部門対象でスキャンファクスジョブ動作中でなければ.
// comment 2022/07/27 Sky中野 [IT6_2.2MR3][OP_BTS-38572].
//		if( ppc_TrackManager->getTrackEnableAtFax()
		if( PnlComGetTrackManager()->getTrackEnableAtFax()
		    && False == PnlComGetJobActionOn( cp_scanfaxJob ) ) {
			c_JobControl.InitJobSetting( cp_scanfaxJob );				// スキャンファクスジョブを初期化
		}
		// 部門対象でスキャンファクスジョブ動作中であれば.
// comment 2022/07/27 Sky中野 [IT6_2.2MR3][OP_BTS-38572].
//		else if( ppc_TrackManager->getTrackEnableAtFax()
		else if( PnlComGetTrackManager()->getTrackEnableAtFax()
		         && True == PnlComGetJobActionOn( cp_scanfaxJob ) ) {
			b_InheritorOff = True;
		}
	} else {
		// コピージョブ動作中でなければ.
		if( False == PnlComGetJobActionOn( cp_copyJob ) ) {
			c_JobControl.InitJobSetting( cp_copyJob );				// コピージョブを初期化
		} else {
			b_InheritorOff = True;
		}
		// スキャンジョブ動作中でなければ.
		if( False == PnlComGetJobActionOn( cp_scanJob ) ) {
			c_JobControl.InitJobSetting( cp_scanJob );				// スキャンジョブを初期化
		} else {
			b_InheritorOff = True;
		}
		// FAXジョブ動作中でなければ.
		if( False == PnlComGetJobActionOn( cp_faxJob ) ) {
			c_JobControl.InitJobSetting( cp_faxJob );				// ファックスジョブを初期化
		} else {
			b_InheritorOff = True;
		}
		// ScanFaxジョブ動作中でなければ.
		if( False == PnlComGetJobActionOn( cp_scanfaxJob ) ) {
			c_JobControl.InitJobSetting( cp_scanfaxJob );				// スキャンファクスジョブを初期化
		} else {
			b_InheritorOff = True;
		}
	}
	// 継承しない.
	if( b_InheritorOff ) {
		c_JobControl.setInheritorOff();
	}
// comment Sky森本（弘） 2018/06/26 [Eagle][市場問題(FQ-OPSD-1700387-OFP195)] 短縮宛先が選択されているにも関わらず送信操作ログに全宛先解除が記録される．
	// モードリセット処理中格納
	PNLC_OperationLog::newInstance()->setInitJobSetting( False );
}
//概要    :ファイル名入力済み取得.
Bool PnlComGetFileNameOn( TYPC_Common* const pc_Common )
{
	Bool b_Result = True;
// システムのバッファサイズに合わせる.
	char sc_FileName[TYPD_CmnFileNameLen + PCGD_EndCode];		// 画像ファイル名.
	// 初期化.
	memset( sc_FileName, '\0', sizeof( sc_FileName ) );

	// ファイル名取得.
	if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
		pc_Common->getFileNameUTF8( sc_FileName, TYPE_CharSetUTF8 );
	} else {
		pc_Common->getFileNameUTF8( sc_FileName, getCharSetForCAPI() );
	} // DonauLastFum【ネットワーク通信文字拡張】【13東阪】2009/04/30 Add.
	// 入力されていなければ.
	if( sc_FileName[0] == '\0' ) {
		b_Result = False;
	}
	return b_Result;
}
//-------------------------------------------------------------------------------------------------
// 概要		: 認証結果通知を受けた後、認証情報のE-mailアドレスにユーザー名を設定する.
//-------------------------------------------------------------------------------------------------
void PnlComSetUserNameIntoEmailAdr( APIC_User* pc_User )
{
	// 外部サーバー認証設定時、且つ、一般ユーザーのログイン時のみ認証情報のE-mailアドレスにユーザー名を設定する.
	if( ( NULL != pc_User )
	    && ( TYPE_UserAuthenticationServer == PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()) )
	    && ( TYPE_UserTypeUser == pc_User->getUserType() ) ) {
		// ユーザー名を取得.
		char sc_UserName[ UACD_MAX_UserName ];
		memset( sc_UserName, '\0', sizeof( sc_UserName ) );
		pc_User->getUserNameUTF8( sc_UserName, TYPE_CharSetUTF8 );
		// E-mail設定を取得.
		TYPS_MailNotification st_MailNotification = pc_User->getMailNotification();
		// E-mailアドレスにユーザー名を設定する.
		memset( st_MailNotification.sc_UserMailAdrs, '\0', sizeof( st_MailNotification.sc_UserMailAdrs ) );
		strncpy( st_MailNotification.sc_UserMailAdrs, sc_UserName, ( sizeof( st_MailNotification.sc_UserMailAdrs ) - 1 ) );							// E-mailアドレスにユーザー名をセットする.
		pc_User->setMailNotification( st_MailNotification, JLGE_InspectLogIfOperationPanel, pc_User, TYPE_RegistrationTypeOnlyOne );				// ユーザー情報を更新する.
		pc_User->setRegistration( True, TYPE_RegistrationTypeOnlyOne, JLGE_InspectLogIfOperationPanel, False, TYPE_Registration_State_ReNew, False, PnlComGetUser(), PnlComGetAuthorityID() );	// 更新を確定する(不揮発に保存する).
	}
}

TYPE_BackDensity	e_AryBackDensity[] = {
	TYPE_BackDensityLevelD2,	// －２
	TYPE_BackDensityLevelD1,	// －１
	TYPE_BackDensityLevelN,		// ０（中央）
	TYPE_BackDensityLevelL1,	// ＋１
	TYPE_BackDensityLevelL2,	// ＋２
	TYPE_BackDensityLevelL3,	// ＋３
	TYPE_BackDensityLevelL4,	// ＋４
	TYPE_BackDensityLevelL5,	// ＋５
	TYPE_BackDensityLevelL6,	// ＋６（うすく）
};
const uchar uc_SizeOfAryBackDensity = sizeof( e_AryBackDensity ) / sizeof( TYPE_BackDensity );
//概要    :下地濃度・1レベル濃いレベルを取得.
TYPE_BackDensity PnlComGetBackDensityDeep( TYPE_BackDensity e_BackDensityNow )
{
	uchar uc_Counter = 0;
	for( ; uc_SizeOfAryBackDensity > uc_Counter ; ++uc_Counter ) {
		if( e_BackDensityNow == e_AryBackDensity[uc_Counter] ) {
			break;
		}
	}
	// こく最大値の場合の場合は最大値を返す
	uc_Counter = ( uchar )( ( uc_Counter == 0 ) ? uc_Counter : uc_Counter - 1 );
	return e_AryBackDensity[uc_Counter];
}
//概要    :下地濃度・1レベル薄いレベルを取得.
TYPE_BackDensity PnlComGetBackDensityLight( TYPE_BackDensity e_BackDensityNow )
{
	uchar uc_Counter = 0;
	for( ; uc_SizeOfAryBackDensity > uc_Counter ; ++uc_Counter ) {
		if( e_BackDensityNow == e_AryBackDensity[uc_Counter] ) {
			break;
		}
	}
	// うすく最大値の場合は最大値を返す
	uc_Counter = ( uchar )( ( uc_Counter == uc_SizeOfAryBackDensity -1 ) ? uc_Counter : uc_Counter + 1 );
	if( uc_SizeOfAryBackDensity <= uc_Counter ) {
		return TYPE_BackDensityLevelL6;
	}
	return e_AryBackDensity[uc_Counter];
}
struct PCGS_ImageAdjustCopyDensity {
	TYPE_ImageAdjust e_ImageAdjust;
	uchar			 uc_Index;
} s_AryImageAdjustCopyDensity[] = {
	{ TYPE_ImageAdjustP09, 0 },
	{ TYPE_ImageAdjustP08, 0 },
	{ TYPE_ImageAdjustP07, 0 },
	{ TYPE_ImageAdjustP06, 1 },
	{ TYPE_ImageAdjustP05, 1 },
	{ TYPE_ImageAdjustP04, 2 },
	{ TYPE_ImageAdjustP03, 2 },
	{ TYPE_ImageAdjustP02, 3 },
	{ TYPE_ImageAdjustP01, 3 },
	{ TYPE_ImageAdjustStd, 4 },
	{ TYPE_ImageAdjustM01, 5 },
	{ TYPE_ImageAdjustM02, 5 },
	{ TYPE_ImageAdjustM03, 6 },
	{ TYPE_ImageAdjustM04, 6 },
	{ TYPE_ImageAdjustM05, 7 },
	{ TYPE_ImageAdjustM06, 7 },
	{ TYPE_ImageAdjustM07, 8 },
	{ TYPE_ImageAdjustM08, 8 },
	{ TYPE_ImageAdjustM09, 8 },
};
const uchar uc_SizeOfAryImageAdjustCopyDensity = sizeof( s_AryImageAdjustCopyDensity ) / sizeof( PCGS_ImageAdjustCopyDensity );
//
//概要    :コピー濃度・1レベル濃いレベルを取得.
TYPE_ImageAdjust PnlComGetCopyDensityDeep( TYPE_ImageAdjust e_ImageAdjustNow )
{
	//	コピー濃度を調整(細かい→粗い).
	e_ImageAdjustNow = PnlComGetCopyDensityAdjustDetailToRough( e_ImageAdjustNow );
	TYPE_ImageAdjust e_ImageAdjustNext = TYPE_ImageAdjustP09;
	uchar uc_Counter = 0;
	for( ; uc_SizeOfAryImageAdjustRough > uc_Counter ; ++uc_Counter ) {
		if( e_ImageAdjustNow == e_AryImageAdjustRough[uc_Counter] ) {
			break;
		}
		e_ImageAdjustNext = e_AryImageAdjustRough[uc_Counter];
	}
	return e_ImageAdjustNext;
}
//概要    :コピー濃度・1レベル薄いレベルを取得.
TYPE_ImageAdjust PnlComGetCopyDensityLight( TYPE_ImageAdjust e_ImageAdjustNow )
{
	//	コピー濃度を調整(細かい→粗い).
	e_ImageAdjustNow = PnlComGetCopyDensityAdjustDetailToRough( e_ImageAdjustNow );
	uchar uc_Counter = 0;
	for( ; uc_SizeOfAryImageAdjustRough > uc_Counter ; ++uc_Counter ) {
		if( e_ImageAdjustNow == e_AryImageAdjustRough[uc_Counter] ) {
			break;
		}
	}
	//	元々Enumの最後の値が設定されていた場合を考慮し、最後の有効値と比較.
#ifdef LINUX
	uc_Counter = ( uchar )( std::min( uc_Counter + 1, uc_SizeOfAryImageAdjustRough - 1 ) );
#else
	uc_Counter = ( uchar )( min( uc_Counter + 1, uc_SizeOfAryImageAdjustRough - 1 ) );
#endif /*LINUX*/
	return e_AryImageAdjustRough[uc_Counter];
}
//概要    :コピー濃度・レベルを調整(細かい→粗い).
TYPE_ImageAdjust PnlComGetCopyDensityAdjustDetailToRough( TYPE_ImageAdjust e_ImageAdjustNow )
{
	uchar uc_Counter = 0;
	for( ; uc_SizeOfAryImageAdjustCopyDensity > uc_Counter ; ++uc_Counter ) {
		if( e_ImageAdjustNow == s_AryImageAdjustCopyDensity[uc_Counter].e_ImageAdjust ) {
			break;
		}
	}
	if( uc_Counter >= uc_SizeOfAryImageAdjustCopyDensity ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return TYPE_ImageAdjustP09;
	}
	//	index範囲チェック.
	if( s_AryImageAdjustCopyDensity[uc_Counter].uc_Index >= uc_SizeOfAryImageAdjustRough ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
	return e_AryImageAdjustRough[s_AryImageAdjustCopyDensity[uc_Counter].uc_Index];
}
//概要    :カラーバランス・1レベル濃いレベルを取得.
TYPE_ImageAdjust PnlComGetColorBalanceDeep( TYPE_ImageAdjust e_ImageAdjustNow, uchar uc_Offset )
{
	//	処理過程で値がマイナス値をとりうるので、「uchar」ではなく「char」とする.
	char sc_Counter = 0;
	for( ; uc_SizeOfAryImageAdjustCopyDensity > sc_Counter ; ++sc_Counter ) {
		if( e_ImageAdjustNow == s_AryImageAdjustCopyDensity[( uchar )sc_Counter].e_ImageAdjust ) {
			break;
		}
	}
#ifdef LINUX
	sc_Counter = ( char )( std::max( sc_Counter - uc_Offset, 0 ) );
#else
	sc_Counter = ( char )( max( sc_Counter - uc_Offset, 0 ) );
#endif
	return s_AryImageAdjustCopyDensity[( uchar )sc_Counter].e_ImageAdjust;
}
//概要    :カラーバランス・1レベル薄いレベルを取得.
TYPE_ImageAdjust PnlComGetColorBalanceLight( TYPE_ImageAdjust e_ImageAdjustNow, uchar uc_Offset )
{
	uchar uc_Counter = 0;
	for( ; uc_SizeOfAryImageAdjustCopyDensity > uc_Counter ; ++uc_Counter ) {
		if( e_ImageAdjustNow == s_AryImageAdjustCopyDensity[uc_Counter].e_ImageAdjust ) {
			break;
		}
	}
	//	元々Enumの最後の値が設定されていた場合を考慮し、最後の有効値と比較.
#ifdef LINUX
	uc_Counter = ( uchar )( std::min( uc_Counter + uc_Offset, uc_SizeOfAryImageAdjustCopyDensity - 1 ) );
#else
	uc_Counter = ( uchar )( min( uc_Counter + uc_Offset, uc_SizeOfAryImageAdjustCopyDensity - 1 ) );
#endif /*LINUX*/
	return s_AryImageAdjustCopyDensity[uc_Counter].e_ImageAdjust;
}
