//概要    :枠消し処理共通クラス：メトリック系：ボタン（押された）
void PCGC_FrameEraseCom::procButtonOnMetric( uchar option )
{
	const PCGS_EraseFrameButton s_EraseFrameButtonMetricTbl[] = {
		{ s_MmbPartsMetric.uc_KeyIdFrame,	PCGD_SelFrameEraseFrame,	&s_MmbFrameEraseInfo.sf_FrameSize	},
		{ s_MmbPartsMetric.uc_KeyIdTop,		PCGD_SelFrameEraseTop,		&s_MmbFrameEraseInfo.sf_TopSize		},
		{ s_MmbPartsMetric.uc_KeyIdLeft,	PCGD_SelFrameEraseLeft,		&s_MmbFrameEraseInfo.sf_LeftSize	},
		{ s_MmbPartsMetric.uc_KeyIdRight,	PCGD_SelFrameEraseRight,	&s_MmbFrameEraseInfo.sf_RightSize	},
		{ s_MmbPartsMetric.uc_KeyIdBottom,	PCGD_SelFrameEraseBottom,	&s_MmbFrameEraseInfo.sf_BottomSize	},
	};
	const uchar uc_EraseFrameButtonMetricTbl = ( uchar )( sizeof( s_EraseFrameButtonMetricTbl ) / sizeof( PCGS_EraseFrameButton ) );
	// 枠、上、下、左、右選択ボタン押下チェック.
	for( uchar i = 0; i < uc_EraseFrameButtonMetricTbl; i++ ) {
		if( option == s_EraseFrameButtonMetricTbl[i].uc_KeyId ) {
			// キーに該当する選択値を設定する.
			ss_MmbSelDirection = s_EraseFrameButtonMetricTbl[i].ss_Select;
			const float sf_FrameErase = *( s_EraseFrameButtonMetricTbl[i].psf_Size );
			// 指定されている値を設定.
			s_MmbPartsMetric.pc_ComPartsFreeSizeInput->setValue( sf_FrameErase );
			break;
		}
	}
	// 選択ボタン以外のボタン押下チェック.
	if( ( option == s_MmbPartsMetric.uc_KeyIdSizeUp ) || ( option == s_MmbPartsMetric.uc_KeyIdSizeDown ) ) {
		// 消去量の＋－キー.
		s_MmbPartsMetric.pc_ComPartsFreeSizeInput->procButtonOn( option );
		s_MmbPartsMetric.pc_ComPartsFreeSizeInput->getValue( *s_EraseFrameButtonMetricTbl[ss_MmbSelDirection].psf_Size );
	} else if( option == s_MmbPartsMetric.uc_KeyIdNonErase ) {
		// 消去しないキーのボタン.
		s_MmbPartsMetric.pc_ComPartsFreeSizeInput->procClear( option );
		*s_EraseFrameButtonMetricTbl[ss_MmbSelDirection].psf_Size = 0.0f;
	}
}
