//概要    :枠消し処理共通クラス：メトリック系：画面セットアップ
void PCGC_FrameEraseCom::setupGamenMetric( short option )
{
	const PCGS_EraseFramePartsInfo	s_EraseFrameInfoTbl[] = {
		{ PCGD_SelFrameEraseFrame,  s_MmbPartsMetric.pc_FrameSize,		s_MmbPartsMetric.pc_FrameMillimeter,	s_MmbPartsMetric.pc_FrameNonErase,	s_MmbPartsMetric.pc_FrameSizeBak	},
		{ PCGD_SelFrameEraseTop,    s_MmbPartsMetric.pc_TopSize,		s_MmbPartsMetric.pc_TopMillimeter,		s_MmbPartsMetric.pc_TopNonErase,	s_MmbPartsMetric.pc_TopSizeBak		},
		{ PCGD_SelFrameEraseLeft,   s_MmbPartsMetric.pc_LeftSize,		s_MmbPartsMetric.pc_LeftMillimeter,		s_MmbPartsMetric.pc_LeftNonErase,	s_MmbPartsMetric.pc_LeftSizeBak		},
		{ PCGD_SelFrameEraseRight,  s_MmbPartsMetric.pc_RightSize,		s_MmbPartsMetric.pc_RightMillimeter,	s_MmbPartsMetric.pc_RightNonErase,	s_MmbPartsMetric.pc_RightSizeBak	},
		{ PCGD_SelFrameEraseBottom, s_MmbPartsMetric.pc_BottomSize,		s_MmbPartsMetric.pc_BottomMillimeter,	s_MmbPartsMetric.pc_BottomNonErase,	s_MmbPartsMetric.pc_BottomSizeBak	}
	};
	const uchar uc_SizeEraseFrameInfoTbl = ( uchar )( sizeof( s_EraseFrameInfoTbl ) / sizeof( PCGS_EraseFramePartsInfo ) );
	// ボタン選択位置の表示.
	s_MmbPartsMetric.pc_RotSelectButton->select( ss_MmbSelDirection );
	// 現在の消去方向をセット
	if( NULL != s_MmbPartsMetric.pc_FrameErasseSetDirectionTitle ) {
		switch( ss_MmbSelDirection ) {
			case PCGD_SelFrameEraseFrame:	s_MmbPartsMetric.pc_FrameErasseSetDirectionTitle->changeText( s_ITMFrameEraseAll );		break;
			case PCGD_SelFrameEraseTop:		s_MmbPartsMetric.pc_FrameErasseSetDirectionTitle->changeText( s_ITMFrameEraseTop );		break;
			case PCGD_SelFrameEraseLeft:	s_MmbPartsMetric.pc_FrameErasseSetDirectionTitle->changeText( s_ITMFrameEraseLeft );	break;
			case PCGD_SelFrameEraseRight:	s_MmbPartsMetric.pc_FrameErasseSetDirectionTitle->changeText( s_ITMFrameEraseRight );	break;
			case PCGD_SelFrameEraseBottom:	s_MmbPartsMetric.pc_FrameErasseSetDirectionTitle->changeText( s_ITMFrameEraseBottom );	break;
			default:	LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	break;
		}
	}
	// 消去量の表示.
	if( NULL != s_MmbPartsMetric.pc_FrameSizeBak ) {
		s_MmbPartsMetric.pc_ComPartsFreeSizeInput->showFreeSizeInputCLCD( ( s_MmbPartsMetric.pc_FrameSizeBak->isActivating() ), ( s_MmbPartsMetric.pc_FrameSizeBak->isActivating() ) );
	} else {
		s_MmbPartsMetric.pc_ComPartsFreeSizeInput->showFreeSizeInput();
	}
	// 調整値表示エリアが非活性状態ならば、本関数を抜ける.
	if( NULL != s_MmbPartsMetric.pc_FrameSizeBak ) {
		if( False == s_MmbPartsMetric.pc_FrameSizeBak->isActivating() ) {
			return;
		}
	}
	// フリーサイズクラスの入力エラー表示.
	if( True == b_EraseFrameError ) {
		// 1キー入力or一定時間でのエラー解除された場合.
		if( False == s_MmbPartsMetric.pc_ComPartsFreeSizeInput->getError() ) {
			b_EraseFrameError = False;
			for( uchar i = 0; i < ( ( uchar )( sizeof( b_AryEraseFrameError ) / sizeof( Bool ) ) ); i++ ) {
				b_AryEraseFrameError[i] = False;
			}
			// エラーの解除.
			s_MmbPartsMetric.pc_ComPartsFreeSizeInput->setError( False );
		}
	}
	// 消去量の取得.
	float sf_FrameErase = 0.0f;
	s_MmbPartsMetric.pc_ComPartsFreeSizeInput->getValue( sf_FrameErase );
	// 消去しないキーの選択状態表示.
	const Bool b_SelectNonFrameErase = ( ( 0.0f == sf_FrameErase ) ? True : False );
	s_MmbPartsMetric.pc_KeyFrameNonDelete->select( b_SelectNonFrameErase );
	// 選択位置と消去量の連動表示
	float sf_AryEraseSize[5];
	sf_AryEraseSize[0] = s_MmbFrameEraseInfo.sf_FrameSize;
	sf_AryEraseSize[1] = s_MmbFrameEraseInfo.sf_TopSize;
	sf_AryEraseSize[2] = s_MmbFrameEraseInfo.sf_LeftSize;
	sf_AryEraseSize[3] = s_MmbFrameEraseInfo.sf_RightSize;
	sf_AryEraseSize[4] = s_MmbFrameEraseInfo.sf_BottomSize;
	for( uchar i = 0; i < uc_SizeEraseFrameInfoTbl; i++ ) {
		// 「消去しない」文字列を非表示、消去量を表示状態とする
		if( NULL != s_EraseFrameInfoTbl[i].pc_EraseFrameSizeBak ) {
			s_EraseFrameInfoTbl[i].pc_EraseFrameSizeBak->showEnableAdd( s_EraseFrameInfoTbl[i].pc_EraseFrameNonErase , False );
			s_EraseFrameInfoTbl[i].pc_EraseFrameSizeBak->showEnableAdd( s_EraseFrameInfoTbl[i].pc_EraseFrameSize , True );
			s_EraseFrameInfoTbl[i].pc_EraseFrameSizeBak->showEnableAdd( s_EraseFrameInfoTbl[i].pc_EraseFrameMillimeter , True );
		} else {
			s_EraseFrameInfoTbl[i].pc_EraseFrameNonErase->showEnable( False );
			s_EraseFrameInfoTbl[i].pc_EraseFrameSize->showEnable( True );
			s_EraseFrameInfoTbl[i].pc_EraseFrameMillimeter->showEnable( True );
		}
		if( ( ( PCGD_SelFrameEraseFrame == ss_MmbSelDirection ) && ( 1 > i ) )
		    || ( ( PCGD_SelFrameEraseFrame != ss_MmbSelDirection ) && ( 0 != i ) ) ) {
			// 現在選択されているのが「枠」で、かつテーブル位置が枠関連のパーツを示している
			// または、現在選択されているのが「枠」以外で、かつテーブル位置が枠以外のパーツを示している
			if( 0 == sf_AryEraseSize[i] ) {
				// 「消去しない」表示
				if( NULL != s_EraseFrameInfoTbl[i].pc_EraseFrameSizeBak ) {
					s_EraseFrameInfoTbl[i].pc_EraseFrameSizeBak->showEnableAdd( s_EraseFrameInfoTbl[i].pc_EraseFrameSize , False );
					s_EraseFrameInfoTbl[i].pc_EraseFrameSizeBak->showEnableAdd( s_EraseFrameInfoTbl[i].pc_EraseFrameMillimeter , False );
					s_EraseFrameInfoTbl[i].pc_EraseFrameSizeBak->showEnableAdd( s_EraseFrameInfoTbl[i].pc_EraseFrameNonErase , True );
				} else {
					s_EraseFrameInfoTbl[i].pc_EraseFrameSize->showEnable( False );
					s_EraseFrameInfoTbl[i].pc_EraseFrameMillimeter->showEnable( False );
					s_EraseFrameInfoTbl[i].pc_EraseFrameNonErase->showEnable( True );
				}
			}
			// 設定内容を表示
			if( NULL != s_EraseFrameInfoTbl[i].pc_EraseFrameSizeBak ) {
				s_EraseFrameInfoTbl[i].pc_EraseFrameSizeBak->set( s_EraseFrameInfoTbl[i].pc_EraseFrameSize, sf_AryEraseSize[i], True, -1, b_AryEraseFrameError[i] );
				if( True == b_AryEraseFrameError[i] ) {
					s_EraseFrameInfoTbl[i].pc_EraseFrameSizeBak->showEnableAdd( s_EraseFrameInfoTbl[i].pc_EraseFrameNonErase , False );
					s_EraseFrameInfoTbl[i].pc_EraseFrameSizeBak->showEnableAdd( s_EraseFrameInfoTbl[i].pc_EraseFrameMillimeter , False );
					s_EraseFrameInfoTbl[i].pc_EraseFrameSizeBak->showEnableAdd( s_EraseFrameInfoTbl[i].pc_EraseFrameSize , True );
				}
			} else {
				// 「消去しない」以外の場合、設定値を表示する
				if( 0 != sf_AryEraseSize[i] ) {
					s_EraseFrameInfoTbl[i].pc_EraseFrameSize->set( sf_AryEraseSize[i], True );
				}
			}
		}
	}
	// 不要なフィールドを非表示.
	if( PCGD_SelFrameEraseFrame == ss_MmbSelDirection ) {
		//	「枠」が選択状態
		for( uchar j = 1; j <= 4; j++ ) {
			// 上下左右は非表示とする
			if( NULL != s_EraseFrameInfoTbl[j].pc_EraseFrameSizeBak ) {
				s_EraseFrameInfoTbl[j].pc_EraseFrameSizeBak->showEnableAdd( s_EraseFrameInfoTbl[j].pc_EraseFrameSize , False );
				s_EraseFrameInfoTbl[j].pc_EraseFrameSizeBak->showEnableAdd( s_EraseFrameInfoTbl[j].pc_EraseFrameMillimeter , False );
				s_EraseFrameInfoTbl[j].pc_EraseFrameSizeBak->showEnableAdd( s_EraseFrameInfoTbl[j].pc_EraseFrameNonErase , False );
			} else {
				s_EraseFrameInfoTbl[j].pc_EraseFrameSize->showEnable( False );
				s_EraseFrameInfoTbl[j].pc_EraseFrameMillimeter->showEnable( False );
				s_EraseFrameInfoTbl[j].pc_EraseFrameNonErase->showEnable( False );
			}
		}
	} else {
		// 「上下左右」いずれかが選択状態ならば枠を非表示とする
		if( NULL != s_EraseFrameInfoTbl[0].pc_EraseFrameSizeBak ) {
			s_EraseFrameInfoTbl[0].pc_EraseFrameSizeBak->showEnableAdd( s_EraseFrameInfoTbl[0].pc_EraseFrameSize , False );
			s_EraseFrameInfoTbl[0].pc_EraseFrameSizeBak->showEnableAdd( s_EraseFrameInfoTbl[0].pc_EraseFrameMillimeter , False );
			s_EraseFrameInfoTbl[0].pc_EraseFrameSizeBak->showEnableAdd( s_EraseFrameInfoTbl[0].pc_EraseFrameNonErase , False );
		} else {
			s_EraseFrameInfoTbl[0].pc_EraseFrameSize->showEnable( False );
			s_EraseFrameInfoTbl[0].pc_EraseFrameMillimeter->showEnable( False );
			s_EraseFrameInfoTbl[0].pc_EraseFrameNonErase->showEnable( False );
		}
	}
}
