//概要    :枠消し処理共通クラス：テンキー
void PCGC_FrameEraseCom::proc10Key( uchar option )
{
	float sf_EraseSize = 0.0f;
	switch( PnlComGetUnitSystem() )
	{
		// mm（数値）.
		case TYPE_UnitSystemMM_Number:
			b_EraseFrameError = s_MmbPartsMetric.pc_ComPartsFreeSizeInput->proc10Key( option );
			if( 0 <= ss_MmbSelDirection && ss_MmbSelDirection < ( ( uchar )( sizeof( b_AryEraseFrameError ) / sizeof( Bool ) ) ) ) {
				b_AryEraseFrameError[ss_MmbSelDirection] = b_EraseFrameError;
			}
			if( True == b_EraseFrameError ) {
				// エラー状態セット.
				onlyPanel.setErrorNumberFieldPartsKind( EP_ErrorPartsKind_NumberField );
			}
			// 枠消し量の取得.
			s_MmbPartsMetric.pc_ComPartsFreeSizeInput->getValue( sf_EraseSize );
			break;
		// inch（分数／数値）.
		case TYPE_UnitSystemInch_Fraction:
			s_MmbPartsInch.pc_ComPartsFreeSizeInput->proc10Key( option );
			// 枠消し量の取得.
			s_MmbPartsInch.pc_ComPartsFreeSizeInput->getValue( sf_EraseSize );
			break;
		case TYPE_UnitSystemInch_Number:
			b_EraseFrameError = s_MmbPartsInch.pc_ComPartsFreeSizeInput->proc10Key( option );
			if( 0 <= ss_MmbSelDirection && ss_MmbSelDirection < ( ( uchar )( sizeof( b_AryEraseFrameError ) / sizeof( Bool ) ) ) ) {
				b_AryEraseFrameError[ss_MmbSelDirection] = b_EraseFrameError;
			}
			if( True == b_EraseFrameError ) {
				// エラー状態セット.
				onlyPanel.setErrorNumberFieldPartsKind( EP_ErrorPartsKind_NumberField );
			}
			// 枠消し量の取得.
			s_MmbPartsInch.pc_ComPartsFreeSizeInput->getValue( sf_EraseSize );
			break;
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return;
	}
	switch( ss_MmbSelDirection ) {
		case PCGD_SelFrameEraseFrame:	s_MmbFrameEraseInfo.sf_FrameSize = sf_EraseSize;	break;	// 枠.
		case PCGD_SelFrameEraseTop:		s_MmbFrameEraseInfo.sf_TopSize = sf_EraseSize;		break;	// 上.
		case PCGD_SelFrameEraseLeft:	s_MmbFrameEraseInfo.sf_LeftSize = sf_EraseSize;		break;	// 左.
		case PCGD_SelFrameEraseRight:	s_MmbFrameEraseInfo.sf_RightSize = sf_EraseSize;	break;	// 右.
		case PCGD_SelFrameEraseBottom:	s_MmbFrameEraseInfo.sf_BottomSize = sf_EraseSize;	break;	// 下.
		default:	LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	break;
	}
}
//概要    :枠消し処理共通クラス：クリアー
void PCGC_FrameEraseCom::procClear( uchar option )
{
	float sf_EraseSize = 0.0f;
	switch( PnlComGetUnitSystem() )
	{
		// mm（数値）.
		case TYPE_UnitSystemMM_Number:
			s_MmbPartsMetric.pc_ComPartsFreeSizeInput->procClear( option );
			// 枠消し量の取得.
			s_MmbPartsMetric.pc_ComPartsFreeSizeInput->getValue( sf_EraseSize );
			break;
		// inch（分数／数値）.
		case TYPE_UnitSystemInch_Fraction:
		case TYPE_UnitSystemInch_Number:
			s_MmbPartsInch.pc_ComPartsFreeSizeInput->procClear( option );
			// 枠消し量の取得.
			s_MmbPartsInch.pc_ComPartsFreeSizeInput->getValue( sf_EraseSize );
			break;
		default:
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return;
	}
	switch( ss_MmbSelDirection ) {
		case PCGD_SelFrameEraseFrame:	s_MmbFrameEraseInfo.sf_FrameSize = sf_EraseSize;	break;	// 枠.
		case PCGD_SelFrameEraseTop:		s_MmbFrameEraseInfo.sf_TopSize = sf_EraseSize;		break;	// 上.
		case PCGD_SelFrameEraseLeft:	s_MmbFrameEraseInfo.sf_LeftSize = sf_EraseSize;		break;	// 左.
		case PCGD_SelFrameEraseRight:	s_MmbFrameEraseInfo.sf_RightSize = sf_EraseSize;	break;	// 右.
		case PCGD_SelFrameEraseBottom:	s_MmbFrameEraseInfo.sf_BottomSize = sf_EraseSize;	break;	// 下.
		default:	LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	break;
	}
}
//概要    :枠消し処理共通クラス：メトリック系：最小値のチェック
Bool PCGC_FrameEraseCom::checkMinValueMetric()
{
	float sf_DummyMax = 0.0f;
	// 最小値の取得と補正.
	float sf_MinValue = 0.0f;
	s_MmbPartsMetric.pc_ComPartsFreeSizeInput->getMinValue( sf_MinValue );
	procCorrectMaxMin( sf_DummyMax, sf_MinValue );
	// 枠選択中.
	if( PCGD_SelFrameEraseFrame == ss_MmbSelDirection ) {
		float sf_FrameSize = s_MmbFrameEraseInfo.sf_FrameSize;
		procCorrectMaxMin( sf_DummyMax, sf_FrameSize );
		if( ( 0.0f != sf_FrameSize ) && ( sf_FrameSize < sf_MinValue ) ) {
			// エラー設定.
			s_MmbPartsMetric.pc_ComPartsFreeSizeInput->setValue( sf_FrameSize );
			s_MmbPartsMetric.pc_ComPartsFreeSizeInput->setError( True );
			return False;
		}
	} else {
		float sf_TopSize = s_MmbFrameEraseInfo.sf_TopSize;
		procCorrectMaxMin( sf_DummyMax, sf_TopSize );
		if( ( 0.0f != sf_TopSize ) && ( sf_TopSize < sf_MinValue ) ) {
			// エラー設定.
			ss_MmbSelDirection = PCGD_SelFrameEraseTop;
			s_MmbPartsMetric.pc_ComPartsFreeSizeInput->setValue( sf_TopSize );
			s_MmbPartsMetric.pc_ComPartsFreeSizeInput->setError( True );
			return False;
		}
		float sf_LeftSize = s_MmbFrameEraseInfo.sf_LeftSize;
		procCorrectMaxMin( sf_DummyMax, sf_LeftSize );
		if( ( 0.0f != sf_LeftSize ) && ( sf_LeftSize < sf_MinValue ) ) {
			// エラー設定.
			ss_MmbSelDirection = PCGD_SelFrameEraseLeft;
			s_MmbPartsMetric.pc_ComPartsFreeSizeInput->setValue( sf_LeftSize );
			s_MmbPartsMetric.pc_ComPartsFreeSizeInput->setError( True );
			return False;
		}
		float sf_RightSize = s_MmbFrameEraseInfo.sf_RightSize;
		procCorrectMaxMin( sf_DummyMax, sf_RightSize );
		if( ( 0.0f != sf_RightSize ) && ( sf_RightSize < sf_MinValue ) ) {
			// エラー設定.
			ss_MmbSelDirection = PCGD_SelFrameEraseRight;
			s_MmbPartsMetric.pc_ComPartsFreeSizeInput->setValue( sf_RightSize );
			s_MmbPartsMetric.pc_ComPartsFreeSizeInput->setError( True );
			return False;
		}
		float sf_BottomSize = s_MmbFrameEraseInfo.sf_BottomSize;
		procCorrectMaxMin( sf_DummyMax, sf_BottomSize );
		if( ( 0.0f != sf_BottomSize ) && ( sf_BottomSize < sf_MinValue ) ) {
			// エラー設定.
			ss_MmbSelDirection = PCGD_SelFrameEraseBottom;
			s_MmbPartsMetric.pc_ComPartsFreeSizeInput->setValue( sf_BottomSize );
			s_MmbPartsMetric.pc_ComPartsFreeSizeInput->setError( True );
			return False;
		}
	}
	return True;
}
