//概要    :枠消し処理共通クラス：枠消し量設定
Bool PCGC_FrameEraseCom::setFrameErase()
{
	Bool b_Result = False;
	Bool b_Check = False;
	switch( PnlComGetUnitSystem() )
	{
		// mm（数値）.
		case TYPE_UnitSystemMM_Number:
			// 最小値のチェック.
			b_Check = checkMinValueMetric();
			break;
		// inch（分数／数値）.
		case TYPE_UnitSystemInch_Fraction:
		case TYPE_UnitSystemInch_Number:
			// 最小値のチェック.
			b_Check = checkMinValueInch();
			break;
		default:
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return False;
	}
	if( True == b_Check ) {
		const Bool b_FrameErase = ( ( PCGD_SelFrameEraseFrame == ss_MmbSelDirection ) ? True : False );
		// 枠消し量の取得.
		const float sf_EraseTop    = ( ( b_FrameErase ) ? s_MmbFrameEraseInfo.sf_FrameSize : s_MmbFrameEraseInfo.sf_TopSize );
		const float sf_EraseLeft   = ( ( b_FrameErase ) ? s_MmbFrameEraseInfo.sf_FrameSize : s_MmbFrameEraseInfo.sf_LeftSize );
		const float sf_EraseRight  = ( ( b_FrameErase ) ? s_MmbFrameEraseInfo.sf_FrameSize : s_MmbFrameEraseInfo.sf_RightSize );
		const float sf_EraseBottom = ( ( b_FrameErase ) ? s_MmbFrameEraseInfo.sf_FrameSize : s_MmbFrameEraseInfo.sf_BottomSize );
		if( ( 0.0f == sf_EraseTop ) && ( 0.0f == sf_EraseLeft ) && ( 0.0f == sf_EraseRight ) && ( 0.0f == sf_EraseBottom ) ) {
			// 入力エラー状態.
			if( NULL != s_MmbPartsMetric.pc_ComPartsFreeSizeInput ) {
				s_MmbPartsMetric.pc_ComPartsFreeSizeInput->setError( True );
			}
			if( NULL != s_MmbPartsInch.pc_ComPartsFreeSizeInput ) {
				s_MmbPartsInch.pc_ComPartsFreeSizeInput->setError( True );
			}
			b_EraseFrameError = True;
			if( 0 <= ss_MmbSelDirection && ss_MmbSelDirection < ( ( uchar )( sizeof( b_AryEraseFrameError ) / sizeof( Bool ) ) ) ) {
				b_AryEraseFrameError[ss_MmbSelDirection] = b_EraseFrameError;
			}
			// エラー状態セット.
			onlyPanel.setErrorNumberFieldPartsKind( EP_ErrorPartsKind_NumberField );
			return False;
		}
		// 枠消し量の設定.
		pc_MmbOriginalErase->setTop( sf_EraseTop );
		pc_MmbOriginalErase->setLeft( sf_EraseLeft );
		pc_MmbOriginalErase->setRight( sf_EraseRight );
		pc_MmbOriginalErase->setBottom( sf_EraseBottom );
		// 枠消しか各サイドイレースかの設定.
		pc_MmbOriginalErase->setFlameOrEachSideErase( b_FrameErase );
		b_Result = True;
	}
	return b_Result;
}
//概要    :枠消し処理共通クラス：左エリア表示処理・枠消し
struct PCGS_LeftAreaFrameErase {
	Bool b_Top;
	Bool b_Left;
	Bool b_Right;
	Bool b_Bottom;
	short ss_Select;
};
void PCGC_FrameEraseCom::setupLeftFrameErase()
{
	// 枠消し画像ローテーションテーブル
	PCGS_LeftAreaFrameErase s_LeftAreaFrameEraseTbl[] = {
//		 上 左 右 下  select値
		{ 0, 0, 0, 0,	 0 		},		// OFF
		{ 0, 0, 0, 1,	 5 		},		// 下
		{ 0, 0, 1, 0,	 4 		},		// 右
		{ 0, 0, 1, 1,	11 		},		// 右＋下
		{ 0, 1, 0, 0,	 3 		},		// 左
		{ 0, 1, 0, 1,	10 		},		// 左＋下
		{ 0, 1, 1, 0,	 9 		},		// 左＋右
		{ 0, 1, 1, 1,	15 		},		// 左＋右＋下
		{ 1, 0, 0, 0,	 2 		},		// 上
		{ 1, 0, 0, 1,	 8 		},		// 上＋下
		{ 1, 0, 1, 0,	 7 		},		// 上＋右
		{ 1, 1, 0, 0,	 6 		},		// 上＋左
		{ 1, 0, 1, 1,	14 		},		// 上＋右＋下
		{ 1, 1, 0, 1,	13 		},		// 上＋左＋下
		{ 1, 1, 1, 0,	12 		},		// 上＋左＋右
		{ 1, 1, 1, 1,	 1 		},		// 枠
	};
	const uchar uc_LeftAreaFrameEraseTbl = ( uchar )( sizeof( s_LeftAreaFrameEraseTbl ) / sizeof( PCGS_LeftAreaFrameErase ) );
	short ss_FrameErase = 0;
	// 現在の枠消し情報を取得
	Bool b_TopSize		= ( 0 == s_MmbFrameEraseInfo.sf_TopSize )?0:1;
	Bool b_LeftSize		= ( 0 == s_MmbFrameEraseInfo.sf_LeftSize )?0:1;
	Bool b_RightSize	= ( 0 == s_MmbFrameEraseInfo.sf_RightSize )?0:1;
	Bool b_BottomSize	= ( 0 == s_MmbFrameEraseInfo.sf_BottomSize )?0:1;
	for( uchar i = 0; i < uc_LeftAreaFrameEraseTbl; i++ ) {
		if( ( b_TopSize    == s_LeftAreaFrameEraseTbl[i].b_Top )
		    && ( b_LeftSize   == s_LeftAreaFrameEraseTbl[i].b_Left )
		    && ( b_RightSize  == s_LeftAreaFrameEraseTbl[i].b_Right )
		    && ( b_BottomSize == s_LeftAreaFrameEraseTbl[i].b_Bottom ) ) {
			// テーブルの情報と現在の枠消し情報が全て一致
			ss_FrameErase = s_LeftAreaFrameEraseTbl[i].ss_Select;
			// 枠が設定中の場合は枠アイコンを表示する(全辺「消去しない」時は枠消しOFFアイコンを表示)
			if( PCGD_SelFrameEraseFrame == ss_MmbSelDirection ) {
				ss_FrameErase = ( 0 == s_MmbFrameEraseInfo.sf_FrameSize )?0:1;
			}
			break;
		}
	}
	// 画像を選択
	if( TYPE_UnitSystemMM_Number == PnlComGetUnitSystem() )
	{
		s_MmbPartsMetric.pc_Rot_LeftFrameErase->changeGraphic( ( uchar )ss_FrameErase );			// 左エリア・枠消し(メトリック)
	} else {
		s_MmbPartsInch.pc_Rot_LeftFrameErase->changeGraphic( ( uchar )ss_FrameErase );		// 左エリア・枠消し(インチ)
	}
}

