//概要    :折目消し処理共通クラス：ボタン（押された）
void PCGC_CreaseEraseCom::procButtonOn( uchar option )
{
	if( ( option == s_MmbParts.uc_KeyIdSizeDown )
	    || ( option == s_MmbParts.uc_KeyIdSizeUp )
	    || ( option == s_MmbParts.uc_KeyIdChangeDigit ) ) {
		// ＋／－キーのボタン
		s_MmbParts.pc_ComPartsFreeSizeInput->procButtonOn( option );
		// 設定値をC_APIに設定
		float sf_EraseSize;
		s_MmbParts.pc_ComPartsFreeSizeInput->getValue( sf_EraseSize );
// comment 2016/05/03 HCLT-Ashok.D [CQ529019] Null check activity.
//		pc_MmbJob->getJobSpec()->pc_Scan->c_OriginalErase.setCenter( sf_EraseSize );
	    if ( NULL != pc_MmbJob ) {
	    	pc_MmbJob->getJobSpec()->pc_Scan->c_OriginalErase.setCenter( sf_EraseSize );
	    }
	}
	setCenterErase();
}
//概要    :折目消し処理共通クラス：画面セットアップ
void PCGC_CreaseEraseCom::setupGamen( short option )
{
	// 最小値0判定
	float sf_MinValue;
	float sf_NowEraseSize;
	s_MmbParts.pc_ComPartsFreeSizeInput->getMinValue( sf_MinValue );
	s_MmbParts.pc_ComPartsFreeSizeInput->getValue( sf_NowEraseSize );
	if( ( 0.0f == sf_NowEraseSize ) && ( 0.0f != sf_MinValue ) ) {
		// s_MmbPartsInchが0以外の値で、かつ現在の値が0ならば初期値に戻す.
		s_MmbParts.pc_ComPartsFreeSizeInput->setInitialValue();
	} else if( ( 0.0f == sf_NowEraseSize ) && ( 0.0f == sf_MinValue ) ) {
		// 最小値が0で、かつ現在の値が0ならば消去量=0を設定.
		s_MmbParts.pc_ComPartsFreeSizeInput->setValue( sf_NowEraseSize, True );
	}
	// 値を表示する
	s_MmbParts.pc_ComPartsFreeSizeInput->showFreeSizeInput();
}
//概要    :折目消し処理共通クラス：画面開始処理
void PCGC_CreaseEraseCom::startGamen()
{
// comment 2016/05/03 HCLT-Ashok.D [CQ529019] Null check activity.
	if ( NULL == pc_MmbJob ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	// 消去量の取得
	float sf_EraseSize = pc_MmbJob->getJobSpec()->pc_Scan->c_OriginalErase.getCenter();
	// ミリ／インチ切り替え時に起こる最大値/最小値オーバーを補正
	sf_EraseSize = reviseMersurementUnit( sf_EraseSize, PCGD_MaxCreaseErase, PCGD_MaxCreaseEraseInch, PCGD_MaxCreaseEraseInchMM, PCGD_MinCreaseErase, PCGD_MinCreaseEraseInch, PCGD_MinCreaseEraseInchMM );
	if( 0.0f == sf_EraseSize ) {
		sf_EraseSize = s_MmbParts.sf_Default;
		pc_MmbJob->getJobSpec()->pc_Scan->c_OriginalErase.setCenter( sf_EraseSize );
		// 入力可能にセット
		s_MmbParts.pc_ComPartsFreeSizeInput->setEnable( True );
		if( 0.0f == s_MmbParts.sf_Default ) {
			s_MmbParts.pc_ComPartsFreeSizeInput->setInitialValue();
		} else {
			s_MmbParts.pc_ComPartsFreeSizeInput->setValue( sf_EraseSize );
		}
	} else {
		// 入力可能にセット
		s_MmbParts.pc_ComPartsFreeSizeInput->setEnable( True );
		s_MmbParts.pc_ComPartsFreeSizeInput->setValue( sf_EraseSize );
	}
}
//概要    :折目消し処理共通クラス：テンキー
void PCGC_CreaseEraseCom::proc10Key( uchar option )
{
	// テンキー処理.
	s_MmbParts.pc_ComPartsFreeSizeInput->proc10Key( option );
	// 消去量の取得.
	float sf_EraseSize = 0;
	s_MmbParts.pc_ComPartsFreeSizeInput->getValue( sf_EraseSize );
	// 設定値を登録する
// comment 2016/05/03 HCLT-Ashok.D [CQ529019] Null check activity.
//	pc_MmbJob->getJobSpec()->pc_Scan->c_OriginalErase.setCenter( sf_EraseSize );
	if ( NULL != pc_MmbJob ) {
		pc_MmbJob->getJobSpec()->pc_Scan->c_OriginalErase.setCenter( sf_EraseSize );
	}
	setCenterErase();
}
//概要    :折目消し処理共通クラス：クリアー
void PCGC_CreaseEraseCom::procClear( uchar option )
{
	// クリアー処理.
	switch( PnlComGetUnitSystem() )
	{
		case TYPE_UnitSystemMM_Number:
		case TYPE_UnitSystemInch_Fraction:	s_MmbParts.pc_ComPartsFreeSizeInput->procClear( option );	break;	// mm表示, inch表示（分数）
		case TYPE_UnitSystemInch_Number:	s_MmbParts.pc_ComPartsFreeSizeInput->setInitialValue();	break;	// inch表示（少数）
		default:	LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	return;
	}
	// 設定値を登録する
// comment 2016/05/03 HCLT-Ashok.D [CQ529019] Null check activity.
//	pc_MmbJob->getJobSpec()->pc_Scan->c_OriginalErase.setCenter( 0.0f );
	if ( NULL != pc_MmbJob ) {
		pc_MmbJob->getJobSpec()->pc_Scan->c_OriginalErase.setCenter( 0.0f );
	}
	setCenterErase();
}
//概要    :折目消し処理共通クラス：折目消し量設定
void PCGC_CreaseEraseCom::setCenterErase( )
{
	float sf_FrameSize;
	if( pc_MmbJob == PnlComGetJobCopy() ) {
		// 設定値を登録する
		sf_FrameSize = pc_MmbJob->getJobSpec()->pc_Scan->c_OriginalErase.getCenter();
		// コピー動作時：OperationSettingのCopy側へ情報設定
		PnlComGetOperationSetting()->setEraseCrease( sf_FrameSize );
	}
}
