//概要    :小文字→大文字変換
void toUpperString( char* sc_LowerString, char* sc_UpperString )
{
	// sc_LowerStringとsc_UpperStringのサイズは同一にしておくこと
	char sc_UpperCode;
	for( short i = 0; '\0' != *sc_LowerString; i++, sc_LowerString++ ) {
		sc_UpperCode = 0;
		if( ( 'a' <= *sc_LowerString ) && ( 'z'>= *sc_LowerString ) ) {
			// 文字列内に小文字を発見した
			sc_UpperCode = ( 'a' - 'A' );
		}
		*sc_UpperString++ = ( char )( *sc_LowerString - sc_UpperCode );
	}
	*sc_UpperString = '\0';
}
//概要    :*,#キー押下時の文字列操作.
void setSharpAsterKey( char* sc_dataBuff, 		//文字列連結バッファ.
                       uchar option )			//キーオプション.
{
	if( ( sc_dataBuff == NULL ) || ( ( option != 10 ) && ( option != 11 ) ) ) {
		return;
	}
	char sc_key[2];
	memset( sc_key,'\0',sizeof( sc_key ) );
	if( option == 11 ) {
		sc_key[0] = 0x2A;		//*.
	} else {
		sc_key[0] = 0x23;		//#.
	}
	strcat( sc_dataBuff, ( const char* )sc_key );
}
//概要　：設定変更情報クラス(分割読み込み停止中)   : バックアップ領域取得.
void PDPC_SettingChangeBasicInfo::getBasicInfoErea( PDPS_SetChangeBackupInfo** ps_SetChangeBasicInfo, short option )
{
	// 設定変更画面内戻る時.
	if( 0 == option ) {
		( *ps_SetChangeBasicInfo ) = &s_MmbSetChangeReturnInfo;
	} else if( 1 == option ) {
		// 読込み停止中画面遷移時.
		TYPC_Common* pc_Common = comPanelJob->getJobSpec()->pc_Common;
		// ジョブタイプが割り込みコピーの時.
		if( TYPE_JobTypeIntCopy == pc_Common->c_JobType.getJobType() ) {
			// 割り込み用の領域を返す.
			( *ps_SetChangeBasicInfo ) = &s_MmbSetChangeBasicIntModeCopyInfo;
		} else {
			( *ps_SetChangeBasicInfo ) = &s_MmbSetChangeBasicInfo;
		}
	} else { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
}
