	ps_SetChangeBasicInfo->c_MmbMagTemplate = pc_Common->c_Mag.getMag();
	ps_SetChangeBasicInfo->b_AmsOn = pc_Common->c_Mag.getAmsOn();
	ps_SetChangeBasicInfo->b_EraseAll = pc_Scan->c_OriginalErase.getFlameOrEachSideErase();		// 枠消し(True:枠、False:枠以外)
	ps_SetChangeBasicInfo->sf_EraseFrameTop = pc_Scan->c_OriginalErase.getTop();
	ps_SetChangeBasicInfo->sf_EraseFrameLeft = pc_Scan->c_OriginalErase.getLeft();
	ps_SetChangeBasicInfo->sf_EraseFrameRight = pc_Scan->c_OriginalErase.getRight();
	ps_SetChangeBasicInfo->sf_EraseFrameBottom = pc_Scan->c_OriginalErase.getBottom();
	ps_SetChangeBasicInfo->sf_EraseCreaseCopy = pc_Scan->c_OriginalErase.getCenter();
	ps_SetChangeBasicInfo->b_AutoOriginalSize = pc_Scan->c_OriginalSize.getAutoSize();
	ps_SetChangeBasicInfo->c_PaperSize = pc_Scan->c_OriginalSize.getPaperSize();
	ps_SetChangeBasicInfo->b_ApsOn = pc_Print->c_PaperTray.getApsOn();
	ps_SetChangeBasicInfo->e_FeedTray = pc_Print->c_PaperTray.getFeedTray();
	ps_SetChangeBasicInfo->b_FeedTrayEnable = pc_Print->c_PaperTray.getFeedTrayEnable();
	ps_SetChangeBasicInfo->e_OverridePaper = pc_Print->c_PaperTray.getOverridePaper();
	ps_SetChangeBasicInfo->b_AcsOn = pc_Scan->getAcsOn();
	ps_SetChangeBasicInfo->e_ColorMode = pc_Common->getColorMode();
	ps_SetChangeBasicInfo->b_2ColorOn = pc_Common->c_2ColorMode.get2ColorOn();
	ps_SetChangeBasicInfo->e_2ColorMono = pc_Common->c_2ColorMode.getMonoColor();
	ps_SetChangeBasicInfo->b_MonoColorOn = pc_Common->c_MonoColor.getMonoColorOn();
	ps_SetChangeBasicInfo->e_MonoColor = pc_Common->c_MonoColor.getMonoColor();
	ps_SetChangeBasicInfo->e_MonoColorMode = pc_Common->c_MonoColor.getMonoColorMode();
	ps_SetChangeBasicInfo->e_PrintBindDirection = pc_Print->c_BindDirection.getBindDirection();
	ps_SetChangeBasicInfo->e_StapleMode = pc_Print->c_Finishing.getStapleMode();
	ps_SetChangeBasicInfo->e_StaplePosition = pc_Print->c_Finishing.getStaplePosition();
	ps_SetChangeBasicInfo->b_StaplePositionAuto = pc_Print->c_Finishing.getStaplePositionAuto();
	ps_SetChangeBasicInfo->e_PunchMode = pc_Print->c_Finishing.getPunchMode();
	ps_SetChangeBasicInfo->e_PunchPosition = pc_Print->c_Finishing.getPunchPosition();
	ps_SetChangeBasicInfo->b_PunchPositionAuto = pc_Print->c_Finishing.getPunchPositionAuto();
	ps_SetChangeBasicInfo->e_OpenDirection = pc_Print->c_BindDirection.getOpenDirection();
