//概要    :下地除去処理共通クラス共通部：下地除去設定(デフォルト設定)
void PCGC_BackDensityComCom::setDensityDefault( Bool b_Type, Bool b_UseType )
{
// comment 2016/05/03 HCLT-Ashok.D [CQ529019] Null check activity.
	if ( NULL == pc_MmbJob ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	static Bool _b_BackupUseType = True;
	if( True == b_Type ) {
		// Color
		TYPE_BackDensity e_BackLevel;
		if( True == b_UseType ) {
			// Default
			if( pc_MmbJob->getJobSpec()->pc_Common->c_ImageAdjust.getBackDensity() == TYPE_BackDensityLevelN		// 現在値が普通.
			    && _b_BackupUseType == True ) {					// 前押下が自動ではない.
				bl_MmBuzzerCancel = True;						// キー受付音鳴らさない.
			}
			e_BackLevel = TYPE_BackDensityLevelN;
		} else {
			// UnSelect
			e_BackLevel = TYPE_BackDensityUnselect;
		}
		_b_BackupUseType = b_UseType;
		pc_MmbJob->getJobSpec()->pc_Common->c_ImageAdjust.setBackDensity( e_BackLevel );
	} else {
		// Mono
		TYPE_MonoDensity e_MonoLevel;
		if( True == b_UseType ) {
			// Default
			if( pc_MmbJob->getJobSpec()->pc_Common->c_ImageAdjust.getMonoDensity() == TYPE_MonoDensityN			// 現在値が普通.
			    && _b_BackupUseType == True ) {					// 前押下が自動ではない.
				bl_MmBuzzerCancel = True;						// キー受付音鳴らさない.
			}
			e_MonoLevel = TYPE_MonoDensityN;
		} else {
			// UnSelect
			e_MonoLevel = TYPE_MonoDensityUnselect;
		}
		_b_BackupUseType = b_UseType;
		pc_MmbJob->getJobSpec()->pc_Common->c_ImageAdjust.setMonoDensity( e_MonoLevel );
	}
}
//概要    :下地除去処理共通クラス共通部：下地除去設定
void PCGC_BackDensityComCom::setDensity( Bool b_Type, uchar uc_Density )
{
// comment 2016/05/03 HCLT-Ashok.D [CQ529019] Null check activity.
	if ( NULL == pc_MmbJob ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	if( True == b_Type ) {
		// Color
		pc_MmbJob->getJobSpec()->pc_Common->c_ImageAdjust.setBackDensity( ( TYPE_BackDensity )uc_Density );
	} else {
		// Mono
		pc_MmbJob->getJobSpec()->pc_Common->c_ImageAdjust.setMonoDensity( ( TYPE_MonoDensity )uc_Density );;
	}
}
//概要    :下地除去処理共通クラス共通部：下地除去取得
uchar PCGC_BackDensityComCom::getDensity( Bool b_Type )
{
// comment 2016/05/03 HCLT-Ashok.D [CQ529019] Null check activity.
	if ( NULL == pc_MmbJob ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return TYPE_BackDensityUnselect; // returning default value of back density.;
	}
	TYPE_BackDensity e_BackDensity;
	TYPE_MonoDensity e_MonoDensity;
	if( True == b_Type ) {
		// Color
		e_BackDensity = pc_MmbJob->getJobSpec()->pc_Common->c_ImageAdjust.getBackDensity();
		return ( uchar )e_BackDensity;
	}
	// Mono
	e_MonoDensity = pc_MmbJob->getJobSpec()->pc_Common->c_ImageAdjust.getMonoDensity();
	return ( uchar )e_MonoDensity;
}
//概要    :下地除去処理共通クラス共通部：ゲージレベルUp/Down処理
void PCGC_BackDensityComCom::levelUpDown( Bool b_Type, Bool& b_AutoExpo, uchar option )
{
	const uchar uc_LoopCount = ( True == b_Type )?uc_BackDensityLevelTbl:uc_MonoDensityLevelTbl;
	for( uchar i = 0; i < uc_LoopCount; i++ ) {
		if( True == b_Type ) {
			// Color
			TYPE_BackDensity e_BackDensity = ( TYPE_BackDensity )getDensity( b_Type );
			if( e_BackDensity == e_BackDensityLevelTbl[i] ) {
				// C_APIとテーブルの値が一致した
				if( ( option == s_MmbParts.uc_KeyIdDark ) && ( uc_MmbMax < ( uchar )e_BackDensity ) ) {
					//「こく」ボタンの場合.
					b_AutoExpo = False;
					setDensity( b_Type, ( uchar )e_BackDensityLevelTbl[i-1] );
					break;
				} else if( ( option == s_MmbParts.uc_KeyIdLight ) && ( uc_MmbMin > ( uchar )e_BackDensity ) ) {
					//「うすく」ボタンの場合.
					b_AutoExpo = False;
					setDensity( b_Type, ( uchar )e_BackDensityLevelTbl[i+1] );
					break;
				} else {
					bl_MmBuzzerCancel = True;						// キー受付音鳴らさない.
				}
			}
		} else {
			// Mono
			TYPE_MonoDensity e_MonoDensity = ( TYPE_MonoDensity )getDensity( b_Type );
			if( e_MonoDensity == e_MonoDensityLevelTbl[i] ) {
				// C_APIとテーブルの値が一致した
				if( ( option == s_MmbParts.uc_KeyIdDark ) && ( uc_MmbMax < ( uchar )e_MonoDensity ) ) {
					//「こく」ボタンの場合.
					b_AutoExpo = False;
					setDensity( b_Type, ( uchar )e_MonoDensityLevelTbl[i-1] );
					break;
				} else if( ( option == s_MmbParts.uc_KeyIdLight ) && ( uc_MmbMin > ( uchar )e_MonoDensity ) ) {
					//「うすく」ボタンの場合.
					b_AutoExpo = False;
					setDensity( b_Type, ( uchar )e_MonoDensityLevelTbl[i+1] );
					break;
				} else {
					bl_MmBuzzerCancel = True;						// キー受付音鳴らさない.
				}
			}
		}
	}
}
//概要    :下地除去処理共通クラス共通部：ボタン（押された）.
void PCGC_BackDensityComCom::procButtonOn( Bool b_Type, uchar option )
{
// comment 2016/05/03 HCLT-Ashok.D [CQ529019] Null check activity.
	if ( NULL == pc_MmbJob ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	Bool 			 b_On = False;
	Bool			 b_AutoExpo = pc_MmbJob->getJobSpec()->pc_Common->c_ImageAdjust.getAutoExpo();
	bl_MmBuzzerCancel = False;		// キー受付音鳴らす.
	if( ( option == s_MmbParts.uc_KeyIdDark ) || ( option == s_MmbParts.uc_KeyIdLight ) ) {
		// 「こく」/「うすく」キー押下.
		if( True == combinationCheck( e_MmbCombManuDensity, pc_MmbJob ) ) {
			if( True == b_AutoExpo ) {
				// 自動が押されていた場合は0に設定する.
				b_AutoExpo = False;
				b_On = True;
				setDensityDefault( b_Type, True );
			}
		}
	} else if( option == s_MmbParts.uc_KeyIdNomal ) {
		// 「ふつう」キー押下.
		if( True == combinationCheck( e_MmbCombManuDensity, pc_MmbJob ) ) {
			b_AutoExpo = False;
			b_On = True;
			setDensityDefault( b_Type, True );
		}
	} else if( option == s_MmbParts.uc_KeyIdAuto ) {
		// 「自動」キー押下.
		if( True == combinationCheck( e_MmbCombAutoDensity, pc_MmbJob ) ) {
			b_AutoExpo = True;
			b_On = True;
			setDensityDefault( b_Type, False );
		}
	} else { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }
	// ゲージUp/Downの判定
	if( False == b_On ) {
		levelUpDown( b_Type, b_AutoExpo, option );
	}
	// 更新値をC_APIに設定
	pc_MmbJob->getJobSpec()->pc_Common->c_ImageAdjust.setAutoExpo( b_AutoExpo );
}
