void PCGC_BackDensityCom::setupGamen( short option )
{
// comment 2016/05/03 HCLT-Ashok.D [CQ529019] Null check activity.
	if ( NULL == pc_MmbJob ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	// 自動ボタンの表示
	Bool b_On = isOn( e_MmbCombAutoDensity, pc_MmbJob );
	s_MmbParts.pc_KeyAuto->select( b_On );
	// ゲージ表示
	TYPE_BackDensity e_BackDensity = pc_MmbJob->getJobSpec()->pc_Common->c_ImageAdjust.getBackDensity();
	uchar			 uc_Select = 1;
	if( True == b_On ) {
		// 自動の場合はカーソル無しの画像を表示
		uc_Select = 0;
	} else {
		for( uchar i = 0; i < uc_BackDensityLevelTbl; i++, uc_Select++ ) {
			if( e_BackDensity == e_BackDensityLevelTbl[i] ) {
				// 現在C_APIに設定されている値とテーブルの値が一致した
				break;
			}
		}
	}
	s_MmbParts.pc_GraphGuage->changeGraphic( uc_Select );
}
