//概要    :画面表示用共通関数 : 給紙口カセットの紙残量詳細(％)を取得
short getRemainPaper( const TYPE_FeedTray e_FeedTray )
{
	short ss_Percent = 0;
	APIC_FeedTray* pc_FeedTray = PnlComGetFeedTray();
	// 用紙残量取得.
	short sc_RemainPaper = pc_FeedTray->getRemainPaper( e_FeedTray );
	// 総収納可能用紙枚数取得.
	short sc_TotalPaper = pc_FeedTray->getTotalPaper( e_FeedTray );
	// 残％算出.
	if( sc_TotalPaper != 0 ) {
		// ＬＣＣ、ＬＣＴトレイの場合
		Bool b_LCCLCT = False;
		if( e_FeedTray != TYPE_FeedTrayUnselect ) {
			if( pc_FeedTray->getTrayType( e_FeedTray ) == TYPE_TrayTypeLCC
			    || pc_FeedTray->getTrayType( e_FeedTray ) == TYPE_TrayTypeLCT ) {
				b_LCCLCT = True;
			}
		}
		if( b_LCCLCT == True ) {
			// ＬＣＴトレイの場合.
			ss_Percent = ( short )( ( ( float )sc_RemainPaper / ( float )sc_TotalPaper ) * 100.0f );
		} else {
			// マーク表示が違うため、特殊値(-1)を設定する.
			ss_Percent = -1;
		}
	} else {
		// 総収納可能用紙枚数が０の場合(ありえない) .
		// ペーパーエンプティ.
		ss_Percent = 0 ;
	}
	return ss_Percent;
}
