//概要    :用紙種類・サイズの再設定
void PnlComResetFeedSizeKind( TYPC_Print* pc_Print )
{
	if( NULL == pc_Print ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	APIC_FeedTray* pc_FeedTray = PnlComGetFeedTray();
	// 選択トレイの取得.
	const TYPE_FeedTray e_FeedTray = pc_Print->c_PaperTray.getFeedTray();
	if( ( False == pc_Print->c_PaperTray.getApsOn() ) && ( TYPE_FeedTrayMax > e_FeedTray ) ) {
		TYPC_PaperType c_PaperType = pc_FeedTray->getPaperType( e_FeedTray );
		TYPC_PaperSize c_PaperSize = pc_FeedTray->getPaperSize( e_FeedTray );
// comment 2015/05/14 OPS1-Sky村井 [Helios][CQ511775] コピーセキュリティー不適合用紙種類警告がでない.
//		pc_Print->c_PaperType = c_PaperType;
		pc_Print->setPaperType(c_PaperType);
		pc_Print->c_PaperSize = c_PaperSize;
	}
}
