// ===============================================================================================
//	［クラス］	PCGC_FaxUserCom : FAXユーザ共通
//	概要     : 応用設定パラメータ値（読込サイズ）がデフォルトから変化したかどうかを判定する
//	戻り値   : Bool True/False （デフォルトから変化した / デフォルトから変化していない）
// ===============================================================================================
Bool isFaxOriginalSizeChange( TYPC_JobSpec* c_JobSpec )
{
	TYPC_Scan* pc_Scan = c_JobSpec->pc_Scan;
	Bool b_Return = True;		// デフォルトから変化あり
#ifdef DEF_A4_Cus	// VenusMLK OPS2 Sky高田(庸) 2015/07/21.
	if ( TYPE_SystemType_US == PnlComGetDestination() ) {
		if (TYPE_SizeCodeLetterSef == pc_Scan->c_OriginalSize.getPaperSize().e_SizeCode) {
			b_Return = False;
		}
	} else {
		if (TYPE_SizeCodeA4Sef == pc_Scan->c_OriginalSize.getPaperSize().e_SizeCode) {
			b_Return = False;
		}
	}
#else // DEF_A4_Cus	// VenusMLK OPS2 Sky高田(庸) 2015/07/21.
	// 現在のJobSpec値が工場出荷値と同じ場合は変化なし
	if( pc_Scan->c_OriginalSize.getAutoSize() == c_JobSpecFaxDefult.pc_Scan->c_OriginalSize.getAutoSize() ) {
		b_Return = False;	// デフォルトから変化なし
	}
#endif // DEF_A4_Cus	// VenusMLK OPS2 Sky高田(庸) 2015/07/21.
	return ( b_Return );
}
// ===============================================================================================
//	［クラス］	PCGC_FaxUserCom : FAXユーザ共通
//	概要     : 通信設定パラメータ値（Fコード送信）がデフォルトから変化したかどうかを判定する
//	戻り値   : Bool True/False （デフォルトから変化した / デフォルトから変化していない）
// ===============================================================================================
Bool isFaxFcodeTxChange( TYPC_JobSpec* c_JobSpec )
{
	TYPC_FaxAct* pc_FaxAct = &( c_JobSpec->pc_Fax->c_FaxAct );
	Bool b_Return;
	char sc_TxSubAddr[20+1];	// SUBアドレスID
	memset( sc_TxSubAddr, '\0', sizeof( sc_TxSubAddr ) );
	c_JobSpec->pc_Fax->c_FaxAct.getTxSubAddr( sc_TxSubAddr );
	if( ( pc_FaxAct->getTxMode() == TYPE_TxModeMailbox )		// 親展送信
	    || ( pc_FaxAct->getTxMode() == TYPE_TxModeRelayReq ) ) {	// 中継依頼送信
		b_Return = True;	// デフォルトから変化あり
	} else if( ( pc_FaxAct->getTxMode() == TYPE_TxModePcFax )
	           && ( '\0' != sc_TxSubAddr[0] ) ) {
		// PC-Fax送信(Fコード送信)に対応.
		b_Return = True;	// デフォルトから変化あり
	} else {
		b_Return = False;	// デフォルトから変化なし
	}
	return ( b_Return );
}
// ===============================================================================================
//	［クラス］	PCGC_FaxUserCom : FAXユーザ共通
//	概要     : 通信設定パラメータ値（ポーリング送信）がデフォルトから変化したかどうかを判定する
//	戻り値   : Bool True/False （デフォルトから変化した / デフォルトから変化していない）
// ===============================================================================================
Bool isFaxPollingTxChange( TYPC_JobSpec* c_JobSpec )
{
	if( NULL == c_JobSpec ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return ( False );
	}
	TYPC_Send* pc_Send = c_JobSpec->pc_Send;
	if( pc_Send == NULL ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return ( False );
	}
	TYPC_FaxCommon* pc_FaxCommon = &( c_JobSpec->pc_Fax->c_FaxCommon );
	if( pc_FaxCommon == NULL ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return ( False );
	}
	Bool b_Return = True;		// デフォルトから変化あり
	// 掲示板送信原稿登録ＯＮであるのに、掲示板ボックスNo.が設定されていない場合は、掲示板送信原稿登録ＯＦＦ
	if( ( pc_FaxCommon->getRegistBulletinTxOn() == True )
	    && ( pc_Send->c_ComSend.c_DirectAddressBook.pageBoxAddress( 1 )->getOn() == False ) ) {
		pc_FaxCommon->setRegistBulletinTxOn( False );
	}
	// 現在のJobSpec値が工場出荷値と同じ場合は変化なし
	if( ( pc_FaxCommon->getRegistPolledTxDocOn() == c_JobSpecFaxDefult.pc_Fax->c_FaxCommon.getRegistPolledTxDocOn() )	// Rev2.0修正
	    && ( pc_FaxCommon->getRegistBulletinTxOn()  == c_JobSpecFaxDefult.pc_Fax->c_FaxCommon.getRegistBulletinTxOn() ) ) {
		b_Return = False;	// デフォルトから変化なし
	}
	return ( b_Return );
}
// ===============================================================================================
//	［クラス］	PCGC_FaxUserCom : FAXユーザ共通
//	概要     : 通信設定パラメータ値（ポーリング受信）がデフォルトから変化したかどうかを判定する
//	戻り値   : Bool True/False （デフォルトから変化した / デフォルトから変化していない）
// ===============================================================================================
Bool isFaxPollingRxChange( TYPC_JobSpec* c_JobSpec )
{
	if( NULL == c_JobSpec ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return ( False );
	}
	TYPC_FaxAct* pc_FaxAct = &( c_JobSpec->pc_Fax->c_FaxAct );
	if( pc_FaxAct == NULL ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return ( False );
	}
	Bool b_Return;
	// 発呼モードが「ポーリング受信」または「掲示板ポーリング受信」の場合は
	// ポーリング受信が設定されていることになので「True」（＝デフォルトから変化あり）
	if( ( pc_FaxAct->getTxMode() == TYPE_TxModePollRx )			// ポーリング受信
	    || ( pc_FaxAct->getTxMode() == TYPE_TxModeBulPollRx ) ) {		// 掲示板ポーリング受信
		b_Return = True;	// デフォルトから変化あり
	}
	// 上記に該当しない場合は、デフォルトのままなので「False」
	else {
		b_Return = False;	// デフォルトから変化なし
	}
	return ( b_Return );
}
