// ===============================================================================================
//	［クラス］	PCGC_FaxUserCom : FAXユーザ共通
//	概要     : 通信設定パラメータ値（パスワード送信）がデフォルトから変化したかどうかを判定する
//	戻り値   : Bool True/False （デフォルトから変化した / デフォルトから変化していない）
// ===============================================================================================
Bool isFaxPasswordTxChange( TYPC_JobSpec* c_JobSpec )
{
	TYPC_FaxAct* pc_FaxAct = &( c_JobSpec->pc_Fax->c_FaxAct );
	if( pc_FaxAct == NULL ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return ( False );
	}
	Bool b_Return;
	char sc_TxLocalPwd[20+1];	// ローカルPasswordID
	memset( sc_TxLocalPwd, '\0', sizeof( sc_TxLocalPwd ) );
	c_JobSpec->pc_Fax->c_FaxAct.getTxLocalPwd( ( char* )&sc_TxLocalPwd );
	// 発呼モードが「閉域送信」の場合は「True」
	// パスワード送信が設定されていることになので「True」（＝デフォルトから変化あり）
	if( pc_FaxAct->getTxMode() == TYPE_TxModeClose ) {
		b_Return = True;	// デフォルトから変化あり
	} else if( ( TYPE_TxModePcFax == pc_FaxAct->getTxMode() )
	           && ( '\0' != sc_TxLocalPwd[0] ) ) {
		// PC-Fax送信(パスワード送信)に対応.
		b_Return = True;	// デフォルトから変化あり
	} else {
		b_Return = False;	// デフォルトから変化なし
	}
	return ( b_Return );
}
