// ===============================================================================================
//	［クラス］					 : グローバル関数
//	概要     : FaxIPポート番号のデフォルトを返す
//	備考     : デフォルトはネットワーク設定/ネットワークファクス設定/SMTP送信設定のポート番号
// ===============================================================================================
ushort getFaxIPAddressPortNoDefault()
{
	ushort	us_IpPortNo = PNLD_DefultIPFaxPortNo;		// ポート番号
	// SMTP送信設定API取得
	APIC_SmtpSendSetting* pc_SmtpSendSetting = APIC_SmtpSendSetting::newInstance();
	// SMTP送信設定に登録されているポート番号を取得
	if( pc_SmtpSendSetting != NULL ) {
		us_IpPortNo = pc_SmtpSendSetting->getPortNumber();
	}
	return us_IpPortNo;
}
// ===============================================================================================
//	［クラス］					 : グローバル関数
//	概要     : FaxIPポート番号のデフォルトで指定されたJob内のポート番号宛先を初期化する
//	戻り値   : void
//	備考     : デフォルトはネットワーク設定/ネットワークファクス設定/SMTP送信設定のポート番号
// ===============================================================================================
void initJobFaxIPAddressPortNo( APIC_Job* pc_Job )
{
	ushort	us_IpPortNo = PNLD_DefultIPFaxPortNo;		// ポート番号
	// SMTP送信設定API取得
	APIC_SmtpSendSetting* pc_SmtpSendSetting = APIC_SmtpSendSetting::newInstance();
	// SMTP送信設定に登録されているポート番号を取得
	if( pc_SmtpSendSetting != NULL ) {
		us_IpPortNo = pc_SmtpSendSetting->getPortNumber();
	}
	if( pc_Job != NULL ) {
		// IPポート番号を不揮発設定値で初期化
		for( short ss_index = 1; ss_index <= TYPD_MaxDirectMailAddress; ss_index++ ) {
			pc_Job->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageMailAddress( ss_index )->setIPFaxPortNum( us_IpPortNo );
		}
	}
}
