// comment 2019/08/19 Sky東島 [EagleHigh][1TB対応].
//#define PCGD_BoxCallBackMaxNum 200                          // ボックスコールバック数最大値.【ジョブスタート失敗時対応】.
#define PCGD_BoxCallBackMaxNum DOCD_DocFileCntBoxMax_1T          // ボックスコールバック数最大値.【ジョブスタート失敗時対応】.
PCGC_OneStartJob c_DocOneStartJob[ PCGD_BoxCallBackMaxNum ];		// ジョブ開始要求リスト.【ジョブスタート失敗時対応】.
//概要    :空き設定領域検索.
PCGC_OneStartJob* PCGC_ManageCallback::getReqStartCallbackArea()
{
	uchar uc_i = 0;
	for( uc_i = 0; uc_i < PCGD_BoxCallBackMaxNum; uc_i++ ) {
		if( c_DocOneStartJob[ uc_i ].pc_Job == NULL ) {
			// 空き領域有り.
			return( &c_DocOneStartJob[ uc_i ] );
		}
	}
	// 空き領域無し.
	return( NULL );
}
//概要　　：インスタンス解放共通.
static void ans_docComStart(
    APIC_Job*		pc_ApiJob,		// 対象ジョブ.
    ushort          us_potision )   // 対象位置.
{
	onlyPanel.decTPJobReqStart();
	if( pc_ApiJob == NULL ) {
		// ジョブ履歴を取得する
		TYPC_JobHistory* pc_JobHistory = c_DocOneStartJob[ us_potision ].pc_Job->getJobHistory();
		if( NULL != pc_JobHistory ) {
			// 解放直前にジョブがエラー値をセットするため、このタイミングしか検知できないのでここで検知.
			if( True == c_DocOneStartJob[ us_potision ].pc_Job->isWarning( ERROR_PDFANotContinue ) ) {
				onlyPanel.setPanelWarning( PNL_ERROR_PDFANotContinue );
				onlyPanel.ul_PDFANotContinueJobId = c_DocOneStartJob[ us_potision ].pc_Job->getJobStatus()->getJobID();
			}
			// ジョブ実行結果を取得する
			TYPE_DeleteJobCause e_JobResult = pc_JobHistory->getDeleteJobCause();
			if( TYPE_DeleteJobCause_DocUse == e_JobResult ) {
				// ジョブ破棄要因が文書使用中のとき.
				// 仕上がりプレビューの中止をコールしておく.
				// ジョブタイプ取得.
				onlyPanel.e_DeleteJobType = c_DocOneStartJob[ us_potision ].pc_Job->getJobSpec()->pc_Common->c_JobType.getJobType();
				onlyPanel.setPanelWarning( PNL_ERROR_DocUsed );	// 文書使用中のためジョブ破棄フラグをON.
			}
		}
		c_DocOneStartJob[ us_potision ].pc_Job->deleteInstance();
	}
	c_DocOneStartJob[ us_potision ].pc_Job = NULL;
// comment 2021/07/09 2DWS2G-Sky毛穴 [IT6_2.2] OP_BTS-34621.
	// 中間認証＋IdPの対応.
	APIC_User *pc_User = PnlComGetUser();
	Bool bl_IdpUserLogin = False ;
	if ( NULL != pc_User ) {
		bl_IdpUserLogin = pc_User->isIdpCacheUserNo( pc_User->getUserNo() ) ;
	}
//	if( TYPE_UserAuthenticationIntermeddiateServer == PnlComGetLoginUserAuthenticationType() ) {	// ユーザーが中間認証でログイン.
	if( TYPE_UserAuthenticationIntermeddiateServer == PnlComGetLoginUserAuthenticationType() 	// ユーザーが中間認証でログイン.
	   && ( False == bl_IdpUserLogin )
	) {
		CallBackIndi( TYPE_PNL_CallBack_MidTouchAndGo );      // コールバックイベント発生 .
	}
}
