// static変数の初期化
short PCGC_ManageBoxJoblist::ss_reqCheckBind = 0;
//概要　　：req_checkBind 処理中の数を取得.
short PCGC_ManageBoxJoblist::getreqCheckBind()
{
	return ss_reqCheckBind;
}
//概要　　：req_checkBind 処理中の数をセット.
void PCGC_ManageBoxJoblist::setreqCheckBind( short cnt )
{
	ss_reqCheckBind = cnt;
}
//概要　　：req_checkBind 処理中の数をインクリメント.
void PCGC_ManageBoxJoblist::setreqCheckBindCountUp()
{
	ss_reqCheckBind++;		// req_checkBind 処理中の数をインクリメント.
}
//概要　　：req_checkBind 処理中の数をデクリメント.
void PCGC_ManageBoxJoblist::setreqCheckBindCountDown()
{
	if(	0 < ss_reqCheckBind	)	// 負値にならないように１以上の場合
	{
		ss_reqCheckBind--;		// req_checkBind 処理中の数をデクリメント.
	}
}
