//概要　　：ジョブステータスオリジナルデータ反映関数.
void setOrignalJobStatusData( TYPC_JobStatus* pc_Current, TYPC_JobStatus* pc_Original )
{
	// 原稿枚数取得 - 設定.
	short ss_NumOfOriginals = pc_Original->getNumOfOriginals();
	pc_Current->setNumOfOriginals( ss_NumOfOriginals );
	// 差込ページの原稿枚数 - 設定.
	ushort us_NumOfOriginalsOfOriginalInsertion = pc_Original->getNumOfOriginalsOfOriginalInsertion();
	pc_Current->setNumOfOriginalsOfOriginalInsertion( us_NumOfOriginalsOfOriginalInsertion );
	// 原稿枚数取得 - 設定.
	short ss_NumOfOriginalsDeleteBlankPage = pc_Original->getNumOfOriginalsDeleteBlankPage();
	pc_Current->setNumOfOriginalsDeleteBlankPage( ss_NumOfOriginalsDeleteBlankPage );
}
//概要　　：ノンソート出力時にステープルモードを解除
void cancelStapleWithGroup( APIC_Job* pc_APIJob )
{
	// スタートキー押下時、モード変更確定時にステープルモードを解除する
// Comment 2015/07/8 【HCL-Hanuman】【ZeusS_ZX0】【RQ-142】 To support get number of copies for new API from function version type4 onwards.
//	if (isOn(CNK_Group, pc_APIJob) == True							// ノンソート（注：「CNK_Group」は、制御・表示上ノンソートのこと） 
//     && pc_APIJob->getJobSpec()->pc_Print->getNumOfCopies() == 1	// 置数：１ 
//     &&(isOn(CNK_Staple,        pc_APIJob) == True					// コーナーステープル 
//     	  || isOn(CNK_2PointStaple,  pc_APIJob) == True					// 2点サイドステープル
//     	  || isOn(CNK_CenterStaple,  pc_APIJob) == True)) {				// 2点センターステープル
//        // ノンソート、かつ置数１，かつステープルが設定されているとき、ステープルを解除する 
//     cancel(CNK_Staple,       CNK_Size, pc_APIJob);				// コーナーステープル 
//     cancel(CNK_2PointStaple, CNK_Size, pc_APIJob);				// 2点サイドステープル
//     cancel(CNK_CenterStaple, CNK_Size, pc_APIJob);				// 2点センターステープル
//    }
//Comment 2020/05/26 [HCLT-prasanjeet][IT6_HeliosMLK][OP_BTS-23920] when auto is ON staple is not happen.
    if ( True == pc_APIJob->getJobSpec()->pc_Print->c_SortMode.getEnableSortChange()){
	    return;
	}	
	int32_t i32_NumOfCopies = pc_APIJob->getJobSpec()->pc_Print->getNumOfCopies();
// Comment 2017/11/29 【HCLT-Tarun】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
	if( 0 != pc_APIJob->getJobSpec()->pc_Print->getNumOfCarbonCopy() ) {						// Number of CarbonCopy sets is not Zero. 
		i32_NumOfCopies = pc_APIJob->getJobSpec()->pc_Print->getNumOfCarbonCopy();
	}
	if (isOn(CNK_Group, pc_APIJob) == True							// ノンソート（注：「CNK_Group」は、制御・表示上ノンソートのこと） 
		&& 1 == i32_NumOfCopies 									// 置数：１ 
		&&(isOn(CNK_Staple,        pc_APIJob) == True				// コーナーステープル 
			|| isOn(CNK_2PointStaple,  pc_APIJob) == True			// 2点サイドステープル
			|| isOn(CNK_CenterStaple,  pc_APIJob) == True)) {		// 2点センターステープル
		// ノンソート、かつ置数１，かつステープルが設定されているとき、ステープルを解除する 
		cancel(CNK_Staple,       CNK_Size, pc_APIJob);				// コーナーステープル 
		cancel(CNK_2PointStaple, CNK_Size, pc_APIJob);				// 2点サイドステープル
		cancel(CNK_CenterStaple, CNK_Size, pc_APIJob);				// 2点センターステープル
	}
}
//概要    ：SMBブラウジングの対象がUNICODEをサポートしていたら引数指定の文字コードに変換する.
void convertWhenUTF8( const char* psc_UTF8String, const LIBE_CharSet e_FromStringCharSet, char* psc_FromString, unsigned int un_FromStringBufferSize )
{
	if( psc_UTF8String == NULL || psc_FromString == NULL ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	Bool b_convert = APIC_SmbBrowsing::newInstance()->isUnicodeSupport();
	if( b_convert == True ) {
		PnlComGetUTF8Str( psc_UTF8String, e_FromStringCharSet, psc_FromString, un_FromStringBufferSize );	// DonauLastFum【ネットワーク通信文字拡張】【13東阪】2009/04/30 Add.
	} else {
		strncpy( psc_FromString, psc_UTF8String, un_FromStringBufferSize );
	}
}
//-----------------------------------------------------------------------------------------------------------------------
//概要     :BOX表示許可/不許可判定
//戻り値   :True:表示許可 Bool:表示不許可
Bool bl_isBoxShowEnable(
    PCGE_BoxRegType boxkind ,Bool bl_LimitCheck )		// TYPE_BoxReg参照
{
	Bool ret = True ;	// 戻り値 許可で初期化
	PNLE_IsFaxMode e_isFaxmode = PNLE_IsFaxMode_NON;		// FAX接続種別
	// Fax接続種別を取得
	onlyPanel.isFaxModekind( &e_isFaxmode );
	APIC_FaxPanelSetting* pc_FaxPanelSetting = PnlComGetFaxPanelSetting();	// ファクスパネル設定.
	TYPE_FaxRelayMenu e_Relay = pc_FaxPanelSetting->getRelayMenu();			// 中継表示.
// PnlComGetUser()　NULLチェック対応.
	// キーモード取得(PageAccess接続時は中継,掲示板,ﾌｧｲﾘﾝｸﾞﾅﾝﾊﾞｰの各ボックスは非表示とするため) BugDB#70362の対応.
	TYPE_KeyMode	e_keyMode = APIC_KeyDevice::getKeyMode();
	APIC_FaxBoxSetting* pc_FaxBoxSetting = APIC_FaxBoxSetting::newInstance();	// 【304362】【課金MAP】【13開発 森本】merge.
	switch( boxkind ) {
		case PCGE_BoxRegType_RelayReqRX :		// 中継ボックス
			do {
				if( ( e_isFaxmode == PNLE_IsFaxMode_NON )			// Fax機能無し
				    || ( e_isFaxmode == PNLE_IsFaxMode_IFAX ) 		// IFax使用時 .
				    || ( e_isFaxmode == PNLE_IsFaxMode_RFAX ) ) {	// Faxサーバー使用時
					ret = False ;
					break;
				}
				if( e_Relay == TYPE_FaxRelayMenuNo ) {	//パネル設定中継表示なし
					ret = False ;
					break;
				}
// comment 2015/11/09 OPS1-Sky後藤 [MinervaSBK][CQ 521169] 中継ボックスはユーザー毎の制限に依存しない.
//				if ( ( NULL != PnlComGetUser() && TYPE_UserTypeAdmin != PnlComGetUser()->getUserType() )
				if ((True == bl_LimitCheck) && ( NULL != PnlComGetUser() && TYPE_UserTypeAdmin != PnlComGetUser()->getUserType() )
				    &&( TYPE_FuncLimit_Disable == PnlComCheckOperationAccountStatus( PNLE_ACCOUNT_STATUS_TYPE_Fax ) ) ) {
					//管理者でないかつユーザー機能制限ファックス操作不許可
					ret = False ;
					break;
				}
				if( e_keyMode == TYPE_KeyModePageAcses ) {	// PageAccess接続時は中継表示なし BugDB#70362対応.
					ret = False ;
					break;
				}
				// Prefix/Suffixを使用する場合、「中継ボックス」キーを非表示にする.
				if( True == onlyPanel.isFaxServerEnable() ) {
					ret = False ;
					break;
				}
				if( True == APIC_SoftDipSw::newInstance()->getSoftDipSwBit( 25, 3 ) &&	// スイッチ33の5bit目(0x20)有効時.
				    TYPE_KeyModeVendor == e_keyMode ) {									// キーカウンタIFベンダ装着時.
					ret = False;
					break;
				}
			} while( 0 ) ;
			break;
		case PCGE_BoxRegType_Bulletin :		//掲示板ボックス
			do {
				if( ( e_isFaxmode == PNLE_IsFaxMode_NON )			// Fax機能無し
				    || ( e_isFaxmode == PNLE_IsFaxMode_IFAX ) 		// IFax使用時 .
				    || ( e_isFaxmode == PNLE_IsFaxMode_RFAX ) ) {	// Faxサーバー使用時
					ret = False ;
					break;
				}
				if( ( True == bl_LimitCheck ) && ( NULL != PnlComGetUser() && TYPE_UserTypeAdmin != PnlComGetUser()->getUserType() )
				    && ( TYPE_FuncLimit_Disable == PnlComCheckOperationAccountStatus( PNLE_ACCOUNT_STATUS_TYPE_Fax ) ) ) {
					//管理者でないかつユーザー機能制限ファックス操作不許可
					ret = False ;
					break;
				}
				if( e_keyMode == TYPE_KeyModePageAcses ) {
					ret = False ;
					break;
				}
				if( PnlComGetExtRegAuthAppNo() != 0 ) {		// 認証登録アプリが登録されている場合.
					if( False == pc_FaxBoxSetting->getBulletinBoardBox() ) {	// 掲示板ボックス機能OFFの場合.
						ret = False;		// 表示不許可.
						break;
					}
				}
				// Prefix/Suffixを使用する場合、「掲示板ボックス」キーを非表示にする.
				if( True == onlyPanel.isFaxServerEnable() ) {
					ret = False ;
					break;
				}
				if( True == APIC_SoftDipSw::newInstance()->getSoftDipSwBit( 25, 3 ) &&	// スイッチ33の5bit目(0x20)有効時.
				    TYPE_KeyModeVendor == e_keyMode ) {									// キーカウンタIFベンダ装着時.
					ret = False;
					break;
				}
			} while( 0 ) ;
			break;
		case PCGE_BoxRegType_FilingNumber :		// ファイリングナンバーボックス.
			do {
				if( PNLE_AppOptionStatus_Enable != PnlComGetEnableAppOptionStatus( TYPE_AppOptionStamp ) ) {
					ret = False ;
					break;
				}
				if( NULL != PnlComGetUser() && TYPE_UserTypeAdmin != PnlComGetUser()->getUserType() ) {	// 管理者でないまたは、外部Ｉ／Ｆ選択がコントローラ１（Fiery）の場合.	// 13開発大村 Fiery対応.
					ret = False ;
					break;
				}
				if( e_keyMode == TYPE_KeyModePageAcses ) {
					ret = False ;
					break;
				}
			} while( 0 ) ;
			break;
		case PCGE_BoxRegType_Polling:		// ポーリングボックス.
			do {
				if( PnlComGetExtRegAuthAppNo() != 0 ) {		// 認証登録アプリが登録されている場合.
					if( False == pc_FaxBoxSetting->getPollingSendBox() ) {	// ポーリングボックス機能OFFの場合.
						ret = False;			// 表示不許可.
						break;
					}
				}
			} while( 0 );
			break;
		default : break ;
	}
	return( ret ) ;
}

