//概要    :カラーを表す文字列の取得
TEXT_ID PnlComGetColorStr( const TYPE_MonoColor e_MonoColor )
{
	// カラー判定.
	TEXT_ID puc_ColorStr = s_MonoColorRed;
	for( uchar i = 0; uc_SizeMonoColorModeTbl > i; ++i ) {
		if( e_MonoColor == s_MonoColorModeTbl[ i ].e_MonoColorCode ) {
			// カラー文字列を戻り値とする.
			puc_ColorStr = s_MonoColorModeTbl[ i ].puc_parts;
			break;
		}
	}
	return puc_ColorStr;
}
//概要    :カラーステータス表示文字列設定
Bool PnlComSetColorStr( TYPC_Common* const pc_Common, TYPC_Scan* const pc_Scan, TEXT_ID* puc_ColorStr )
{
	Bool b_2ColorOn = False;
	if( ( NULL == pc_Common ) || ( NULL == pc_Scan ) || ( NULL == puc_ColorStr ) ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return b_2ColorOn;
	}
	if( pc_Scan->getAcsOn() ) {
		// オートカラー.
		*puc_ColorStr = ( TEXT_ID )uc_ColorModeTable[0];
	} else if( pc_Common->c_2ColorMode.get2ColorOn() ) {
		// ２色カラー.
		*puc_ColorStr = ( TEXT_ID )PnlComGetColorStr( pc_Common->c_2ColorMode.getMonoColor() );
		b_2ColorOn = True;
	} else if( pc_Common->c_MonoColor.getMonoColorOn() ) {
		// モノカラー.
		*puc_ColorStr = ( TEXT_ID )PnlComGetColorStr( pc_Common->c_MonoColor.getMonoColor() );
	} else {
		switch( pc_Common->getColorMode() ) {
			case TYPE_ColorModeFullColor:	*puc_ColorStr = ( TEXT_ID )uc_ColorModeTable[1];	break;	// フルカラー.
			case TYPE_ColorModeBlack:		*puc_ColorStr = ( TEXT_ID )uc_ColorModeTable[2];	break;	// ブラック.
			case TYPE_ColorModeNoColor:																// 上記いずれかが選択されているはず.
			case TYPE_ColorModeUnselect:
				if( True == pc_Common->getBinary() ) {
					*puc_ColorStr = ( TEXT_ID )uc_ColorModeTable[2];									// 白黒2値はブラックと表示.
					break;
				}
			default:	LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	break;
		}
	}
	return b_2ColorOn;
}
//概要    :カラーステータスセットアップ
void PnlComSetColorStataus( TYPC_Common* const pc_Common, TYPC_Scan* const pc_Scan, PCGS_SetupColorModeStatus* ps_TxtColorStatus )
{
	TEXT_ID puc_ColorStr = 0;
	if( ( NULL == pc_Common ) || ( NULL == pc_Scan ) || ( NULL == ps_TxtColorStatus ) ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	if( ( NULL == ps_TxtColorStatus->pc_ColorStatus ) || ( NULL == ps_TxtColorStatus->pc_2ColorOnStatus ) || ( NULL == ps_TxtColorStatus->pc_2ColorStatus ) ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	Bool b_2ColorOn = PnlComSetColorStr( pc_Common, pc_Scan, &puc_ColorStr );
	if( 0 == puc_ColorStr ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	if( b_2ColorOn ) {
		// ２色カラー設定時.
		ps_TxtColorStatus->pc_ColorStatus->showEnable( False );
		ps_TxtColorStatus->pc_2ColorOnStatus->showEnable( True );
		ps_TxtColorStatus->pc_2ColorStatus->showEnable( True );
		ps_TxtColorStatus->pc_2ColorStatus->changeText( puc_ColorStr );
	} else {
		// ２色カラー以外設定時.
		ps_TxtColorStatus->pc_2ColorOnStatus->showEnable( False );
		ps_TxtColorStatus->pc_2ColorStatus->showEnable( False );
		ps_TxtColorStatus->pc_ColorStatus->showEnable( True );
		ps_TxtColorStatus->pc_ColorStatus->changeText( puc_ColorStr );
	}
}
//概要    :画面表示用共通関数 : 給紙口パーツの表示
void setupPaperCassetCreateSize( PSizeField* const pc_SizeField, const TYPE_FeedTray e_FeedTray, const Bool bl_StatusDisp, const Bool bl_KindDisp )
{
	if( NULL == pc_SizeField ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	APIC_FeedTray* pc_FeedTray = PnlComGetFeedTray();
	// 用紙に関する情報（サイズ・種類・状態）を取得.
	TYPC_PaperSize c_PaperSize = pc_FeedTray->getPaperSize( e_FeedTray );
	TYPC_PaperType c_PaperType = pc_FeedTray->getPaperType( e_FeedTray );
	TYPE_PaperType e_PaperType = c_PaperType.getPaperType();
	Bool b_Feed2ndSidedPaper = c_PaperType.getFeed2ndSidedPaper();
	TYPE_PaperStatus e_PaperStatus = pc_FeedTray->getPaperStatus( e_FeedTray );
	// サイズ情報セット.
// comment 2019/01/22 SCD2-4G Sky武井 OP_BTS-2216【開発提起】【Nランク】【RQ-720】紙種自動検知がONで用紙種類が未確定の時に、未確定であることがわかるアイコンを用紙種類の設定値表示箇所に表示する。.
//	pc_SizeField->setCasetSize( c_PaperSize, e_PaperType, b_Feed2ndSidedPaper, e_PaperStatus, e_FeedTray, getRemainPaper( e_FeedTray ) );
	pc_SizeField->setCasetSize( c_PaperSize, e_PaperType, b_Feed2ndSidedPaper, PnlComGet_isMediaUndecided( e_FeedTray ), e_PaperStatus, e_FeedTray, getRemainPaper( e_FeedTray ) );
}
//概要    :現行用紙ステータス
void PnlComSetPaperStataus( TYPC_Print* const pc_Print, APIC_FeedTray* const pc_FeedTray, PSizeField* pc_TxtPaperStatus )
{
	if( ( NULL == pc_Print ) ||( NULL == pc_FeedTray ) || ( NULL == pc_TxtPaperStatus ) ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	// トレイ設定取得.
	const TYPE_FeedTray e_FeedTray = pc_Print->c_PaperTray.getFeedTray();
	// オート用紙でなおかつ給紙トレイが無効の場合.
	if( ( pc_Print->c_PaperTray.getApsOn() ) && ( False == pc_Print->c_PaperTray.getFeedTrayEnable() ) ) {
		// オート設定.
		pc_TxtPaperStatus->setAuto();
	}
	// その他.
	else {
		// 選択トレイの情報表示.
		setupPaperCassetCreateSize( pc_TxtPaperStatus, e_FeedTray, True, True );
	}
}
//概要    :現行倍率ステータスの表示
void setupInputMagStatus( APIC_Job* pc_Job, PCGS_setupMagCopy* ps_MagDisp, const TYPE_MagType e_MagType, const TYPC_Point<float> c_MagTemplate,
                          const short ss_MagInpDigit, const Bool b_AmsOn, const Bool b_Available, const TYPE_OriginalSizeMode e_OriginalSizeMode,
                          const Bool b_BasicGamenOn, const Bool b_FixMagOn )
{
	if( ( NULL == pc_Job ) || ( NULL == ps_MagDisp ) ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	if( ( NULL == ps_MagDisp->p_Txt_MagPeke )
	    || ( NULL == ps_MagDisp->p_Btx_MagValue )
	    || ( NULL == ps_MagDisp->p_Num_MagValue )
	    || ( NULL == ps_MagDisp->p_Txt_XYZoomX )
	    || ( NULL == ps_MagDisp->p_Txt_XYZoomY )
	    || ( NULL == ps_MagDisp->p_Num_XYZoomX )
	    || ( NULL == ps_MagDisp->p_Num_XYZoomY ) ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	PActivatable*    pc_tempAct    = dynamic_cast< PActivatable* >( ps_MagDisp->p_Btx_MagValue );
	PActivatableAdd* pc_tempActAdd = dynamic_cast< PActivatableAdd* >( ps_MagDisp->p_Btx_MagValue );
	if( pc_tempAct == NULL && pc_tempActAdd == NULL ) {
		// PActibatable型およびPActibatableAdd型でないパーツを指定した場合.
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "setupInputMagStatus", UC_PNL_ERROR_USE );
		return;
	}
	Bool b_isAdd = False;	// ActivatableAddフラグ.
	if( NULL != pc_tempAct ) {
		b_isAdd = False;
	} else {
		b_isAdd = True;
	}
	// 独立ズーム選択時.
	if( TYPE_MagTypeXyZoom == e_MagType ) {
		// 通常倍率パーツの非表示.
		if( b_isAdd == True ) {
			pc_tempActAdd->showEnableAdd( ps_MagDisp->p_Num_MagValue,False );		// 通常倍率・倍率値.
		} else {
			pc_tempAct->showEnableAdd( False );		// 通常倍率・倍率値.
		}
		ps_MagDisp->p_Txt_MagPeke->showEnable( False );		// 「x」または「オート倍率」.
		// 縦横変倍パーツの表示.
		ps_MagDisp->p_Txt_XYZoomX->showEnable( True );		// 「X：x」.
		ps_MagDisp->p_Txt_XYZoomY->showEnable( True );		// 「Y：x」.
		ps_MagDisp->p_Num_XYZoomX->showEnable( True );		// 縦横変倍・倍率値X.
		ps_MagDisp->p_Num_XYZoomY->showEnable( True );		// 縦横変倍・倍率値Y.
		// 倍率値の設定.
		ps_MagDisp->p_Num_XYZoomX->magSet( c_MagTemplate.x, ss_MagInpDigit, True );
		ps_MagDisp->p_Num_XYZoomY->magSet( c_MagTemplate.y, ss_MagInpDigit, True );
	} else {
		// 縦横変倍パーツの非表示.
		ps_MagDisp->p_Txt_XYZoomX->showEnable( False );		// 「X：x」.
		ps_MagDisp->p_Txt_XYZoomY->showEnable( False );		// 「Y：x」.
		ps_MagDisp->p_Num_XYZoomX->showEnable( False );		// 縦横変倍・倍率値X.
		ps_MagDisp->p_Num_XYZoomY->showEnable( False );		// 縦横変倍・倍率値Y.
		// 通常倍率パーツの表示.
		ps_MagDisp->p_Txt_MagPeke->showEnable( True );		// 「x」または「オート倍率」.
		Bool b_Auto = False;
		if( b_AmsOn ) {
			TYPC_JobStatus* pc_JobStatus = pc_Job->getJobStatus();
			// 画像入力状態の取得.
			const TYPE_InputStatus e_InputStatus = pc_JobStatus->getInputStatus();
			// 「読み取り終了」または「入力アイドル状態」.
			if( ( TYPE_InputStatusScanEnd == e_InputStatus ) || ( TYPE_InputStatusIdle == e_InputStatus ) ) {
				// 原稿サイズ確定.
				if( False == b_Available ) {
					b_Auto = True;
				}
			} else {
				// 「読み取り終了」または「入力アイドル状態」以外時（動作中）.
				APIC_Original* pc_Original = PnlComGetOriginal();
				// 倍率が無効の場合.
				if( False == b_Available ) {
					b_Auto = True;
				}
				// ADFの場合.
				APIC_AutoSelect* _pc_AutoSelect = comPanelJob->getAutoSelect();
				if( ( NULL != _pc_AutoSelect ) && ( TYPE_OriginalSettingADF == _pc_AutoSelect->chkOriginalSetting( True ) ) ) {
					// ADF・原稿サイズが未確定の場合(次原稿なし).
					if( False == comPanelJob->isADFOriginalSizeFixed() ) {
						// 原稿混載で原稿サイズが不明の場合(読みこみ停止中用).
						if( ( TYPE_SizeCodeUnknown == pc_Original->getAdfOriginalSize().e_SizeCode )
						    && ( TYPE_OriginalSizeModeMix == e_OriginalSizeMode ) ) {
							b_Auto = True;
						}
					}
				} else {
					// 手置きの場合.
					// 手置き・原稿サイズが未確定の場合(プラテン上に原稿なし).
					if( False == comPanelJob->isPlatenOriginalSizeFixed() ) {
						// 原稿混載で原稿サイズが不明の場合(読みこみ停止中用)、倍率が無効の場合.
						if( ( TYPE_SizeCodeUnknown == pc_Original->getPlatenOriginalSize().e_SizeCode )
						    && ( TYPE_OriginalSizeModeMix == e_OriginalSizeMode ) ) {
							b_Auto = True;
						}
					}
				}
			}
		}
		if( b_Auto ) {
			// 通常倍率パーツの非表示.
			if( b_isAdd == True ) {
				pc_tempActAdd->showEnableAdd( ps_MagDisp->p_Num_MagValue,False );		// 通常倍率・倍率値.
				pc_tempActAdd->changeText( ps_MagDisp->p_Txt_MagPeke, s_CHTAutoColor );		// 通常倍率・倍率値.
			} else {
				pc_tempAct->showEnableAdd( False );		// 通常倍率・倍率値.
			}
		} else {
			// 通常倍率パーツの表示.
			if( b_isAdd == True ) {
				pc_tempActAdd->showEnableAdd( ps_MagDisp->p_Num_MagValue,True );		// 通常倍率・倍率値.
				pc_tempActAdd->changeText( ps_MagDisp->p_Txt_MagPeke,s_Space1 );		// 通常倍率・倍率値.
			} else {
				pc_tempAct->showEnableAdd( True );		// 通常倍率・倍率値.
			}
			// 倍率値の設定.
			if( b_isAdd == True ) {
				pc_tempActAdd->magSet( ps_MagDisp->p_Num_MagValue,c_MagTemplate.x, ss_MagInpDigit, True );
			} else {
				pc_tempAct->magSet( c_MagTemplate.x, ss_MagInpDigit, True );
			}
		}
	}
}
//概要    :現行片面/両面ステータス
void PnlComSetFaceStataus( TYPC_Print* const pc_Print, TYPC_Scan* const pc_Scan, PSinglePartsText* pc_TxtFaceStatus, PSinglePartsGraphic* pc_BtxFaceStatus )
{
	uchar uc_SelectFace = 0;
	PActivatable*    pc_tempAct    = dynamic_cast< PActivatable* >( pc_BtxFaceStatus );
	PActivatableAdd* pc_tempActAdd = dynamic_cast< PActivatableAdd* >( pc_BtxFaceStatus );
	if( pc_tempAct == NULL && pc_tempActAdd == NULL ) {
		// PActibatable型およびPActibatableAdd型でないパーツを指定した場合.
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PnlComSetFaceStataus", UC_PNL_ERROR_USE );
		return;
	}
	Bool b_isAdd = False;	// ActivatableAddフラグ.
	if( NULL != pc_tempAct ) {
		b_isAdd = False;
	} else {
		b_isAdd = True;
	}
	if( ( NULL == pc_Print ) || ( NULL == pc_Scan ) || ( NULL == pc_TxtFaceStatus ) ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	if( pc_Scan->getDuplex() ) {
		// 両面/両面、両面/片面選択、.
		uc_SelectFace = ( ( TYPE_DuplexModeOn == pc_Print->getDuplexMode() ) ? 3: 2 );
	} else {
		// 片面/両面、片面/片面選択.
		uc_SelectFace = ( ( TYPE_DuplexModeOn == pc_Print->getDuplexMode() ) ? 1: 0 );
	}
	if( NULL == pc_BtxFaceStatus ) {
		pc_TxtFaceStatus->changeText( uc_FaceModeTable[uc_SelectFace] );
	} else {
		if( True == b_isAdd ) {
			pc_tempActAdd->changeText( pc_TxtFaceStatus,uc_FaceModeTable[uc_SelectFace] );
		} else {
			pc_tempAct->changeText( uc_FaceModeTable[uc_SelectFace] );
		}
	}
}
