//概要    :カラーステータス表示文字列設定
Bool PnlComSetColorStr( TYPC_Common* const pc_Common, TYPC_Scan* const pc_Scan, TEXT_ID* puc_ColorStatus, TEXT_ID* ptd_Color )
{
	if( ( NULL == pc_Common ) || ( NULL == pc_Scan ) || ( NULL == puc_ColorStatus ) || ( NULL == ptd_Color ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PnlComSetColorStr", UC_PNL_ERROR_PARAMETER );
		return False;
	}
	Bool b_2ColorOn = False;
	if( True == pc_Scan->getAcsOn() ) {
		// オートカラー.
		*puc_ColorStatus = uc_ColorModeTable[ 0 ];
	} else if( True == pc_Common->c_2ColorMode.get2ColorOn() ) {
		// ２色カラー.
		*puc_ColorStatus = uc_ColorModeTable[ 3 ];
		*ptd_Color = PnlComGetColorStr( pc_Common->c_2ColorMode.getMonoColor() );
		b_2ColorOn = True;
	} else if( True == pc_Common->c_MonoColor.getMonoColorOn() ) {
		// モノカラー.
		*puc_ColorStatus = uc_ColorModeTable[ 4 ];
		*ptd_Color = PnlComGetColorStr( pc_Common->c_MonoColor.getMonoColor() );
		b_2ColorOn = True;
	} else {
		switch( pc_Common->getColorMode() ) {
			case TYPE_ColorModeFullColor:	*puc_ColorStatus = uc_ColorModeTable[ 1 ];	break;	// フルカラー.
			case TYPE_ColorModeBlack:		*puc_ColorStatus = uc_ColorModeTable[ 2 ];	break;	// ブラック.
			case TYPE_ColorModeNoColor:															// 上記いずれかが選択されているはず.
			case TYPE_ColorModeUnselect:
				if( True == pc_Common->getBinary() ) {
					*puc_ColorStatus = uc_ColorModeTable[2];									// 白黒2値はブラックと表示.
					break;
				}
			default:	PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PnlComSetColorStr", UC_PNL_ERROR_IMPOSSIBLE );	break;
		}
	}
	return b_2ColorOn;
}
//概要    :カラーステータス表示アイコン設定.
void PnlComSetColorIcon( TYPC_Common* const pc_Common, TYPC_Scan* const pc_Scan, PSinglePartsGraphic* pc_ColorIcon )
{
	if( ( NULL == pc_Common ) || ( NULL == pc_Scan ) || ( NULL == pc_ColorIcon ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PnlComSetColorIcon", UC_PNL_ERROR_PARAMETER );	return;
	}
	if( pc_Scan->getAcsOn() ) {
		// オートカラー.
		pc_ColorIcon->showEnable( True );
		pc_ColorIcon->changeGraphic( uc_ColorModeIconTable[0] );
	} else if( pc_Common->c_2ColorMode.get2ColorOn() ) {
		// ２色カラー.
		pc_ColorIcon->showEnable( False );
	} else if( pc_Common->c_MonoColor.getMonoColorOn() ) {
		// モノカラー.
		pc_ColorIcon->showEnable( False );
	} else {
		switch( pc_Common->getColorMode() ) {
			case TYPE_ColorModeFullColor:	pc_ColorIcon->changeGraphic( uc_ColorModeIconTable[1] );	break;	// フルカラー.
			case TYPE_ColorModeBlack:		pc_ColorIcon->changeGraphic( uc_ColorModeIconTable[2] );	break;	// ブラック.
			case TYPE_ColorModeNoColor:																		// 上記いずれかが選択されているはず.
			case TYPE_ColorModeUnselect:
				if( True == pc_Common->getBinary() ) {
					pc_ColorIcon->changeGraphic( uc_ColorModeIconTable[2] );								// 白黒2値はブラックと表示.
					break;
				}
			default:	PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PnlComSetColorIcon", UC_PNL_ERROR_IMPOSSIBLE );	break;
		}
		pc_ColorIcon->showEnable( True );
	}
}
//概要    :カラーステータスセットアップ
void PnlComSetColorStataus( TYPC_Common* const pc_Common, TYPC_Scan* const pc_Scan, PCGS_SetupColorMode* pst_SetupColorMode )
{
	if( ( NULL == pc_Common ) || ( NULL == pc_Scan ) || ( NULL == pst_SetupColorMode ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PnlComSetColorStataus", UC_PNL_ERROR_PARAMETER );
		return;
	}
	if(	( NULL == pst_SetupColorMode->pc_Key_ColorStatus )
	    || ( NULL == pst_SetupColorMode->pc_Ktx_Status )
	    || ( NULL == pst_SetupColorMode->pc_Ktx_Color )
	    || ( NULL == pst_SetupColorMode->pc_Gra_ColorStatusIcon ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PnlComSetColorStataus", UC_PNL_ERROR_PARAMETER );
		return;
	}
	TEXT_ID td_Status = s_EXPAutoColor;
	TEXT_ID td_Color = s_MonoColorRed;
	const Bool b_2ColorOn = PnlComSetColorStr( pc_Common, pc_Scan, &td_Status, &td_Color );
	if( True == b_2ColorOn ) {
		// ２色カラー・モノカラー設定時.
		pst_SetupColorMode->pc_Key_ColorStatus->showEnableAdd( pst_SetupColorMode->pc_Ktx_Color, True );
		pst_SetupColorMode->pc_Key_ColorStatus->changeText( pst_SetupColorMode->pc_Ktx_Status, td_Status );
		pst_SetupColorMode->pc_Key_ColorStatus->changeText( pst_SetupColorMode->pc_Ktx_Color, td_Color );
	} else {
		// ２色カラー以外設定時.
		pst_SetupColorMode->pc_Key_ColorStatus->showEnableAdd( pst_SetupColorMode->pc_Ktx_Color, False );
		pst_SetupColorMode->pc_Key_ColorStatus->changeText( pst_SetupColorMode->pc_Ktx_Status, td_Status );
	}
	// カラーアイコン表示.
	PnlComSetColorIcon( pc_Common, pc_Scan, pst_SetupColorMode->pc_Gra_ColorStatusIcon );
}
//概要    :画面表示用共通関数 : 給紙口パーツの表示
void setupPaperCassetCreateSize( const TYPE_FeedTray e_FeedTray, PSinglePartsGraphic* pc_Btx_PaperStatus, PSizeField* pc_Tsf_PaperStatus )
{
	if( NULL == pc_Btx_PaperStatus ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "setupPaperCassetCreateSize", UC_PNL_ERROR_PARAMETER );
		return;
	}
	APIC_FeedTray* pc_FeedTray = PnlComGetFeedTray();
	// 用紙サイズを取得.
	TYPC_PaperSize c_PaperSize = pc_FeedTray->getPaperSize( e_FeedTray );
// comment 2020/01/17 Sky東島 [EagleBK][OP_BTS-12665].
	correctNonStandardPaperSize( &c_PaperSize , e_FeedTray );
	// 用紙種類を取得.
	TYPC_PaperType c_PaperType = pc_FeedTray->getPaperType( e_FeedTray );
	TYPE_PaperType e_PaperType = c_PaperType.getPaperType();
	Bool b_Feed2ndSidedPaper = c_PaperType.getFeed2ndSidedPaper();
	// 用紙のステータスを取得.
	TYPE_PaperStatus e_PaperStatus = pc_FeedTray->getPaperStatus( e_FeedTray );
	PActivatable* pc_Act = dynamic_cast< PActivatable* >( pc_Btx_PaperStatus );
	PActivatableAdd* pc_ActAdd = dynamic_cast< PActivatableAdd* >( pc_Btx_PaperStatus );
	if( NULL != pc_Act ) {
		// サイズ情報セット.
// comment 2019/01/22 SCD2-4G Sky武井 OP_BTS-2216【開発提起】【Nランク】【RQ-720】紙種自動検知がONで用紙種類が未確定の時に、未確定であることがわかるアイコンを用紙種類の設定値表示箇所に表示する。.
//		pc_Act->setCasetSize( c_PaperSize, e_PaperType, b_Feed2ndSidedPaper, e_PaperStatus, e_FeedTray, getRemainPaper( e_FeedTray ) );
		pc_Act->setCasetSize( c_PaperSize, e_PaperType, b_Feed2ndSidedPaper, PnlComGet_isMediaUndecided( e_FeedTray ), e_PaperStatus, e_FeedTray, getRemainPaper( e_FeedTray ) );
	} else if( NULL != pc_ActAdd ) {
		if( NULL == pc_Tsf_PaperStatus ) {
			PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "setupPaperCassetCreateSize", UC_PNL_ERROR_PARAMETER );
			return;
		}
		// サイズ情報セット.
// comment 2019/01/22 SCD2-4G Sky武井 OP_BTS-2216【開発提起】【Nランク】【RQ-720】紙種自動検知がONで用紙種類が未確定の時に、未確定であることがわかるアイコンを用紙種類の設定値表示箇所に表示する。.
//		pc_ActAdd->setCasetSize( pc_Tsf_PaperStatus, c_PaperSize, e_PaperType, b_Feed2ndSidedPaper, e_PaperStatus, e_FeedTray, getRemainPaper( e_FeedTray ) );
		pc_ActAdd->setCasetSize( pc_Tsf_PaperStatus, c_PaperSize, e_PaperType, b_Feed2ndSidedPaper, PnlComGet_isMediaUndecided( e_FeedTray ), e_PaperStatus, e_FeedTray, getRemainPaper( e_FeedTray ) );
	} else {
		// PActibatable型およびPActibatableAdd型でないパーツを指定した場合.
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "setupPaperCassetCreateSize", UC_PNL_ERROR_USE );
		return;
	}
}
//概要    :現行用紙ステータスアイコン表示.
void PnlComSetPaperStatausIcon( TYPC_Print* const pc_Print, APIC_FeedTray* const pc_FeedTray, PSinglePartsGraphic* pc_Gra_PaperStatus, PActivatableAdd* pc_Paper )
{
	if( ( NULL == pc_Print ) ||( NULL == pc_FeedTray ) || ( NULL == pc_Gra_PaperStatus ) || ( NULL == pc_Paper ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PnlComSetPaperStatausIcon", UC_PNL_ERROR_PARAMETER );
		return;
	}
	PButtonAdd* pc_Key_GotoPaper = dynamic_cast< PButtonAdd* >( pc_Paper );
	PActivatableAdd* pc_Btx_Paper = dynamic_cast< PActivatableAdd* >( pc_Paper );
	// オート用紙でなおかつ給紙トレイが無効の場合.
	if( ( pc_Print->c_PaperTray.getApsOn() ) && ( False == pc_Print->c_PaperTray.getFeedTrayEnable() ) ) {
		// オート設定時はアイコン非表示.
		if( NULL != pc_Key_GotoPaper ) {
			pc_Key_GotoPaper->showEnableAdd( pc_Gra_PaperStatus, False );
		} else {
			pc_Btx_Paper->showEnableAdd( pc_Gra_PaperStatus, False );
		}
	}
	// その他.
	else {
		// トレイ設定取得.
		const TYPE_FeedTray e_FeedTray = pc_Print->c_PaperTray.getFeedTray();
		// 用紙種類、両面2面目フラグ、用紙SEF/LEFの取得.
		TYPC_PaperType c_PaperType = pc_FeedTray->getPaperType( e_FeedTray );
		const TYPE_PaperType e_PaperType = c_PaperType.getPaperType();
		const Bool b_2ndSidedPaper = c_PaperType.getFeed2ndSidedPaper();
		const Bool b_PaperTypeSefLef = pc_FeedTray->getPaperSize( pc_Print->c_PaperTray.getFeedTray() ).isTate();
		// 用紙アイコンの検索、.
		for( uchar i = 0; uc_PaperTypeStatausIconInfoTbl > i; ++i ) {
			// 用紙種類、両面2面目フラグと用紙SEF/LEFフラグが一致した場合.
			if( ( e_PaperType == st_PaperTypeStatausIconInfoTbl[i].e_PaperType )
			    && ( b_2ndSidedPaper == st_PaperTypeStatausIconInfoTbl[i].b_2ndSidedPaper )
			    && ( b_PaperTypeSefLef == st_PaperTypeStatausIconInfoTbl[i].b_PaperTypeSefLef ) ) {
				// 用紙アイコンの切り替え.
				if( NULL != pc_Key_GotoPaper ) {
					pc_Key_GotoPaper->changeGraphic( pc_Gra_PaperStatus, st_PaperTypeStatausIconInfoTbl[i].puc_GraPaperType );
				} else {
					pc_Btx_Paper->changeGraphic( pc_Gra_PaperStatus, st_PaperTypeStatausIconInfoTbl[i].puc_GraPaperType );
				}
				break;
			}
		}
		if( NULL != pc_Key_GotoPaper ) {
			pc_Key_GotoPaper->showEnableAdd( pc_Gra_PaperStatus, True );
		} else {
			pc_Btx_Paper->showEnableAdd( pc_Gra_PaperStatus, True );
		}
	}
}
//概要    :現行用紙ステータス
void PnlComSetPaperStataus( TYPC_Print* const pc_Print,
                            APIC_FeedTray* const pc_FeedTray,
                            PSinglePartsGraphic* pc_Btx_PaperStatus,
                            PSizeField* pc_Tsf_PaperStatus,
                            PSinglePartsText* pc_Txt_PaperStatusAuto )
{
	if( ( NULL == pc_Print ) ||( NULL == pc_FeedTray ) || ( NULL == pc_Btx_PaperStatus ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PnlComSetPaperStataus", UC_PNL_ERROR_PARAMETER );
		return;
	}
	// トレイ設定取得.
	const TYPE_FeedTray e_FeedTray = pc_Print->c_PaperTray.getFeedTray();
	// オート用紙でなおかつ給紙トレイが無効の場合.
	if( ( pc_Print->c_PaperTray.getApsOn() ) && ( False == pc_Print->c_PaperTray.getFeedTrayEnable() ) ) {
		PActivatable* pc_Act = dynamic_cast< PActivatable* >( pc_Btx_PaperStatus );
		PActivatableAdd* pc_ActAdd = dynamic_cast< PActivatableAdd* >( pc_Btx_PaperStatus );
		if( NULL != pc_Act ) {
			// オート設定.
			pc_Act->setAuto();
		} else if( NULL != pc_ActAdd ) {
			if( NULL == pc_Tsf_PaperStatus ) {
				PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PnlComSetPaperStataus", UC_PNL_ERROR_PARAMETER );
				return;
			}
			// オート設定.
			if( NULL != pc_Txt_PaperStatusAuto ) {	// 「自動」をサイズフィールドと
				pc_ActAdd->showEnableAdd( pc_Tsf_PaperStatus, False );
				pc_ActAdd->showEnableAdd( pc_Txt_PaperStatusAuto, True );
			} else {
				pc_ActAdd->setAuto( pc_Tsf_PaperStatus );
			}
		} else {
			// PActibatable型およびPActibatableAdd型でないパーツを指定した場合.
			PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PnlComSetPaperStataus", UC_PNL_ERROR_USE );
			return;
		}
	}
	// その他.
	else {
		// 給紙口パーツの表示.
		setupPaperCassetCreateSize( e_FeedTray, pc_Btx_PaperStatus, pc_Tsf_PaperStatus );
		PActivatableAdd* pc_ActAdd = dynamic_cast< PActivatableAdd* >( pc_Btx_PaperStatus );
		if( ( NULL != pc_ActAdd ) && ( NULL != pc_Txt_PaperStatusAuto ) ) {
			pc_ActAdd->showEnableAdd( pc_Tsf_PaperStatus, True );
			pc_ActAdd->showEnableAdd( pc_Txt_PaperStatusAuto, False );
		}
	}
}
//概要    :固定倍率ステータスの取得
Bool getFixMagStataus( const TYPE_MagType e_MagType, TEXT_ID* ptd_FixMag )
{
	if( NULL == ptd_FixMag ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "getFixMagStataus", UC_PNL_ERROR_PARAMETER );
		return False;
	}
	// 現行設定固定倍率検索.
	for( uchar i = 0; uc_SizeMagFixPartsTbl > i; ++i ) {
		// 固定倍率が一致した場合.
		if( e_MagType == s_MagFixPartsTbl[ i ].MagType ) {
			// 仕向けにより表示文字列を変更する.
			uchar uc_SelectDestination = 0;
			switch( PnlComGetDestination() ) {
				case TYPE_SystemType_JP:	uc_SelectDestination = 0;	break;
				case TYPE_SystemType_US:	uc_SelectDestination = 1;	break;
				case TYPE_SystemType_EU:	uc_SelectDestination = 2;	break;
				default:	PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "getFixMagStataus", UC_PNL_ERROR_IMPOSSIBLE );	return False;
			}
			// 固定倍率表示.
			*ptd_FixMag = s_MagFixPartsTbl[ i ].pcu_parts[ uc_SelectDestination ];
			return True;
		}
	}
	return False;
}
//概要    :現行倍率ステータスの表示
void setupInputMagStatus( APIC_Job* pc_Job, const Bool b_AmsOn, const Bool b_Available, const TYPE_MagType e_MagType,
                          const TYPC_Point<float> c_MagTemplate, const TYPE_OriginalSizeMode e_OriginalSizeMode,
                          const short ss_MagInpDigit, PCGS_SetupMag* pst_SetupMagCopy )
{
	if( ( NULL == pc_Job ) || ( NULL == pst_SetupMagCopy ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "setupInputMagStatus", UC_PNL_ERROR_PARAMETER );
		return;
	}
	if(	( NULL == pst_SetupMagCopy->pc_Btx_MagStatus )
	    || ( NULL == pst_SetupMagCopy->pc_Num_MagValue )
	    || ( NULL == pst_SetupMagCopy->pc_Ktx_MagTxtX )
	    || ( NULL == pst_SetupMagCopy->pc_Ktx_MagTxtY )
	    || ( NULL == pst_SetupMagCopy->pc_Num_MagValueX )
	    || ( NULL == pst_SetupMagCopy->pc_Num_MagValueY )
	    || ( NULL == pst_SetupMagCopy->pc_Ktx_MagTxtFix )
	    || ( NULL == pst_SetupMagCopy->pc_Ktx_MagTxtAuto ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "setupInputMagStatus", UC_PNL_ERROR_PARAMETER );
		return;
	}
	// 独立ズーム選択時.
	if( TYPE_MagTypeXyZoom == e_MagType ) {
		// 「自動」ステータスパーツの非表示.
		pst_SetupMagCopy->pc_Btx_MagStatus->showEnableAdd( pst_SetupMagCopy->pc_Ktx_MagTxtAuto, False );	// 「自動」.
		// 通常倍率パーツの非表示.
		pst_SetupMagCopy->pc_Btx_MagStatus->showEnableAdd( pst_SetupMagCopy->pc_Num_MagValue, False );	// 通常倍率・倍率値.
		pst_SetupMagCopy->pc_Btx_MagStatus->showEnableAdd( pst_SetupMagCopy->pc_Ktx_MagTxtFix, False );	// 固定倍率表示.
		// 縦横変倍パーツの表示.
		pst_SetupMagCopy->pc_Btx_MagStatus->showEnableAdd( pst_SetupMagCopy->pc_Ktx_MagTxtX, True );	// 「X：」.
		pst_SetupMagCopy->pc_Btx_MagStatus->showEnableAdd( pst_SetupMagCopy->pc_Ktx_MagTxtY, True );	// 「Y：」.
		pst_SetupMagCopy->pc_Btx_MagStatus->showEnableAdd( pst_SetupMagCopy->pc_Num_MagValueX, True );	// 縦横変倍・倍率値X.
		pst_SetupMagCopy->pc_Btx_MagStatus->showEnableAdd( pst_SetupMagCopy->pc_Num_MagValueY, True );	// 縦横変倍・倍率値Y.
		// 倍率値の設定.
		pst_SetupMagCopy->pc_Btx_MagStatus->magSet( pst_SetupMagCopy->pc_Num_MagValueX, c_MagTemplate.x, ss_MagInpDigit, True, True, False );
		pst_SetupMagCopy->pc_Btx_MagStatus->magSet( pst_SetupMagCopy->pc_Num_MagValueY, c_MagTemplate.y, ss_MagInpDigit, True, True, False );
	} else {
		// 縦横変倍パーツの非表示.
		pst_SetupMagCopy->pc_Btx_MagStatus->showEnableAdd( pst_SetupMagCopy->pc_Ktx_MagTxtX, False );	// 「X：」.
		pst_SetupMagCopy->pc_Btx_MagStatus->showEnableAdd( pst_SetupMagCopy->pc_Ktx_MagTxtY, False );	// 「Y：」.
		pst_SetupMagCopy->pc_Btx_MagStatus->showEnableAdd( pst_SetupMagCopy->pc_Num_MagValueX, False );	// 縦横変倍・倍率値X.
		pst_SetupMagCopy->pc_Btx_MagStatus->showEnableAdd( pst_SetupMagCopy->pc_Num_MagValueY, False );	// 縦横変倍・倍率値Y.
		pst_SetupMagCopy->pc_Btx_MagStatus->showEnableAdd( pst_SetupMagCopy->pc_Ktx_MagTxtFix, False );	// 固定倍率表示.
		// 通常倍率パーツの表示.
		pst_SetupMagCopy->pc_Btx_MagStatus->showEnableAdd( pst_SetupMagCopy->pc_Num_MagValue, True );
		Bool b_Auto = False;
		if( True == b_AmsOn ) {
			TYPC_JobStatus* pc_JobStatus = pc_Job->getJobStatus();
			// 画像入力状態の取得.
			const TYPE_InputStatus e_InputStatus = pc_JobStatus->getInputStatus();
			// 「読み取り終了」または「入力アイドル状態」.
			if( ( TYPE_InputStatusScanEnd == e_InputStatus ) || ( TYPE_InputStatusIdle == e_InputStatus ) ) {
				// 倍率が無効の場合.
				if( False == b_Available ) {
					b_Auto = True;
				}
			}
			// 「読み取り終了」または「入力アイドル状態」以外時（動作中）.
			else {
				APIC_Original* pc_Original = PnlComGetOriginal();
				// 倍率が無効の場合.
				if( False == b_Available ) {
					b_Auto = True;
				}
				// ADFの場合.
				APIC_AutoSelect* _pc_AutoSelect = pc_Job->getAutoSelect();
				if( ( NULL != _pc_AutoSelect ) && ( TYPE_OriginalSettingADF == _pc_AutoSelect->chkOriginalSetting( True ) ) ) {
					// ADF・原稿サイズが未確定の場合(次原稿なし).
					if( False == comPanelJob->isADFOriginalSizeFixed() ) {
						// 原稿混載で原稿サイズが不明の場合(読みこみ停止中用).
						if( ( TYPE_SizeCodeUnknown == pc_Original->getAdfOriginalSize().e_SizeCode )
						    && ( TYPE_OriginalSizeModeMix == e_OriginalSizeMode ) ) {
							b_Auto = True;
						}
					}
				} else {
					// 手置きの場合.
					// 手置き・原稿サイズが未確定の場合(プラテン上に原稿なし).
					if( False == comPanelJob->isPlatenOriginalSizeFixed() ) {
						// 原稿混載で原稿サイズが不明の場合(読みこみ停止中用)、倍率が無効の場合.
						if( ( TYPE_SizeCodeUnknown == pc_Original->getPlatenOriginalSize().e_SizeCode )
						    && ( TYPE_OriginalSizeModeMix == e_OriginalSizeMode ) ) {
							b_Auto = True;
						}
					}
				}
			}
		}
		if( True == b_Auto ) {
			// 通常倍率パーツの非表示.
			pst_SetupMagCopy->pc_Btx_MagStatus->showEnableAdd( pst_SetupMagCopy->pc_Num_MagValue, False );	// 通常倍率・倍率値.
			pst_SetupMagCopy->pc_Ktx_MagTxtAuto->changeText( s_ZoomAuto );
			// 「自動」ステータス表示.
			pst_SetupMagCopy->pc_Btx_MagStatus->showEnableAdd( pst_SetupMagCopy->pc_Ktx_MagTxtAuto, True );
		} else {
			// 「自動」ステータス非表示.
			pst_SetupMagCopy->pc_Btx_MagStatus->showEnableAdd( pst_SetupMagCopy->pc_Ktx_MagTxtAuto, False );
			// 倍率値の設定.
			pst_SetupMagCopy->pc_Btx_MagStatus->magSet( pst_SetupMagCopy->pc_Num_MagValue, c_MagTemplate.x, ss_MagInpDigit, True, True, False );
#ifdef DEF_LCD_7INCH
			TEXT_ID td_FixMag = s_pNOTA3ToB4AndA4ToB5_W128H018A;
#else // #ifdef DEF_LCD_7INCH.
			TEXT_ID td_FixMag = s_ITMA3ToB4AndA4ToB5;
#endif // #ifdef DEF_LCD_7INCH.
			if( True == getFixMagStataus( e_MagType, &td_FixMag ) ) {
				// 固定倍率の設定.
				pst_SetupMagCopy->pc_Btx_MagStatus->changeText( pst_SetupMagCopy->pc_Ktx_MagTxtFix, td_FixMag );
				pst_SetupMagCopy->pc_Btx_MagStatus->showEnableAdd( pst_SetupMagCopy->pc_Ktx_MagTxtFix, True );
			}
		}
	}
	//「小さめ」キー表示.
	TYPC_Common* pc_Common = pc_Job->getJobSpec()->pc_Common;
	if( NULL != pst_SetupMagCopy->pc_Ktx_MagTxtSmall ) {
		pst_SetupMagCopy->pc_Btx_MagStatus->showEnableAdd( pst_SetupMagCopy->pc_Ktx_MagTxtSmall, pc_Common->c_Mag.getMinimal() );	//「小さめ」On時は非表示.
	}
}
//概要    :現行倍率ステータスの表示
void PnlComSetMagStatus( APIC_Job* pc_Job, const short ss_MagInpDigit, PCGS_SetupMag* pst_SetupMagCopy )
{
	if( ( NULL == pc_Job ) || ( NULL == pst_SetupMagCopy ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "setupMagStatus", UC_PNL_ERROR_PARAMETER );
		return;
	}
	TYPC_Common* pc_Common = pc_Job->getJobSpec()->pc_Common;
	TYPC_Scan* pc_Scan = pc_Job->getJobSpec()->pc_Scan;
	// オート倍率フラグ、倍率有効フラグ、倍率の種類、倍率値、原稿モードの取得.
	const Bool b_AmsOn = pc_Common->c_Mag.getAmsOn();
	const Bool b_Available = pc_Common->c_Mag.getAvailable();
	const TYPE_MagType e_MagType = pc_Common->c_Mag.getMagType();
	TYPC_Point<float> c_MagTemplate = pc_Common->c_Mag.getMag().xyReverse();
	TYPE_OriginalSizeMode e_OriginalSizeMode = pc_Scan->c_OriginalSize.getOriginalSizeMode();
	// 現行倍率ステータスの表示.
	setupInputMagStatus( pc_Job, b_AmsOn, b_Available, e_MagType, c_MagTemplate, e_OriginalSizeMode, ss_MagInpDigit, pst_SetupMagCopy );
}
//概要    :現行片面/両面ステータス
void PnlComSetFaceStataus( TYPC_JobSpec* c_JobSpec, PCGS_SetupFace* pst_SetupFace )
{
	if( ( NULL == c_JobSpec ) || ( NULL == pst_SetupFace ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PnlComSetFaceStataus", UC_PNL_ERROR_PARAMETER );
		return;
	}
	if(	( NULL == pst_SetupFace->pc_Btx_FaceStatus )
	    || ( NULL == pst_SetupFace->pc_Ktx_Face )
	    || ( NULL == pst_SetupFace->pc_Ktx_Nin1 )
	    || ( NULL == pst_SetupFace->pc_Gra_FaceStatausLeft )
	    || ( NULL == pst_SetupFace->pc_Gra_FaceStatausRight ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "setupInputMagStatus", UC_PNL_ERROR_PARAMETER );
		return;
	}
	uchar	uc_FaceFrom = 0;
	uchar	uc_FaceTo   = 0;
	uchar	uc_Nin1     = 0;
	// 現行片面／両面ステータス文字表示.
	PnlComSetFaceStatausStr( c_JobSpec, pst_SetupFace->pc_Btx_FaceStatus, pst_SetupFace->pc_Ktx_Face, pst_SetupFace->pc_Ktx_Nin1, &uc_FaceFrom, &uc_FaceTo, &uc_Nin1 );
	// 現行片面/両面ステータスのアイコン表示.
	pst_SetupFace->pc_Btx_FaceStatus->changeGraphic( pst_SetupFace->pc_Gra_FaceStatausLeft,  uc_FaceFromStatausIconTable[ uc_FaceFrom ] );	// 片面/両面アイコンの左絵.
	pst_SetupFace->pc_Btx_FaceStatus->changeGraphic( pst_SetupFace->pc_Gra_FaceStatausRight, uc_FaceToStatausIconTable[ uc_FaceTo ] );		// 片面/両面アイコンの右絵.
}
//概要    :現行片面/両面ステータス文字表示
void PnlComSetFaceStatausStr(
    TYPC_JobSpec*			c_JobSpec,
    PActivatableAdd*		pc_ParentParts,
    PSinglePartsText*		pc_Txt_Status1,
    PSinglePartsText*		pc_Txt_Status2,
    uchar*					puc_FaceFrom,
    uchar*					puc_FaceTo,
    uchar*					puc_Nin1 )
{
	if(	( NULL == c_JobSpec )
	    || ( NULL == pc_ParentParts )
	    || ( NULL == pc_Txt_Status1 )
	    || ( NULL == pc_Txt_Status2 )
	    || ( NULL == puc_FaceFrom )
	    || ( NULL == puc_FaceTo )
	    || ( NULL == puc_Nin1 ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "setupInputMagStatus", UC_PNL_ERROR_PARAMETER );
		return;
	}
	TYPC_Scan*	pc_Scan	= c_JobSpec->pc_Scan;
	TYPC_Print*	pc_Print= c_JobSpec->pc_Print;
	// 両面／片面モードの取得.
	*puc_FaceFrom = ( pc_Scan->getDuplex() == True )? 1 : 0;
	*puc_FaceTo   = ( pc_Print->getDuplexMode() == TYPE_DuplexModeOff )? 0 : 1;
	if( pc_Print->getDuplexMode() == TYPE_DuplexModePageMix && PnlComGetJBDocStatus() != NULL ) {
		*puc_FaceTo = ( PnlComGetJBDocStatus()->getDuplexPrint() == False ) ? 0 : 1;
	}
	// 以下の式は、片／片、片／両、両／片、両／両のパターンのみ有効なので、これ以外のパターンが増えたら変更して下さい.
	uchar uc_SelectFaceStr  = ( uchar )( ( *puc_FaceFrom*2 ) + *puc_FaceTo );
	// Ｎin１の取得.
	Bool b_Nin1On = False;
	uchar i = 0;
	for( i = 0; uc_SizeNin1PartsTbl > i; ++i ) {
		if( True == isOn( st_Nin1PartsTbl[ i ].e_Combination, c_JobSpec ) ) {
			// 現行Nin1ステータスの切り替え.
			b_Nin1On = True;
			break;
		}
	}
	// 現行片面/両面ステータスの表示処理.
	pc_ParentParts->changeText( pc_Txt_Status1, uc_FaceModeTable[ uc_SelectFaceStr ] );
	// Ｎin1ステータスの表示処理.
	*puc_Nin1 = 0;
	if( True == b_Nin1On ) {
		pc_ParentParts->changeText( pc_Txt_Status2, st_Nin1PartsTbl[ i ].td_Nin1 );
		*puc_Nin1 = 1;
	}
	pc_ParentParts->showEnableAdd( pc_Txt_Status2, b_Nin1On );
}
//概要    :現行片面/両面ステータス文字表示
void PnlComGetFaceTextStr(
    TYPC_JobSpec*			c_JobSpec,
    TEXT_ID*				setupFace1,
    TEXT_ID*				setupFace2,
    uchar*					puc_FaceFrom,
    uchar*					puc_FaceTo,
    uchar*					puc_Nin1 )
{
	if(	( NULL == c_JobSpec )
	    || ( NULL == puc_FaceFrom )
	    || ( NULL == puc_FaceTo )
	    || ( NULL == puc_Nin1 ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "setupInputMagStatus", UC_PNL_ERROR_PARAMETER );
		return;
	}
	TYPC_Scan*	pc_Scan	= c_JobSpec->pc_Scan;
	TYPC_Print*	pc_Print= c_JobSpec->pc_Print;
	// 両面／片面モードの取得.
	*puc_FaceFrom = ( pc_Scan->getDuplex() == True )? 1 : 0;
	*puc_FaceTo   = ( pc_Print->getDuplexMode() == TYPE_DuplexModeOff )? 0 : 1;
	if( pc_Print->getDuplexMode() == TYPE_DuplexModePageMix && PnlComGetJBDocStatus() != NULL ) {
		*puc_FaceTo = ( PnlComGetJBDocStatus()->getDuplexPrint() == False ) ? 0 : 1;
	}
	// 以下の式は、片／片、片／両、両／片、両／両のパターンのみ有効なので、これ以外のパターンが増えたら変更して下さい.
	uchar uc_SelectFaceStr  = ( uchar )( ( *puc_FaceFrom*2 ) + *puc_FaceTo );
	// Ｎin１の取得.
	Bool b_Nin1On = False;
	uchar i = 0;
	for( i = 0; uc_SizeNin1PartsTbl > i; ++i ) {
		if( True == isOn( st_Nin1PartsTbl[ i ].e_Combination, c_JobSpec ) ) {
			// 現行Nin1ステータスの切り替え.
			b_Nin1On = True;
			break;
		}
	}
	// 現行片面/両面ステータスの表示処理.
	*setupFace1 = uc_FaceModeTable[ uc_SelectFaceStr ];
	// Ｎin1ステータスの表示処理.
	*puc_Nin1 = 0;
	if( True == b_Nin1On ) {
		*setupFace2 = st_Nin1PartsTbl[ i ].td_Nin1;
		*puc_Nin1 = 1;
	}
}
//概要    :PCプリント片面/両面/ページ編集ステータスセットアップ.
void PnlComSetPCPrintFaceCombPageStataus( APIC_Job* pc_Job, PSinglePartsText* p_Txt_CopyFaceStatus, PSinglePartsText* p_Txt_CopyCombPageStatus )
{
	if( !( NULL != pc_Job ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }
	if( !( NULL != p_Txt_CopyFaceStatus ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }
	if( !( NULL != p_Txt_CopyCombPageStatus ) ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }
	TYPC_Print* pc_Print = pc_Job->getJobSpec()->pc_Print;
	TEXT_ID puc_Str = NULL;
	switch( pc_Print->getDuplexMode() ) {
		case TYPE_DuplexModeOff: puc_Str = s_1Sided; break;	// 片面.
		case TYPE_DuplexModeOn: puc_Str = s_2Sided; break;	// 両面.
		case TYPE_DuplexModePageMix:	// 片面/両面ページ混在
			// 片面プリント.
			if( False == pc_Job->getJobStatus()->getDuplexPrint() ) {
				puc_Str = s_1Sided;	// 片面.
			} else {
				// 両面プリント.
				puc_Str = s_2Sided;	// 両面.
			}
			break;
	}
	p_Txt_CopyFaceStatus->changeText( puc_Str );
	// Nin1の情報は取得できないため非表示.
	p_Txt_CopyCombPageStatus->showEnable( False );
}
