void SetMsgBoxPopup_WarningCode( char* char_ScreenNo )
{
	// Find Warning ID of Screen.
	Bool bl_MsgBoxPopup = False;
	ushort i = 0;
	while( s_MsgBoxPopup[i].ec_WarningName != TYPE_WarningName_Non ) {
		if( strcmp( char_ScreenNo, s_MsgBoxPopup[i].sc_strScreenNumber ) == 0 ) {
			bl_MsgBoxPopup = True;
			break;
		}
		i++;
	}

	PNLC_WarningDataLib* pc_WarnDataLib = PNLC_WarningDataLib::newInstance();

	// Set Warning ID of Screen.
	if( bl_MsgBoxPopup == True ) {
		TYPE_WarningName	p_WarningName = s_MsgBoxPopup[i].ec_WarningName;

		// Check Warning Type
		if( s_MsgBoxPopup[i].ec_WarningName < PANEL_ERROR_MINIMUM_DEBUG ) {
			pc_WarnDataLib->setNewSystemWarningDebug( p_WarningName );			// System Warning Type.
		} else {
			pc_WarnDataLib->setNewPanelWarningDebug( p_WarningName );				// Panel Warning Type.
		}
	}
}


