//概要　　：宛先種別をパネル表示用宛先種別に変換.
TYPE_PanelSendMode convertSendMode( TYPE_SendMode e_SendMode )
{
	switch( e_SendMode ) {
		case TYPE_SendModeNotSetting: return TYPE_PanelSendModeNotSetting; break;	// 未設定状態
		case TYPE_SendModeFax: return TYPE_PanelSendModeFax; break;	// Ｇ３ＦＡＸ送信
		case TYPE_SendModeIfax: return TYPE_PanelSendModeIfax; break;	// Ｉ－ＦＡＸ送信
		case TYPE_SendModeEmail: return TYPE_PanelSendModeEmail; break;	// Ｅ－Ｍａｉｌ送信
		case TYPE_SendModeFtp: return TYPE_PanelSendModeFtp; break;	// ＦＴＰ送信
		case TYPE_SendModeSmb: return TYPE_PanelSendModeSmb; break;	// ＳＭＢ送信
		case TYPE_SendModeBox: return TYPE_PanelSendModeBox; break;	// ＢＯＸ送信
		case TYPE_SendModeIPAddressFax: return TYPE_PanelSendModeIPAddressFax; break;	// IP AddressFax.
		case TYPE_SendModeWebDav: return TYPE_PanelSendModeWebDav; break;	// WebDAV送信
		case TYPE_SendModeScanServer: return TYPE_PanelSendModeScanServer; break;	// スキャンサーバー送信(Distirbuted Scan) DonauLastFum【DistributedScan】【13加藤た】2009/03/23.
		case TYPE_SendModeSharedFolder: return TYPE_PanelSendModeSMBSharedFolder; break;	// 共有フォルダ(汎用ファイル)送信.
// comment 2019/01/29 SCD2-Sky薗﨑 [EagleH][OP_BTS-2266]【RQ-272】実行中リストでIP-FAX（T38）受信ジョブが設定不可と一瞬表示される不具合対応.
		case TYPE_SendModeIPFax: return TYPE_PanelSendModeIPFaxT38; break;	// IP-Fax(T.38)送信の場合.
		default:
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return TYPE_PanelSendModeNotSetting;
			break;
	}
}
//概要　　：送信履歴用宛先種別をパネル表示用宛先種別に変換.
TYPE_PanelSendMode convertSendLogSendMode( TYPE_SendLogSendMode e_SendLogSendMode )
{
	switch( e_SendLogSendMode ) {
		case TYPE_SendLogSendModeEmail: return TYPE_PanelSendModeEmail; break;	// Ｅ－Ｍａｉｌ送信
		case TYPE_SendLogSendModeFtp: return TYPE_PanelSendModeFtp; break;	// ＦＴＰ送信
		case TYPE_SendLogSendModeSmb: return TYPE_PanelSendModeSmb; break;	// ＳＭＢ送信
		case TYPE_SendLogSendModeFax: return TYPE_PanelSendModeFax; break;	// Ｇ３ＦＡＸ送信
		case TYPE_SendLogSendModeIfax: return TYPE_PanelSendModeIfax; break;	// Ｉ－ＦＡＸ送信
		case TYPE_SendLogSendModeTcpSocket: return TYPE_PanelSendModeTcpSocket; break;	// Tcp Socket
		case TYPE_SendLogSendModePSWC: return TYPE_PanelSendModePSWC; break;	// PSWC
		case TYPE_SendLogSendModeOpenAPI: return TYPE_PanelSendModeOpenAPI; break;	// Oepn API
		case TYPE_SendLogSendModeWebDav: return TYPE_PanelSendModeWebDav; break;	// WebDAV送信
		default:
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return TYPE_PanelSendModeNotSetting;
			break;
	}
}
//概要    :ボックス保存されたドキュメントがファクス受信か判断.
//引数    :TYPE_JobType.
//戻り値  :ファクス受信はTrue、ファクス受信以外にはFalseを返す.
Bool checkFaxtoBoxJobType( TYPE_JobType e_JobType )
{
	Bool b_Result = False;
	//	ファクス受信であれば、Trueを返す.
	switch( e_JobType ) {
		case TYPE_JobTypeFaxReceive:		// ＦＡＸ受信プリント.
		case TYPE_JobTypeIfaxReceive:		// ＩＦａｘ受信.
		case TYPE_JobTypeFaxReceiveTimer: b_Result = True; break;	// ＦＡＸ（タイマーポーリング受信）.
		default: break;
	}
	return b_Result;
}
//概要　　：原稿サイズ確定状況の判定
Bool PnlComIsFixedOriginalSize( APIC_Job* pc_Job )
{
	if( NULL != pc_Job ) {
		if( ( ( ( True == pc_Job->isPlatenOriginalSizeFixed() )
		        && ( TYPE_SizeCodeUnknown != ppc_Original->getPlatenOriginalSize().e_SizeCode ) )
		      || ( EP_PNS_SeparateScanStop == onlyPanel.ep_PanelStatus ) )
		    || ( ( ( ( True == pc_Job->isADFOriginalSizeFixed() )
		             && ( TYPE_SizeCodeUnknown != ppc_Original->getAdfOriginalSize().e_SizeCode ) )
		           || ( EP_PNS_SeparateScanStop == onlyPanel.ep_PanelStatus ) )
		         && ( False == isOn( CNK_MixOriginal, pc_Job ) )
		         && ( False == isOn( CNK_OriginalZore, pc_Job ) )
		         && ( False == isOn( CNK_FaxOriginalLong, pc_Job ) ) ) )
		{
			return True;
		}
	}
	return False;
}
