//概要：.
Bool progJobCheckAndSetForceMemoryIn( APIC_Job* pc_Job, Bool bl_checkonly )
{
	PCGC_JobSpecCopyBackup* _pc_JobSpecCopyBackup = PnlComGetJobSpecCopyBack();
	APIC_AutoSelect* _pc_AutoSelect = comPanelJob->getAutoSelect();
	if( ( ( comPanelJob->getJobSpec()->pc_Common->c_JobType.getJobType() == TYPE_JobTypeCopy )			// コピージョブ
	      || ( comPanelJob->getJobSpec()->pc_Common->c_JobType.getJobType() == TYPE_JobTypeIntCopy )		// 割込みジョブ
	      || ( comPanelJob->getJobSpec()->pc_Common->c_JobType.getJobType() == TYPE_JobTypeScan ) )			// スキャンジョブ
	    && ( ( NULL != _pc_AutoSelect ) && ( TYPE_OriginalSettingPlaten == _pc_AutoSelect->chkOriginalSetting( True ) ) )
	    && ( ( ( ( NULL != _pc_JobSpecCopyBackup ) && ( False == _pc_JobSpecCopyBackup->b_SortAutoChangeOn ) ) && ( True == isOn( CNK_Sort, pc_Job ) ) )      // マニュアル設定でのソートモード.
	         || ( pc_Job->getJobSpec()->pc_Print->c_Nin1.getNin1() != TYPE_Nin1_1in1 )                                           // Ｎin１コピー
	         || ( ( isOn( CNK_2SideCopy, pc_Job ) == True ) && ( !( isOn( CNK_BookSeparation, pc_Job ) ) ) ) // 両面コピー
	         || ( pc_Job->getJobSpec()->pc_Print->c_Finishing.getStapleMode() != TYPE_StapleModeNone )   // ステープル
	         || ( isOn( CNK_OriginalInsertion, pc_Job ) == True )                                        // 差込ページ.
	         || ( isOn( CNK_CoverMode, pc_Job )         == True )                                        // 表紙（インターシートの一部）.
	         || ( isOn( CNK_MiddleMode, pc_Job )        == True )                                        // インターシート.
	         || ( isOn( CNK_Chapter, pc_Job )           == True )                                        // 章分け.
	         || ( isOn( CNK_AdminPrint, pc_Job )        == True )                                        // 管理ナンバー（連番印字）
	         || ( isOn( CNK_OnePieceOutput, pc_Job )    == True )                                        // １部先出し
	         || ( isOn( CNK_2SideOrig, pc_Job )		    == True ) ) ) {	                                 //  両面原稿
		// コピージョブかつ手置き原稿で、ソート or Nin1コピー or 両面コピー（但しブック分割でない時） or ステープル設定時 or 管理ナンバー設定時
		if( False == bl_checkonly ) {
			pc_Job->getJobSpec()->pc_Scan->c_MemoryIn.setMemoryInOn( True );
			pc_Job->getJobSpec()->pc_Scan->c_MemoryIn.setMemoryInContinue( True );
		}
		return True;
	}
	// ブック連写、表紙有り時は分割読込みにする.
	if( TYPE_PageShotNone != pc_Job->getJobSpec()->pc_Scan->c_PageShot.getPageShot()
	    && TYPE_PageShotCoverNon != pc_Job->getJobSpec()->pc_Scan->c_PageShot.getPageShotCover() ) {
		if( False == bl_checkonly ) {
			pc_Job->getJobSpec()->pc_Scan->c_MemoryIn.setMemoryInOn( True );
			pc_Job->getJobSpec()->pc_Scan->c_MemoryIn.setMemoryInContinue( True );
		}
		return True;
	}
	return False;
}
