void PnlComDocSetupScanGamenStatus( short option ) {
	APIC_Job* pc_Job = NULL;
	if( !( NULL != pc_Job ) ) {
		//ログを書く.
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
	}

//解像度ステータスセットアップ表示.
	PnlComSetScanResolutionStataus( pc_Job, &Txt_DocScanResolutioninfo_com,( PSinglePartsGraphic* )&Gra_DocPaperResolution_com );

//片面/両面ステータスセットアップ表示.
	PnlComSetScanFaceStataus( pc_Job, &Txt_DocCopyFaceInfo2_com );
}
//関数------------------------------------------------------------------------------------------------------------------
//概要    ：ジョブ詳細の取得の共通関数
//備考    ：
//戻値    ：
//作成者  ：AWS_マキ.
//レビュー：
//変更履歴：
void PnlComDocSetScanFaxImageDensity( APIC_Job* pc_Job,
                                      PSinglePartsText*  p_Txt_ScanFaxImageStatus,
                                      PSinglePartsText*  p_Txt_ScanFaxDensityStatus,
                                      PSinglePartsGraphic*  p_Gra_ScanFaxSetUpScanContrast,
                                      PActivatableAdd*  p_Btx_ScanFaxSetUpScanContrast )
{
	if( ( NULL == pc_Job ) || ( NULL == p_Txt_ScanFaxImageStatus ) || ( NULL == p_Gra_ScanFaxSetUpScanContrast ) || ( NULL == p_Btx_ScanFaxSetUpScanContrast ) ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}

	TYPC_Common* pc_Common = pc_Job->getJobSpec()->pc_Common;
	TEXT_ID      puc_Str   = NULL;
	//原稿画像モードを判定.
	switch( pc_Common->c_OriginalImageMode.getOriginalImageMode() ) {
		case TYPE_OriginalImageModeText:	puc_Str = s_pITMText_W116H016A;	break; 	// 文字.
		case TYPE_OriginalImageModeTextPhoto:		// 文字＋印画紙写真.
		case TYPE_OriginalImageModeTextPrintImage:	// 文字+印刷写真.
			puc_Str = s_pKEYTextPhoto_W116H016A;
			break;
		case TYPE_OriginalImageModePhoto:	// 印画紙写真.
		case TYPE_OriginalImageModePrintImage:	// 印刷写真.
			puc_Str = s_pKEYPhoto_W116H016A;
			break;
		case TYPE_OriginalImageModePencil:		puc_Str = s_pKEYDotMatrixOriginal_W116H016A;	break;	//薄文字.
		case TYPE_OriginalImageModeGeneration:	puc_Str = s_pKEYCopiedPaper_W116H016A;			break;	//コピー原稿.
		case TYPE_OriginalImageModeCustom:		puc_Str = s_pITMCustomState_W116H016A;			break;	//カスタム.
// Comment 2016/11/10 [IT5_3.4] [AR1007447] [HCL-Sivaguru] Adding the case for Contrast Bar code.
		case TYPE_OriginalImageModeSimplebinary:	puc_Str = s_pITMBinaryMode_W116H016A;		break;	//BarCode/ Contrast.
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	break;
	}
	//パーツセットアップ.
	p_Btx_ScanFaxSetUpScanContrast->changeText( p_Txt_ScanFaxImageStatus, puc_Str );
	p_Btx_ScanFaxSetUpScanContrast->showEnableShowAdd( p_Txt_ScanFaxImageStatus, True );

	//濃度のアイコン表示.
	switch( pc_Common->c_ImageAdjust.getDensity().getImageAdjust() ) {
		//濃度がL4の場合.
		case TYPE_ImageAdjustM09: p_Btx_ScanFaxSetUpScanContrast->changeGraphic( p_Gra_ScanFaxSetUpScanContrast, i00_799_000_sm4_X116_Y32 ); break;
		//濃度がL3の場合.
		case TYPE_ImageAdjustM06: p_Btx_ScanFaxSetUpScanContrast->changeGraphic( p_Gra_ScanFaxSetUpScanContrast, i00_799_000_sm3_X116_Y32 ); break; // L3.
		//濃度がL2濃度が.
		case TYPE_ImageAdjustM04: p_Btx_ScanFaxSetUpScanContrast->changeGraphic( p_Gra_ScanFaxSetUpScanContrast, i00_799_000_sm2_X116_Y32 ); break; // L2.
		//濃度がL1濃度が.
		case TYPE_ImageAdjustM02: p_Btx_ScanFaxSetUpScanContrast->changeGraphic( p_Gra_ScanFaxSetUpScanContrast, i00_799_000_sm1_X116_Y32 ); break; // L1.
		//濃度がD1濃度が.
		case TYPE_ImageAdjustP02: p_Btx_ScanFaxSetUpScanContrast->changeGraphic( p_Gra_ScanFaxSetUpScanContrast, i00_799_000_sp1_X116_Y32 ); break; // D1.
		//濃度がD2濃度が.
		case TYPE_ImageAdjustP04: p_Btx_ScanFaxSetUpScanContrast->changeGraphic( p_Gra_ScanFaxSetUpScanContrast, i00_799_000_sp2_X116_Y32 ); break; // D2.
		//濃度がD3濃度が.
		case TYPE_ImageAdjustP06: p_Btx_ScanFaxSetUpScanContrast->changeGraphic( p_Gra_ScanFaxSetUpScanContrast, i00_799_000_sp3_X116_Y32 ); break; // D3.
		//濃度がD4濃度が.
		case TYPE_ImageAdjustP09: p_Btx_ScanFaxSetUpScanContrast->changeGraphic( p_Gra_ScanFaxSetUpScanContrast, i00_799_000_sp4_X116_Y32 ); break; // D4.
		//デフォールト.
		default: p_Btx_ScanFaxSetUpScanContrast->changeGraphic( p_Gra_ScanFaxSetUpScanContrast, i00_799_000_s0_X116_Y32 ); break;
	}
	//パーツセットアップ.
	p_Btx_ScanFaxSetUpScanContrast->showEnableShowAdd( p_Txt_ScanFaxDensityStatus,  False ); // 「自動」を非表示.
	p_Btx_ScanFaxSetUpScanContrast->showEnableShowAdd( p_Gra_ScanFaxSetUpScanContrast, True );  // レベルゲージを表示.
}
