//概要    ：ジョブ詳細の取得の共通関数
//備考    ：
//戻値    ：
//作成者  ：AWS_マキ.
//レビュー：
//変更履歴：
/*================================================================================================
［機能］	用紙サイズを取得する.
--------------------------------------------------------------------------------------------------
［引数］	TYPC_PaperSize    size       : 用紙サイズ.
［戻値］	ushort.
================================================================================================*/
ushort PnlComDocGetPaperSize( TYPC_PaperSize size )
{
	uchar i = 0;
	ushort us_TextID = 0;

	//サイズコード.
	if( TYPE_SizeCodeNonStandard == size.e_SizeCode ) {
		return us_TextID;
	}

	if( TYPE_SizeCodeFlsSef == size.e_SizeCode ) {
		switch( pc_MachineSetting->getFLSType() ) {
#ifdef DEF_LCD_7INCH
			case TYPE_FLSType85x135:
				us_TextID = s_pNOTPaperSizeFoolscap_001_W096H018A; break;		// 8_1/2inch x 13_1/2inch.
			case TYPE_FLSType220x330:
				us_TextID = s_pNOTPaperSizeFoolscap_002_W096H018A; break;		// 220mm x 330mm.
			case TYPE_FLSType85x13:
				us_TextID = s_pNOTPaperSizeFoolscap_003_W096H018A; break;		// 8_1/2inch x 13inch.
			case TYPE_FLSType825x13:
				us_TextID = s_pNOTPaperSizeFoolscap_004_W096H018A; break;		// 8_1/4inch x 13inch.
			case TYPE_FLSType8125x1325:
				us_TextID = s_pNOTPaperSizeFoolscap_005_W096H018A; break;		// 8_1/8inch x 13_1/4inch.
			case TYPE_FLSType8x13:
				us_TextID = s_pNOTPaperSizeFoolscap_006_W096H018A; break;		// 8inch x 13inch.
#else // #ifdef DEF_LCD_7INCH.
			case TYPE_FLSType85x135:
				us_TextID = s_pNOTPaperSizeFoolscap_001_W96H016A; break;		// 8_1/2inch x 13_1/2inch.
			case TYPE_FLSType220x330:
				us_TextID = s_pNOTPaperSizeFoolscap_002_W96H016A; break;		// 220mm x 330mm.
			case TYPE_FLSType85x13:
				us_TextID = s_pNOTPaperSizeFoolscap_003_W96H016A; break;		// 8_1/2inch x 13inch.
			case TYPE_FLSType825x13:
				us_TextID = s_pNOTPaperSizeFoolscap_004_W96H016A; break;		// 8_1/4inch x 13inch.
			case TYPE_FLSType8125x1325:
				us_TextID = s_pNOTPaperSizeFoolscap_005_W96H016A; break;		// 8_1/8inch x 13_1/4inch.
			case TYPE_FLSType8x13:
				us_TextID = s_pNOTPaperSizeFoolscap_006_W96H016A; break;		// 8inch x 13inch.
#endif // #ifdef DEF_LCD_7INCH.
			default:break;
		}
		return us_TextID;
	}
	// サイズコード検索.

	for( i = 0; i < sizeof( tbl_PaperSizeCode )/sizeof( PNLC_PaperSizeCode ); i++ ) {
		//テーブル内に一致するサイズコードがあるか検索.
		if( tbl_PaperSizeCode[ i ].size == size.e_SizeCode ) {
			//一致した場合.
			if( ( True == size.b_WideOn )												// ワイド用紙.
			    && ( s_Dummy != tbl_PaperSizeCode[ i ].us_WideTextID ) ) {
				// ワイド紙指定時.
				us_TextID = tbl_PaperSizeCode[ i ].us_WideTextID;
			} else {
				us_TextID = tbl_PaperSizeCode[ i ].us_TextID;
			}
		}
	}

	// 洋形2号の場合.
	if( TYPE_SizeCodeJpLetterY2 == size.e_SizeCode ) {
		// 日本仕向け以外.
		if( TYPE_SystemType_JP != PnlComGetDestination() ) {
#ifdef DEF_LCD_7INCH
#ifdef DEF_KRONOSS_Cus
			us_TextID = s_pNOTenvC6_W096H018A;
#else // DEF_KRONOSS_Cus.
			us_TextID = s_pNOTenvC6SEF_W096H018A;
#endif // DEF_KRONOSS_Cus.
#else // #ifdef DEF_LCD_7INCH.
			us_TextID = s_pNOTenvC6SEF_W056H016A;
#endif // #ifdef DEF_LCD_7INCH.
		}
	}

#ifdef DEF_A4_Cus  // A3A4共通化FUM ST 2015.01.22 Sky藤本.
	if ( TYPE_SizeCodeJpLetterY2Lef == size.e_SizeCode ) {
		// 日本仕向け以外.
		if ( TYPE_SystemType_JP != PnlComGetDestination() ) {
			us_TextID = s_pNOTenvC6LEF_W096H018A;
		}
	}
#endif  // DEF_A4_Cus A3A4共通化FUM ED 2015.01.22 Sky藤本.
	return us_TextID;
}
// ===============================================================================================
/**
@name	::/PnlComGetUTF8Str
@brief	パネル外部から取得した文字列をUTF-8で扱うよう変更する.
		LIBF_ConvertFromUTF8()を2番目の引数LIBE_CharSetUTF8を使って呼び出すよう変更.
		対応箇所が多いため、この関数をラップさせる.
*/
// ===============================================================================================
unsigned int PnlComGetUTF8Str( const char* psc_UTF8String, const LIBE_CharSet e_FromStringCharSet, char* psc_FromString, unsigned int un_FromStringBufferSize )
{
	unsigned int uiRet;

	if( NULL == psc_UTF8String ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	return 0; }	// NULLチェックを追加.//【 静的解析対応 : 柳川 : 2011.03.03 : CID-142889 】.
	if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {		// Donau拡張機能3、Amur機能拡張2以降なら.
		// UTF-8へ変換する.
		uiRet = LIBF_ConvertFromUTF8( psc_UTF8String,
		                              LIBE_CharSetUTF8,
		                              psc_FromString,
		                              un_FromStringBufferSize );

	} else {
		// 指定のキャラセットへ変換する.
		uiRet = LIBF_ConvertFromUTF8( psc_UTF8String,
		                              e_FromStringCharSet,
		                              psc_FromString,
		                              un_FromStringBufferSize );
	}

	return uiRet;
}

// ===============================================================================================
/**
@name	::/PnlComSetUTF8Str
@brief	パネル外部から取得した文字列をUTF-8で扱うよう変更する.
		LIBF_ConvertToUTF8()を1番目の引数LIBE_CharSetUTF8を使って呼び出すよう変更.
		対応箇所が多いため、この関数をラップさせる.
*/
// ===============================================================================================
unsigned int PnlComSetUTF8Str( const LIBE_CharSet e_ToStringCharSet, const char* psc_ToString, char* psc_UTF8String, unsigned int un_UTF8StringBufferSiz )
{
	unsigned int uiRet;

	if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {		// Donau拡張機能3、Amur機能拡張2以降なら.
		// UTF-8から変換する.
		uiRet = LIBF_ConvertToUTF8( LIBE_CharSetUTF8,
		                            psc_ToString,
		                            psc_UTF8String,
		                            un_UTF8StringBufferSiz );
	} else {
		// 指定のから変換する.
		uiRet = LIBF_ConvertToUTF8( e_ToStringCharSet,
		                            psc_ToString,
		                            psc_UTF8String,
		                            un_UTF8StringBufferSiz );
	}

	return uiRet;
}


/**
 *	@brief	Job TypeからAccount Statusを取得.
 *	@param	対象となるJob Type.
 *	@retval	Account Status.
 */
PNLE_ACCOUNT_STATUS_TYPE getAccountStatusTypeFromJobType( TYPE_JobType eType )
{
	PNLE_ACCOUNT_STATUS_TYPE	funcType;

	// PullPrint or PullPrintBrowser起動中.
	if( ( ScanOapExtSet.isActiveGeneralApplication() ) &&
	    ( TYPE_ExtTypePullPrint == ScanOapExtSet.getExtAppType() ||
	      TYPE_ExtTypeBrowserPull == ScanOapExtSet.getExtAppType() ) ) {
		return PNLE_ACCOUNT_STATUS_TYPE_Print;
	}

	switch( eType ) {
		case TYPE_JobTypeCopy:
		case TYPE_JobTypeIntCopy:
		{
			funcType = PNLE_ACCOUNT_STATUS_TYPE_Copy;
			break;
		}
		case TYPE_JobTypeScan:
		case TYPE_JobTypeTwain:
		{
			funcType = PNLE_ACCOUNT_STATUS_TYPE_Scan;
			break;
		}
		case TYPE_JobTypeFaxSendQuick:
		case TYPE_JobTypeFaxSendMemory:
		case TYPE_JobTypeFaxSendTimer:
		case TYPE_JobTypeFaxReceive:
		case TYPE_JobTypeIfaxReceive:
		case TYPE_JobTypeFaxReceiveTimer:
		case TYPE_JobTypeFaxReceivePolling:
		{
			funcType = PNLE_ACCOUNT_STATUS_TYPE_Fax;
			break;
		}
		default:
		{
			funcType = PNLE_ACCOUNT_STATUS_TYPE_Print;
			break;
		}
	};

	return funcType;
}
/**
 *	@brief	コピー画面ステータス設定.
 *	@param	結果応答へのポインタ.
 *	@param	ユーザー機能使用制限.
 *	@param	部門機能使用制限.
 *	@retval	結果応答が有効かどうか.
 */
Bool isEnableFunctionLimitation( Bool* pbl_Result, short userMask, short trackMask )
{
	APIC_User*	pc_User	= PnlComGetUser();			// ユーザー取得.
	APIC_Track*	pc_Track	= PnlComGetTrack();			// 部門取得.
	Bool		bl_Ret		= False;					// 結果応答が有効かどうか.

	if( pc_User && pc_Track && pbl_Result ) {
		*pbl_Result = APIC_UserAuthentication::newInstance()->checkEnableFunctionLimitation(
		                  TYPD_UserFunctionMask_None, pc_User, TYPD_TrackFunctionMask_None, pc_Track );
		bl_Ret = True;
	} else {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
	}

	return bl_Ret;
}
/**
 *	@brief	機能の制限を取得.
 *	@param	対象の機能管理構造体.
 *	@param	判定機能.
 *	@retval	機能制限結果、内部でエラーの場合は強制的に「TYPE_FuncLimit_Disable」を応答.
 */
TYPE_FuncLimit getFunctionLimitation( TYPS_FunctionLimitation* ps_FuncLimit, PNLE_ACCOUNT_STATUS_TYPE e_UserAccountStatus )
{
	TYPE_FuncLimit retFuncLimit = TYPE_FuncLimit_Disable;

	if( ps_FuncLimit ) {
		switch( e_UserAccountStatus ) {
			// コピー操作				:禁止/ブラックのみ許可/許可.
			case PNLE_ACCOUNT_STATUS_TYPE_Copy:					retFuncLimit = ps_FuncLimit->e_EnableCopy;					break;
			// スキャナー操作			:禁止/ブラックのみ許可/許可.
			case PNLE_ACCOUNT_STATUS_TYPE_Scan:					retFuncLimit = ps_FuncLimit->e_EnableScan;					break;
			// FAX(IFAX)操作			:禁止/ブラックのみ許可/許可.
			case PNLE_ACCOUNT_STATUS_TYPE_Fax:					retFuncLimit = ps_FuncLimit->e_EnableFax;					break;
			// プリンター印字			:禁止/ブラックのみ許可/許可.
			case PNLE_ACCOUNT_STATUS_TYPE_Print:				retFuncLimit = ps_FuncLimit->e_EnablePrint;					break;
			// 蓄積文書操作				:禁止/許可/送信文書の印字_禁止.
			case PNLE_ACCOUNT_STATUS_TYPE_BoxOperation:			retFuncLimit = ps_FuncLimit->e_EnableBoxOperation;			break;
			// 送信文書の印字			:禁止/ブラックのみ許可/許可.
			case PNLE_ACCOUNT_STATUS_TYPE_PrintOfSendDocument:	retFuncLimit = ps_FuncLimit->e_EnablePrintOfSendDocument;	break;
			// 外部メモリ読込			:禁止/許可.
			case PNLE_ACCOUNT_STATUS_TYPE_ScanToUsb:			retFuncLimit = ps_FuncLimit->e_EnableScanToUsb;				break;
			// ブラウザ使用				:禁止/許可.
			case PNLE_ACCOUNT_STATUS_TYPE_WebBrowser:			retFuncLimit = ps_FuncLimit->e_EnableBrowser;				break;
			// 生体／ICカード登録		:禁止/許可.
			case PNLE_ACCOUNT_STATUS_TYPE_ICCard:				retFuncLimit = ps_FuncLimit->e_EnableBioIccSetInfo;			break;
			// 外部メモリ読込			:禁止/許可.
			case PNLE_ACCOUNT_STATUS_TYPE_UsbMemoryReading:		retFuncLimit = ps_FuncLimit->e_EnableUsbMemoryReading;		break;
			// ファイルアップロード操作	:禁止/許可.
			case PNLE_ACCOUNT_STATUS_TYPE_FileUpload:			retFuncLimit = ps_FuncLimit->e_BrowserFileUpload;			break;
			// ファイルダウンロード操作	:禁止/許可.
			case PNLE_ACCOUNT_STATUS_TYPE_FileDownload:			retFuncLimit = ps_FuncLimit->e_BrowserFileDownload;			break;
			default:																										break;
		}
	} else {
		retFuncLimit = TYPE_FuncLimit_Disable;
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
	}

	return retFuncLimit;
}
/**
 *	@brief	ユーザー認証の機能制限を取得.
 *	@param	対象の機能管理構造体.
 *	@param	判定機能.
 *	@retval	機能制限結果、内部でエラーの場合は強制的に「TYPE_FuncLimit_Disable」を応答.
 */
TYPE_FuncLimit getFunctionLimitationUser( TYPS_FunctionLimitation* ps_FuncLimit, PNLE_ACCOUNT_STATUS_TYPE e_UserAccountStatus )
{
	return getFunctionLimitation( ps_FuncLimit, e_UserAccountStatus );
}
/**
 *	@brief	部門管理の機能制限を取得.
 *	@param	対象の機能管理構造体.
 *	@param	判定機能.
 *	@retval	機能制限結果、内部でエラーの場合は強制的に「TYPE_FuncLimit_Disable」を応答.
 */
TYPE_FuncLimit getFunctionLimitationTrack( TYPS_FunctionLimitation* ps_FuncLimit, PNLE_ACCOUNT_STATUS_TYPE e_UserAccountStatus )
{
	TYPE_FuncLimit retFuncLimit = TYPE_FuncLimit_Disable;

	switch( e_UserAccountStatus ) {
		case PNLE_ACCOUNT_STATUS_TYPE_Copy:						// コピー操作.
		case PNLE_ACCOUNT_STATUS_TYPE_Scan:						// スキャナー操作.
		case PNLE_ACCOUNT_STATUS_TYPE_Fax:						// FAX(IFAX)操作.
		case PNLE_ACCOUNT_STATUS_TYPE_Print:					// プリンター印字.
		case PNLE_ACCOUNT_STATUS_TYPE_PrintOfSendDocument:		// 送信文書の印字.
		{
			retFuncLimit = getFunctionLimitation( ps_FuncLimit, e_UserAccountStatus );
			break;
		}
		default:											// その他の機能は無判定.
		{
			retFuncLimit = TYPE_FuncLimit_Enable;
			break;
		}
	}

	return retFuncLimit;
}
/**
 *	@brief	機能の制限を比較.
 *	@param	制限１.
 *	@param	制限２.
 *	@retval	２つの制限を比較し、より高い制限を応答する.
 */
TYPE_FuncLimit compareOperationAccountStatus( TYPE_FuncLimit funcLimit, TYPE_FuncLimit compFuncLimit )
{
	TYPE_FuncLimit	retFuncLimit	= TYPE_FuncLimit_Disable;

	if( ( TYPE_FuncLimit_Disable == funcLimit ) || ( TYPE_FuncLimit_Disable == compFuncLimit ) ) {
		// どちらかにDisableがあれば、Disable応答.
		retFuncLimit = TYPE_FuncLimit_Disable;
	} else if( ( TYPE_FuncLimit_OnlyBlack == funcLimit ) || ( TYPE_FuncLimit_OnlyBlack == compFuncLimit ) ) {
		// どちらかにOnlyBlackがあれば、OnlyBlack応答.
		retFuncLimit = TYPE_FuncLimit_OnlyBlack;
	} else {
		retFuncLimit = funcLimit;
	}

	return retFuncLimit;
}
/**
 *	@brief	機能の制限をチェック.
 *	@param	判定機能.
 *	@retval	結果応答が有効かどうか.
 */
TYPE_FuncLimit PnlComCheckOperationAccountStatus( PNLE_ACCOUNT_STATUS_TYPE e_UserAccountStatus )
{
	TYPE_FuncLimit retFuncLimit = TYPE_FuncLimit_Enable;

	if( PnlComGetUserAccountOn() ) {
		// ユーザ認証.
		APIC_User* pc_User = PnlComGetUser();

		if( pc_User ) {
			TYPS_FunctionLimitation s_UserFuncLimit = pc_User->getFunctionLimitation();

			if( PnlComGetTrackOn() ) {
				// ユーザ認証かつ、部門管理.
				APIC_Track*	pc_Track	= PnlComGetTrack();

				if( pc_Track ) {
					TYPE_FuncLimit			userFuncLimit		= getFunctionLimitationUser( &s_UserFuncLimit, e_UserAccountStatus );
					TYPS_FunctionLimitation	s_TrackFuncLimit	= pc_Track->getFunctionLimitation();
					TYPE_FuncLimit			trackFuncLimit		= getFunctionLimitationTrack( &s_TrackFuncLimit, e_UserAccountStatus );

					retFuncLimit = compareOperationAccountStatus( userFuncLimit, trackFuncLimit );
				} else {
					retFuncLimit = TYPE_FuncLimit_Disable;
				}
			} else {
				// ユーザ認証のみ.
				retFuncLimit = getFunctionLimitationUser( &s_UserFuncLimit, e_UserAccountStatus );
			}
		}
	} else if( PnlComGetTrackOn() ) {
		// 部門管理.
		APIC_Track* pc_Track = PnlComGetTrack();

		if( pc_Track ) {
			TYPS_FunctionLimitation s_TrackFuncLimit = pc_Track->getFunctionLimitation();

			retFuncLimit = getFunctionLimitationTrack( &s_TrackFuncLimit, e_UserAccountStatus );
		} else {
			retFuncLimit = TYPE_FuncLimit_Disable;
		}
	}
	return retFuncLimit;
}
