/**	
@name	::/PnlComIsPublicOrOtherUser
@brief	指定されたユーザーがパブリック又はOtherユーザーか判定する.
*/	
// =============================================================================================== .
Bool	PnlComIsPublicOrOtherUser( int32_t sl_IndexNo )
{
	Bool b_isPublicOrOther = False ;
	switch( sl_IndexNo ){
		case TYPD_NotSetting           :  // 設定なし
		case TYPD_IndexUserPublic      :  // ＰＵＢＬＩＣのインデックス番号   .
// Comment 2017/09/12【HCLT-Sindhu】【IT5 4.2】【RQ686】【WP1012 & WP1030】Public user and Other user support for Network 2.
		case TYPD_IndexUserPublicNW2   :
		case TYPD_IndexUserOtherNW2    :
		case TYPD_IndexUserOther       :  // ＯｔｈｅｒＵｓｅｒのインデックス番号（[Ph2.0対応]互換性保持の為、1005に変更） .
			b_isPublicOrOther = True ;
			break;
		default :
			break ;
	}
	return b_isPublicOrOther ;
}
	
