/**
@name	::/getDisplayForJobList
@brief	ジョブリストの表示/非表示を判定.
		戻り値：True:表示 False:非表示
		e_JobListType：ジョブリストのタイプ.
*/
// ===============================================================================================
Bool	getDisplayForJobList( JBLE_JobListType e_JobListType )
{
	Bool	b_Display = True;
	switch( e_JobListType ) {
		case JBLE_ActiveJobListType:    // アクティブジョブリストタイプ.
			b_Display = PnlComGetSystemSetting()->getDisplayForExecutingJob();
			break;
		case JBLE_LogJobListType:       // 履歴ジョブリストタイプ
			b_Display = PnlComGetSystemSetting()->getDisplayForJobHistory();
			break;
		default:	break;
	}
	return b_Display;
}

/**
 *	@brief	機能の制限をチェック.
 *	@param	判定機能.
 *	@param	ユーザーインスタンス.
 *  @param	部門インスタンス.
 *	@retval	結果応答が有効かどうか.
 */
TYPE_FuncLimit PnlComCheckAccountStatus( PNLE_ACCOUNT_STATUS_TYPE e_UserAccountStatus,
        APIC_User* pc_User,
        APIC_Track* pc_Track )
{
	TYPE_FuncLimit retFuncLimit = TYPE_FuncLimit_Enable;

	if( NULL != pc_User ) {
		TYPS_FunctionLimitation s_UserFuncLimit = pc_User->getFunctionLimitation();

		if( NULL != pc_Track ) {
			TYPE_FuncLimit			userFuncLimit		= getFunctionLimitationUser( &s_UserFuncLimit, e_UserAccountStatus );
			TYPS_FunctionLimitation	s_TrackFuncLimit	= pc_Track->getFunctionLimitation();
			TYPE_FuncLimit			trackFuncLimit		= getFunctionLimitationTrack( &s_TrackFuncLimit, e_UserAccountStatus );

			retFuncLimit = compareOperationAccountStatus( userFuncLimit, trackFuncLimit );
		} else {
			// ユーザ認証のみ.
			retFuncLimit = getFunctionLimitationUser( &s_UserFuncLimit, e_UserAccountStatus );
		}
	} else if( NULL != pc_Track ) {
		TYPS_FunctionLimitation s_TrackFuncLimit = pc_Track->getFunctionLimitation();
		retFuncLimit = getFunctionLimitationTrack( &s_TrackFuncLimit, e_UserAccountStatus );
	} else {
		retFuncLimit = TYPE_FuncLimit_Disable;
	}

	return retFuncLimit;
}
