/**
 *	@brief	ハードテンキーがあるかないか.
 *	@param	なし.
 *	@retval	ハードテンキーの有無.
 */
Bool PnlComIsHard10Key()
{
	Bool bl_Ret = True;
	APIC_SystemInfo*	pc_SystemInfo = PnlComGetSystemInfo();
	if( NULL == pc_SystemInfo ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
	} else {
		if( False == pc_SystemInfo->isSlidePanel() ) {
			TYPD_PanelOption e_PanelOption = pc_SystemInfo->getSlidelessPanelOptionInfo();
			// ハード10キーオプション情報.
			bl_Ret = ( e_PanelOption & TYPD_PanelOption10Key ) ? True : False;
		}
	}
	return bl_Ret;
}
//================================================================================================
//［機能］	制御文字をバックスラッシュ'\ , ＼ '等に変換する.
//［引数］	char *psc_in	: 入力文字列.
//			char *psc_out	: 出力文字列.
//［戻値］	なし.
//================================================================================================
void PnlComConvertCtrlToBackslash( char* psc_in , char* psc_out )
{
	// バッファのチェック.
	if( NULL == psc_in || NULL == psc_out ) {
		return;
	}

	// 終端まで繰り返し.
	for( ; *psc_in != '\0'; psc_in++ ) {
		uchar uc_in = *( ( uchar* )psc_in );
		if( uc_in < ' ' || uc_in == 0x7F ) {		// 制御文字.
			*psc_out++ = '\\';		// '\\'.
		} else {
			*psc_out++ = *psc_in;
		}
	}

	*psc_out = *psc_in;	// 終端.
}
/**
 *	@brief	Publicユーザー機能制限時に認証画面を表示するかどうか.
 *	@param	無し.
 *	@retval	True:表示する False：表示しない.
 */
Bool PnlComIsNeedUserChangeFunction()
{
	Bool bl_Ret = False;	// 認証画面を表示するかどうか.

// comment 2017/12/06 SCD2-Sky溝部 [FQ-OPSD-1700460-OFP240] AR1007239をロールバック対応(正式対応は別途検討(FQ-OPSD-1700253-OFP142に合わせて検討)).
//	comment 2017/03/31 HCLT-Prem [IT5_4.0] [AR1007239] Removing the Vendor2 related condition check.
//comment 2018/05/17 HCLT-Meenakshi [IT6_Eagle] [AR1045394] 制限機能使用時のログイン設定に応じて認証画面の表示を切り替える.
//	if( TYPE_KeyModeVendorKM == PnlComGetMachineSetting()->getKeyMode()	// ベンダー2装着時(キーカウンター挿入時も同様).
//	    && True == PnlComGetUserAccountPublic() ) {						// Publicユーザーでログイン中.
	if( ( TYPE_LimitationFunctionUsingLoginOn == PnlComGetSystemSetting()->getLimitationFunctionUsingLogin() )		// 制限機能使用時のログイン設定が"要求する".
		&& ( True == PnlComGetUserAccountPublic() ) ) {																// Publicユーザーでログイン中.
		bl_Ret = True;
	}
	return bl_Ret;
}
//================================================================================================
//［機能］指定された回線の使用設定が引数で渡された使用設定を含んでいるかどうかを判定する.
//［引数］TYPE_CommLine	: 回線N (N:2～4).
//			TYPE_2ndCircuitSet	: 回線2使用設定.
//［戻値］True :指定された回線が装着、且つ設定された使用設定と引数で渡された使用設定が同じ場合.
//        True :指定された回線が装着、且つ設定された使用設定が引数で渡された使用設定を含む場合.
//        False:上記以外.
//================================================================================================
Bool isFaxUsableExpansionLineSingle( TYPE_CommLine e_CommLine, TYPE_2ndCircuitSet e_2ndCircuitSet )
{
	Bool	bl_ret = False;

	if( False == PnlComGetSystemInfo()->getFaxExistAll( e_CommLine ) ) {
		bl_ret = False;		//回線が非装着なのでFalseを返す.
	} else if( TYPE_2ndCircuitSetCom == PnlComGetFaxJobSetting()->getCircuitSetAll( e_CommLine ) ) {
		bl_ret = True;		//回線の使用設定が「送受信兼用」の場合はTrueを返す.
	} else if( e_2ndCircuitSet == PnlComGetFaxJobSetting()->getCircuitSetAll( e_CommLine ) ) {
		bl_ret = True;		//回線の使用設定が引数の使用設定と同じ場合はTrueを返す.
	}
	return bl_ret;
}
//================================================================================================
//［機能］機能拡張2以降、回線別受信設定ＯＮ時、強制メモリ受信ボックス遷移時、パスワード入力画面を  .
//        表示するかどうかを判定する .
//［引数］なし.
//［戻値］True :機能拡張2以降、且つ回線別受信設定がＯＮ、且つ各回線において、下記条件を満たす場合。
//              回線NにおいてisFaxUsableExpansionLineSingle==TRUE、且つ強制メモリー受信が「する」の場合.
//        False:上記以外.
//================================================================================================
Bool isShowInputPasswordForcedMemoryBox()
{
	Bool bl_ret = False;

	if( ( True == PLBC_FuncVersionCheck::isOK_MiZe_Type2() )	// 機能拡張2以降.
	    && ( TYPE_ReceiveInfoApportionOn == PnlComGetFaxJobSetting()->getReceiveInfoApportionOn() )	//回線別受信設定がＯＮの時.
	    && ( ( True == isFaxUsableExpansionLineSingle( TYPE_CommLine1, TYPE_2ndCircuitSetRx )	// 回線1が装着されていて受信に使用可能.
	           && TYPE_RcvFunc_CompulsionRxOn == PnlComGetFaxGfpSetting()->getRcvFunc_CompulsionRxAll( TYPE_CommLine1 ) )	// 回線1の強制メモリー受信が「する」.
	         || ( True == isFaxUsableExpansionLineSingle( TYPE_CommLine2, TYPE_2ndCircuitSetRx )	// 回線2が装着されていて受信に使用可能.
	              && TYPE_RcvFunc_CompulsionRxOn == PnlComGetFaxGfpSetting()->getRcvFunc_CompulsionRxAll( TYPE_CommLine2 ) )	// 回線2の強制メモリー受信が「する」.
	         || ( True == isFaxUsableExpansionLineSingle( TYPE_CommLine3, TYPE_2ndCircuitSetRx )	// 回線3が装着されていて受信に使用可能.
	              && TYPE_RcvFunc_CompulsionRxOn == PnlComGetFaxGfpSetting()->getRcvFunc_CompulsionRxAll( TYPE_CommLine3 ) )	// 回線3の強制メモリー受信が「する」.
	         || ( True == isFaxUsableExpansionLineSingle( TYPE_CommLine4, TYPE_2ndCircuitSetRx )	// 回線4が装着されていて受信に使用可能.
	              && TYPE_RcvFunc_CompulsionRxOn == PnlComGetFaxGfpSetting()->getRcvFunc_CompulsionRxAll( TYPE_CommLine4 ) ) ) )	// 回線4の強制メモリー受信が「する」.
	{
		bl_ret = True;
	}
	return bl_ret;
}

