//==================================================================================================
int32_t PnlComConvertDeviceUserIndex( int32_t index ) // 2013/11/01 【US-20U-PN3G】20万人対応.
{
// Comment 2018/01/29 HCLT_Hanuman [IT5_4.2][AR1038061] To improve performance.
////Comment 2017/09/04 [HCL-Harish] [IT5 4.2][RQ-686] [WP533] Multiple Network support - User Count and Track Index.
////Comment 2017/10/17 [HCL-Harish] [IT5 4.2][AR1030218] User Registeration Count.
//	if ( True == APIC_VlanSetting::newInstance()->getVlanEnable() ) {
	if ( True == PNLC_NetworkLan::getInstance()->getVlanEnableWrapper() ) {
		TYPE_NetworkSpecific e_NetworkSpecific  = PNLC_NetworkLan::getInstance()->getAdminNWLine( );
//Comment 2017/11/14 [HCL-Harish] [IT5 4.2][AR1032820] Adding suport in case of External + Intermediate Authentication.
		TYPE_UserAuthentication e_UserAuthNW1 = PnlComGetUserAuthentication()->getUserAuthentication(TYPE_NetworkSpecific_NW1);
		Bool b_MidCtrlNW1 = PnlComGetUserAuthentication()->getMidauthControl(TYPE_NetworkSpecific_NW1);
		if ( TYPE_NetworkSpecific_NW1 == e_NetworkSpecific ) {
//			if( TYPE_UserAuthenticationDeviceAndMidAuth == PnlComGetUserAuthentication()->getUserAuthentication( TYPE_NetworkSpecific_NW1 ) ) {	// 認証形式が「本体装置認証＋拡張サーバー認証」の場合.
			if( TYPE_UserAuthenticationDeviceAndMidAuth == e_UserAuthNW1 ) {	// 認証形式が「本体装置認証＋拡張サーバー認証」の場合.
				index += TYPD_MidAuthServerUserIdMax;
			}
		} else if ( TYPE_NetworkSpecific_NW2 == e_NetworkSpecific ) {
//			if ( TYPE_UserAuthenticationOff != PnlComGetUserAuthentication()->getUserAuthentication( TYPE_NetworkSpecific_NW1 ) ) {
//				if( TYPE_UserAuthenticationIntermeddiateServer == PnlComGetUserAuthentication()->getUserAuthentication( TYPE_NetworkSpecific_NW1 ) 		// Enhanced Server.
//					|| TYPE_UserAuthenticationDeviceAndMidAuth == PnlComGetUserAuthentication()->getUserAuthentication( TYPE_NetworkSpecific_NW1 ) ) {	// Main + Enhanced Server.
			if ( TYPE_UserAuthenticationOff != e_UserAuthNW1 ) {
				if( ( TYPE_UserAuthenticationIntermeddiateServer == e_UserAuthNW1 ) 							// Enhanced Server.
					|| ( TYPE_UserAuthenticationDeviceAndMidAuth == e_UserAuthNW1 )								// Main + Enhanced Server.
					|| (  ( TYPE_UserAuthenticationServer == e_UserAuthNW1 ) && (True == b_MidCtrlNW1) ) ) {	// External + InterMediate.
					index += TYPD_MidAuthServerUserIdMax;
				}
			}
		}
	} else {
// Comment 2017/11/22【HCLT-Tanu】【IT5 4.2】【RQ686】API Correction.
//		if( TYPE_UserAuthenticationDeviceAndMidAuth == PnlComGetUserAuthentication()->getUserAuthentication( ) ) {	// 認証形式が「本体装置認証＋拡張サーバー認証」の場合.
	    if( TYPE_UserAuthenticationDeviceAndMidAuth == PnlComGetUserAuthentication()->getUserAuthentication( PNLC_NetworkLan::getInstance()->getLine()) ) {	// 認証形式が「本体装置認証＋拡張サーバー認証」の場合.
			index += TYPD_MidAuthServerUserIdMax;
		}
	}
	return index;
}
//Comment 2017/09/04 [HCL-Harish] [IT5 4.2][RQ-686] [WP533] Multiple Network support - User Count and Track Index.
int32_t PnlComConvertDeviceUserIndexVLAN()
{
	int32_t index = 0;
	TYPE_NetworkSpecific e_NetworkSpecific  = PNLC_NetworkLan::getInstance()->getAdminNWLine( );
// Comment 2018/01/29 HCLT_Hanuman [IT5_4.2][AR1038061] To improve performance.
//	if ( True == APIC_VlanSetting::newInstance()->getVlanEnable() ) {
	if ( True == PNLC_NetworkLan::getInstance()->getVlanEnableWrapper() ) {
//Comment 2017/10/17 [HCL-Harish] [IT5 4.2][AR1030218] User Registeration Count.
//		  && ( TYPE_UserAuthenticationOff !=  PnlComGetUserAuthentication()->getUserAuthentication( TYPE_NetworkSpecific_NW2 )
//		  && ( TYPE_UserAuthenticationOff !=  PnlComGetUserAuthentication()->getUserAuthentication( TYPE_NetworkSpecific_NW1 ) ) ) ) {
		if ( ( TYPE_NetworkSpecific_NW2 == e_NetworkSpecific
		  	&& ( TYPE_UserAuthenticationOff !=  PnlComGetUserAuthentication()->getUserAuthentication( TYPE_NetworkSpecific_NW1 )
		  		&& TYPE_UserAuthenticationIntermeddiateServer !=  PnlComGetUserAuthentication()->getUserAuthentication( TYPE_NetworkSpecific_NW1 ) ) )
			&& TYPE_UserAuthenticationOff !=  PnlComGetUserAuthentication()->getUserAuthentication( TYPE_NetworkSpecific_NW2 ) ) {
//Comment 2017/10/29 [HCL-Harish] [IT5 4.2][WP1146] User Registeration and track - Counter.
//			index = 500;
//Comment 2017/11/14 [HCL-Harish] [IT5 4.2][AR1032820] Adding suport in case of External + Intermediate Authentication.
//			if ( TYPE_UserAuthenticationDeviceAndMidAuth ==  PnlComGetUserAuthentication()->getUserAuthentication( TYPE_NetworkSpecific_NW1 ) ) {
//Comment 2018/01/11 [HCL-Harish] [IT5 4.2][AR1032820_ReOpen] Adding suport in case of External + Intermediate Authentication.
//			if ( TYPE_UserAuthenticationDeviceAndMidAuth ==  PnlComGetUserAuthentication()->getUserAuthentication( TYPE_NetworkSpecific_NW1 ) 
//				|| ( TYPE_UserAuthenticationServer ==  PnlComGetUserAuthentication()->getUserAuthentication( TYPE_NetworkSpecific_NW1 )
//					&& True == PnlComGetUserAuthentication()->getMidauthControl(TYPE_NetworkSpecific_NW1) ) ) {
			if ( TYPE_UserAuthenticationServer ==  PnlComGetUserAuthentication()->getUserAuthentication( TYPE_NetworkSpecific_NW1 )
				&& True == PnlComGetUserAuthentication()->getMidauthControl( TYPE_NetworkSpecific_NW1 ) ) {
				return index;
			} else if ( TYPE_UserAuthenticationDeviceAndMidAuth ==  PnlComGetUserAuthentication()->getUserAuthentication( TYPE_NetworkSpecific_NW1 ) ) {
				index = ( PnlComGetTrackManager()->getMaxTrack( ) - PnlComGetTrackManager()->getTrackCntNo() - PnlComGetTrackManager()->getCacheCntNo() ) - PnlComGetTrackManager()->getNW2UserCntNo( );
			} else {
				index = PnlComGetTrackManager()->getMaxTrack( ) - PnlComGetTrackManager()->getTrackCntNo() - PnlComGetTrackManager()->getNW2UserCntNo( );
			}
		}
	}
	return index;
}

//================================================================================================
//［機能］認証方式が本体装置＋外部サーバーでの認証、もしくは本体装置＋拡張サーバーでの認証時に
//　　　　どちら用のユーザーかを取得する
//        上記以外の場合、認証方式を返却する.
//［引数］なし.
//［戻値］認証タイプ(TYPE_UserAuthentication)
//        認証方式が本体装置＋外部サーバーでの認証、もしくは本体装置＋拡張サーバーの場合は、
//          APIC_User::getLoginUserAuthenticationType()の戻り値を返却する.
//        上記の条件を満たさない、もしくはPnlComGetUser()がNULLの場合は、
//　　　　  認証方式が返却する.
//================================================================================================
TYPE_UserAuthentication PnlComGetLoginUserAuthenticationType()
{
	TYPE_UserAuthentication eUserAuthentication = PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine());
	APIC_User* pc_User = PnlComGetUser();
	if( NULL != pc_User ) {
		if( TYPE_UserAuthenticationDeviceAndServer== eUserAuthentication ) {		//本体装置+外部サーバでの認証.
			eUserAuthentication = pc_User->getLoginUserAuthenticationType();	// ユーザー認証タイプを返す.
		}
		if( TYPE_UserAuthenticationDeviceAndMidAuth == eUserAuthentication )	{	//本体装置+拡張サーバでの認証.
			if( TYPE_UserTypeUser == pc_User->getUserType() ) {
				// 一般ユーザー.
				eUserAuthentication = pc_User->getLoginUserAuthenticationType();	// ユーザー認証タイプを返す.
			} else {
				// 特殊ユーザー.
				eUserAuthentication = TYPE_UserAuthenticationIntermeddiateServer;	// 拡張サーバー認証を返す.
			}
		}
	}
	return eUserAuthentication;
}


//==================================================================================================
//［機能］ユーザー認証方式「本体+拡張サーバー」時の認証モード（本体認証 or 拡張サーバー認証）設定処理.
// [引数] なし.
// [戻値] なし.
//==================================================================================================
void PnlComSetUserAuthenticationMode()
{
// comment 2020/11/17 2DWS2G-Sky肥後 クラウドSSO認証開発v1_Step2.
	APIC_UserAuthentication* pc_UserAuth = PnlComGetUserAuthentication();
	if( NULL != pc_UserAuth ) {
// comment 2021/02/18 Sky東野 クラウドSSO認証開発v1_Step2 OP_BTS-31035 start.
//		if ( True == pc_UserAuth->getAuthIdPMode() ) {
//			if( True == cp_IwsSetting->getIwsAuthScreenStartup() ){
		if ( (True == pc_UserAuth->getAuthIdPMode()) && (True == cp_IwsSetting->getIwsAuthScreenStartup()) ){
// comment 2021/03/29 2DWS2G-Sky東野 クラウドSSO認証開発v1_Step2 認証カスタマイズアプリ正式化対応.
			if( True == pc_UserAuth->getIdPAuthPrioritySetting() ) {
				// IdP認証を優先.
				onlyPanel.e_NowUserAuthMode = PNLE_NowUserAuthModeIdPAuth;
				return;
			} else if( (TYPE_UserAuthenticationIntermeddiateServer == pc_UserAuth->getDefaultUserAuthentication(PNLC_NetworkLan::getInstance()->getLine())) 
					|| (TYPE_UserAuthenticationIntermeddiateServer == PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine())) ){
				// IdP認証：優先しない、認証方式：「拡張サーバー認証」or デフォルト認証方式「拡張サーバー認証」.
				onlyPanel.e_NowUserAuthMode = PNLE_NowUserAuthModeMidAuth;
				return;
			} else if( (TYPE_UserAuthenticationDevice == pc_UserAuth->getDefaultUserAuthentication(PNLC_NetworkLan::getInstance()->getLine())) 
					|| (TYPE_UserAuthenticationServer == pc_UserAuth->getDefaultUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()))
					|| (TYPE_UserAuthenticationDevice == PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()))
					|| (TYPE_UserAuthenticationServer == PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine())) ){
				// IdP認証：優先しない、認証方式：「本体認証」or「外部サーバー認証」or デフォルト認証方式：「本体認証」or「外部サーバー認証」.
				onlyPanel.e_NowUserAuthMode = PNLE_NowUserAuthModeDevice;
				return;
			}
//			}
// comment 2021/02/18 Sky東野 クラウドSSO認証開発v1_Step2 OP_BTS-31035 end.
		} else {
// comment 2020/12/16 2DWS2G-Sky Nakano クラウドSSO認証開発v1_Step2 [OP_BTS-29855].
/*
	ldp認証On->Offになったときに拡張サーバー認証に戻す処理 .
	PNLE_NowUserAuthModeIdPAuth -> PNLE_NowUserAuthModeMidAuth .
*/
			if( TYPE_UserAuthenticationIntermeddiateServer == PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine() ) ) {
				if( onlyPanel.e_NowUserAuthMode == PNLE_NowUserAuthModeIdPAuth ) {
// comment 2021/02/08 Sky東野 クラウドSSO認証開発v1_Step2 OP_BTS-30925 start.
//					if(  ( TYPE_UserAuthenticationIdP == pc_UserAuth->getDefaultUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()) ) 
//						|| ( TYPE_UserAuthenticationDeviceAndIdP == pc_UserAuth->getDefaultUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()) ) ) {							// デフォルト認証方式「IdP認証」.
//						onlyPanel.e_NowUserAuthMode = PNLE_NowUserAuthModeMidAuth; 
//						return; 
//					} 
					onlyPanel.e_NowUserAuthMode = PNLE_NowUserAuthModeMidAuth;
					return;
// comment 2021/02/08 Sky東野 クラウドSSO認証開発v1_Step2 OP_BTS-30925 end.
				}
			}
		}
	}
	if( ( NULL != PnlComGetUserAuthentication() )
	    && ( TYPE_UserAuthenticationDeviceAndMidAuth == PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()) ) ) {					// ユーザー認証方式「本体＋拡張サーバー」.
		if( True == onlyPanel.bl_isEnlargeDisplayMode ) {
			// 拡大表示時は認証モードを「本体認証」に設定.
			onlyPanel.e_NowUserAuthMode = PNLE_NowUserAuthModeDevice;
		} else {
			// 通常表示時はデフォルト認証方式により認証モードを設定.
			if( TYPE_UserAuthenticationDevice == PnlComGetUserAuthentication()->getDefaultUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()) ) {						// デフォルト認証方式「本体認証」.
				// 認証モードを「本体認証」に設定.
				onlyPanel.e_NowUserAuthMode = PNLE_NowUserAuthModeDevice;
// comment 2021/04/30 Sky東島 [IT6_2.2][OP_BTS-32561].
				PNLC_AuthenticationManager::newInstance()->setLoginStatus( False );
			} else if( TYPE_UserAuthenticationIntermeddiateServer == PnlComGetUserAuthentication()->getDefaultUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()) ) {	// デフォルト認証方式「拡張サーバー認証」.
				// 認証モードを「拡張サーバー認証」に設定.
				onlyPanel.e_NowUserAuthMode = PNLE_NowUserAuthModeMidAuth;
			} else {
				// 何もしない.
			}
		}
	}
}
