//==================================================================================================
//［機能］Check's for any IWS Job running , the current running application and new application number are same.
// [引数] uchar.
// [戻値] Bool.
// [履歴] Newly created Funciton to Check any IWS Job running , he current running application and new application number are same.
//==================================================================================================
Bool LaunchOAPApplication( uchar option )
{
	if( False == c_ExtPanel.isEnableMFPFunction() ) {
		return False;
	}
	ushort us_CurrentAppNo = 0;
	ushort us_NewAppNo = 0;
	TYPS_ApplicationKeySetting ps_ApplicationKeyId;
	TYPE_ApplicationKeyId	e_ApplicationKeyId[NVDD_MAX_ApplicationKeyId];	// アプリ情報取得バッファ.
	memset( &ps_ApplicationKeyId, 0x00, sizeof( ps_ApplicationKeyId ) );
	if( NULL != PnlComGetApplicationKeySetting() ) {
		if( TYPE_AppKeyResultOK == PnlComGetApplicationKeySetting()->getApplicationKeyId( &ps_ApplicationKeyId ) ) {
			memcpy( e_ApplicationKeyId, &( ps_ApplicationKeyId.uc_ApplicationKeyId ), sizeof( e_ApplicationKeyId ) );
			if( ( option > 0 ) && ( TYPE_ApplicationKeyIdAppSingle == e_ApplicationKeyId[ option - 1 ] ) )
			{
				us_NewAppNo = ps_ApplicationKeyId.uc_ApplicationKeyIdAppInfo[ option - 1 ];
				if( True == ExtSet.isActiveGeneralApplication() ) {
					if( us_NewAppNo > TYPD_ExtMaxApplication ) {
						ushort us_NewRightFaxNo = ( ushort )( us_NewAppNo - TYPD_ExtMaxApplication );
						ushort us_CurrnetRightFaxNo = ExtSet.getSettingAppIndexNow();
						if( us_CurrnetRightFaxNo == us_NewRightFaxNo ) {
							return False;
						}
					}
					return True;
				} else if( True == ScanOapExtSet.isActiveGeneralApplication( TYPE_JobTypeCopy, PNLE_CheckType_ALL ) ) {
					us_CurrentAppNo = ScanOapExtSet.getCurrentAppNo();
					if( ( us_CurrentAppNo == us_NewAppNo ) || ( True == onlyPanel.bl_IWSAction ) ) {
						return False;
					} else {
						return True;
					}
				}
			} else {
				int appKindCount = 0;
				appKindCount += ScanOapExtSet.getRegistAppCount( TYPE_ExtTypeScanD );
				appKindCount += ScanOapExtSet.getRegistAppCount( TYPE_ExtTypeScanS );
				appKindCount += ScanOapExtSet.getRegistAppCount( TYPE_ExtTypePullPrint );
				appKindCount += ScanOapExtSet.getRegistAppCount( TYPE_ExtTypeBrowserScan );
				appKindCount += ScanOapExtSet.getRegistAppCount( TYPE_ExtTypeBrowserLauncher );
				appKindCount += ScanOapExtSet.getRegistAppCount( TYPE_ExtTypeBrowserPull );
				appKindCount += ScanOapExtSet.getRegistAppCount( TYPE_ExtTypeBrowserGeneral );
				appKindCount += ExtSet.countApps();
// comment 2019/04/16 SCD2-Sky中野 [EagleH] 目的別UI_1ペイン対応.
				if( PNLE_UIModeLightUI == PNLC_WebUIControl::getInstance()->getUIMode() ) {
					appKindCount += ScanOapExtSet.getRegistAppCount( TYPE_ExtTypeCustomUI );
				}
				
				if( appKindCount > 1 ) {
					return True;
				} else {
					return False;
				}
			}
		}
	}
	return False;
}

//==================================================================================================
//［機能］LaunchOAPApplicationのアプリ指定版.
// [引数] uchar.
// [戻値] Bool.
//==================================================================================================
Bool LaunchOAPApplicationSpecify( uchar uc_AppNo )
{
	if( False == c_ExtPanel.isEnableMFPFunction() ) {
		return False;
	}
	ushort us_CurrentAppNo = 0;
	if( uc_AppNo > 0 )
	{
		if( True == ExtSet.isActiveGeneralApplication() ) {
			if( uc_AppNo > TYPD_ExtMaxApplication ) {
				ushort us_NewRightFaxNo = ( ushort )( uc_AppNo - TYPD_ExtMaxApplication );
				ushort us_CurrnetRightFaxNo = ExtSet.getSettingAppIndexNow();
				if( us_CurrnetRightFaxNo == us_NewRightFaxNo ) {
					return False;
				}
			}
			return True;
		} else if( True == ScanOapExtSet.isActiveGeneralApplication( TYPE_JobTypeCopy, PNLE_CheckType_ALL ) ) {
			us_CurrentAppNo = ScanOapExtSet.getCurrentAppNo();
			if( ( us_CurrentAppNo == uc_AppNo ) || ( True == onlyPanel.bl_IWSAction ) ) {
				return False;
			} else {
				return True;
			}
		}
	} else {
		int appKindCount = 0;
		appKindCount += ScanOapExtSet.getRegistAppCount( TYPE_ExtTypeScanD );
		appKindCount += ScanOapExtSet.getRegistAppCount( TYPE_ExtTypeScanS );
		appKindCount += ScanOapExtSet.getRegistAppCount( TYPE_ExtTypePullPrint );
		appKindCount += ScanOapExtSet.getRegistAppCount( TYPE_ExtTypeBrowserScan );
		appKindCount += ScanOapExtSet.getRegistAppCount( TYPE_ExtTypeBrowserLauncher );
		appKindCount += ScanOapExtSet.getRegistAppCount( TYPE_ExtTypeBrowserPull );
		appKindCount += ScanOapExtSet.getRegistAppCount( TYPE_ExtTypeBrowserGeneral );
		appKindCount += ExtSet.countApps();
// comment 2019/04/16 SCD2-Sky中野 [EagleH] 目的別UI_1ペイン対応.
		if( PNLE_UIModeLightUI == PNLC_WebUIControl::getInstance()->getUIMode() ) {
			appKindCount += ScanOapExtSet.getRegistAppCount( TYPE_ExtTypeCustomUI );
		}
		
		if( appKindCount > 1 ) {
			return True;
		} else {
			return False;
		}
	}
	return False;
}
// comment 2015/11/18 OPS1-Sky稲井[特ROM][IT5-7_機種マージ]Scan To SMBでユーザー名/パスワードのデフォルト値の設定を可能にする要望.
//================================================================================================.
//	[機能]	LDAP登録No5のユーザー名とパスワードを取得する.
//------------------------------------------------------------------------------------------------.
//	[引数]	(OUT)char *psc_UserName.
//	[引数]	(OUT)char *psc_Password.
//	[戻値]	なし.
//	[備考]	ユーザー名、パスワードの領域サイズについては呼び出し元で保障する.
//			領域は257byte(取得元は256byte+1で領域確保している)が必要.
//================================================================================================.
void PnlComGetLdapUserNameAndPassword(char *psc_UserName, char *psc_Password)
{
	//LDAP登録No5のユーザー名とパスワードを設定する(空白時も同様)
	APIC_LdapSetting* pc_LdapSetting  = APIC_LdapSetting::newInstance(PNLD_LdapSetting_SMBInput);
	if((NULL != pc_LdapSetting) && (NULL != psc_UserName) && (NULL != psc_Password)){
		pc_LdapSetting->getLoginNameUTF8( psc_UserName, LIBE_CharSetUTF8);	// ログイン名取得.
		pc_LdapSetting->getPasswordUTF8( psc_Password, LIBE_CharSetUTF8);	// パスワード取得.
	}
}

// 概要		：HDDが利用可能かどうか(※HDD非装着時は可能と判断する).
// 引数		：なし.
// 戻り値	：可能(True)、不可能(False) .
// 備考		：コピー画面でオーバーレイ、登録オーバーレイ、ボックス保存、プログラムジョブを利用できるかどうかの判定に使用.
Bool isHDDStateReady()
{
	Bool bl_Result = True;	// 利用可.
	PNLC_NotifyEventInfo* pc_NtfEventInfo = PNLC_NotifyEventInfo::newInstance();	// データの管理クラス.
	if( NULL == pc_NtfEventInfo ) {	// 管理クラス参照不可.
		bl_Result = False;	// 利用不可.
	} else {
		if( True == PnlComGetHddInfo()->getHddExist()	// HDD装着.
		    && ( TYPE_HddStatusFormated != PnlComGetHddInfo()->getHddStatus()	// HDDの準備が完了していない.
		         || False == pc_NtfEventInfo->getBoxReady() ) ) {	// データ整合状態チェックが完了していない.
			bl_Result = False;	// 利用不可.
		}
	}
	return bl_Result;
}

// ===============================================================================================
/**
@name	::/PnlComCheckUbqStorageUse
@brief	ユビキタスプリントのストレージ機能が利用可能かチェックする.
	戻り値.利用可能：True、利用不可：False.
*/
// ===============================================================================================
Bool PnlComCheckUbqStorageUse()
{
	Bool b_Check = False;

	//ストレージ/クライアント両機能共に利用不可かのチェック.
	b_Check = PnlComCheckUbqUse();

	if( True == b_Check ) {
		//ストレージ機能が利用可能かのチェック.
		if( TYPE_AppOptSettingOff == SYSF_getAppOptionSetting( TYPE_AppOptionUbiquitousStorage ) ) {
			b_Check = False;
		}
	}

	return b_Check;
}

