Bool PnlComCheckUbqUse()
{
// [MinervaSBK][RQ-268] サーバーレスユビキタス拡張サーバ認証対応 start.
//	Bool b_Check = False;
	Bool b_Check = True;
// [MinervaSBK][RQ-268] サーバーレスユビキタス拡張サーバ認証対応 end.

	// オプションライセンス（FEK16 ユビキタスプリント）無効であれば利用不可.
	if( TYPE_CategoryState_ENABLE != PnlComGetEnablerSetting()->getFEK_CotegoryState( TYPE_FEKType16 ) ) {
		b_Check = False;
		return b_Check;
	}

	// OpenAPI設定のアクセス設定が不可であれば利用不可.
//Comment 2017/12/19 [HCL-Catherine] [IT5 4.2][RQ-686] [ WP1377]The new API is used and to detect the current network type, new API arguments are passed.
    TYPE_NetworkSpecific e_NetworkSpecific = PNLC_NetworkLan::getInstance()->getLine();
//	if( False == PnlComGetOpenApiSetting()->getEnableOpenAPI() ) {
	if( False == PnlComGetOpenApiSetting()->getEnableOpenAPI(e_NetworkSpecific) ) {
		b_Check = False;
		return b_Check;
	}

	// セキュリティー強化モードOnであれば利用不可.
	if( True == PnlComGetSystemSetting()->getSecurityLevelUpOn() ) {
		return False;
	}

// [MinervaSBK][RQ-268] サーバーレスユビキタス拡張サーバ認証対応 start.
	// 機能拡張3版以降は拡張サーバー時にサーバーレスユビキタスプリント使用可能とする.
// ユビキタス[AR1008922]【市場問題】機能バージョンが2.1/2.0だとLK-114使用時にドライバから認証指定なし印刷ができない start.
//	if( True == PLBC_FuncVersionCheck::isOK_IT5_Type3() ) {
	if( TYPE_UbqFuncVersion3_Enable == PnlComGetUbiquitousSetting()->getUbqFuncVersion3() ) {
// ユビキタス[AR1008922]【市場問題】機能バージョンが2.1/2.0だとLK-114使用時にドライバから認証指定なし印刷ができない end.
		// ユーザー認証方式がOFF(認証しない)であれば利用不可.
		if( TYPE_UserAuthenticationOff == PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()) ) {
			b_Check = False;
			return b_Check;
		}
	} else {
	// ユーザー認証方式取得.
	TYPE_UserAuthentication e_UserAuthentication = PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine());

	// 認証形態取得.
	TYPE_AUTHMETHOD e_AuthMethod = PnlComGetAuthDeviceSetting()->getAuthMethodSetting(True,PNLC_NetworkLan::getInstance()->getLine());

	// ユーザー認証方式
	switch( e_UserAuthentication ) {
		// 本体認証.
		case TYPE_UserAuthenticationDevice:
		// 拡張サーバー＋本体認証.
		case TYPE_UserAuthenticationDeviceAndMidAuth:
			// 認証形態
			switch( e_AuthMethod ) {
				case TYPE_AuthMethod_None:				// 認証デバイスを使用しない.
				case TYPE_AuthMethod_Icc:				// カード認証のみ.
				case TYPE_AuthMethod_Icc_Password:		// カード認証+パスワード.
				case TYPE_AuthMethod_Vein_1_1:			// 生体認証1対1認証.
				case TYPE_AuthMethod_Vein_1_N:			// 生体認証1対N認証.
					b_Check = True;
					break;
				default:
					b_Check = False;
					break;
			}
			break;
		// 外部サーバ.
		case TYPE_UserAuthenticationServer:
			// 認証形態
			switch( e_AuthMethod ) {
				case TYPE_AuthMethod_None:				// 認証デバイスを使用しない.
				case TYPE_AuthMethod_Icc:				// カード認証のみ.
					// 拡張サーバなし.
// comment 2017/10/31 【HCL-TANU】【IT5_4.2】【RQ686】【IT Defect AR1030817].
//					if( False == PnlComGetUserAuthentication()->getMidauthControl() ) {
					if( False == PnlComGetUserAuthentication()->getMidauthControl(PNLC_NetworkLan::getInstance()->getLine()) ) {
						b_Check = True;
					}
					else {
						b_Check = False;
					}
					break;
				default:
					b_Check = False;
					break;
			}
			break;
		// 本体+外部サーバー認証.
		case TYPE_UserAuthenticationDeviceAndServer:
			// 認証形態
			switch( e_AuthMethod ) {
				case TYPE_AuthMethod_None:				// 認証デバイスを使用しない.
				case TYPE_AuthMethod_Icc:				// カード認証のみ.
				case TYPE_AuthMethod_Icc_Password:		// カード認証+パスワード.
				case TYPE_AuthMethod_Vein_1_1:			// 生体認証1対1認証.
				case TYPE_AuthMethod_Vein_1_N:			// 生体認証1対N認証.
					b_Check = True;
					break;
				default:
					b_Check = False;
					break;
			}
			break;
			default:
				b_Check = False;
				break;
		}
	}
// [MinervaSBK][RQ-268] サーバーレスユビキタス拡張サーバ認証対応 end.

	return b_Check;

}


//==================================================================================================
//［機能］ユーザー認証状態の設定.
// [引数] なし.
// [戻値] なし.
//==================================================================================================
static int32_t sl_PanelLoginStatus_User = TYPD_NotSetting;
void PnlComSetPanelLoginStatus_User( PCGE_SetPanelLoginStatusType e_Status, TYPE_UserResult e_Result )
{
	int32_t i32_UserNo = sl_PanelLoginStatus_User;

	switch( e_Status ) {
		case PCGE_SetPanelLoginStatusType_NoLogin:	// 未ログイン.
			i32_UserNo = TYPD_NotSetting;								// 未ログイン(-1).
			break;
		case PCGE_SetPanelLoginStatusType_Request:	// ログイン要求中.
			i32_UserNo = 0;												// 認証処理中(0).
			break;
		case PCGE_SetPanelLoginStatusType_Result:	// ログイン結果.
		{
			// 結果.
			switch( e_Result ) {
				case TYPE_UserResultOk:					// 成功.
				case TYPE_UserResultFunctionInvalid:	// 機能制限対応 「不正値あり」.
					if( NULL != PnlComGetUser() ) {
						i32_UserNo = PnlComGetUser()->getUserNo();	// ユーザー番号.
					} else {
						// 有りあえない.
						LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
						i32_UserNo = TYPD_NotSetting;	// 未ログイン(-1).
					}
					break;
				case TYPE_UserResultContinue:			// 継続.
					// 前の状態を維持する.
					break;
				default:								// その他.
					// エラー.
					i32_UserNo = TYPD_NotSetting;					// 未ログイン(-1).
					break;
			}
		}
		break;
		default:
			break;
	}

	// UACのAPIをコール.
	if( sl_PanelLoginStatus_User != i32_UserNo ) {
		APIC_PanelLoginStatus* pc_PanelLoginStatus = APIC_PanelLoginStatus::newInstance();
		if( NULL != pc_PanelLoginStatus ) {

// comment Sky新大阪 [特ROM対応][IT5-6] 文書名の再利用機能対応.
			if( APIC_SoftDipSw::newInstance()->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW213, 4 ) == True ) // DipSWNo.213 bit4がOnのとき.
			{
				memset( onlyPanel.sc_backUp_SendFileName, '\0', ( sizeof( char ) * PCGD_FileNameUTF8_241 ) );			// 送信ファイル名のバックアップ領域.
				onlyPanel.bl_EditSendFileName = False;																	// 文書名を変更したかどうかのフラグをクリア.
			}

			PanelLog( PNLD_LogKind_Auth, "setPanelLoginUserNo: UserNo[%d]", i32_UserNo, 0, 0, 0, 0, 0 );
			pc_PanelLoginStatus->setPanelLoginUserNo( i32_UserNo );
		}
		sl_PanelLoginStatus_User = i32_UserNo;	// 前回値保持.
// comment [特ROM対応][IT5-80] 拡張サーバ認証時にユーザのActiveDirectoryアカウントでHomeDirectoryにSMB送信を行う対応.
		if( ( TYPD_NotSetting != i32_UserNo ) ){	// ログイン時.
			if( ( True == APIC_SoftDipSw::newInstance()->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW236, 0 ) )		// DipSwNo236 Bit0がOn.
			 && ( 0    != i32_UserNo ) ){																			// ログイン要求中ではない.
				// ScanToHomeのAD認証画面に入力されたログイン名・パスワードをクリア.
				memset(PNLC_ScanFaxDataLib::newInstance()->getADInput_LoginName(),     0, PNLC_ScanFaxDataLib::newInstance()->getADInput_LoginNameSize());
				memset(PNLC_ScanFaxDataLib::newInstance()->getADInput_LoginPassword(), 0, PNLC_ScanFaxDataLib::newInstance()->getADInput_LoginPasswordSize());
			}
		}
	}
}
// 認証要求中のチェック.
Bool PnlComIsRequestPanelLoginStatus_User()
{
	return ( 0 == sl_PanelLoginStatus_User );	// 認証処理中(0).
}

