// comment 2015/03/02 HCLT_Rengaraaj [HeliosL][MZ2ND-54-Merge Activity]送信禁止ドメイン設定追加.
//==================================================================================================.
//［機能］送信禁止ドメインチェック処理.
// [引数] Emailアドレスポインタ.
// [戻値] 登録されている場合は、True、それ以外がFalseを戻り値とする（登録されていない、エラー、致命的エラーなど）.
// comment 2015/03/02 HCLT_Rengaraaj [HeliosL][MZ2ND-54-Merge Activity]送信禁止ドメインチェック処理追加.
//==================================================================================================.
#define PNLD_Max_ScanRefusalDomainName			IGCD_DOMAIN_LEN	//mfp\system\igc\igcg\interface\IGC_APID_Const.h(99).	//255.
#define PNLD_Index_Max_ScanRefusalDomain			10			// 送信禁止ドメイン登録最大数(10).

Bool isScanRefusalDomainName( char* psc_EmailAddressName )
{
	Bool	bl_Ret = False;	//戻り値：初期値は送信禁止ドメインに登録されていないとする．
// comment 2015/03/03 HCLT_Jeevitha [HeliosL][MZV-29-Merge Activity] 指定したドメインのScan to Emailのみを許可する対応.
	if( True == APIC_SoftDipSw::newInstance()->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW216, 3 ) ) // DipSWNo.216 bit3.
	{
		bl_Ret = True; //DipSwNo216 bit3がONの場合は、デフォルトはTrue(=ドメイン名が一致していないので許可しない)にする.
	}
	char	sc_DomainName[( IGCD_DOMAIN_LEN * 3 ) + 1];	//CommonAPIからの取得文字列格納用(ヌル文字分加算しておく).
	char*	psc_Email_DomainName = NULL;	//Emailアドレスのドメイン名の＠以降の位置.

	//初期化.
	memset( sc_DomainName, '\0', sizeof( sc_DomainName ) );

	//システム設定（ＡＰＩ）へアクセスできないか？.
	if ( NULL == PnlComGetSystemSetting() ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return bl_Ret;}
	//Emailアドレス文字列のポインタがNULLでないことを確認する.
	if ( NULL == psc_EmailAddressName ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return bl_Ret;}

	//Emailのアドレスが入力されていないか？.
	if (0 == strlen(psc_EmailAddressName) ) {	//未入力チェック.
		//送信禁止ドメインでないためFalseとする．
	} else {
		psc_Email_DomainName = strchr(psc_EmailAddressName, '@');	//Emailアドレス文字列から"@"の位置を探索する.
		if ( NULL == psc_Email_DomainName ) {	//@が見つからなかったか？.
			//送信禁止ドメインでないためFalseとする．
		} else {
			psc_Email_DomainName++;	//@以降を比較対象文字列とするため一文字先に進める.

			//文字数チェック
			if ( (0 == strlen(psc_Email_DomainName)) || (PNLD_Max_ScanRefusalDomainName < strlen(psc_Email_DomainName)) ) {	//ドメイン名なしまたは最大文字数超か？
				//送信禁止ドメインでないためFalseとする．
			} else {
			//システム設定（ＡＰＩ）から取得した送信禁止ドメイン文字列とEmailアドレスのドメイン名の＠以降の文字列を比較する.
				uchar uc_Index = 0;
				for ( uc_Index = 1; uc_Index < ( uchar )( PNLD_Index_Max_ScanRefusalDomain + 1 ); uc_Index++ ) {
					PnlComGetSystemSetting()->getScanRefusalDomainName( uc_Index, sc_DomainName, getCharSetForCAPI() );
					if (0 == strlen(sc_DomainName) ) {	//sc_DomainNameが登録されていないか？.
						//送信禁止ドメインでないためFalseとする．
						break;	//これ以上ループしない.
					}
					if (0 == strncmp( sc_DomainName,psc_Email_DomainName,sizeof(sc_DomainName) ) ) {	//完全一致か？（確保している領域の最大まで比較する）.
						bl_Ret = True;	//送信禁止ドメインのためTrueとする（ここ以外はTrueにならない）
// comment 2015/03/03 HCLT_Jeevitha [HeliosL][MZV-29-Merge Activity] 指定したドメインのScan to Emailのみを許可する対応.
						if( True == APIC_SoftDipSw::newInstance()->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW216, 3 ) ) // DipSWNo.216 bit3.
						{
							bl_Ret = False; //DipSwNo216 bit3がONの場合は、ここだけがFalse(=ドメイン名が一致したので許可)となる.
						}
						break;	//これ以上ループしない.
					}
				}
			}
		}
	}
	return bl_Ret;
}

//==================================================================================================
//［機能］認証&プリントにて、認証時にプリントと同時にログイン出来るかどうかの判定処理.
// [引数] なし.
// [戻値] True：認証時にプリントと同時にログイン出来る設定である.
//        False：認証時にプリントと同時にログイン出来る設定ではない.
//==================================================================================================
Bool isTouchAndGoAndLogin()
{
	Bool bl_Ret = False;
	APIC_SoftDipSw* pc_SoftDipSw = APIC_SoftDipSw::newInstance();
	APIC_UserAuthentication* pc_UserAuthentication = PnlComGetUserAuthentication();
	if((NULL != pc_SoftDipSw) && (NULL != pc_UserAuthentication)) {
		if( (True == pc_SoftDipSw->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW200, 7 )) 
		  &&(TYPE_UserAuthenticationDevice == pc_UserAuthentication->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()))){
			//DipSW200 bit7=ONかつ認証方式=[本体認証]の場合にTrueを返す.
		bl_Ret	= True;
	}
	}else{
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
	}
	return bl_Ret;
}

//==================================================================================================
//［機能］サーバーデータ取得カスタマイズ機能有効可否判定.
//==================================================================================================
Bool PnlComIsExtServerDataGet()
{
	ACSE_ExtServerDataGet	e_ExtServerDataAcquireCustomInfo	= ACSE_ExtServerDataGet_Convent;
	APIC_AuthCust*	pc_AuthCust	= APIC_AuthCust::newInstance();
	if ( 0 == pc_AuthCust ) {
		return( False );
	}
	pc_AuthCust->getExtServerDataGetEnable( &e_ExtServerDataAcquireCustomInfo );

	Bool	bl_Ret	= False;
	switch ( e_ExtServerDataAcquireCustomInfo ) {
	case ACSE_ExtServerDataGet_NoCustom:	// サーバーデータ取得カスタマイズ機能無効.
		break;
	case ACSE_ExtServerDataGet_Custom:	// サーバーデータ取得カスタマイズ機能有効.
		bl_Ret	= True;
		break;
	case ACSE_ExtServerDataGet_Convent:		// コンフィグファイルの設定未使用(従来動作).
	default:
		{
			APIC_SoftDipSw*	pc_SoftDipSw	= APIC_SoftDipSw::newInstance();
			if ( 0 == pc_SoftDipSw ) {
				return( False );
			}
			Bool	bl_Enable	= pc_SoftDipSw->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW200, 3 );
			if ( True == bl_Enable ) {
				bl_Ret	= True;
			}
		}
		break;
	}

	return( bl_Ret );
}

//==================================================================================================
//［機能］E-mailアドレスからユーザー名を取得する機能有効可否判定.
//==================================================================================================
Bool PnlComIsUseUserNameIntoEmailAddress()
{
	ACSE_ShortAddrScanToMe	e_Mode	= ACSE_ShortAddrScanToMe_Convent;
	APIC_AuthCust*	pc_AuthCust	= APIC_AuthCust::newInstance();
	if ( 0 != pc_AuthCust ) {
		pc_AuthCust->getShortAddressScanToMe( &e_Mode );
	}

	Bool	bl_Ret	= False;
	switch ( e_Mode ) {
	case ACSE_ShortAddrScanToMe_NoCustom:	// 短縮宛先 ScanToMe機能無効.
		break;
	case ACSE_ShortAddrScanToMe_Custom:		// 短縮宛先 ScanToMe機能有効.
		bl_Ret	= True;
		break;
	case ACSE_ShortAddrScanToMe_Convent:	// コンフィグファイルの設定未使用(従来動作).
	default:
		{
			APIC_SoftDipSw*		pc_SoftDipSw	= APIC_SoftDipSw::newInstance();
			if ( 0 == pc_SoftDipSw ) {
				return( False );
			}
			if ( True == pc_SoftDipSw->getSoftDipSwBitForPanelSpecNo( PNLD_LOGSYSTEMSETTING, 4 ) ) {
				bl_Ret	= True;
			}
		}
		break;
	}

	return( bl_Ret );
}

//==================================================================================================
//［機能］カード認証時、キャッシュ機能で保存されているユーザー情報をもとにScan To Homeを利用可能とする機能有効可否判定.
//==================================================================================================
Bool PnlComIsUseCachedUserInfoScanToHome()
{
	ACSE_ShortAddrScanToHome	e_Mode	= ACSE_ShortAddrScanToHome_Convent;
	APIC_AuthCust*	pc_AuthCust	= APIC_AuthCust::newInstance();
	if ( 0 != pc_AuthCust ) {
		pc_AuthCust->getShortAddressScanToHome( &e_Mode );
	}

	Bool	bl_Ret	= False;
	switch ( e_Mode ) {
	case ACSE_ShortAddrScanToHome_NoCustom:	// 短縮宛先 ScanToHome機能無効.
		break;
	case ACSE_ShortAddrScanToHome_Custom:	// 短縮宛先 ScanToHome機能有効.
		bl_Ret	= True;
		break;
	case ACSE_ShortAddrScanToHome_Convent:	// コンフィグファイルの設定未使用(従来動作).
	default:
		{
			APIC_SoftDipSw*		pc_SoftDipSw	= APIC_SoftDipSw::newInstance();
			if ( 0 == pc_SoftDipSw ) {
				return( False );
			}
			if ( True == pc_SoftDipSw->getSoftDipSwBitForPanelSpecNo( 70, 2 ) ) {
				bl_Ret	= True;
			}
		}
		break;
	}

	return( bl_Ret );
}

//==================================================================================================
//［機能］カードユーザーのScanToHome送信先をADから自動取得する機能有効可否判定.
//==================================================================================================
Bool PnlComIsAutoGetScanToHomeAddrFromAD()
{
	ACSE_ShortAddrScanToHome_ICC	e_Mode	= ACSE_ShortAddrScanToHome_ICC_Convent;
	APIC_AuthCust*	pc_AuthCust	= APIC_AuthCust::newInstance();
	if ( 0 != pc_AuthCust ) {
		pc_AuthCust->getShortAddressScanToHome_LDAP_ICCardAuth( &e_Mode );
	}

	Bool	bl_Ret	= False;
	switch ( e_Mode ) {
	case ACSE_ShortAddrScanToHome_ICC_NoCustom:	// 短縮宛先 ScanToHome(LDAP-ICカード認証設定)無効.
		break;
	case ACSE_ShortAddrScanToHome_ICC_Custom:	// 短縮宛先 ScanToHome(LDAP-ICカード認証設定)有効.
		bl_Ret	= True;
		break;
	case ACSE_ShortAddrScanToHome_ICC_Convent:	// コンフィグファイルの設定未使用(従来動作).
	default:
		{
			APIC_SoftDipSw*		pc_SoftDipSw	= APIC_SoftDipSw::newInstance();
			if ( 0 == pc_SoftDipSw ) {
				return( False );
			}
			if ( True == pc_SoftDipSw->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW215, 0 ) ) {
				bl_Ret	= True;
			}
		}
		break;
	}

	return( bl_Ret );
}

// 概要 :トラブルコード設定処理. 
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//void PnlComSetProcessTroubleInfo( uchar uc_DetailCode )
void PnlComSetProcessTroubleInfo( uchar uc_DetailCode, uint32_t ui32_LineNum )
{

	{
		void* array[128];
		int size;

		size = backtrace( array, sizeof(array) / sizeof(array[0]) );
		printf("=== backtrace start ===\n");
		backtrace_symbols_fd( array, size, 1 );
		printf("=== backtrace end ===\n");
	}

	APIC_SystemStatus*	pc_Status	= PnlComGetSystemStatus();
	if ( 0 != pc_Status ) {
		pc_Status->setFatal( PNLD_ErrCode_Process_SeqCustom );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
		if (NULL != pc_BFW_System){
		    pc_BFW_System ->registDetailCode( PNLD_DetailCode_FileIdentification_0x1900740019000000 | (ui32_LineNum << 4));
		}
	}
	SYSF_logMsg( "SequenceCustomError 0x%4X", PNLD_ErrMask_PnlComLocal_SeqCustom | ( uc_DetailCode & PNLD_TroubleDetailMask_SeqCustom ) );
	
	// 表示中画面のエラーコード表示.
	uint32_t i32_ErrorCodeMask = 0;
	PNLC_PopupListControl* pc_PopupListCtrl = PNLC_PopupListControl::newInstance();
	if( 0 == pc_PopupListCtrl ) {
		SYSF_logMsg( "PNLC_PopupListControl is NULL" );
		return;
	}
	
	if( True == pc_PopupListCtrl->isPopupOpen() ) {
		PLayerControl* pc_NowSeqPopup = pc_PopupListCtrl->getNowPopup();
		if( 0 == pc_NowSeqPopup ) {
			SYSF_logMsg( "NowPopup is NULL" );
			return;
		}
		
		for( ushort us_cnt = 0; us_cnt < sizeof( sp_SeqGamenTroubleTable ) / sizeof( SP_SeqGamenTroubleTable ); ++us_cnt ) {
			if( pc_NowSeqPopup == sp_SeqGamenTroubleTable[ us_cnt ].pc_SeqGamen ) {
				i32_ErrorCodeMask = sp_SeqGamenTroubleTable[ us_cnt ].us_ErrorCodeMask;
				break;
			}
		}
		
	} else {
		PBasicMessageProc* pc_NowGamen = PBasicMessageProc::getNowGamen();
		if ( 0 == pc_NowGamen ) {
			SYSF_logMsg( "NowGamen is NULL" );
			return;
		}
		
		for( ushort us_cnt = 0; us_cnt < sizeof( sp_SeqGamenTroubleTable ) / sizeof( SP_SeqGamenTroubleTable ); ++us_cnt ) {
			if( pc_NowGamen == sp_SeqGamenTroubleTable[ us_cnt ].pc_SeqGamen ) {
				i32_ErrorCodeMask = sp_SeqGamenTroubleTable[ us_cnt ].us_ErrorCodeMask;
				break;
			}
		}
	}
	SYSF_logMsg( "NowGamenErrorCode 0x%4X", i32_ErrorCodeMask );
}

