// 概要 :認証シーケンス画面クラスインスタンス取得処理.
void PnlComSeqNextGamenInsGetCustom( ushort usAuthScreenID, PBasicMessageProc** pc_SeqNextGamen, char* pc_SeqNextGamenType )
{
	if ( ( 0 == pc_SeqNextGamen ) || ( 0 == pc_SeqNextGamenType ) ) {
		printf("PnlComSetProcessTroubleInfo %d, pc_SeqNextGamen is NULL or pc_SeqNextGamenType is NULL : %s(%d)\n", PNLD_TroubleDetailCode_IllegalParam_GetNextGamen, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalParam_GetNextGamen );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalParam_GetNextGamen , __LINE__ );
		return;
	}
	for( ushort i = 0; i < sizeof( sp_SeqNextGamenTable ) / sizeof( SP_SeqNextGamenTable ); ++i ) {
		// 該当する認証シーケンスIDと一致した場合は、対応する画面インスタンスと画面の種類を設定.
		if( sp_SeqNextGamenTable[i].usScreenID == usAuthScreenID ) {
			*pc_SeqNextGamen = sp_SeqNextGamenTable[i].pc_SeqNextGamen;
			*pc_SeqNextGamenType = sp_SeqNextGamenTable[i].c_SeqNextGamenType;
			return;
		}
	}
	// 該当する認証シーケンスIDと一致しない場合.
	*pc_SeqNextGamen = NULL;
	*pc_SeqNextGamenType = TYPD_NextGamenDisplayType_Error;
}

// 概要 :ユーザー認証処理.
void PnlComSeqUserAuthenticate( TYPS_AuthSeqOutParam* pt_FromMngParam, APIC_UserLoginResultNotifier* pc_Observer )
{
	// NULLチェック.
	if( 0 == pt_FromMngParam ) {
		printf("PnlComSetProcessTroubleInfo %d, pt_FromMngParam is NULL : %s(%d)\n", PNLD_TroubleDetailCode_GetParam_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetParam_Null );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetParam_Null , __LINE__ );
		return;
	}
	
	// オブザーバ宣言
	APIC_UserLoginResultNotifier* pc_UserLoginResultNotifier = &cc_UserLoginResultNotifierSeqCustom;
	if( 0 != pc_Observer ) {
		pc_UserLoginResultNotifier = pc_Observer;		// オブザーバ設定.
	}
	// ユーザ認証に必要なパラメータ定義.
	char sc_UserNameTemporary[PCGD_MaxUserName*3 + PCGD_EndCode] = { 0 };				// ユーザ名(MAX192byte).
	char sc_UserPasswordTemporary[PCGD_UserPasswordUTF8] = { 0 };						// パスワード(MAX64byte).
	char sc_SelSrvIndex = APID_AuthenticationServerIndexNone;							// 外部サーバーインデックス.
	char sc_ServerName[APID_MaxLengthOfServerName + PCGD_EndCode] = { 0 };				// 外部サーバ名(MAX32byte).
	short ss_UserFunctionMask = 0;														// 機能使用制限.
	TYPE_LoginDeviceType e_LoginDevType = TYPE_LoginDeviceType_None;					// 認証デバイス種別.
	TYPE_LoginAuthorityMode uc_LoginAuthorityMode = TYPE_LoginAuthorityMode_User;		// ログイン権限モード.
	
	// 内部パラメータの設定.
	ushort array_no = 0;
	ushort	size;
	
	// ユーザ名.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_USR_NAME );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size >= sizeof( sc_UserNameTemporary ) ) {
			size	= sizeof( sc_UserNameTemporary ) - 1;
		}
		memcpy( sc_UserNameTemporary, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		sc_UserNameTemporary[size]	= '\0';
	}

	// パスワード.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_USR_PASS );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size >= sizeof( sc_UserPasswordTemporary ) ) {
			size	= sizeof( sc_UserPasswordTemporary ) - 1;
		}
		// 登録後の認証の場合、登録情報を確認し認証時に設定する情報を更新する.
		if( True == b_LocalRegist ){
			b_LocalRegist = False;
			// パスワードの有効/無効を判定.
			if( ACSE_UserAutoRegistInfo_Off == sc_RegistUserInfo[ACSE_UserAutoRegistInfoType_PassWord] ){
				// 登録しない場合、認証時パスワード不要のため設定しない.
			}else{
				// 登録する場合、引継情報のパスワードを設定.
				memcpy( sc_UserPasswordTemporary, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
				sc_UserPasswordTemporary[size]	= '\0';
			}
		} else {
			memcpy( sc_UserPasswordTemporary, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
			sc_UserPasswordTemporary[size]	= '\0';
		}
	}

	// 外部サーバーインデックス.
	if(( pt_FromMngParam->st_actionParam.st_ParamAuth.usAuthForm == TYPD_PASM_AUTHKIND_EXTSERVER ) &&
		( pt_FromMngParam->st_actionParam.st_ParamAuth.scAuthDevice == ACSE_AuthServer_Fixed )) {
		// 動作情報(動作パラメータ) 外部サーバー認証先：認証カスタマイズ情報の指定サーバーで認証指定時、.
		// 認証カスタマイズ情報の指定サーバーでユーザ認証.
		sc_SelSrvIndex = pt_FromMngParam->st_actionParam.st_ParamAuth.scServerIndex;

		// 外部サーバー名取得. 
		APIC_AuthenticationSeverSetting* apicAuth = APIC_AuthenticationSeverSetting::newInstance();
		if (NULL == apicAuth) {LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return;}

		if( (APID_AuthenticationServerIndexNone < sc_SelSrvIndex) && (APID_MaxNumberOfAuthenticationSever >= sc_SelSrvIndex) ) {
			apicAuth->getServerName( sc_SelSrvIndex, sc_ServerName );
		}
	} else if( pt_FromMngParam->st_actionParam.st_ParamAuth.usAuthForm == TYPD_PASM_AUTHKIND_DEVICE ){
		// 動作種別(動作パラメータ)本体認証先指定時、サーバーインデックスを本体に設定.
		// 本体への認証のため外部サーバ名は不要.
		APIC_UserAuthentication* pc_UserAuthentication = APIC_UserAuthentication::newInstance();
		if( NULL == pc_UserAuthentication ){LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return;}

		TYPE_UserAuthentication e_UserAuthentication = pc_UserAuthentication->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine());
		if( TYPE_UserAuthenticationDeviceAndServer == e_UserAuthentication ){	// 本体装置+外部サーバでの認証.
			sc_SelSrvIndex = APID_DeviceAuthenticationIndex;		// (本体+外部認証時の)本体認証のサーバーインデックスを設定.
		}else{
			sc_SelSrvIndex = APID_AuthenticationServerIndexNone;	// デフォルトサーバなしを設定.
		}
	} else {
		array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_SRV_INDEX );
		if( array_no < TYPD_PASM_ATMDATA_MAX ) {
			size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
			if ( size == sizeof( sc_SelSrvIndex ) ) {
				memcpy( &sc_SelSrvIndex, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
			}
		}

		// 外部サーバー名.
		array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_SRV_NAME );
		if( array_no < TYPD_PASM_ATMDATA_MAX ) {
			size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
			if ( size >= sizeof( sc_ServerName ) ) {
				size	= sizeof( sc_ServerName ) - 1;
			}
			memcpy( sc_ServerName, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
			sc_ServerName[size]	= '\0';
		}
	}

	// 機能使用制限.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKINDFUNCTIONMASK );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size == sizeof( ss_UserFunctionMask ) ) {
			memcpy( &ss_UserFunctionMask, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		}
	}

	// 認証デバイス種別.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_DEVICE_TYPE );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size == sizeof( e_LoginDevType ) ) {
			memcpy( &e_LoginDevType, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		}
	}

	// ログイン権限モード.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_AUTHORITY_MODE );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size == sizeof( uc_LoginAuthorityMode ) ) {
			memcpy( &uc_LoginAuthorityMode, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		}
	}

	// IGC拡張パラメータ:要求元識別固有ナンバーの指定 
	TYPS_IGC_ExtensionParameter s_IGC_ExtensionParameter;
	s_IGC_ExtensionParameter.ul_DevDiscriminationNo = (onlyPanel.ec_IntMode == EC_IntMode_Off) ? 
							TYPE_OperationDeviceTypePanel_ONE : TYPE_OperationDeviceTypePanel_TWO;

	// ユーザ認証処理.
	APIC_User::req_login_ex( sc_UserNameTemporary,					// ユーザー名.
							 sc_UserPasswordTemporary,				// ユーザーパスワード.
							 sc_SelSrvIndex,						// 認証用外部サーバーインデックス.
							 sc_ServerName,							// 認証用外部サーバー名.
							 ss_UserFunctionMask,					// 機能使用制限.
							 pc_UserLoginResultNotifier,			// ログイン結果通知オブジェクト.
							 NULL,									// 将来の為の予約引数.
							 JLGE_InspectLogIfOperationPanel,		// インターフェース番号.
							 False,									// 監査ログ記録 しない.
							 False,									// 認証失敗時のみ 監査ログ 記録(※注意：「監査ログ記録 しない」が「False」時のみ有効).
							 &s_IGC_ExtensionParameter,				// IGC拡張パラメータ.
							 e_LoginDevType,						// ログインする認証デバイス種別.
							 TYPE_LoginMode_Normal,					// PKI 認証時中間認証を行うかどうか.
							 True,									// パスワードチェック有無フラグ.
							 uc_LoginAuthorityMode,					// ログイン権限モード.
							 TYPE_PKILoginModePassword,					// PKI種別.	// comment Sky東島 [RQ-686] 複合機の複数ネットワーク対応.
							 PNLC_NetworkLan::getInstance()->getLine()	// NW種別	// comment Sky東島 [RQ-686] 複合機の複数ネットワーク対応.
							);
	
	// 次画面の設定.
	if( False == onlyPanel.bl_isEnlargeDisplayMode ) { // 通常画面の場合.
		if( APID_AuthenticationServerIndexNone != sc_SelSrvIndex ) {		// 外部サーバーインデックスが本体認証以外の場合.
			PNLC_PopupListControl* pc_PopupListCtrl = PNLC_PopupListControl::newInstance();
			if( 0 == pc_PopupListCtrl ) {
				printf("PnlComSetProcessTroubleInfo %d, pc_PopupListCtrl is NULL : %s(%d)\n", PNLD_TroubleDetailCode_IllegalAddPopParam, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalAddPopParam );
				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalAddPopParam , __LINE__ );
				return;
			}
			if( True == pc_PopupListCtrl->isPopupOpen() ) {
				// P.U表示中の場合はP.U変更.
				// ただし、P.UがWarning系の場合にP.U変更を行うとWarning画面が消えてしまうため変更しないようにする.
				ushort us_GamenWarningNo;
				us_GamenWarningNo = onlyPanel.isAllGamenWarning( onlyPanel.cc_DisplayJob );

				if( 0 == us_GamenWarningNo ) {
					pc_PopupListCtrl->setChangePopup(
						&gp_ExcludedWait_act_SeqCustom,
						NULL
					);
				}
			} else {
				// P.U非表示の場合はP.U追加.
				pc_PopupListCtrl->addPopup(
					&gp_ExcludedWait_act_SeqCustom,
					PBasicMessageProc::getNowGamen(),
					NULL
				);
			}
		}
	} else { // 拡大画面の場合.
		if( APID_AuthenticationServerIndexNone != sc_SelSrvIndex ) {		// 外部サーバーインデックスが本体認証以外の場合.
			PBasicMessageProc::setNextGamen( &gp_EnlAct_ExcludedWait_SeqCustom );		// 「しばらくお待ちください」画面.
		}
	}
}

// 概要 :部門認証処理.
void PnlComSeqTrackAuthenticate( TYPS_AuthSeqOutParam* pt_FromMngParam )
{
	// NULLチェック.
	if( 0 == pt_FromMngParam ) {
		printf("PnlComSetProcessTroubleInfo %d, pt_FromMngParam is NULL : %s(%d)\n", PNLD_TroubleDetailCode_GetParam_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetParam_Null );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetParam_Null , __LINE__ );
		return;
	}
	
	// 部門認証に必要なパラメータ定義.
	char sc_MmbTrackName[PCGD_MaxTrackName + PCGD_EndCode] = { 0 };						// 部門名(MAX192byte).
	char sc_MmbTrackPassword[PCGD_TrackPasswordUTF8] = { 0 };							// 部門パスワード(MAX64byte).
	short ss_TrackFunctionMask = 0;														// 機能使用制限.
	TYPE_TrackResult e_TrackResult = TYPE_TrackResultPasswordNG;						// 部門結果.
	TYPE_LoginMode e_LoginMode = TYPE_LoginMode_Normal;									// 認証方式.
	int32_t i32_UserNo = 0;																	// ジョブログインスタンス取得用ユーザーNo.
	
	// 内部パラメータの設定.
	ushort array_no = 0;
	ushort	size;
	
	// 部門名.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_TRK_NAME );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size >= sizeof ( sc_MmbTrackName ) ) {
			size	= sizeof( sc_MmbTrackName ) - 1;
		}
		memcpy( sc_MmbTrackName, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		sc_MmbTrackName[size]	= '\0';
	}

	// 部門パスワード.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_TRK_PASS );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size >= sizeof( sc_MmbTrackPassword ) ) {
			size	= sizeof( sc_MmbTrackPassword ) - 1;
		}
		memcpy( sc_MmbTrackPassword, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		sc_MmbTrackPassword[size]	= '\0';
	}

	// 機能使用制限.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKINDFUNCTIONMASK );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size == sizeof( ss_TrackFunctionMask ) ) {
			memcpy( &ss_TrackFunctionMask, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		}
	}

	// 認証方式.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_AUTH_TYPE );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size == sizeof( e_LoginMode ) ) {
			memcpy( &e_LoginMode, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		}
	}

	// ジョブログインスタンス取得用ユーザーNo.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_USR_NO_FOR_JOBLOG );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size == sizeof( i32_UserNo ) ) {
			memcpy( &i32_UserNo, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		}
	}

	// 部門認証処理.
	APIC_Track::req_login( sc_MmbTrackName,												// 部門名.
						   sc_MmbTrackPassword,											// パスワード.
						   ss_TrackFunctionMask,										// 機能使用制限.
						   &PCNC_TrackLoginResultNotifierSeqCustom::notifyLoginResult,	// コールバック関数.
						   &e_TrackResult,												// 部門認証結果.
						   JLGE_InspectLogIfOperationPanel,								// 監査ログ インターフェース番号.
						   False,														// 監査ログ記録 しない.
						   False,														// 認証失敗時のみ 監査ログ 記録(※注意：「監査ログ記録 しない」が「False」時のみ有効).
						   True,														// パスワード規約確認.
						   e_LoginMode,													// 認証方式.
						   i32_UserNo													// ジョブログインスタンス取得用ユーザーNo.
						);
	
	
	char sc_SelSrvIndex = APID_AuthenticationServerIndexNone;							// 外部サーバーインデックス.
	// 外部サーバーインデックス.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_SRV_INDEX );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size == sizeof( sc_SelSrvIndex ) ) {
			memcpy( &sc_SelSrvIndex, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		}
	}
	
	// 次画面の設定.
	if( False == onlyPanel.bl_isEnlargeDisplayMode ) { // 通常画面の場合.		
		if( APID_AuthenticationServerIndexNone != sc_SelSrvIndex ) {		// 外部サーバーインデックスが本体認証以外の場合.
			PNLC_PopupListControl* pc_PopupListCtrl = PNLC_PopupListControl::newInstance();
			if( 0 == pc_PopupListCtrl ) {
				printf("PnlComSetProcessTroubleInfo %d, pc_PopupListCtrl is NULL : %s(%d)\n", PNLD_TroubleDetailCode_IllegalAddPopParam, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalAddPopParam );
				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalAddPopParam , __LINE__ );
				return;
			}
			if( True == pc_PopupListCtrl->isPopupOpen() ) {
				// P.U表示中の場合はP.U変更.
				// ただし、P.UがWarning系の場合にP.U変更を行うとWarning画面が消えてしまうため変更しないようにする.
				ushort us_GamenWarningNo;
				us_GamenWarningNo = onlyPanel.isAllGamenWarning( onlyPanel.cc_DisplayJob );

				if( 0 == us_GamenWarningNo ) {
					pc_PopupListCtrl->setChangePopup(
						&gp_ExcludedWait_act_SeqCustom,
						NULL
					);
				}
			} else {
				// P.U非表示の場合はP.U追加.
				pc_PopupListCtrl->addPopup(
					&gp_ExcludedWait_act_SeqCustom,
					PBasicMessageProc::getNowGamen(),
					NULL
				);
			}
		}
	} else { // 拡大画面の場合.
		if( APID_AuthenticationServerIndexNone != sc_SelSrvIndex ) {		// 外部サーバーインデックスが本体認証以外の場合.
			PBasicMessageProc::setNextGamen( &gp_EnlAct_ExcludedWait_SeqCustom );		// 「しばらくお待ちください」画面.
		}
	}
}

// ユーザー登録確認処理.
void PnlComSeqRegistConfirm( TYPS_AuthSeqOutParam* pt_FromMngParam )
{
	// NULLチェック.
	if( 0 == pt_FromMngParam ) {
		printf("PnlComSetProcessTroubleInfo %d, pt_FromMngParam is NULL : %s(%d)\n", PNLD_TroubleDetailCode_GetParam_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetParam_Null );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetParam_Null , __LINE__ );
		return;
	}
	
	// ユーザ登録確認に必要なパラメータ定義.
	char sc_UserNameTemporary[PCGD_MaxUserName*3 + PCGD_EndCode]  = { 0 };				// ユーザ名(MAX192byte).
	char sc_UserPasswordTemporary[PCGD_UserPasswordUTF8]  = { 0 };						// パスワード(MAX64byte).
	char sc_SelSrvIndex = APID_AuthenticationServerIndexNone;							// 外部サーバーインデックス.
	short ss_UserFunctionMask = 0;														// 機能使用制限.
	TYPE_LoginAuthorityMode uc_LoginAuthorityMode = TYPE_LoginAuthorityMode_User;		// ログイン権限モード.
	
	// 内部パラメータの設定.
	ushort array_no = 0;
	ushort	size;
	
	// ユーザ名.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_USR_NAME );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size >= sizeof( sc_UserNameTemporary ) ) {
			size	= sizeof( sc_UserNameTemporary ) - 1;
		}
		memcpy( sc_UserNameTemporary, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		sc_UserNameTemporary[size]	= '\0';
	}

	// パスワード.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_USR_PASS );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size >= sizeof( sc_UserPasswordTemporary ) ) {
			size	= sizeof( sc_UserPasswordTemporary ) - 1;
		}
		memcpy( sc_UserPasswordTemporary, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		sc_UserPasswordTemporary[size]	= '\0';
	}

	// 外部サーバーインデックス.
	if( pt_FromMngParam->st_actionParam.st_ParamRegistConfirm.scAuthDevice == ACSE_AuthServer_Fixed ) {
		// 動作情報(動作パラメータ) ユーザ登録確認先：認証カスタマイズ情報の指定サーバーで認証指定時、.
		// 認証カスタマイズ情報の指定サーバーでユーザ登録確認.
		sc_SelSrvIndex = pt_FromMngParam->st_actionParam.st_ParamRegistConfirm.scServerIndex;
	} else {
		// ユーザー指定サーバーでユーザ登録確認.
		array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_SRV_INDEX );
		if( array_no < TYPD_PASM_ATMDATA_MAX ) {
			size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
			if ( size == sizeof( sc_SelSrvIndex ) ) {
				memcpy( &sc_SelSrvIndex, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
			}
		}
	}
	
	// 機能使用制限.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKINDFUNCTIONMASK );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size == sizeof( ss_UserFunctionMask ) ) {
			memcpy( &ss_UserFunctionMask, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		}
	}
	
	// ログイン権限モード.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_AUTHORITY_MODE );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size == sizeof( uc_LoginAuthorityMode ) ) {
			memcpy( &uc_LoginAuthorityMode, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		}
	}

	
	// ユーザ登録確認処理.
	APIC_PASM* pc_ApicPasm = APIC_PASM::newInstance();
	if( 0 == pc_ApicPasm ) {
		printf("PnlComSetProcessTroubleInfo %d, pc_ApicPasm is NULL : %s(%d)\n", PNLD_TroubleDetailCode_PasmInstance_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_PasmInstance_Null );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_PasmInstance_Null , __LINE__ );
		return;
	}

	// ユーザー情報登録確認要求 仕様：.
	// サーバーインデックスが、 (本体+外部認証時の)本体認証のサーバーインデックス(APID_DeviceAuthenticationIndex(=101))の場合,.
	// APID_AuthenticationServerIndexNone(=0)を指定する。.
	char sc_SelSrvIndex_req_UserRegConfirm = sc_SelSrvIndex;
	if( APID_DeviceAuthenticationIndex == sc_SelSrvIndex_req_UserRegConfirm ) {
		sc_SelSrvIndex_req_UserRegConfirm = APID_AuthenticationServerIndexNone;
	}
	pc_ApicPasm->req_UserRegConfirm( sc_SelSrvIndex_req_UserRegConfirm,				// 認証用外部サーバーインデックス.
									 sc_UserNameTemporary,							// ユーザー名.
									 sc_UserPasswordTemporary,						// ユーザーパスワード.
									 ss_UserFunctionMask,							// 機能使用制限.
									 JLGE_InspectLogIfOperationPanel,				// インターフェース番号.
									 False,											// 監査ログ記録 しない.
									 False,											// 認証失敗時のみ 監査ログ 記録(※注意：「監査ログ記録 しない」が「False」時のみ有効).
									 uc_LoginAuthorityMode							// ログイン権限モード.
								);

	// 次画面の設定.
	if( False == onlyPanel.bl_isEnlargeDisplayMode ) { // 通常画面の場合.
		if( APID_AuthenticationServerIndexNone != sc_SelSrvIndex ) {		// 外部サーバーインデックスが本体認証以外の場合.
			PNLC_PopupListControl* pc_PopupListCtrl = PNLC_PopupListControl::newInstance();
			if( 0 == pc_PopupListCtrl ) {
				printf("PnlComSetProcessTroubleInfo %d, pc_PopupListCtrl is NULL : %s(%d)\n", PNLD_TroubleDetailCode_IllegalAddPopParam, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalAddPopParam );
				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalAddPopParam , __LINE__ );
				return;
			}
			if( True == pc_PopupListCtrl->isPopupOpen() ) {
				// P.U表示中の場合はP.U変更.
				// ただし、P.UがWarning系の場合にP.U変更を行うとWarning画面が消えてしまうため変更しないようにする.
				ushort us_GamenWarningNo;
				us_GamenWarningNo = onlyPanel.isAllGamenWarning( onlyPanel.cc_DisplayJob );

				if( 0 == us_GamenWarningNo ) {
					pc_PopupListCtrl->setChangePopup(
						&gp_ExcludedWait_act_SeqCustom,
						NULL
					);
				}
			} else {
				// P.U非表示の場合はP.U追加.
				pc_PopupListCtrl->addPopup(
					&gp_ExcludedWait_act_SeqCustom,
					PBasicMessageProc::getNowGamen(),
					NULL
				);
			}
		}
	} else { // 拡大画面の場合.
		if( APID_AuthenticationServerIndexNone != sc_SelSrvIndex ) {		// 外部サーバーインデックスが本体認証以外の場合.
			PBasicMessageProc::setNextGamen( &gp_EnlAct_ExcludedWait_SeqCustom );		// 「しばらくお待ちください」画面.
		}
	}
}


// 概要 :ユーザー登録処理.
void PnlComSeqRegist( TYPS_AuthSeqOutParam* pt_FromMngParam )
{
	// NULLチェック.
	if( 0 == pt_FromMngParam ) {
		printf("PnlComSetProcessTroubleInfo %d, pt_FromMngParam is NULL : %s(%d)\n", PNLD_TroubleDetailCode_GetParam_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetParam_Null );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetParam_Null , __LINE__ );
		return;
	}
	
	// ユーザ登録に必要なパラメータ定義.
	char sc_UserName[PCGD_MaxUserName*3 + PCGD_EndCode] = { 0 };			// ユーザ名(MAX192byte).
	char sc_UserPassword[PCGD_UserPasswordUTF8] = { 0 };					// パスワード(MAX64byte).
	char sc_SrvIndex = APID_AuthenticationServerIndexNone;					// ユーザー登録サーバーインデックス.
	TYPE_LoginDeviceType e_LoginDevType = TYPE_LoginDeviceType_None;					// 認証デバイス種別.
	
	// 内部パラメータの設定.
	ushort array_no = 0;
	ushort	size;
	
	// ユーザ名.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_USR_NAME );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size >= sizeof( sc_UserName ) ) {
			size	= sizeof( sc_UserName ) - 1;
		}
		memcpy( sc_UserName, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		sc_UserName[size]	= '\0';
	}

	// パスワード.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_USR_PASS );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size >= sizeof( sc_UserPassword ) ) {
			size	= sizeof( sc_UserPassword ) - 1;
		}
		memcpy( sc_UserPassword, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		sc_UserPassword[size]	= '\0';
	}

	// ユーザー登録サーバーインデックス.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_SRV_INDEX );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size == sizeof( sc_SrvIndex ) ) {
			memcpy( &sc_SrvIndex, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		}
	}
	
	// 認証デバイス種別.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_DEVICE_TYPE );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size == sizeof( e_LoginDevType ) ) {
			memcpy( &e_LoginDevType, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		}
	}

	// ユーザ登録処理.
	APIC_PASM* pc_ApicPasm = APIC_PASM::newInstance();
	if( 0 == pc_ApicPasm ) {
		printf("PnlComSetProcessTroubleInfo %d, pc_ApicPasm is NULL : %s(%d)\n", PNLD_TroubleDetailCode_PasmInstance_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_PasmInstance_Null );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_PasmInstance_Null , __LINE__ );
		return;
	}

	ACSE_UserAutoRegistDest e_UserAutoRegistDest = ACSE_UserAutoRegistDest_Mfp;
	
	// 動作種別が登録である場合.
	if( TYPD_PASM_ACTPARAMKIND_REGISTUSER == pt_FromMngParam->ucActionParamKind ){
		// 動作情報からユーザ登録パラメータを取得.
		e_UserAutoRegistDest = pt_FromMngParam->st_actionParam.st_ParamRegist.scRegistServer;
		// 取得した結果から設定するIndexを決定.
		switch( e_UserAutoRegistDest ){
		case ACSE_UserAutoRegistDest_Mfp:			// MFP本体に登録する.
			sc_SrvIndex = 0;		// Indexを0(本体)に設定.
			break;
		case ACSE_UserAutoRegistDest_AuthServer:	// 認証先サーバーに登録する.
			// 引継情報で設定されているIndexを使用するため設定不要.
			break;
		case ACSE_UserAutoRegistDest_FixServer:		// 固定サーバーに登録する.
			sc_SrvIndex = pt_FromMngParam->st_actionParam.st_ParamRegist.scServerIndex;		// コンフィグに指定されているIndexを指定.
			break;
		default:									// 範囲外.
			printf("PnlComSetProcessTroubleInfo %d, e_UserAutoRegistDest is %d : %s(%d)\n", PNLD_TroubleDetailCode_ConfError, e_UserAutoRegistDest, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//			PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_ConfError );
			PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_ConfError , __LINE__ );
			return;
		}
		
	}else{
		// 動作種別が異なるためエラー.
		printf("PnlComSetProcessTroubleInfo %d, pt_FromMngParam->ucActionParamKind is %d : %s(%d)\n", PNLD_TroubleDetailCode_ConfError, pt_FromMngParam->ucActionParamKind, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_ConfError );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_ConfError , __LINE__ );
		return;
	}

	for( int i = 0; i < ACID_RegistUserInfoMaxSize; i++ ){
		sc_RegistUserInfo[i] = pt_FromMngParam->st_actionParam.st_ParamRegist.scRegistUserInfo[i];
	}
	b_LocalRegist = True;

	// ユーザー情報の自動登録要求 仕様：.
	// サーバーインデックスが、 (本体+外部認証時の)本体認証のサーバーインデックス(APID_DeviceAuthenticationIndex(=101))の場合,.
	// APID_AuthenticationServerIndexNone(=0)を指定する。.
	char sc_SelSrvIndex_req_UserAutoRegistCustom = sc_SrvIndex;
	if( APID_DeviceAuthenticationIndex == sc_SelSrvIndex_req_UserAutoRegistCustom ) {
		sc_SelSrvIndex_req_UserAutoRegistCustom = APID_AuthenticationServerIndexNone;
	}
	pc_ApicPasm->req_UserAutoRegistCustom( sc_UserName,							// 登録するユーザー名.
										   sc_UserPassword,						// 登録するユーザーパスワード.
										   sc_SelSrvIndex_req_UserAutoRegistCustom,// ユーザー登録サーバーインデックス.
										   JLGE_InspectLogIfOperationPanel,		// インターフェース番号.
										   False,								// 監査ログ記録 しない.
							 			   e_LoginDevType						// ログインする認証デバイス種別.
										  );

	// 次画面の設定.
	if( False == onlyPanel.bl_isEnlargeDisplayMode ) { // 通常画面の場合.
		if( APID_AuthenticationServerIndexNone != sc_SrvIndex ) {		// 外部サーバーインデックスが本体認証以外の場合.
			PNLC_PopupListControl* pc_PopupListCtrl = PNLC_PopupListControl::newInstance();
			if( 0 == pc_PopupListCtrl ) {
				printf("PnlComSetProcessTroubleInfo %d, pc_PopupListCtrl is NULL : %s(%d)\n", PNLD_TroubleDetailCode_IllegalAddPopParam, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalAddPopParam );
				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalAddPopParam , __LINE__ );
				return;
			}
			if( True == pc_PopupListCtrl->isPopupOpen() ) {
				// P.U表示中の場合はP.U変更.
				// ただし、P.UがWarning系の場合にP.U変更を行うとWarning画面が消えてしまうため変更しないようにする.
				ushort us_GamenWarningNo;
				us_GamenWarningNo = onlyPanel.isAllGamenWarning( onlyPanel.cc_DisplayJob );

				if( 0 == us_GamenWarningNo ) {
					pc_PopupListCtrl->setChangePopup(
						&gp_ExcludedWait_act_SeqCustom,
						NULL
					);
				}
			} else {
				// P.U非表示の場合はP.U追加.
				pc_PopupListCtrl->addPopup(
					&gp_ExcludedWait_act_SeqCustom,
					PBasicMessageProc::getNowGamen(),
					NULL
				);
			}
		}
	} else { // 拡大画面の場合.
		if( APID_AuthenticationServerIndexNone != sc_SrvIndex ) {		// 外部サーバーインデックスが本体認証以外の場合.
			PBasicMessageProc::setNextGamen( &gp_EnlAct_ExcludedWait_SeqCustom );		// 「しばらくお待ちください」画面.
		}
	}
}

// 概要 :ユーザー情報取得処理.
void PnlComSeqGetUserData ( TYPS_AuthSeqOutParam* pt_FromMngParam )
{
	// NULLチェック.
	if( 0 == pt_FromMngParam ) {
		printf("PnlComSetProcessTroubleInfo %d, pt_FromMngParam is NULL : %s(%d)\n", PNLD_TroubleDetailCode_GetParam_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetParam_Null );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetParam_Null , __LINE__ );
		return;
	}
	
	// ユーザ情報取得に必要なパラメータ定義.
	char sc_UserName[PCGD_MaxUserName*3 + PCGD_EndCode] = { 0 };				// ユーザ名(MAX192byte).
	char sc_UserPassword[PCGD_UserPasswordUTF8] = { 0 };						// パスワード(MAX64byte).
	char sc_SrvIndex = APID_AuthenticationServerIndexNone;						// データ取得先サーバーID.
	TYPE_LoginMode uc_LoginMode = TYPE_LoginMode_Normal;						// ログイン権限モード.
	TYPE_UserResult e_UserResult = TYPE_UserResultOtherError;					// ユーザー認証結果.
	
	// 内部パラメータの設定.
	ushort array_no = 0;
	ushort	size;
	
	// 認証結果の取得.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_RES );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size == sizeof( e_UserResult ) ) {
			memcpy( &e_UserResult,
					pt_FromMngParam->st_ATMGetInfo[array_no].pvData,
					size
			);
		}
	}

	// 「ユーザー名」と「パスワード」は、認証が成功した場合にユーザー情報インスタンスの引継ぎ情報からパラメータを取得.
	// ユーザ名.
	if(		( TYPE_UserResultOk == e_UserResult )
		||	( TYPE_UserResultFunctionNG == e_UserResult )
		||	( TYPE_UserResultOk_PasswordUnReg == e_UserResult )
		||	( TYPE_UserResult_CacheAuthSuccess == e_UserResult ) ) {
		array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_USRINSTANCE_NAME );
	} else {
		array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_USR_NAME );
	}
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size >= sizeof( sc_UserName ) ) {
			size	= sizeof( sc_UserName ) - 1;
		}
		memcpy( sc_UserName, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		sc_UserName[size]	= '\0';
	}

	// パスワード.
	if(		( TYPE_UserResultOk == e_UserResult )
		||	( TYPE_UserResultFunctionNG == e_UserResult )
		||	( TYPE_UserResultOk_PasswordUnReg == e_UserResult )
		||	( TYPE_UserResult_CacheAuthSuccess == e_UserResult ) ) {
		array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_USRINSTANCE_PASS );
	} else {
		array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_USR_PASS );
	}
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size >= sizeof( sc_UserPassword ) ) {
			size	= sizeof( sc_UserPassword ) - 1;
		}
		memcpy( sc_UserPassword, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		sc_UserPassword[size]	= '\0';
	}

	// データ取得先サーバーID.
	if( pt_FromMngParam->st_actionParam.st_ParamGet.scDataGetServer == ACSE_AuthServer_Fixed ) {
		// 動作情報(動作パラメータ) データ取得先：認証カスタマイズ情報の指定サーバー指定時、.
		// 認証カスタマイズ情報の指定サーバーで データ取得.
		sc_SrvIndex = pt_FromMngParam->st_actionParam.st_ParamGet.scServerIndex;
	} else {
		// ユーザー指定サーバーでデータ取得.
		array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_SRV_INDEX );
		if( array_no < TYPD_PASM_ATMDATA_MAX ) {
			size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
			if ( size == sizeof( sc_SrvIndex ) ) {
				memcpy( &sc_SrvIndex, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
			}
		}
	}
	
	// ログイン権限モード.
	array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_AUTHORITY_MODE );
	if( array_no < TYPD_PASM_ATMDATA_MAX ) {
		size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
		if ( size == sizeof( uc_LoginMode ) ) {
			memcpy( &uc_LoginMode, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
		}
	}

	// ユーザ情報取得処理.
	APIC_PASM* pc_ApicPasm = APIC_PASM::newInstance();
	if( 0 == pc_ApicPasm ) {
		printf("PnlComSetProcessTroubleInfo %d, pc_ApicPasm is NULL : %s(%d)\n", PNLD_TroubleDetailCode_PasmInstance_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_PasmInstance_Null );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_PasmInstance_Null , __LINE__ );
		return;
	}
	pc_ApicPasm->req_ExtServerDataGet( sc_SrvIndex,			// ユーザー登録サーバーインデックス.
									   sc_UserName,			// ユーザー名.
									   sc_UserPassword,		// ユーザーパスワード.
									   uc_LoginMode			// 認証方式.
									  );

	// 次画面の設定.
	if( False == onlyPanel.bl_isEnlargeDisplayMode ) { // 通常画面の場合.
		if( APID_AuthenticationServerIndexNone != sc_SrvIndex ) {		// 外部サーバーインデックスが本体認証以外の場合.
			PNLC_PopupListControl* pc_PopupListCtrl = PNLC_PopupListControl::newInstance();
			if( 0 == pc_PopupListCtrl ) {
				printf("PnlComSetProcessTroubleInfo %d, pc_PopupListCtrl is NULL : %s(%d)\n", PNLD_TroubleDetailCode_IllegalAddPopParam, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalAddPopParam );
				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalAddPopParam , __LINE__ );
				return;
			}
			if( True == pc_PopupListCtrl->isPopupOpen() ) {
				// P.U表示中の場合はP.U変更.
				// ただし、P.UがWarning系の場合にP.U変更を行うとWarning画面が消えてしまうため変更しないようにする.
				ushort us_GamenWarningNo;
				us_GamenWarningNo = onlyPanel.isAllGamenWarning( onlyPanel.cc_DisplayJob );

				if( 0 == us_GamenWarningNo ) {
					pc_PopupListCtrl->setChangePopup(
						&gp_ExcludedWait_act_SeqCustom,
						NULL
					);
				}
			} else {
				// P.U非表示の場合はP.U追加.
				pc_PopupListCtrl->addPopup(
					&gp_ExcludedWait_act_SeqCustom,
					PBasicMessageProc::getNowGamen(),
					NULL
				);
			}
		}
	} else { // 拡大画面の場合.
		if( APID_AuthenticationServerIndexNone != sc_SrvIndex ) {		// 外部サーバーインデックスが本体認証以外の場合.
			PBasicMessageProc::setNextGamen( &gp_EnlAct_ExcludedWait_SeqCustom );		// 「しばらくお待ちください」画面.
		}
	}
}

// 概要 :シーケンス終了処理.
Bool PnlComSeqEndSequence( TYPS_AuthSeqOutParam* pt_FromMngParam)
{
	// シーケンスカスタマイズでは認証処理を行なわずに認証終了することがある(コンフィグ不正での認証エラーなど).
	// 認証処理がされずにシーケンス終了することで警告フラグが残ったままとなり、次にrebuildGamenがコールされたとき警告フラグに対応する画面が表示されてしまう.
	// 認証に関連するフラグはシーケンス終了でoffしておく.
	onlyPanel.resetPanelWarning( PNL_ERROR_UserCertificatePenalty );
	onlyPanel.resetPanelWarning( PNL_ERROR_UserCertificateServerBusy );
	onlyPanel.resetPanelWarning( PNL_ERROR_UserCertificateUserFull );
	onlyPanel.resetPanelWarning( PNL_ERROR_CertificateFailedPenalty );
	onlyPanel.resetPanelWarning( PNL_ERROR_CertificateFailedPenaltyBox );
	onlyPanel.resetPanelWarning( PNL_ERROR_CertificateFailedPassword );
	onlyPanel.resetPanelWarning( PNL_ERROR_PassWordDocCertificate );
	onlyPanel.resetPanelWarning( PNL_ERROR_UserCertificate );			
	onlyPanel.resetPanelWarning( PNL_ERROR_UserCertificateCardIDSizeOver );
	onlyPanel.resetPanelWarning( PNL_ERROR_SecurityDocumentCertificate );
	onlyPanel.resetPanelWarning( PNL_ERROR_BoxPasswordCertificate );
	onlyPanel.resetPanelWarning( PNL_OTHER_UserAccountRegistAndAuth );

	Bool bl_FailedCheck = False;									// 処理失敗検知用.
	
	// ローカル変数の初期化.
	b_LocalRegist = False;

	// NULLチェック.
	if( 0 == pt_FromMngParam ) {
		printf("PnlComSetProcessTroubleInfo %d, pt_FromMngParam is NULL : %s(%d)\n", PNLD_TroubleDetailCode_GetParam_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetParam_Null );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetParam_Null , __LINE__ );
		return True;
	}
	
	// ユーザ登録に必要なパラメータ定義.
	char sc_TrackName[PCGD_MaxTrackName + PCGD_EndCode] = { 0 };								// 部門名(MAX192byte).

	ACSE_GetTrackSetting e_Valid = ACSE_GetTrackSetting_Convent;		// 部門名取得設定.

	if( TYPD_PASM_ACTPARAMKIND_SUCCESS == pt_FromMngParam->ucActionParamKind ) {		// 動作情報種別がシーケンス正常終了の場合.
		// 機能制限情報不正値判定.
		PnlComSeqFuncLimit(pt_FromMngParam);

		// 内部パラメータの設定.
		ushort array_no = 0;
		ushort	size;
		// 部門名.
		array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_TRK_NAME );
		if( array_no < TYPD_PASM_ATMDATA_MAX ) {
			size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
			if ( size >= sizeof( sc_TrackName ) ) {
				size	= sizeof( sc_TrackName ) - 1;
			}
			memcpy( sc_TrackName, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
			sc_TrackName[size]	= '\0';
		}
		
		// ログイン部門名認証チェック情報取得処理.
		APIC_PASM* pc_ApicPasm = APIC_PASM::newInstance();
		if( 0 == pc_ApicPasm ) {
			printf("PnlComSetProcessTroubleInfo %d, pc_ApicPasm is NULL : %s(%d)\n", PNLD_TroubleDetailCode_PasmInstance_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//			PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_PasmInstance_Null );
			PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_PasmInstance_Null , __LINE__ );
			return True;
		}
		pc_ApicPasm->getAuthCustInfoGetTrackSetting( &e_Valid );
		if( e_Valid == ACSE_GetTrackSetting_Custom && 0 >= strlen( sc_TrackName ) ) {	// 部門名取得設定が機能有効、かつ部門名がブランク(空)の場合.
			// 次画面の設定.
			PNLC_PopupListControl* pc_PopupListCtrl = PNLC_PopupListControl::newInstance();
			if( 0 == pc_PopupListCtrl ) {
				printf("PnlComSetProcessTroubleInfo %d, pc_PopupListCtrl is NULL : %s(%d)\n", PNLD_TroubleDetailCode_IllegalAddPopParam, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalAddPopParam );
				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalAddPopParam , __LINE__ );
				return True;
			}
			if( False == onlyPanel.bl_isEnlargeDisplayMode ) { // 通常画面の場合.
				if( True == pc_PopupListCtrl->isPopupOpen() ) {
					// P.U表示中の場合はP.U変更.
					// ただし、P.UがWarning系の場合にP.U変更を行うとWarning画面が消えてしまうため変更しないようにする.
					ushort us_GamenWarningNo;
					us_GamenWarningNo = onlyPanel.isAllGamenWarning( onlyPanel.cc_DisplayJob );

					if( 0 == us_GamenWarningNo ) {
						pc_PopupListCtrl->setChangePopup(
							&gp_UserCertificate_warn_Custom_SeqCustom,
							NULL
						);
					}
				} else {
					// P.U非表示の場合はP.U追加.
					pc_PopupListCtrl->addPopup(
						&gp_UserCertificate_warn_Custom_SeqCustom,
						PBasicMessageProc::getNowGamen(),
						NULL
					);
				}
			} else { // 拡大画面の場合.
				pc_PopupListCtrl->addPopup( &gp_EnlWarn_UserCertificate_Custom_SeqCustom, PBasicMessageProc::getNowGamen(), 0 );
			}
			return False;			// エラーなし.
		}
		
		// 特殊ユーザ切り替え.
		// ログイン権限モード.
		TYPE_LoginAuthorityMode uc_LoginAuthorityMode = TYPE_LoginAuthorityMode_User;		// ログイン権限モード.
		array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMGetInfo( pt_FromMngParam, TYPD_PASM_ATMDATAKIND_AUTHORITY_MODE );
		if( array_no < TYPD_PASM_ATMDATA_MAX ) {
			size	= pt_FromMngParam->st_ATMGetInfo[array_no].usSize;
			if ( size == sizeof( uc_LoginAuthorityMode ) ) {
				memcpy( &uc_LoginAuthorityMode, pt_FromMngParam->st_ATMGetInfo[array_no].pvData, size );
			}
		}

		APIC_User* pc_User = pc_LocalUser;								// ユーザ認証結果(ユーザ情報).
		TYPE_UserResult e_UserResult = e_MmbCallBackLocalUserResult;	// ユーザ処理結果.
		short ss_AuthorityID = PnlComGetAuthorityID();					// ユーザ識別ID.
		uchar uc_userChangeRet = 0;
		PNLS_ProfileInfo s_ProfileInfo;
		PnlComSeqGetProfileInfo( &s_ProfileInfo );

		uc_userChangeRet = APIC_PASM::procAuthConfirmedCustom( &pc_User, &e_UserResult, &ss_AuthorityID );

		if ( NULL == pc_User ) {
			bl_FailedCheck	= True;
		} else {
			if( TYPD_PASM_AUTHORITYMODE_INVALID == uc_userChangeRet ) {
				if( False == pc_User->getRegistration() ){
					pc_User->setRegistration( True, TYPE_RegistrationTypeOnlyOne, JLGE_InspectLogIfOperationPanel, False, TYPE_Registration_State_ReNew,  True, pc_User, PnlComGetAuthorityID());
				}else{
					pc_User->setRegistration( True, TYPE_RegistrationTypeOnlyOne, JLGE_InspectLogIfOperationPanel, False, TYPE_Registration_State_New,  True, pc_User, PnlComGetAuthorityID());
				}
				// 権限付与なしのため現在の情報を反映.
				PnlComSetTrack( pc_LocalTrack );
				PCGC_PanelMain::PnlMainProfileSwitch( s_ProfileInfo.ul_IndexNo, s_ProfileInfo.ul_SessionID );			// プロファイル情報反映.
			}else if( ( TYPD_PASM_AUTHORITYMODE_VALID == uc_userChangeRet ) ){
				// 特殊ユーザ切り替え処理失敗時、失敗検知フラグをTrueにする.
				if( NULL == pc_User || TYPE_UserResultOk != e_UserResult || ( -1 ) == ss_AuthorityID ) {
					bl_FailedCheck = True;
				}
				// 権限付与ありの場合、変換されたユーザ情報を元にプロファイル情報を更新.
				LAPC_BFW_System* p_lapcBfwSystem = LAPC_BFW_System::newInstance();
				if( NULL == p_lapcBfwSystem ) {
					printf("PnlComSetProcessTroubleInfo %d, p_lapcBfwSystem is NULL : %s(%d)\n", PNLD_TroubleDetailCode_LapcBfwSystem_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//					PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_LapcBfwSystem_Null );
					PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_LapcBfwSystem_Null , __LINE__ );
					return True;		// エラーあり.
				}
	
				// ユーザインスタンスがNULL以外、かつ認証成功、かつ識別IDが-1以外の場合、認証結果変更処理を行う.
				if( False == bl_FailedCheck ) {
					API_RESULT e_Result = LAPE_ResultNG;			// 認証結果変更処理の結果.
					LAPC_AUT_Authentication  AUT_Authentication(LAPC_BFW_System::newInstance());
					LAPS_LoginInfo s_SessionInfo = {};
					uint32_t ui32_SessionID = 0;
	
					// ユーザ/部門IDを変換.
					TYPS_LoginInfo s_LoginInfo;
					// Comment 2017/02/20 HCL_Sasaki IT5_4.0 Klockwork Changes ID:78913.
					TYPS_LoginInfo s_UpDataLoginInfo = {};
// Comment 2016/09/13 [HCLT_Surajit] [1002990] 【IT5_3.3】Klocwork Changes ID: 78511 [UNINIT.STACK.MIGHT] initialized member variable ul_SessionID of s_UpDataLoginInfo with default value 0 .
					s_UpDataLoginInfo.ul_SessionID = 0;
// Comment 2017/01/18 [HCLT_Shalini] [1010037] 【IT5_3.4】Klocwork Changes ID: 76946,76961 [UNINIT.STACK.MIGHT] initialized member variable ul_TrackID,ul_UserID of s_UpDataLoginInfo with default value 0 .
					s_UpDataLoginInfo.ul_TrackID = 0;
					s_UpDataLoginInfo.ul_UserID  = 0;
					for( short sc_Cnt = 0; sc_Cnt <= 2; sc_Cnt++ ){
						APIC_User::getLocalLoginInfo( sc_Cnt, &s_LoginInfo );
						// セッションIDを比較.
						if( s_ProfileInfo.ul_SessionID == s_LoginInfo.ul_SessionID ){
							s_UpDataLoginInfo.ul_SessionID = s_LoginInfo.ul_SessionID;
							// ユーザIDを専用のIDに変換.
							switch( pc_User->getUserNo() ){
								case TYPD_IndexUserAdmin:				// 管理者の場合.
									s_SessionInfo.userId = LAPE_USR_SpUserId_Admin;
									s_UpDataLoginInfo.ul_UserID = TYPD_IndexUserAdmin;
									if( 0 != s_LoginInfo.ul_TrackID ){	// 部門と連動してログインしている場合.
										s_SessionInfo.trackId = LAPE_USR_SpTrackId_Admin;
										s_UpDataLoginInfo.ul_TrackID = TYPD_IndexTrackAdmin;
									}else{
										s_SessionInfo.trackId = LAPD_USR_InvalidId;
										s_UpDataLoginInfo.ul_TrackID = 0;
									}
									break;
								case TYPD_IndexUserBoxAdmin:			// BOX管理者の場合.
									s_SessionInfo.userId = LAPE_USR_SpUserId_BoxAdmin;
									s_UpDataLoginInfo.ul_UserID = TYPD_IndexUserBoxAdmin;
									if( 0 != s_LoginInfo.ul_TrackID ){	// 部門と連動してログインしている場合.
										s_SessionInfo.trackId = LAPE_USR_SpTrackId_BoxAdmin;
										s_UpDataLoginInfo.ul_TrackID = TYPD_IndexTrackBoxAdmin;
									}else{
										s_SessionInfo.trackId = LAPD_USR_InvalidId;
										s_UpDataLoginInfo.ul_TrackID = 0;
									}
									break;
								default:
									break;
							}
							break;
						}
					}
					ui32_SessionID = s_ProfileInfo.ul_SessionID;				// セッションID.
					s_SessionInfo.authorityId = ss_AuthorityID;				// ユーザ識別ID.
					
					e_Result = AUT_Authentication.requestSessionUpdate( ui32_SessionID, s_SessionInfo );
					
					if( LAPE_ResultOK == e_Result ) {		// 認証結果変更成功時.
						if( False == pc_User->getRegistration() ){
							pc_User->setRegistration( True, TYPE_RegistrationTypeOnlyOne, JLGE_InspectLogIfOperationPanel, False, TYPE_Registration_State_ReNew, True, pc_User, ss_AuthorityID );
						}else{
							pc_User->setRegistration( True, TYPE_RegistrationTypeOnlyOne, JLGE_InspectLogIfOperationPanel, False, TYPE_Registration_State_New, True, pc_User, ss_AuthorityID );
						}
						PnlComSetAuthorityID( ss_AuthorityID );		// ユーザ識別IDの設定.
						PnlComSetUser( pc_User );					// 変更したユーザ情報を設定.
						PnlComSetTrack( pc_LocalTrack );
						PCGC_PanelMain::PnlMainProfileSwitch( s_ProfileInfo.ul_IndexNo, s_ProfileInfo.ul_SessionID );			// プロファイル情報反映.
						APIC_User::setLocalLoginInfo( sc_Cnt, s_UpDataLoginInfo );
					} else {		// 認証結果変更成功以外の時.
						bl_FailedCheck = True;		// 失敗検知フラグをTrueにする.
					}
				}
			}else{
				bl_FailedCheck = True;		// 失敗検知フラグをTrueにする.
			}
		}
	} else if( TYPD_PASM_ACTPARAMKIND_ERROR == pt_FromMngParam->ucActionParamKind ) {		// 動作情報種別がシーケンス異常終了の場合.
		bl_FailedCheck = True;		// 失敗検知フラグをTrueにする.
		APIC_PASM*	pc_ApicPasm = APIC_PASM::newInstance();
		Bool		bRet = False;
		if( 0 == pc_ApicPasm ) {
			printf("PnlComSetProcessTroubleInfo %d, pc_ApicPasm is NULL : %s(%d)\n", PNLD_TroubleDetailCode_PasmInstance_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//			PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_PasmInstance_Null );
			PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_PasmInstance_Null , __LINE__ );
			return True;
		}

		TYPS_AuthSeqCustomInstanceInfo* pt_InstanceInfo = pt_FromMngParam->st_actionParam.st_ParamEnd.pt_InstanceInfo;
		for( short sc_Cnt = 0; sc_Cnt < pt_FromMngParam->st_actionParam.st_ParamEnd.ucDataNum; sc_Cnt++, pt_InstanceInfo++ ){
			if (NULL == pt_InstanceInfo){
				break;	// データなし.
			}

			// 種別がユーザーインスタンスでインスタンスがNULLで無い場合はclearNewUser()を行う.
			if	(  ( TYPD_PASM_INSTANCE_USER	== pt_InstanceInfo->ucKind )
				&& ( NULL						!= pt_InstanceInfo->st_Instance.pc_User ) ){
				bRet = pc_ApicPasm->clearNewUser( pt_InstanceInfo->st_Instance.pc_User );
				if (False == bRet){
					SYSF_logMsg("APIC_PASM::clearNewUser is False");
				}
			}
		}
	} else {		// 動作種別が正常終了、異常終了以外の場合.
		printf("PnlComSetProcessTroubleInfo %d, pt_FromMngParam->ucActionParamKind is %d : %s(%d)\n", PNLD_TroubleDetailCode_Invalid_ActParamKind, pt_FromMngParam->ucActionParamKind, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Invalid_ActParamKind );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Invalid_ActParamKind , __LINE__ );
		return True;
	}

	if( True == bl_FailedCheck ){
		// プロファイルが生成されている場合、ログアウト処理を行う.
		PNLS_ProfileInfo s_ProfileInfo;
		PnlComSeqGetProfileInfo( &s_ProfileInfo );
		std::vector<LAPS_PRF_profile_info> tmp_prfList;
		LAPC_PRF_ProfileDataManager tmp_prfDatMgr( LAPC_BFW_System::newInstance() );
		tmp_prfList.clear();
		API_RESULT e_Result = tmp_prfDatMgr.getProfileList( &tmp_prfList );
		if ( e_Result == LAPE_ResultOK ){
			for( short sc_Cnt = 0; sc_Cnt < static_cast<int>( tmp_prfList.size() ); sc_Cnt++ ){
				ushort us_profile_index = tmp_prfList.at(sc_Cnt).profile_index;
				if ( us_profile_index == s_ProfileInfo.ul_IndexNo ){
					if( tmp_prfList.at(sc_Cnt).session_id == s_ProfileInfo.ul_SessionID ){
						// ログアウトを行う.
						PnlComInitUserAccountInfo( True );
						break;
					}
				}
			}
		}
		
		// 次画面の設定.
		PNLC_PopupListControl* pc_PopupListCtrl = PNLC_PopupListControl::newInstance();
		if( 0 == pc_PopupListCtrl ) {
			printf("PnlComSetProcessTroubleInfo %d, pc_PopupListCtrl is NULL : %s(%d)\n", PNLD_TroubleDetailCode_IllegalAddPopParam, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//			PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalAddPopParam );
			PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalAddPopParam , __LINE__ );
			return True;
		}
		if( False == onlyPanel.bl_isEnlargeDisplayMode ) { // 通常画面の場合.
			if( True == pc_PopupListCtrl->isPopupOpen() ) {
				// P.U表示中の場合はP.U変更.
				// ただし、P.UがWarning系の場合にP.U変更を行うとWarning画面が消えてしまうため変更しないようにする.
				ushort us_GamenWarningNo;
				us_GamenWarningNo = onlyPanel.isAllGamenWarning( onlyPanel.cc_DisplayJob );

				if( 0 == us_GamenWarningNo ) {
					pc_PopupListCtrl->setChangePopup(
						&gp_UserCertificate_warn_Custom_SeqCustom,
						NULL
					);
				}
			} else {
				// P.U非表示の場合はP.U追加.
				pc_PopupListCtrl->addPopup(
					&gp_UserCertificate_warn_Custom_SeqCustom,
					PBasicMessageProc::getNowGamen(),
					NULL
				);
			}
		} else { // 拡大画面の場合.
			pc_PopupListCtrl->addPopup( &gp_EnlWarn_UserCertificate_Custom_SeqCustom, PBasicMessageProc::getNowGamen(), 0 );
		}

	}
	// シーケンス管理処理をリセット.
	TYPE_PASM_RET e_Ret = PnlComSeqReset();
	if( e_Ret != TYPE_PASM_RET_SUCCESS ) {
		printf("PnlComSetProcessTroubleInfo %d, e_Ret is %d : %s(%d)\n", PNLD_TroubleDetailCode_PasmReset_Error, e_Ret, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_PasmReset_Error );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_PasmReset_Error , __LINE__ );
		return True;
	}

	return False;		// エラーなし.
}

// 概要 :認証カスタマイズ機能有効/無効値設定処理.
void PnlComSetSeqCustomValid( uchar uc_AuthSeqCustomValid )
{
	ucAuthSeqCustomLocalValid = uc_AuthSeqCustomValid;		// 認証カスタマイズ機能有効/無効値.
}

// 概要 :認証カスタマイズ機能有効/無効値取得処理.
void PnlComGetSeqCustomValid( uchar* puc_AuthSeqCustomValid )
{
	if( 0 == puc_AuthSeqCustomValid ) {	// NULLの場合.
		printf("PnlComSetProcessTroubleInfo %d, puc_AuthSeqCustomValid is NULL : %s(%d)\n", PNLD_TroubleDetailCode_Invalid_SeqCusValid, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Invalid_SeqCusValid );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Invalid_SeqCusValid , __LINE__ );
		return;
	}
	*puc_AuthSeqCustomValid = ucAuthSeqCustomLocalValid;		// 認証カスタマイズ機能有効/無効値.
}

// 概要 :必要な引き継ぎ情報をInParamに設定する.
short PnlComLocalSetInParam( TYPS_AuthSeqInParam* pt_ToMngParam, TYPS_AuthSeqOutParam* pt_FromMngParam, char c_DataKind, void* pv_Data, ushort us_Size )
{
	// パラメータチェック.
	if( 0 == pt_FromMngParam ) {	// 認証カスタマイズ動作の為のシーケンス情報がNULLだった場合.
		printf("PnlComSetProcessTroubleInfo %d, pt_FromMngParam is NULL : %s(%d)\n", PNLD_TroubleDetailCode_GetParam_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetParam_Null );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetParam_Null , __LINE__ );
		return TYPD_PnlComLocal_PARAMETER_ERROR;
	}

	if( 0 == pt_ToMngParam ) {	// 画面クラスのシーケンス情報がNULLだった場合.
		printf("PnlComSetProcessTroubleInfo %d, pt_ToMngParam is NULL : %s(%d)\n", PNLD_TroubleDetailCode_SetParam_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_SetParam_Null );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_SetParam_Null , __LINE__ );
		return TYPD_PnlComLocal_PARAMETER_ERROR;
	}

	if( 0 == pv_Data ) {			// 引き継ぎ情報に格納するデータのポインタがNULLだった場合.
		printf("PnlComSetProcessTroubleInfo %d, pv_Data is NULL : %s(%d)\n", PNLD_TroubleDetailCode_SetDataPointer_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_SetDataPointer_Null );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_SetDataPointer_Null , __LINE__ );
		return TYPD_PnlComLocal_PARAMETER_ERROR;
	}

	if( 0 == us_Size ) {			// 引き継ぎ情報に格納するデータのサイズが0だった場合.
		printf("PnlComSetProcessTroubleInfo %d, us_Size is NULL : %s(%d)\n", PNLD_TroubleDetailCode_Invalid_SetSize, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Invalid_SetSize );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Invalid_SetSize , __LINE__ );
		return TYPD_PnlComLocal_PARAMETER_ERROR;
	}
	
	// OutParamから「引き継ぎ情報の種類」を検索し、要素番号をarray_noに設定.
	ushort array_no = PnlComLocalGetArrayNo_OutParamTransType_ATMSetInfo( pt_FromMngParam, c_DataKind );		// 要素番号.
	
	if( array_no >= TYPD_PASM_ATMDATA_MAX ) {		// TYPD_PASM_ATMDATA_MAX以上の場合はInParamへの設定不要.
		printf("PnlComSetProcessTroubleInfo %d, array_no is %d : %s(%d)\n", PNLD_TroubleDetailCode_NotFound_GetParam, array_no, __FILE__, __LINE__ );
	} else {

		short sTransNumber_outparam = pt_FromMngParam->st_ATMSetInfo[ array_no ].TransNumber;		// 引き継ぎ番号.
		
		// InParamから「引き継ぎ情報の種類」を検索し、要素番号をarray_noに設定.
		array_no = PnlComLocalGetArrayNo_InParamTransType( pt_ToMngParam, c_DataKind );
		
		if( array_no >= TYPD_PASM_ATMDATA_MAX ) {		// TYPD_PASM_ATMDATA_MAX以上の場合.
			// 引き継ぎ情報が空の要素番号を検索.
			array_no = PnlComLocalGetArrayNo_InParamTransType( pt_ToMngParam, TYPD_PASM_ATMDATAKIND_NONE );
			
			if( array_no >= TYPD_PASM_ATMDATA_MAX ) {		// TYPD_PASM_ATMDATA_MAX以上の場合はレコードの空きなし.
				return TYPD_PnlComLocal_OTHER_ERROR;
			}
		}
		
		// パラメータ設定.
		pt_ToMngParam->st_SeqInfo.st_TransferData[ array_no ].cDataKind = c_DataKind;
		pt_ToMngParam->st_SeqInfo.st_TransferData[ array_no ].sTransNumber = sTransNumber_outparam;
		pt_ToMngParam->st_SeqInfo.st_TransferData[ array_no ].pvData = pv_Data;
		pt_ToMngParam->st_SeqInfo.st_TransferData[ array_no ].usSize = us_Size;
	}
	
	return TYPD_PnlComLocal_SUCCESS;
}

// 概要 :入力情報より認証カスタマイズ情報を取得して、共通領域に保存する.
void PnlComSeqGetAuthInfo( TYPS_AuthSeqInParam* pt_ToMngParam )
{
	// NULLチェック.
	if( 0 == pt_ToMngParam ) {
		printf("PnlComSetProcessTroubleInfo %d, pt_ToMngParam is NULL : %s(%d)\n", PNLD_TroubleDetailCode_SetParam_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_SetParam_Null );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_SetParam_Null , __LINE__ );
		return;
	}
	
	APIC_PASM* pc_ApicPasm = APIC_PASM::newInstance();
	if( 0 == pc_ApicPasm ) {
		printf("PnlComSetProcessTroubleInfo %d, pc_ApicPasm is NULL : %s(%d)\n", PNLD_TroubleDetailCode_PasmInstance_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_PasmInstance_Null );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_PasmInstance_Null , __LINE__ );
		return;
	}
	pc_ApicPasm->getSeqAuthInfo( pt_ToMngParam, &t_FromMngParam );		// 認証カスタマイズ情報取得.
}

// 概要 :認証カスタマイズ共通パラメータ初期化処理.
void PnlComLocalDataInitialize()
{
	// 各パラメータを初期化する.
	pc_LocalUser = 0;												// ユーザ認証結果(ユーザ情報).
	e_MmbCallBackLocalUserResult = TYPE_UserResultOtherError;			// ユーザ認証ログイン結果.
	pc_LocalTrack = 0;												// 部門認証結果(ユーザ情報).
	e_MmbCallBackLocalTrackResult = TYPE_TrackResultPasswordNG;			// 部門認証ログイン結果.
	e_MmbCallBackLocalUserResultConfirm = TYPE_UserResultOtherError;	// ユーザ登録確認結果(ユーザ情報).
	pc_LocalUserRegist = 0;											// ユーザ登録結果(ユーザ情報).
	e_MmbCallBackLocalUserRegistResult = TYPE_UserResultOtherError;		// ユーザ登録ログイン結果.
	static TYPS_ExtServerGetData	st_ExtServerDataInitialize	= {};
	c_LocalExtServerData	= st_ExtServerDataInitialize;
	sc_LocalDataResult1 = 0;											// ユーザ情報結果１(外部サーバーデータ取得の取得結果).
	memset( sc_LocalDataResult2, '\0', sizeof( sc_LocalDataResult2 ) );	// ユーザ情報結果２(取得情報別のデータ取得結果).
	memset( sc_LocalDataResult3, '\0', sizeof( sc_LocalDataResult3 ) );	// ユーザ情報結果３(機能制限項目別のデータ取得、及び解析結果).
	memset( &s_LocalProfileInfo, 0, sizeof(s_LocalProfileInfo) );		// プロファイル情報.
	e_LocalProfileSwitch = PNLE_ProfileSwitch_None;						// プロファイル生成種別.
}

// 概要 :認証カスタマイズ情報取得用の出力情報から、指定された引き継ぎ情報の種類が格納されている構造体の要素番号を取得.
ushort PnlComLocalGetArrayNo_OutParamTransType_ATMSetInfo( TYPS_AuthSeqOutParam* pt_FromMngParam, char c_DataKind )
{
	// 認証カスタマイズ動作のシーケンス情報(pt_FromMngParam)がNULLの場合.
	if( 0 == pt_FromMngParam ) {
		printf("PnlComSetProcessTroubleInfo %d, pt_FromMngParam is NULL : %s(%d)\n", PNLD_TroubleDetailCode_GetParam_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetParam_Null );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetParam_Null , __LINE__ );
		return TYPD_PASM_ATMDATA_MAX;
	}
	
	// 指定された引き継ぎ情報の種類を検索.
	ushort array_no = 0;
	for( array_no = 0; array_no < TYPD_PASM_ATMDATA_MAX; ++array_no ) {
		if( pt_FromMngParam->st_ATMSetInfo[array_no].DataKind == c_DataKind ) {
			break;		// 見つかった場合は繰り返し終了.
		}
	}
	
	return array_no;
}

