// 概要 :コールバック処理.
Bool PnlComSeqCallBack( TYPE_PNL_CallBack option )
{
	short s_ToMngParamResult = TYPD_PnlComLocal_OTHER_ERROR;
	Bool bl_SeqEventSetFlag = False;									// イベント通知設定済みフラグ.
	
	// シーケンス情報の取得.
	TYPS_AuthSeqInParam* pt_ToMngParam = 0;			// シーケンス情報.
	PnlComLocalSeqInDataGetCustom( &pt_ToMngParam );	// シーケンス情報取得.
	
	if( 0 == pt_ToMngParam ) {
		printf("PnlComSetProcessTroubleInfo %d, pt_ToMngParam is NULL : %s(%d)\n", PNLD_TroubleDetailCode_SetParam_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_SetParam_Null );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_SetParam_Null , __LINE__ );
		return bl_SeqEventSetFlag;
	}
	
	// 認証カスタマイズ情報の取得.
	TYPS_AuthSeqOutParam* pt_FromMngParam = 0;			// カスタマイズ情報.
	PnlComLocalSeqOutDataGetCustom( &pt_FromMngParam );		// カスタマイズ情報取得.
	
	if( 0 == pt_FromMngParam ) {
		printf("PnlComSetProcessTroubleInfo %d, pt_FromMngParam is NULL : %s(%d)\n", PNLD_TroubleDetailCode_GetParam_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetParam_Null );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetParam_Null , __LINE__ );
		return bl_SeqEventSetFlag;
	}

	static TYPE_UserResult e_LocalUserResult = TYPE_UserResultPasswordNG;	// ユーザー処理結果.
	static APIC_User* pc_User = 0;
	static TYPE_TrackResult e_LocalTrackResult = TYPE_TrackResultPasswordNG;	// 部門処理結果.
	static APIC_Track* pc_Track = 0;	// 部門認証インスタンス.
	static TYPS_ExtServerGetData* ps_ExtServerGetData = 0;		// ユーザ情報.
	static TYPE_ExtServerDataGetResult	sc_GetResult1 = 0;		// ユーザ情報結果１(外部サーバーデータ取得の取得結果).
	static TYPE_ExtServerDataGetResult*	psc_GetResult2 = 0;		// ユーザ情報結果２(取得情報別のデータ取得結果).
	static TYPE_ExtServerDataGetResult*	psc_GetResult3 = 0;		// ユーザ情報結果３(データ取得した機能制限情報における機能制限可能な機能制限項目別のデータ取得、及び解析結果).

	// コールバックイベント種別の値により処理を分岐する.
	switch( option ){
		case TYPE_PNL_CallBack_ExcludedWait_act_SeqCustom:		// 排他制御中の場合.
		{
			// 次画面の設定.
			if( False == onlyPanel.bl_isEnlargeDisplayMode ) { // 通常画面の場合.
				PNLC_PopupListControl* pc_PopupListCtrl = PNLC_PopupListControl::newInstance();
				if( 0 == pc_PopupListCtrl ) {
					printf("PnlComSetProcessTroubleInfo %d, pc_PopupListCtrl is NULL : %s(%d)\n", PNLD_TroubleDetailCode_IllegalAddPopParam, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//					PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalAddPopParam );
					PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalAddPopParam , __LINE__ );
					return bl_SeqEventSetFlag;
				}
				if( True == pc_PopupListCtrl->isPopupOpen() ) {
					// P.U表示中の場合はP.U変更.
					// ただし、P.UがWarning系の場合にP.U変更を行うとWarning画面が消えてしまうため変更しないようにする.
					ushort us_GamenWarningNo;
					us_GamenWarningNo = onlyPanel.isAllGamenWarning( onlyPanel.cc_DisplayJob );

					if( 0 == us_GamenWarningNo ) {
						pc_PopupListCtrl->setChangePopup(
							&gp_ExcludedWait_act_SeqCustom,
							NULL
						);
					}
				} else {
					// P.U非表示の場合はP.U追加.
					pc_PopupListCtrl->addPopup(
						&gp_ExcludedWait_act_SeqCustom,
						PBasicMessageProc::getNowGamen(),
						NULL
					);
				}
			} else { // 拡大画面の場合.
				PBasicMessageProc::setNextGamen( &gp_EnlAct_ExcludedWait_SeqCustom );		// 「しばらくお待ちください」画面.
			}
			break;
		}
		case TYPE_PNL_CallBack_UserAccount_act_SeqCustom:		// ユーザー認証の場合.
		{
			// ユーザー認証結果の取得.
			PnlComGetLocalUser( &e_LocalUserResult, &pc_User );
			
			if( (TYPE_UserResultOk == e_LocalUserResult) && (0 == pc_User) ) {	// 認証結果がOK且つユーザーオブジェクトがNULLの場合.
				printf("PnlComSetProcessTroubleInfo %d, e_LocalUserResult is TYPE_UserResultOk and pc_User is NULL : %s(%d)\n", PNLD_TroubleDetailCode_Invalid_UserIns, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Invalid_UserIns );
				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Invalid_UserIns , __LINE__ );
				return bl_SeqEventSetFlag;
			}
			
			// t_FromMngParam から認証結果を取得して t_ToMngParam に設定する.
			s_ToMngParamResult = PnlComLocalSetInParam( &t_ToMngParam, &t_FromMngParam, TYPD_PASM_ATMDATAKIND_RES, (void*)&e_LocalUserResult, sizeof( TYPE_UserResult ) );
			
			if( TYPD_PnlComLocal_SUCCESS != s_ToMngParamResult ) {	// 成功以外の場合.
				printf("PnlComSetProcessTroubleInfo %d, s_ToMngParamResult is %d : %s(%d)\n", PNLD_TroubleDetailCode_Failed_SetInParam, s_ToMngParamResult, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam );
				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam , __LINE__ );
				return bl_SeqEventSetFlag;
			}
			
			if( 0 != pc_User ) {
				// 装置認証を考慮し、ユーザーインスタンスのユーザー名とパスワードを引継ぎ情報に設定する.
				static char sc_UserNameTmp[PCGD_UserNameUTF8_193];
				static char sc_UserPassTmp[PCGD_UserPasswordUTF8];
				char sc_LoginServerNameTmp[APID_MaxLengthOfServerName + 1];
				Bool b_UseServer = False;	// True = 外部サーバー：False = 本体認証.
				memset( sc_UserNameTmp, '\0', sizeof(sc_UserNameTmp) );
				memset( sc_UserPassTmp, '\0', sizeof(sc_UserPassTmp) );
				memset( sc_LoginServerNameTmp, '\0', sizeof(sc_LoginServerNameTmp) );
				pc_User->getUserNameUTF8( sc_UserNameTmp, TYPE_CharSetUTF8 );
				pc_User->getLoginServerName( sc_LoginServerNameTmp );
				if( 0 != strlen( sc_LoginServerNameTmp ) ) {
					// 文字列が存在する場合は外部サーバーと判定する.
					b_UseServer = True;

					// DA-518対応.
					// LDAP-ICカード認証で認証OKが返った場合は本体パスワードを取得する.
					// 認証OK（パスワードなし）が返った場合は外部サーバーパスワードを取得する.
					// LDAP-ICカード認証かどうかを判定.
					APIC_AuthenticationSeverSetting* apicAuth = APIC_AuthenticationSeverSetting::newInstance();
					if( NULL != apicAuth )
					{
						if( ( True == apicAuth->getAuthCardSearch(PNLC_NetworkLan::getInstance()->getLine()) ) &&				// 認証カード検索機能がONの時.
							( True == onlyPanel.b_AuthenticationCardSearch ) &&			// 認証カード検索でユーザー認証したかどうか.
							( TYPE_UserResultOk == e_LocalUserResult ) )				// 認証結果がOK.
						{
							// 本体パスワードを取得する.
							b_UseServer = False;
						}
					}
					else
					{
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//						PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam );
						PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam , __LINE__ );
						return bl_SeqEventSetFlag;
					}
				}
				pc_User->getUserPassword( sc_UserPassTmp, b_UseServer );
	
				// ユーザーインスタンスのユーザー名.
				s_ToMngParamResult = PnlComLocalSetInParam( &t_ToMngParam, &t_FromMngParam, TYPD_PASM_ATMDATAKIND_USRINSTANCE_NAME, (void*)sc_UserNameTmp, PCGD_UserNameUTF8_193 );
				if( TYPD_PnlComLocal_SUCCESS != s_ToMngParamResult ) {	// 成功以外の場合.
					printf("PnlComSetProcessTroubleInfo %d, s_ToMngParamResult is %d : %s(%d)\n", PNLD_TroubleDetailCode_Failed_SetInParam, s_ToMngParamResult, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//					PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam );
					PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam , __LINE__ );
					return bl_SeqEventSetFlag;
				}
				// ユーザーインスタンスのパスワード.
				s_ToMngParamResult = PnlComLocalSetInParam( &t_ToMngParam, &t_FromMngParam, TYPD_PASM_ATMDATAKIND_USRINSTANCE_PASS, (void*)sc_UserPassTmp, PCGD_UserPasswordUTF8 );
				if( TYPD_PnlComLocal_SUCCESS != s_ToMngParamResult ) {	// 成功以外の場合.
					printf("PnlComSetProcessTroubleInfo %d, s_ToMngParamResult is %d : %s(%d)\n", PNLD_TroubleDetailCode_Failed_SetInParam, s_ToMngParamResult, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//					PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam );
			PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam , __LINE__ );
					return bl_SeqEventSetFlag;
				}
				// t_FromMngParam からユーザーインスタンスを取得して t_ToMngParam に設定する.
				s_ToMngParamResult = PnlComLocalSetInParam( &t_ToMngParam, &t_FromMngParam, TYPD_PASM_ATMDATAKIND_INS_USR, (void*)&pc_User, sizeof( APIC_User* ) );
				
				if( TYPD_PnlComLocal_SUCCESS != s_ToMngParamResult ) {	// 成功以外の場合.
					printf("PnlComSetProcessTroubleInfo %d, s_ToMngParamResult is %d : %s(%d)\n", PNLD_TroubleDetailCode_Failed_SetInParam, s_ToMngParamResult, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//					PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam );
					PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam , __LINE__ );
					return bl_SeqEventSetFlag;
				}
			
				// 動作結果構造体にデータを設定する.
				pt_ToMngParam->st_SeqInfo.st_ResultData.st_UserData.pc_User = pc_User;	// ユーザーインスタンス.
			}
			
			switch( e_LocalUserResult ){
				case TYPE_UserResultOk:					// OK.
				case TYPE_UserResultOk_PasswordUnReg:	// 認証OK(パスワード未登録).
					e_LocalWarningName = TYPE_WarningName_Non;
					break;
				case TYPE_UserResultPenalty:			// 指定チェック回数以上の認証失敗でペナルティ.
					e_LocalWarningName = PNL_ERROR_UserCertificatePenalty;
					break;
				case TYPE_UserResultServerBusy:			// 外部認証エラーコード：サーバービジー.
					e_LocalWarningName = PNL_ERROR_UserCertificateServerBusy;
					break;
				case TYPE_UserResultDataFull:			// 外部認証エラーコード：ユーザー情報登録不可.
					e_LocalWarningName = PNL_ERROR_UserCertificateUserFull;
					break;
				default:
					e_LocalWarningName = PNL_ERROR_UserCertificate;
					break;
			}

			// イベント情報に認証結果を設定.
			pt_ToMngParam->scEvent = e_LocalUserResult;
			
			// 動作結果種別に 動作情報種別：ユーザー認証/動作結果種別：ユーザー認証 を設定.
			pt_ToMngParam->st_SeqInfo.ucResultKind = TYPD_PASM_ACTPARAMKIND_AUTHUSER;
			
			// カスタマイズON.
			bl_SeqEventSetFlag = True;
			break;
		}
		case TYPE_PNL_CallBack_UserAccountTrack_act_SeqCustom:		// 部門認証の場合.
		{
			// 部門認証結果の取得.
			PnlComGetLocalTrack( &e_LocalTrackResult, &pc_Track );
			
			if( (TYPE_TrackResultOk == e_LocalTrackResult) && (0 == pc_Track) ) {	// 認証結果がOK且つ部門オブジェクトがNULLの場合.
				printf("PnlComSetProcessTroubleInfo %d, e_LocalTrackResult is TYPE_TrackResultOk and pc_Track is NULL : %s(%d)\n", PNLD_TroubleDetailCode_Invalid_TrackIns, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Invalid_TrackIns );
				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Invalid_TrackIns , __LINE__ );
				return bl_SeqEventSetFlag;
			}
			// t_FromMngParam から認証結果を取得して t_ToMngParam に設定する.
			s_ToMngParamResult = PnlComLocalSetInParam( &t_ToMngParam, &t_FromMngParam, TYPD_PASM_ATMDATAKIND_RES, (void*)&e_LocalTrackResult, sizeof( TYPE_TrackResult ) );
			
			if( TYPD_PnlComLocal_SUCCESS != s_ToMngParamResult ) {	// 成功以外の場合.
				printf("PnlComSetProcessTroubleInfo %d, s_ToMngParamResult is %d : %s(%d)\n", PNLD_TroubleDetailCode_Failed_SetInParam, s_ToMngParamResult, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam );
				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam , __LINE__ );
				return bl_SeqEventSetFlag;
			}
			
			if( 0 != pc_Track ) {
				// t_FromMngParam から部門インスタンスを取得して t_ToMngParam に設定する.
				s_ToMngParamResult = PnlComLocalSetInParam( &t_ToMngParam, &t_FromMngParam, TYPD_PASM_ATMDATAKIND_INS_TRK, (void*)&pc_Track, sizeof( APIC_Track* ) );
				
				if( TYPD_PnlComLocal_SUCCESS != s_ToMngParamResult ) {	// 成功以外の場合.
					printf("PnlComSetProcessTroubleInfo %d, s_ToMngParamResult is %d : %s(%d)\n", PNLD_TroubleDetailCode_Failed_SetInParam, s_ToMngParamResult, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//					PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam );
					PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam , __LINE__ );
					return bl_SeqEventSetFlag;
				}
			
				// 動作結果構造体にデータを設定する.
				pt_ToMngParam->st_SeqInfo.st_ResultData.st_TrackData.pc_Track = pc_Track;	// 部門インスタンス.
			}
			
			switch( e_LocalTrackResult ){
				case TYPE_TrackResultOk:
					e_LocalWarningName = TYPE_WarningName_Non;
					break;
				case TYPE_TrackResultPenalty:
					e_LocalWarningName = PNL_ERROR_UserCertificatePenalty;
					break;
				default:
					e_LocalWarningName = PNL_ERROR_UserCertificate;
					break;
			}

			// イベント情報に認証結果を設定.
			pt_ToMngParam->scEvent = e_LocalTrackResult;
			
			// 動作結果種別に 本体部門認証/動作結果種別：本体部門認証 を設定.
			pt_ToMngParam->st_SeqInfo.ucResultKind = TYPD_PASM_ACTPARAMKIND_AUTHTRACK;
			
			// カスタマイズON.
			bl_SeqEventSetFlag = True;
			break;
		}
		case TYPE_PNL_CallBack_RegisterConfirm_act_SeqCustom:		// ユーザ登録確認の場合.
		{
			// ユーザ登録確認結果の取得.
			PnlComGetLocalUserRegistConfirm( &e_LocalUserResult );
			
			// t_FromMngParam から認証結果を取得して t_ToMngParam に設定する.
			s_ToMngParamResult = PnlComLocalSetInParam( &t_ToMngParam, &t_FromMngParam, TYPD_PASM_ATMDATAKIND_RES, (void*)&e_LocalUserResult, sizeof( TYPE_UserResult ) );
			
			if( TYPD_PnlComLocal_SUCCESS != s_ToMngParamResult ) {	// 成功以外の場合.
				printf("PnlComSetProcessTroubleInfo %d, s_ToMngParamResult is %d : %s(%d)\n", PNLD_TroubleDetailCode_Failed_SetInParam, s_ToMngParamResult, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam );
				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam , __LINE__ );
				return bl_SeqEventSetFlag;
			}

			switch( e_LocalUserResult ){
				case TYPE_UserResultOk:					// OK.
				case TYPE_UserResultOk_PasswordUnReg:	// 認証OK(パスワード未登録).
					e_LocalWarningName = TYPE_WarningName_Non;
					break;
				case TYPE_UserResultPenalty:			// 指定チェック回数以上の認証失敗でペナルティ.
					e_LocalWarningName = PNL_ERROR_UserCertificatePenalty;
					break;
				case TYPE_UserResultServerBusy:			// 外部認証エラーコード：サーバービジー.
					e_LocalWarningName = PNL_ERROR_UserCertificateServerBusy;
					break;
				case TYPE_UserResultDataFull:			// 外部認証エラーコード：ユーザー情報登録不可.
					e_LocalWarningName = PNL_ERROR_UserCertificateUserFull;
					break;
				default:
					e_LocalWarningName = PNL_ERROR_UserCertificate;
					break;
			}
			
			// イベント情報に認証結果を設定.
			pt_ToMngParam->scEvent = e_LocalUserResult;
			
			// 動作結果種別に 動作情報種別：ユーザー情報登録確認 を設定.
			pt_ToMngParam->st_SeqInfo.ucResultKind = TYPD_PASM_ACTPARAMKIND_USERREGISTCONFIRM;
			
			// カスタマイズON.
			bl_SeqEventSetFlag = True;
			break;
		}
		case TYPE_PNL_CallBack_UserAutoRegist_act_SeqCustom:		// ユーザ登録の場合.
		{
			// ユーザー登録結果の取得.
			PnlComGetLocalUserRegist( &e_LocalUserResult, &pc_User );
			
			// t_FromMngParam から認証結果を取得して t_ToMngParam に設定する.
			s_ToMngParamResult = PnlComLocalSetInParam( &t_ToMngParam, &t_FromMngParam, TYPD_PASM_ATMDATAKIND_RES, (void*)&e_LocalUserResult, sizeof( TYPE_UserResult ) );
			
			if( TYPD_PnlComLocal_SUCCESS != s_ToMngParamResult ) {	// 成功以外の場合.
				printf("PnlComSetProcessTroubleInfo %d, s_ToMngParamResult is %d : %s(%d)\n", PNLD_TroubleDetailCode_Failed_SetInParam, s_ToMngParamResult, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam );
				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam , __LINE__ );
				return bl_SeqEventSetFlag;
			}
			
			if( 0 != pc_User ) {
				// t_FromMngParam からユーザーインスタンスを取得して t_ToMngParam に設定する.
				s_ToMngParamResult = PnlComLocalSetInParam( &t_ToMngParam, &t_FromMngParam, TYPD_PASM_ATMDATAKIND_INS_USR, (void*)&pc_User, sizeof( APIC_User* ) );
				
				if( TYPD_PnlComLocal_SUCCESS != s_ToMngParamResult ) {	// 成功以外の場合.
					printf("PnlComSetProcessTroubleInfo %d, s_ToMngParamResult is %d : %s(%d)\n", PNLD_TroubleDetailCode_Failed_SetInParam, s_ToMngParamResult, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//					PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam );
					PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam , __LINE__ );
					return bl_SeqEventSetFlag;
				}
			}

			switch( e_LocalUserResult ){
				case TYPE_UserResultOk:					// OK.
				case TYPE_UserResultOk_PasswordUnReg:	// 認証OK(パスワード未登録).
					e_LocalWarningName = TYPE_WarningName_Non;
					break;
				case TYPE_UserResultPenalty:			// 指定チェック回数以上の認証失敗でペナルティ.
					e_LocalWarningName = PNL_ERROR_UserCertificatePenalty;
					break;
				case TYPE_UserResultServerBusy:			// 外部認証エラーコード：サーバービジー.
					e_LocalWarningName = PNL_ERROR_UserCertificateServerBusy;
					break;
				case TYPE_UserResultDataFull:			// 外部認証エラーコード：ユーザー情報登録不可.
					e_LocalWarningName = PNL_ERROR_UserCertificateUserFull;
					break;
				default:
					e_LocalWarningName = PNL_ERROR_UserCertificate;
					break;
			}

			// イベント情報に認証結果を設定.
			pt_ToMngParam->scEvent = e_LocalUserResult;
			
			// 動作結果種別に 動作情報種別：ユーザー登録 を設定.
			pt_ToMngParam->st_SeqInfo.ucResultKind = TYPD_PASM_ACTPARAMKIND_REGISTUSER;
			
			// カスタマイズON.
			bl_SeqEventSetFlag = True;
			break;
		}
		case TYPE_PNL_CallBack_ExtServerDataGet_act_SeqCustom:		// ユーザー情報取得の場合.
		{
			// ユーザー情報取得結果を取得.
			PnlComReqExtLocalServerDataGet( &ps_ExtServerGetData, &sc_GetResult1, &psc_GetResult2, &psc_GetResult3 );
			
			// t_FromMngParam からユーザー情報を取得して t_ToMngParam に設定する.
			s_ToMngParamResult = PnlComLocalSetInParam( &t_ToMngParam, &t_FromMngParam, TYPD_PASM_ATMDATAKIND_SRV_DATA, (void*)ps_ExtServerGetData, sizeof( TYPS_ExtServerGetData ) );
			
			if( TYPD_PnlComLocal_SUCCESS != s_ToMngParamResult ) {	// 成功以外の場合.
				printf("PnlComSetProcessTroubleInfo %d, s_ToMngParamResult is %d : %s(%d)\n", PNLD_TroubleDetailCode_Failed_SetInParam, s_ToMngParamResult, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam );
				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam , __LINE__ );
				return bl_SeqEventSetFlag;
			}
			
			// t_FromMngParam からユーザ情報結果１(外部サーバーデータ取得の取得結果)を取得して t_ToMngParam に設定する.
			s_ToMngParamResult = PnlComLocalSetInParam( &t_ToMngParam, &t_FromMngParam, TYPD_PASM_ATMDATAKIND_RES, (void*)&sc_GetResult1, sizeof( sc_GetResult1 ) );
			
			if( TYPD_PnlComLocal_SUCCESS != s_ToMngParamResult ) {	// 成功以外の場合.
				printf("PnlComSetProcessTroubleInfo %d, s_ToMngParamResult is %d : %s(%d)\n", PNLD_TroubleDetailCode_Failed_SetInParam, s_ToMngParamResult, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam );
				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam , __LINE__ );
				return bl_SeqEventSetFlag;
			}
			
			// t_FromMngParam からユーザ情報結果２(取得情報別のデータ取得結果)を取得して t_ToMngParam に設定する.
			s_ToMngParamResult = PnlComLocalSetInParam( &t_ToMngParam, &t_FromMngParam, TYPD_PASM_ATMDATAKIND_SRV_DATA_RES, (void*)psc_GetResult2, sizeof( TYPE_ExtServerDataGetResult ) * APID_GetInfoMaxNum );
			
			if( TYPD_PnlComLocal_SUCCESS != s_ToMngParamResult ) {	// 成功以外の場合.
				printf("PnlComSetProcessTroubleInfo %d, s_ToMngParamResult is %d : %s(%d)\n", PNLD_TroubleDetailCode_Failed_SetInParam, s_ToMngParamResult, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam );
				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam , __LINE__ );
				return bl_SeqEventSetFlag;
			}
			
			// t_FromMngParam からユーザ情報結果３(データ取得した機能制限情報における機能制限可能な機能制限項目別のデータ取得、及び解析結果)を取得して t_ToMngParam に設定する.
			s_ToMngParamResult = PnlComLocalSetInParam( &t_ToMngParam, &t_FromMngParam, TYPD_PASM_ATMDATAKIND_SRV_DATA_FUNC_RES, (void*)psc_GetResult3, sizeof( TYPE_ExtServerDataGetResult ) * APID_FuncLimitInfoMaxNum );
			
			if( TYPD_PnlComLocal_SUCCESS != s_ToMngParamResult ) {	// 成功以外の場合.
				printf("PnlComSetProcessTroubleInfo %d, s_ToMngParamResult is %d : %s(%d)\n", PNLD_TroubleDetailCode_Failed_SetInParam, s_ToMngParamResult, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam );
				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_Failed_SetInParam , __LINE__ );
				return bl_SeqEventSetFlag;
			}
			
			// 動作結果構造体にデータを設定する.
			pt_ToMngParam->st_SeqInfo.st_ResultData.st_GetData.st_GetData = *ps_ExtServerGetData;						// ユーザ情報(データ取得先サーバから取得したデータ).
			pt_ToMngParam->st_SeqInfo.st_ResultData.st_GetData.e_Result = sc_GetResult1;								// ユーザ情報結果１(外部サーバーデータ取得の取得結果).
			memcpy( pt_ToMngParam->st_SeqInfo.st_ResultData.st_GetData.e_GetDataResult, psc_GetResult2, sizeof( TYPE_ExtServerDataGetResult ) * APID_GetInfoMaxNum ); 					// ユーザ情報結果２(取得情報別のデータ取得結果).
			memcpy( pt_ToMngParam->st_SeqInfo.st_ResultData.st_GetData.e_GetDataResultFunctionMask, psc_GetResult3, sizeof( TYPE_ExtServerDataGetResult ) * APID_FuncLimitInfoMaxNum ); // ユーザ情報結果３(機能制限項目別のデータ取得、及び解析結果).
			
			// イベント情報に認証結果を設定.
			pt_ToMngParam->scEvent = sc_GetResult1;
			
			// 動作結果種別に 動作情報種別：ユーザー情報取得/動作結果種別：ユーザー情報取得 を設定.
			pt_ToMngParam->st_SeqInfo.ucResultKind = TYPD_PASM_ACTPARAMKIND_GETUSERINFO;
			
			// カスタマイズON.
			bl_SeqEventSetFlag = True;
			break;
		}
		default:
			break;
	}
	
	return bl_SeqEventSetFlag;	
}

