// 概要 :サーバーインデックスによりイベント種別を細分化する.
char PnlComChangeAuthenticationEvent( char scSelSrvIndex, TYPD_PASM_EVENT_TYPE scEvent ){

	char scRetEvent = TYPD_PASM_EVENT_DISP_ENTRY_EXTERNAL;

	TYPE_UserAuthentication		e_Auth	= PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine());
	if ( ( TYPE_UserAuthenticationDevice == e_Auth ) || ( TYPE_UserAuthenticationDeviceAndMidAuth == e_Auth ) ) {
		// 本体認証、本体装置+拡張サーバー認証の場合.
		switch( scEvent ){
		case TYPD_PASM_EVENT_TYPE_ENTRY:			scRetEvent = TYPD_PASM_EVENT_DISP_ENTRY_INTERNAL;				break;
		case TYPD_PASM_EVENT_TYPE_LOGIN:			scRetEvent = TYPD_PASM_EVENT_DISP_LOGIN_INTERNAL;				break;
		case TYPD_PASM_EVENT_TYPE_IDKEY:			scRetEvent = TYPD_PASM_EVENT_DISP_IDKEY_INTERNAL;				break;
		case TYPD_PASM_EVENT_TYPE_REGIST_AND_LOGIN:	scRetEvent = TYPD_PASM_EVENT_DISP_REGIST_AND_LOGIN_INTERNAL;	break;
		case TYPD_PASM_EVENT_TYPE_CARD_SUCCESS:		scRetEvent = TYPD_PASM_EVENT_AUTH_SUCCESS_INTERNAL;				break;
		default: break;
		}
	} else {
		if( ( scSelSrvIndex >  APID_AuthenticationServerIndexNone        ) &&
			( scSelSrvIndex <= APID_AuthenticationSeverTypeIccLDAPSecond ) ){
			// 外部サーバー認証の場合.
			switch( scEvent ){
			case TYPD_PASM_EVENT_TYPE_ENTRY:			scRetEvent = TYPD_PASM_EVENT_DISP_ENTRY_EXTERNAL;				break;
			case TYPD_PASM_EVENT_TYPE_LOGIN:			scRetEvent = TYPD_PASM_EVENT_DISP_LOGIN_EXTERNAL;				break;
			case TYPD_PASM_EVENT_TYPE_IDKEY:			scRetEvent = TYPD_PASM_EVENT_DISP_IDKEY_EXTERNAL;				break;
			case TYPD_PASM_EVENT_TYPE_REGIST_AND_LOGIN:	scRetEvent = TYPD_PASM_EVENT_DISP_REGIST_AND_LOGIN_EXTERNAL;	break;
			case TYPD_PASM_EVENT_TYPE_CARD_SUCCESS:		scRetEvent = TYPD_PASM_EVENT_AUTH_SUCCESS_EXTERNAL;				break;
			default: break;
			}
		} else if( scSelSrvIndex == APID_DeviceAuthenticationIndex ) {
			// 本体＋外部サーバー認証時の本体認証の場合.
			switch( scEvent ){
			case TYPD_PASM_EVENT_TYPE_ENTRY:			scRetEvent = TYPD_PASM_EVENT_DISP_ENTRY_INT_EXT;				break;
			case TYPD_PASM_EVENT_TYPE_LOGIN:			scRetEvent = TYPD_PASM_EVENT_DISP_LOGIN_INT_EXT;				break;
			case TYPD_PASM_EVENT_TYPE_IDKEY:			scRetEvent = TYPD_PASM_EVENT_DISP_IDKEY_INT_EXT;				break;
			case TYPD_PASM_EVENT_TYPE_REGIST_AND_LOGIN:	scRetEvent = TYPD_PASM_EVENT_DISP_REGIST_AND_LOGIN_INT_EXT;		break;
			case TYPD_PASM_EVENT_TYPE_CARD_SUCCESS:		scRetEvent = TYPD_PASM_EVENT_AUTH_SUCCESS_INT_EXT;				break;
			default: break;
			}
		}
	}
	return scRetEvent;
}
	
