{
	e_LocalStatus = e_Status;
}

// 概要 :認証シーケンス管理状態取得.
PNLE_SeqCustom_Status PnlComSeqGetStatus()
{
	return e_LocalStatus;
}

// 概要 :認証シーケンス管理のリセット.
TYPE_PASM_RET PnlComSeqReset()
{
	TYPE_PASM_RET e_Ret = TYPE_PASM_RET_ERROR_FAIL;
	APIC_PASM* pc_ApicPasm = APIC_PASM::newInstance();
	if( 0 == pc_ApicPasm ) {
		printf("PnlComSetProcessTroubleInfo %d, pc_ApicPasm is NULL : %s(%d)\n", PNLD_TroubleDetailCode_PasmInstance_Null, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_PasmInstance_Null );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_PasmInstance_Null , __LINE__ );
		return e_Ret;
	}
	// ユーザ認証ユーザ登録確認画面からのキャンセルは検知したカード情報をリセットする.
	TYPE_AUTH_DEVICE_TYPE e_DeviceType = PnlComGetAuthDeviceSetting()->getAuthDeviceType();
	if( TYPE_AuthDeviceType_None != e_DeviceType ){
		// デバイスが接続されている場合.
		if( True == PnlCom_IsEnableAutoLogoutLogin() ){
			// 自動ログインログアウト機能が有効な場合.
			if( False == PnlComGetAuthPollingStatusStop() ){
				// カード検知しているが認証が開始されていないため意図的にここで中断状態とする.
				PnlComSetAuthPollingStatusStop();
			}
			PnlComReqAuthPollingRestart();
		}else{
			// それ以外の場合.
			PnlComReqAuthPollingTerminate();
			PnlComReqAuthPollingStart();
		}
	}else{
		// デバイスが接続されていない場合は何も処理しない.
	}
	PnlComSeqSetStatus( PNLE_SeqCustom_Status_Top );			// ステータス更新.
	// 認証シーケンスカスタマイズ用のユーザーインスタンス保持領域をクリア.
	PnlComSetLocalUser( TYPE_UserResultOtherError, NULL );
	return pc_ApicPasm->reset();
}


