// comment 2015/04/02 OPS1-Sky浜野 [ZeusS][CQ510790] 実行結果が表示されない不具合対応.
/**
 *	@brief	HDDミラーリング リビルド状態取得.
 *	@param	無し.
 *	@retval	TYPE_MirroringHddStatus.
 */
TYPE_MirroringHddStatus PnlComGetHddRebuildStatus()
{
	TYPE_MirroringHddStatus e_HddStatus = TYPE_MirroringHddStatus_Normal;
	
	APIC_HddInfo* pc_HddInfo = PnlComGetHddInfo();
	if( NULL != pc_HddInfo ) {
		if(( True == pc_HddInfo->getMirroringHddDevice( TYPE_HddChanelNo_Chanel_A ) )
		&& ( True == pc_HddInfo->getMirroringHddDevice( TYPE_HddChanelNo_Chanel_B ) )) {
			//HDD(A)の動作状況の取得.
			TYPE_MirroringHddStatus e_MirroringHddStatusA = pc_HddInfo->getMirroringHddStatus( TYPE_HddChanelNo_Chanel_A );
			TYPE_MirroringHddStatus e_MirroringHddStatusB = pc_HddInfo->getMirroringHddStatus( TYPE_HddChanelNo_Chanel_B );
			
			// HDD_A、HDD_Bのどちらかがリビルド中の場合.
			if(	( TYPE_MirroringHddStatus_Rebuild == e_MirroringHddStatusA )
			||	( TYPE_MirroringHddStatus_Rebuild == e_MirroringHddStatusB ) ) {
				e_HddStatus = TYPE_MirroringHddStatus_Rebuild;		// リビルド中.
			}
		}
	}
	
	return e_HddStatus;
}

// 概要 :認証シーケンストップ画面への遷移.
Bool PnlComSeqTransTopGamen()
{
	TYPS_AuthSeqInParam t_SetSeqParam = {0};
	TYPS_AuthSeqOutParam *t_GetSeqParam = NULL;

	APIC_PASM*	pc_Pasm	= APIC_PASM::newInstance();
	if ( 0 == pc_Pasm ) {
		return( False );
	}
	PnlComLocalSeqOutDataGetCustom( &t_GetSeqParam );

	t_SetSeqParam.scEvent	= TYPD_PASM_EVENT_TOP;

	TYPE_PASM_RET	e_Ret	= pc_Pasm->getSeqAuthInfo( &t_SetSeqParam, t_GetSeqParam );
	if ( TYPE_PASM_RET_SUCCESS != e_Ret ) {
		printf("PnlComSetProcessTroubleInfo %d, e_Ret is %d : %s(%d)\n", PNLD_TroubleDetailCode_GetSeqAuthInfoError, e_Ret, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetSeqAuthInfoError );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetSeqAuthInfoError , __LINE__ );
		return( False );
	}

	// MFPの初期表示とMFPの現在の拡大状態が不一致の場合、認証トップで拡大キーが押下されたものを表示する必要がある.
	// 認証トップの画面取得後、拡大キーイベントで問い合わせ拡大キー押下された場合に表示される画面を取得し表示させる.
// comment 2018/08/24 SCD2-4G東島 [Sparrow][1051906].
//	Bool	bl_InitEnlarge	= PnlComGetOperationSetting()->getLargeDisplayInitDispSetting();
	Bool	bl_InitEnlarge	= PnlComIsLargeDisplayInitDisp();
	if ( ( ( True == bl_InitEnlarge ) && ( False == onlyPanel.bl_isEnlargeDisplayMode ) )
		|| ( ( False == bl_InitEnlarge ) && ( True == onlyPanel.bl_isEnlargeDisplayMode ) )
	) {
		t_SetSeqParam.scEvent	= TYPD_PASM_EVENT_DISP_ENLARGEMENTKEY;
		e_Ret	= pc_Pasm->getSeqAuthInfo( &t_SetSeqParam, t_GetSeqParam );
		if ( TYPE_PASM_RET_SUCCESS != e_Ret ) {
			printf("PnlComSetProcessTroubleInfo %d, e_Ret is %d : %s(%d)\n", PNLD_TroubleDetailCode_GetSeqAuthInfoError, e_Ret, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//			PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetSeqAuthInfoError );
			PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetSeqAuthInfoError , __LINE__ );
			return( False );
		}

		// 拡大キーイベントに対する処理種別が画面遷移以外の場合、コンフィグには拡大キーイベントに対する処理がないと判断.
		// 認証トップ画面を表示させるため、再度マネージャリセット→認証トップ画面取得を行なう.
		if ( TYPD_PASM_ACTPARAMKIND_SCRTRANS != t_GetSeqParam->ucActionParamKind ) {
			pc_Pasm->reset();

			t_SetSeqParam.scEvent	= TYPD_PASM_EVENT_TOP;
			TYPE_PASM_RET	e_Ret	= pc_Pasm->getSeqAuthInfo( &t_SetSeqParam, t_GetSeqParam );
			if ( TYPE_PASM_RET_SUCCESS != e_Ret ) {
				printf("PnlComSetProcessTroubleInfo %d, e_Ret is %d : %s(%d)\n", PNLD_TroubleDetailCode_GetSeqAuthInfoError, e_Ret, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetSeqAuthInfoError );
				PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetSeqAuthInfoError , __LINE__ );
				return( False );
			}
		}
	}

	PBasicMessageProc*	pc_GamenInst	= 0;
	char	sc_Type	= TYPD_NextGamenDisplayType_Error;
	PnlComSeqNextGamenInsGetCustom( t_GetSeqParam->st_actionParam.st_ParamScreen.usAuthScreenID, &pc_GamenInst, &sc_Type );
	if ( 0 == pc_GamenInst ) {
		printf("PnlComSetProcessTroubleInfo %d, pc_GamenInst is NULL : %s(%d)\n", PNLD_TroubleDetailCode_GetNextGamenError, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetNextGamenError );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetNextGamenError , __LINE__ );
		return( False );
	}

	if ( TYPD_NextGamenDisplayType_Base == sc_Type ) {
		PBasicMessageProc::setNextGamen( pc_GamenInst );
		// 画面遷移処理後、既存処理で別画面に遷移したかどうか確認するため一時的に取得したインスタンスを保持する.
		PBasicMessageProc::setSeqCustomGamenIns( pc_GamenInst );
	} else if ( TYPD_NextGamenDisplayType_Popup == sc_Type ) {
		PNLC_PopupListControl*	pc_PopupListCtrl	= PNLC_PopupListControl::newInstance();
		PPopupCom*	pc_PopInst	= dynamic_cast<PPopupCom*>( pc_GamenInst );
		if ( ( 0 == pc_PopupListCtrl ) || ( 0 == pc_PopInst ) ) {
			printf("PnlComSetProcessTroubleInfo %d, pc_PopupListCtrl is NULL or pc_PopInst is NULL : %s(%d)\n", PNLD_TroubleDetailCode_IllegalAddPopParam, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//			PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalAddPopParam );
			PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_IllegalAddPopParam , __LINE__ );
			return( False );
		}
		pc_PopupListCtrl->addPopup( pc_PopInst, PBasicMessageProc::getNowGamen(), 0 );
	} else {
		printf("PnlComSetProcessTroubleInfo %d, sc_Type is %d : %s(%d)\n", PNLD_TroubleDetailCode_GetNextGamenError, sc_Type, __FILE__, __LINE__ );
//comment 2017/07/05 SCD2-Sky肥後 [1026857] 新詳細コード対応.
//		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetNextGamenError );
		PnlComSetProcessTroubleInfo( PNLD_TroubleDetailCode_GetNextGamenError , __LINE__ );
		return( False );
	}

	return( True );
}

