//==================================================================================================
//［機能］アクティブジョブ判定制御.
// [引数] APIC_Job* pc_Job：チェック対象ジョブ.
// [戻値] True：アクティブジョブである.
//        False：アクティブジョブではない.
// [履歴] 2015.05.22 OPS1-Sky石賀 [HeliosL][CQ512677] 新規追加.
//==================================================================================================
Bool PnlComIsExistActiveJobList( APIC_Job* pc_Job )
{
	// NULL時は、Falseを返却.
	if ( NULL == pc_Job ) { return False; }

	LIBC_List<APIC_Job>  c_Joblist;	// ジョブのリスト.
	short ss_JobNum      = 0;		// リストの個数. 
	// 全アクティブジョブを取得.
//Comment 2017/11/22【HCLT-Sudheer】【IT5 4.2】【RQ686】 API Correction.
//	ss_JobNum = cp_ActiveJobList->getList(
//								TYPE_ActiveJobListAll,	// アクティブジョブリスト種類.
//								1,						// 開始位置（１～Ｎ）.
//								TYPD_MaxActiveJob,		// 個数.
//								&c_Joblist );       	// リスト. 
	ss_JobNum = cp_ActiveJobList->getList(
								TYPE_ActiveJobListAll,	// アクティブジョブリスト種類.
								1,						// 開始位置（１～Ｎ）.
								TYPD_MaxActiveJob,		// 個数.
								&c_Joblist,
								PNLC_NetworkLan::getInstance()->getLine());       	// リスト. 

	Bool bl_Exist = False;
	APIC_Job* pc_ActiveJob = c_Joblist.findFirst();	// 先頭を取得.
	while ( NULL != pc_ActiveJob ) {
		if ( pc_ActiveJob == pc_Job ) {
			bl_Exist = True;
			break;
		}
		pc_ActiveJob = c_Joblist.findNext();		// 次データを取得
	}
	return bl_Exist;
}


// comment 2015/06/15 OPS1-Sky佐藤 [ZeusS_ZX0][RQ-405] パネルUIのヘブライ語対応.
//==================================================================================================
//［機能］言語設定が右詰め表示言語かどうかの判定処理.
// [引数] 言語設定[IN].
// [戻値] True :右詰め言語である.
//        False:右詰め言語ではない.
// [履歴] [ZeusS_ZX0][RQ-405] 新規追加.
//==================================================================================================
Bool isRightDispLanguage( TYPE_Language e_LangType )
{
	Bool bl_Ret = False;

	if ( ( TYPE_LanguageArabic == e_LangType ) ||		// アラビア語.
		 ( TYPE_LanguageHebrew == e_LangType ) )		// ヘブライ語.
	{
		bl_Ret = True;
	}

	return bl_Ret;
}

// 概要 :機能制限情報不正値判定(onlyPanel.bl_LimitIllegalData に設定).
// 			[MZ-80 AD直連携時の機能制限対応] AD直連携時の機能制限対応.
// 			ユーザー毎の機能制限情報を外部サーバー（AD）から取得する.
// 			従来は APIC_User::req_login_ex()の 結果通知 TYPE_UserResultFunctionInvalid として通知.
// 			認証シーケンス制御では、ユーザデータ取得機能の機能制限データ取得状況に対応して決定する。.
void PnlComSeqFuncLimit(TYPS_AuthSeqOutParam* pt_FromMngParam)
{
	if( NULL == pt_FromMngParam) {
		return;
	}
	APIC_SoftDipSw* pc_SoftDipSw = APIC_SoftDipSw::newInstance();
	if( NULL == pc_SoftDipSw ) {
		return;
	}

	// [MZ-80 AD直連携時の機能制限対応] AD直連携時の機能制限対応.
// comment 2016/01/27 OPS1-MSE秋山 [ZeusS_ZX0][CQ523891]コンフィグも考慮したチェック関数をコールするように修正.
//	if( True == pc_SoftDipSw->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW200, 3 ) ) {
	if( True == PnlComIsExtServerDataGet() ) {
		onlyPanel.bl_LimitIllegalData = True;		// 機能制限情報不正値あり.
		TYPS_AuthSeqCustomInstanceInfo* pt_InstanceInfo = pt_FromMngParam->st_actionParam.st_ParamEnd.pt_InstanceInfo;
		if( NULL != pt_InstanceInfo) {
			ushort us_DataNum = static_cast<ushort>(pt_FromMngParam->st_actionParam.st_ParamEnd.ucDataNum);
			for( ushort us_Cnt = 0; us_Cnt < us_DataNum; us_Cnt++, pt_InstanceInfo++ ){
				if (TYPD_PASM_INSTANCE_GETDATA == pt_InstanceInfo->ucKind) {
					switch(pt_InstanceInfo->st_Instance.st_GetData.e_GetDataResult[ACSE_DataGetType_FuncLimit]) {
// comment 2016/01/27 OPS1-MSE秋山 [ZeusS_ZX0][CQ523891]一部取得OKは不正値ありのためNG側に移動.
//						case TYPE_ExtServerDataGetResult_GetOK:			// 機能制限：外部サーバーデータ取得結果 取得OK.
//						case TYPE_ExtServerDataGetResult_PartGetOK:		// 機能制限：外部サーバーデータ取得結果 一部取得OK.
//							onlyPanel.bl_LimitIllegalData = False;		// 機能制限情報不正値なし.
//							break;
//						case TYPE_ExtServerDataGetResult_AnalyzeNG:		// 機能制限：外部サーバーデータ取得結果 解析NG.
//						case TYPE_ExtServerDataGetResult_GetNG:			// 機能制限：外部サーバーデータ取得結果 取得NG.
//						case TYPE_ExtServerDataGetResult_NoGet:			// 機能制限：外部サーバーデータ取得結果 取得なし.
//						default:
//							onlyPanel.bl_LimitIllegalData = True;		// 機能制限情報不正値あり.
//							break;
						case TYPE_ExtServerDataGetResult_GetOK:			// 機能制限：外部サーバーデータ取得結果 取得OK.
						case TYPE_ExtServerDataGetResult_NoGet:			// 機能制限：外部サーバーデータ取得結果 取得なし.
							onlyPanel.bl_LimitIllegalData = False;		// 機能制限情報不正値なし.
							break;
						case TYPE_ExtServerDataGetResult_PartGetOK:		// 機能制限：外部サーバーデータ取得結果 一部取得OK.
						case TYPE_ExtServerDataGetResult_AnalyzeNG:		// 機能制限：外部サーバーデータ取得結果 解析NG.
						case TYPE_ExtServerDataGetResult_GetNG:			// 機能制限：外部サーバーデータ取得結果 取得NG.
						default:
							onlyPanel.bl_LimitIllegalData = True;		// 機能制限情報不正値あり.
							break;
					}
				}
			}
		}
	}
}
