/**
* @brief Check USB access permission for ALL ( User/Admin/Service).
* @param no.
* @retval PNLE_EnableUSBConnectionPermissionForAll( Allow ALL/Restrict ALL /Individual Setting).
*/
// ===============================================================================================
PNLE_EnableUSBConnectionPermissionForAll PNLC_USBConnectionPermission::getEnableUSBConnectionPermissionForAll()
{
	PNLE_EnableUSBConnectionPermissionForAll e_EnableUSBConnectionPermissionForAll = PNLE_EnableUSBConnectionPermissionForAll_Disable;         // Restrict ALL.
	APIC_SystemSetting* pc_SystemSetting = PnlComGetSystemSetting();
	if ( NULL == pc_SystemSetting  ) { 
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); 
		return e_EnableUSBConnectionPermissionForAll; 
	}
	if (True == pc_SystemSetting->getEnableUSBConnectAll()){
		e_EnableUSBConnectionPermissionForAll = PNLE_EnableUSBConnectionPermissionForAll_Enable;          									// Allow ALL. 
	}
	return e_EnableUSBConnectionPermissionForAll;
}
// ===============================================================================================
/**
* @brief  Check USB access permission for User.
* @param  no.
* @retval PNLE_EnableUSBConnectionPermissionForUser( Allow ALL/Restrict ALL /Individual Setting).
*/
// ===============================================================================================
PNLE_EnableUSBConnectionPermissionForUser PNLC_USBConnectionPermission::getEnableUSBConnectionPermissionForAllUser()
{
	PNLE_EnableUSBConnectionPermissionForUser e_EnableUSBConnectionPermissionForUser = PNLE_EnableUSBConnectionPermissionForUser_Disable;	// Restrict ALL.
	APIC_SystemSetting* pc_SystemSetting = PnlComGetSystemSetting();
	if ( NULL == pc_SystemSetting ) {
	    LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); 
        return e_EnableUSBConnectionPermissionForUser; 
    }
// comment 2017/09/04 【HCL-Ramkishor】【IT5_4.2】【RQ686】【WP975】【詳細制御仕様書_管理No.33】 The new API is used and to detect the current network type, new API arguments are passed.
	TYPE_NetworkSpecific e_NetworkSpecific = PNLC_NetworkLan::getInstance()->getAdminNWLine();
	if ( True == pc_SystemSetting->getEnableUSBConnectAllUser( e_NetworkSpecific ) ) {
        e_EnableUSBConnectionPermissionForUser = PNLE_EnableUSBConnectionPermissionForUser_Enable;											// Allow ALL.
	}
	return e_EnableUSBConnectionPermissionForUser;
}
