// ===============================================================================================
/**
* @brief  Increase  the Counter value.
* @param  ss_AppNo function use frequency counter (IWS-related) type.
* @retval   no.
*/
// ===============================================================================================
struct TYPS_IwsAppDetailInfo {
 char sc_IwsAppID[TYPD_IwsMaxID + 1];
 char sc_IwsAppName[TYPD_IwsMaxAppName + 1];
 char sc_IwsAppType;
};
static TYPS_IwsAppDetailInfo  s_IwsAppInfo[TYPD_IwsMaxApplication];  // Structure to store IWS application details(ID.Name and Type).
static uchar uc_IWSAppCount;      //  Total number IWS app count.

void PnlComIncreaseIwsCnt( short ss_IwsAppNo, TYPE_IwsCnt e_IwsCnt )
{
	APIC_IWSAppInfo* pc_IWSAppInfo = APIC_IWSAppInfo::newInstance();
	if( NULL == pc_IWSAppInfo ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	
	CNTC_CounterIf* pc_IwsCnt = CNTC_CounterIf::newInstance();
	if( NULL == pc_IwsCnt ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	
	pc_IWSAppInfo->lock();
	uc_IWSAppCount = static_cast<uchar>( pc_IWSAppInfo->getApplicationNum() );
	
	// comment [ZeusS_ZX0] 2016/1/13 Sky後藤(拓) CQ523588 IWS情報のアンロック漏れを修正.
	TYPS_IwsAppInfo s_tempAppInfo;            							// Temprorary structure variable of TYPS_IwsAppInfo.
	memset( &s_tempAppInfo, '\0', sizeof( s_tempAppInfo ) );			// initialization of IWS-related Application Information Structure.
//	int appcount = 0;													// Temp variable.
//	int index = 0;														// Temporary variable used for storing index values of TYPS_IwsAppInfo.
//	
//	for( int appindex = 0 ; appindex < TYPD_IwsMaxApplication && ( appcount <  uc_IWSAppCount ) ; appindex++ ) {
//		int ret = pc_IWSAppInfo->getApplication( appindex+1 , s_tempAppInfo );
//		if( ( TYPD_IwsResult_OK == ret ) && ( TYPE_IwsEntryON == s_tempAppInfo.e_Entry ) && ( TYPE_IwsAppTypeGeneral == s_tempAppInfo.e_AppType ) ) {
//			appcount++;
	for( int index = 0 ; index < TYPD_IwsMaxApplication ; index++ ) {
		int ret = pc_IWSAppInfo->getApplication( index+1 , s_tempAppInfo );
		if( ( TYPD_IwsResult_OK == ret ) &&
			( TYPE_IwsEntryON == s_tempAppInfo.e_Entry ) &&
// comment 2019/04/16 SCD2-Sky中野 [EagleH] 目的別UI_1ペイン対応.
//			( TYPE_IwsAppTypeGeneral == s_tempAppInfo.e_AppType ) &&
			( ( TYPE_IwsAppTypeGeneral == s_tempAppInfo.e_AppType ) 
				|| ( TYPE_IwsAppTypeCustomUI == s_tempAppInfo.e_AppType ) ) &&
			( ss_IwsAppNo == s_tempAppInfo.s_BrowserUiSetting.ss_RegistNo ) ) {
			// Copy the Application ID.
			memset( s_IwsAppInfo[index].sc_IwsAppID, 0, sizeof( s_IwsAppInfo[index].sc_IwsAppID ) );
			memcpy( s_IwsAppInfo[index].sc_IwsAppID, s_tempAppInfo.sc_ID, sizeof( s_tempAppInfo.sc_ID ) );
			
			pc_IwsCnt->countFuncUseIWSApp( e_IwsCnt, s_IwsAppInfo[index].sc_IwsAppID );	// Increment the value of counter by default by 1.
			break;
//			index++;
//		}else {
//			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
//			return;
		}
	}
	pc_IWSAppInfo->unlock();
}
