// comment 2017/09/04 住谷 [SecV2] 読み込み中画面でのシステムオートリセット処理追加 Start.
//==================================================================================================
//［機能］セキュリティ強化モード時ジョブ削除判定処理.
// [引数] なし.
// [戻値] Bool.
// [履歴] 2017/09/04 住谷 [SecV2] 読み込み中画面でのシステムオートリセット処理追加.
//==================================================================================================
Bool CheckSecurityUpJobDelete( void )
{
	if( False == APIC_SystemSetting::newInstance()->getSecurityLevelUpOn() ){			// セキュリティ強化モード判定.
		return False;
	}
	
	if( ( EP_PNS_SeparateScanStop == onlyPanel.ep_PanelStatus ) ||						// 分割読込停止中.
		( EP_PNS_ReadStop == onlyPanel.ep_PanelStatus ) ||								// 読込停止中.
		( EP_PNS_ReadErrorStop == onlyPanel.ep_PanelStatus ) ) {						// 読込エラー停止中.
			return True;
	}
	
	return False;
}
//==================================================================================================.
//概要     : セキュリティ強化モード時のシステムオートリセット対象判定.
//戻り値   : Bool.
//備考     : 特定の画面で放置した際、システムオートリセットが実施されないための対策.
//==================================================================================================.
Bool CheckSecurityUpAutoReset(void)
{
	if( False == APIC_SystemSetting::newInstance()->getSecurityLevelUpOn() ){			// セキュリティ強化モード判定.
		return False;
	}

	if( ( EP_PNS_SeparateScanStop == onlyPanel.ep_PanelStatus )							// 分割読込停止中.
	||  ( EP_PNS_ReadStop == onlyPanel.ep_PanelStatus )									// 読込停止中.
	||  ( EP_PNS_ReadErrorStop == onlyPanel.ep_PanelStatus )							// 読込エラー停止中.
	||  ( EP_PNS_Setting == onlyPanel.ep_PanelStatus )									// 設定状態.
	||  ( EP_PNS_PrintStop == onlyPanel.ep_PanelStatus ) ) {							// プリント停止中.
		return True;
	}
	
	return False;
}
